                WarningNote = "Ki\u1EC3m tra danh s\u00E1ch Chi ti\u1EBFt tr\u01B0\u1EDBc khi x\u00F3a.",
                CleanMode = "ItemsList", SupportsRecycleBin = true, DefaultSelected = false, Selected = false,
