if (-not ("DuckUtil.AppCatalogEngine" -as [type])) {
    try {
        if ($PSScriptRoot) {
            $csCandidates = @(
                (Join-Path $PSScriptRoot "..\..\csharp\AppCatalogEngine.cs"),
                (Join-Path $PSScriptRoot "..\csharp\AppCatalogEngine.cs"),
                (Join-Path $PSScriptRoot "csharp\AppCatalogEngine.cs")
            )
            foreach ($cand in $csCandidates) {
                if (Test-Path -LiteralPath $cand) {
                    $appCatalogCs = Get-Content -Raw -Encoding utf8 $cand
                    Add-Type -TypeDefinition $appCatalogCs -ErrorAction SilentlyContinue
                    break
                }
            }
        }
    } catch {}
}

$script:brushOutdatedFg = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(255, 0xF8, 0x71, 0x71))
$script:brushLatestFg   = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(255, 0x34, 0xD3, 0x99))
$script:brushNoneBg     = [System.Windows.Media.Brushes]::Transparent
$script:brushNoneFg     = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(255, 0xF1, 0xF5, 0xF9))

$script:brushOutdatedFg.Freeze()
$script:brushLatestFg.Freeze()
$script:brushNoneFg.Freeze()

$script:cleanNameCache     = [System.Collections.Generic.Dictionary[string, string]]::new([System.StringComparer]::OrdinalIgnoreCase)
$script:versionNumCache    = [System.Collections.Generic.Dictionary[string, long[]]]::new([System.StringComparer]::OrdinalIgnoreCase)
$script:targetAppMetaCache = [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::OrdinalIgnoreCase)
$script:stopWordSet        = [System.Collections.Generic.HashSet[string]]::new([string[]]@("microsoft", "windows", "google", "runtime", "desktop", "client", "studio", "server", "edition", "community", "x64", "x86", "arm64", "arp", "msix", "machine", "user", "app", "pro", "free", "jdk", "jre", "lts", "cli", "ide", "gui", "vpn", "bit"), [System.StringComparer]::OrdinalIgnoreCase)
$script:preSpawnedWinget   = $null

function Get-CleanAppName {
    param([string]$RawName)
    if ([string]::IsNullOrWhiteSpace($RawName)) { return "" }
    $cached = $null
    if ($script:cleanNameCache.TryGetValue($RawName, [ref]$cached)) {
        return $cached
    }
    if ("DuckUtil.AppCatalogEngine" -as [type]) {
        $clean = [DuckUtil.AppCatalogEngine]::CleanCatalogAppName($RawName)
        $script:cleanNameCache[$RawName] = $clean
        return $clean
    }
    $clean = ($RawName -replace '\((?!x64|x86|arm64).*?\)', '').Replace('(', '').Replace(')', '').Trim().ToLowerInvariant()
    $clean = $clean -replace '\b(version|ver|v|release)\s*\d+(\.\d+)*[^\s]*', ''
    $clean = $clean -replace '\b\d+(\.\d+){1,4}(-[a-z0-9.]+)?\b', ''
    $terms = @(" browser", " desktop", " lts", " client", " free", " ce", " community", " end-user", " stable", " edition", " x64", " x86", " 64-bit", " 32-bit")
    foreach ($term in $terms) {
        $clean = $clean.Replace($term, "")
    }
    $clean = ($clean -replace '\s+', ' ').Trim()
    $script:cleanNameCache[$RawName] = $clean
    return $clean
}

function Get-VersionNumbers {
    param([string]$VerStr)
    if ([string]::IsNullOrWhiteSpace($VerStr)) { return [long[]]@() }
    $cached = $null
    if ($script:versionNumCache.TryGetValue($VerStr, [ref]$cached)) {
        return $cached
    }
    if ("DuckUtil.AppCatalogEngine" -as [type]) {
        $arr = [DuckUtil.AppCatalogEngine]::GetVersionNumbers($VerStr)
        $script:versionNumCache[$VerStr] = $arr
        return $arr
    }
    $s = $VerStr.Trim()
    if ($s.StartsWith("<")) { $s = $s.Substring(1).Trim() }
    $m = [System.Text.RegularExpressions.Regex]::Match($s, '\d+(?:[.+_-]\d+)*')
    if (-not $m.Success) {
        $empty = [long[]]@()
        $script:versionNumCache[$VerStr] = $empty
        return $empty
    }
    $parts = $m.Value -split '[.+_-]'
    $nums = [System.Collections.Generic.List[long]]::new()
    foreach ($p in $parts) {
        $v = 0L
        if ([long]::TryParse($p, [ref]$v)) {
            $nums.Add($v)
        }
    }
    $arr = $nums.ToArray()
    $script:versionNumCache[$VerStr] = $arr
    return $arr
}

function Compare-AppVersions {
    param([string]$VerA, [string]$VerB)
    if ("DuckUtil.AppCatalogEngine" -as [type]) {
        return [DuckUtil.AppCatalogEngine]::CompareAppVersions($VerA, $VerB)
    }
    $a = @(Get-VersionNumbers $VerA)
    $b = @(Get-VersionNumbers $VerB)
    if ($a.Count -eq 0 -and $b.Count -eq 0) { return 0 }
    if ($a.Count -gt 0 -and $b.Count -eq 0) { return 1 }
    if ($a.Count -eq 0 -and $b.Count -gt 0) { return -1 }

    $maxLen = [Math]::Max($a.Count, $b.Count)
    for ($i = 0; $i -lt $maxLen; $i++) {
        $va = if ($i -lt $a.Count) { [long]$a[$i] } else { 0L }
        $vb = if ($i -lt $b.Count) { [long]$b[$i] } else { 0L }
        if ($va -gt $vb) { return 1 }
        if ($va -lt $vb) { return -1 }
    }
    return 0
}

function Test-AppUpdateGenuine {
    param([string]$InstalledVer, [string]$AvailableVer)
    if ("DuckUtil.AppCatalogEngine" -as [type]) {
        return [DuckUtil.AppCatalogEngine]::TestAppUpdateGenuine($InstalledVer, $AvailableVer)
    }
    if ([string]::IsNullOrWhiteSpace($AvailableVer)) { return $false }
    $av = $AvailableVer.Trim()
    if ($av -eq "winget" -or $av -eq "msstore" -or $av -eq "Unknown") { return $false }
    if ($av -notmatch '\d') { return $false }
    if ([string]::IsNullOrWhiteSpace($InstalledVer)) { return $false }
    $iv = $InstalledVer.Trim()
    if ($iv -eq "Unknown" -or $iv -eq "Installed" -or $iv -notmatch '\d') { return $false }
    $cmp = Compare-AppVersions $av $iv
    if ($iv.StartsWith("<")) { return ($cmp -ge 0) }
    if ($cmp -gt 0) { return $true }
    $rxPre = '(?i)(?:^|[-.+_])(?:alpha|beta|rc|pre|preview|dev|canary|nightly)(?:$|[-.+_\d])'
    if ($cmp -eq 0 -and ($iv -match $rxPre) -and ($av -notmatch $rxPre)) { return $true }
    return $false
}

function Get-CharDisplayWidth {
    param([int]$Code)
    if (
        ($Code -ge 0x1100 -and $Code -le 0x115F) -or
        ($Code -eq 0x2329 -or $Code -eq 0x232A) -or
        ($Code -ge 0x2E80 -and $Code -le 0x303E) -or
        ($Code -ge 0x3041 -and $Code -le 0x33FF) -or
        ($Code -ge 0x3400 -and $Code -le 0x4DBF) -or
        ($Code -ge 0x4E00 -and $Code -le 0xA4CF) -or
        ($Code -ge 0xA960 -and $Code -le 0xA97F) -or
        ($Code -ge 0xAC00 -and $Code -le 0xD7AF) -or
        ($Code -ge 0xF900 -and $Code -le 0xFAFF) -or
        ($Code -ge 0xFE10 -and $Code -le 0xFE19) -or
        ($Code -ge 0xFE30 -and $Code -le 0xFE6F) -or
        ($Code -ge 0xFF01 -and $Code -le 0xFF60) -or
        ($Code -ge 0xFFE0 -and $Code -le 0xFFE6) -or
        ($Code -ge 0x1F300 -and $Code -le 0x1FAFF)
    ) { return 2 }
    return 1
}

function Get-SliceByDisplayWidth {
    param([string]$Line, [int[]]$Offsets)
    $idIdx    = if ($Offsets.Count -ge 2) { $Offsets[1] } else { -1 }
    $verIdx   = if ($Offsets.Count -ge 3) { $Offsets[2] } else { -1 }
    $availIdx = if ($Offsets.Count -ge 4) { $Offsets[3] } else { -1 }
    $srcIdx   = if ($Offsets.Count -ge 5) { $Offsets[4] } else { -1 }

    $targets = @($idIdx, $verIdx, $availIdx, $srcIdx)
    $charPos = @(-1, -1, -1, -1)
    $w = 0
    for ($i = 0; $i -lt $Line.Length; $i++) {
        for ($t = 0; $t -lt 4; $t++) {
            if ($charPos[$t] -lt 0 -and $targets[$t] -ge 0 -and $w -ge $targets[$t]) {
                $charPos[$t] = $i
            }
        }
        $ch = $Line[$i]
        if ([char]::IsHighSurrogate($ch) -and ($i + 1) -lt $Line.Length -and [char]::IsLowSurrogate($Line[$i + 1])) {
            $cp = [char]::ConvertToUtf32($ch, $Line[$i + 1])
            $w += Get-CharDisplayWidth $cp
            $i++
        } else {
            $w += Get-CharDisplayWidth ([int]$ch)
        }
    }

    return Slice-WingetRowColumnsByPositions -Line $Line -CId $charPos[0] -CVer $charPos[1] -CAvail $charPos[2] -CSrc $charPos[3]
}

function Get-StringDisplayWidth {
    param([string]$Text, [int]$EndIndex = -1)
    if ([string]::IsNullOrEmpty($Text)) { return 0 }
    $limit = if ($EndIndex -ge 0 -and $EndIndex -le $Text.Length) { $EndIndex } else { $Text.Length }
    $w = 0
    for ($i = 0; $i -lt $limit; $i++) {
        $ch = $Text[$i]
        if ([char]::IsHighSurrogate($ch) -and ($i + 1) -lt $limit -and [char]::IsLowSurrogate($Text[$i + 1])) {
            $cp = [char]::ConvertToUtf32($ch, $Text[$i + 1])
            $w += Get-CharDisplayWidth $cp
            $i++
        } else {
            $w += Get-CharDisplayWidth ([int]$ch)
        }
    }
    return $w
}

function Snap-WingetColumnBoundary {
    param([string]$Line, [int]$Pos, [int]$MinPos)
    if ([string]::IsNullOrEmpty($Line) -or $Pos -le $MinPos -or $Pos -ge $Line.Length) { return $Pos }
    if ([char]::IsWhiteSpace($Line[$Pos]) -or [char]::IsWhiteSpace($Line[$Pos - 1])) { return $Pos }

    $leftCand = -1
    $minLeft = [Math]::Max($MinPos + 1, $Pos - 10)
    for ($j = $Pos - 1; $j -ge $minLeft; $j--) {
        if ([char]::IsWhiteSpace($Line[$j])) { $leftCand = $j + 1; break }
    }

    $rightCand = -1
    $maxRight = [Math]::Min($Line.Length - 1, $Pos + 10)
    for ($j = $Pos + 1; $j -le $maxRight; $j++) {
        if ([char]::IsWhiteSpace($Line[$j])) {
            $k = $j
            while ($k -lt $Line.Length -and [char]::IsWhiteSpace($Line[$k])) { $k++ }
            if ($k -lt $Line.Length) { $rightCand = $k }
            break
        }
    }

    if ($leftCand -ge 0 -and $rightCand -ge 0) {
        if (($Pos - $leftCand) -le ($rightCand - $Pos)) { return $leftCand }
        return $rightCand
    }
    if ($leftCand -ge 0) { return $leftCand }
    if ($rightCand -ge 0) { return $rightCand }
    return $Pos
}

function Find-NextWingetColumnStartOrEnd {
    param([string]$Line, [int]$Pos, [int]$MaxEnd)
    $limit = if ($MaxEnd -gt $Pos -and $MaxEnd -le $Line.Length) { $MaxEnd } else { $Line.Length }
    if ($Pos -lt 0 -or $Pos -ge $limit) { return $limit }
    if ([char]::IsWhiteSpace($Line[$Pos]) -or ($Pos -gt 0 -and [char]::IsWhiteSpace($Line[$Pos - 1]))) { return $Pos }
    $j = $Pos
    while ($j -lt $limit -and -not [char]::IsWhiteSpace($Line[$j])) { $j++ }
    while ($j -lt $limit -and [char]::IsWhiteSpace($Line[$j])) { $j++ }
    return $j
}

function Split-WingetTailAvailAndSource {
    param([string]$Tail)
    $avail = ""; $src = ""
    if ([string]::IsNullOrWhiteSpace($Tail)) { return @($avail, $src) }
    $t = $Tail.Trim()
    if ($t -match '^(?i)(winget|msstore)$') {
        return @("", $t)
    }
    $lastSpace = -1
    for ($i = $t.Length - 1; $i -ge 0; $i--) {
        if ([char]::IsWhiteSpace($t[$i])) { $lastSpace = $i; break }
    }
    if ($lastSpace -gt 0) {
        $lastTok = $t.Substring($lastSpace + 1).Trim()
        if ($lastTok -match '^(?i)(winget|msstore)$') {
            $src = $lastTok
            $avail = $t.Substring(0, $lastSpace).Trim()
            return @($avail, $src)
        }
    }
    return @($t, "")
}

function Resolve-WingetRowSource {
    param([string]$AppId, [string]$SrcCol)
    if (-not [string]::IsNullOrWhiteSpace($SrcCol)) {
        $s = $SrcCol.Trim()
        if ($s.Equals("msstore", [System.StringComparison]::OrdinalIgnoreCase)) { return "msstore" }
        return "winget"
    }
    if (-not [string]::IsNullOrWhiteSpace($AppId) -and ($AppId.StartsWith("ARP\", [System.StringComparison]::OrdinalIgnoreCase) -or $AppId.StartsWith("MSIX\", [System.StringComparison]::OrdinalIgnoreCase))) {
        return "local"
    }
    return "winget"
}

function Slice-WingetRowColumnsByPositions {
    param([string]$Line, [int]$CId, [int]$CVer, [int]$CAvail, [int]$CSrc)
    $appName = ""; $appId = ""; $version = ""; $avail = ""; $src = ""
    if ($CId -gt 0 -and $Line.Length -gt $CId) {
        $CId = Snap-WingetColumnBoundary -Line $Line -Pos $CId -MinPos 0
        $appName = $Line.Substring(0, $CId).Trim()
        if ($CVer -gt $CId -and $Line.Length -gt $CVer) {
            $CVer = Snap-WingetColumnBoundary -Line $Line -Pos $CVer -MinPos $CId
            if ($CVer -gt $CId -and $CVer -lt $Line.Length -and -not [char]::IsWhiteSpace($Line[$CVer]) -and -not [char]::IsWhiteSpace($Line[$CVer - 1])) {
                $CVer = Find-NextWingetColumnStartOrEnd -Line $Line -Pos $CVer -MaxEnd $Line.Length
            }
            $appId = if ($CVer -lt $Line.Length) { $Line.Substring($CId, $CVer - $CId).Trim() } else { $Line.Substring($CId).Trim() }
            if ($CVer -lt $Line.Length) {
                if ($CAvail -gt $CVer -and $Line.Length -gt $CAvail) {
                    $availStart = Find-NextWingetColumnStartOrEnd -Line $Line -Pos $CAvail -MaxEnd $Line.Length
                    if ($availStart -le $CVer) { $availStart = $CAvail }
                    if ($availStart -lt $Line.Length) {
                        $verSlice = $Line.Substring($CVer, $availStart - $CVer).Trim()
                        if ($verSlice -eq "<" -or $verSlice -eq ">") {
                            while ($availStart -lt $Line.Length -and [char]::IsWhiteSpace($Line[$availStart])) { $availStart++ }
                            $availStart = Find-NextWingetColumnStartOrEnd -Line $Line -Pos $availStart -MaxEnd $Line.Length
                        }
                    }
                    if ($availStart -ge $Line.Length) {
                        $version = $Line.Substring($CVer).Trim()
                    } else {
                        $version = $Line.Substring($CVer, $availStart - $CVer).Trim()
                        if ($CSrc -gt $availStart -and $Line.Length -gt $CSrc) {
                            $srcStart = Find-NextWingetColumnStartOrEnd -Line $Line -Pos $CSrc -MaxEnd $Line.Length
                            $avail = $Line.Substring($availStart, $srcStart - $availStart).Trim()
                            if ($srcStart -lt $Line.Length) { $src = $Line.Substring($srcStart).Trim() }
                        } elseif ($CSrc -gt 0 -and $CSrc -le $availStart -and $Line.Length -gt $availStart) {
                            $splitTail = Split-WingetTailAvailAndSource -Tail $Line.Substring($availStart)
                            $avail = $splitTail[0]; $src = $splitTail[1]
                        } else {
                            $avail = $Line.Substring($availStart).Trim()
                        }
                    }
                } elseif ($CAvail -gt 0 -and $CVer -ge $CAvail) {
                    $verEnd = $CVer
                    while ($verEnd -lt $Line.Length -and -not [char]::IsWhiteSpace($Line[$verEnd])) { $verEnd++ }
                    $tok = $Line.Substring($CVer, $verEnd - $CVer)
                    if (($tok -eq "<" -or $tok -eq ">") -and $verEnd -lt $Line.Length) {
                        $p = $verEnd
                        while ($p -lt $Line.Length -and [char]::IsWhiteSpace($Line[$p])) { $p++ }
                        while ($p -lt $Line.Length -and -not [char]::IsWhiteSpace($Line[$p])) { $p++ }
                        $verEnd = $p
                    }
                    $version = $Line.Substring($CVer, $verEnd - $CVer).Trim()
                    $availStart = $verEnd
                    while ($availStart -lt $Line.Length -and [char]::IsWhiteSpace($Line[$availStart])) { $availStart++ }
                    if ($availStart -lt $Line.Length) {
                        $tail = $Line.Substring($availStart).Trim()
                        if ($CSrc -gt 0) {
                            $splitTail = Split-WingetTailAvailAndSource -Tail $tail
                            $avail = $splitTail[0]; $src = $splitTail[1]
                        } else {
                            $avail = $tail
                        }
                    }
                } else {
                    $version = $Line.Substring($CVer).Trim()
                }
            }
        } else {
            $appId = $Line.Substring($CId).Trim()
        }
    }
    return @($appName, $appId, $version, $avail, $src)
}

function Test-VersionAtLeastAvailable {
    param([string]$InstalledVer, [string]$WgVer, [string]$WgAvail)
    if ([string]::IsNullOrWhiteSpace($InstalledVer) -or $InstalledVer -match '^(Installed|Unknown)$' -or $InstalledVer -notmatch '\d') { return $false }
    if ([string]::IsNullOrWhiteSpace($WgAvail) -or $WgAvail -match '^(Installed|Unknown)$' -or $WgAvail -notmatch '\d') { return $false }
    if ((Compare-AppVersions $InstalledVer $WgAvail) -ge 0) { return $true }
    $locNums = @(Get-VersionNumbers $InstalledVer)
    $availNums = @(Get-VersionNumbers $WgAvail)
    if ($locNums.Count -ge 2 -and $locNums.Count -lt $availNums.Count) {
        $isPrefix = $true
        for ($i = 0; $i -lt $locNums.Count; $i++) {
            if ($locNums[$i] -ne $availNums[$i]) { $isPrefix = $false; break }
        }
        if ($isPrefix -and -not [string]::IsNullOrWhiteSpace($WgVer) -and ($WgVer -match '\d') -and ((Compare-AppVersions $InstalledVer $WgVer) -gt 0)) {
            return $true
        }
    }
    return $false
}

function Set-PreferredMapEntry {
    param($Map, [string]$Key, $Candidate)
    if ([string]::IsNullOrWhiteSpace($Key) -or $null -eq $Candidate) { return }
    if (-not $Map.ContainsKey($Key)) {
        $Map[$Key] = $Candidate
        return
    }
    $cur = $Map[$Key]
    $curIsLocal = ($cur.Source -eq "local")
    $candIsLocal = ($Candidate.Source -eq "local")

    if ($curIsLocal -ne $candIsLocal) {
        $locItem = if ($curIsLocal) { $cur } else { $Candidate }
        $wgItem = if ($curIsLocal) { $Candidate } else { $cur }
        $hasLocNum = (-not [string]::IsNullOrWhiteSpace($locItem.Version) -and $locItem.Version -notmatch '^(Installed|Unknown)$' -and $locItem.Version -match '\d')
        $hasWgVerNum = (-not [string]::IsNullOrWhiteSpace($wgItem.Version) -and $wgItem.Version -notmatch '^(Installed|Unknown)$' -and $wgItem.Version -match '\d')
        $hasWgAvailNum = (-not [string]::IsNullOrWhiteSpace($wgItem.Available) -and $wgItem.Available -notmatch '^(Installed|Unknown)$' -and $wgItem.Available -match '\d')
        if ($hasLocNum) {
            if ($wgItem.HasUpdate -and $hasWgAvailNum) {
                $Map[$Key] = if (Test-VersionAtLeastAvailable -InstalledVer $locItem.Version -WgVer $wgItem.Version -WgAvail $wgItem.Available) { $locItem } else { $wgItem }
                return
            }
            if (-not $hasWgVerNum -or (Compare-AppVersions $locItem.Version $wgItem.Version) -gt 0) {
                $Map[$Key] = $locItem
                return
            }
        }
        $Map[$Key] = $wgItem
        return
    }

    $curIsSynthetic = ($cur.ID -match '^(ARP|MSIX|LOCAL)\\')
    $candIsSynthetic = ($Candidate.ID -match '^(ARP|MSIX|LOCAL)\\')
    if ($curIsSynthetic -ne $candIsSynthetic) {
        $synItem = if ($curIsSynthetic) { $cur } else { $Candidate }
        $realItem = if ($curIsSynthetic) { $Candidate } else { $cur }
        $hasSynNum = (-not [string]::IsNullOrWhiteSpace($synItem.Version) -and $synItem.Version -notmatch '^(Installed|Unknown)$' -and $synItem.Version -match '\d')
        $hasRealVerNum = (-not [string]::IsNullOrWhiteSpace($realItem.Version) -and $realItem.Version -notmatch '^(Installed|Unknown)$' -and $realItem.Version -match '\d')
        $hasRealAvailNum = (-not [string]::IsNullOrWhiteSpace($realItem.Available) -and $realItem.Available -notmatch '^(Installed|Unknown)$' -and $realItem.Available -match '\d')
        if ($hasSynNum) {
            if ($realItem.HasUpdate -and $hasRealAvailNum) {
                $Map[$Key] = if (Test-VersionAtLeastAvailable -InstalledVer $synItem.Version -WgVer $realItem.Version -WgAvail $realItem.Available) { $synItem } else { $realItem }
                return
            }
            if (-not $hasRealVerNum -or (Compare-AppVersions $synItem.Version $realItem.Version) -gt 0) {
                $Map[$Key] = $synItem
                return
            }
        }
        $Map[$Key] = $realItem
        return
    }

    $verCmp = Compare-AppVersions $Candidate.Version $cur.Version
    $bestVer = if ($verCmp -gt 0 -or [string]::IsNullOrWhiteSpace($cur.Version)) { $Candidate.Version } else { $cur.Version }

    $availCmp = Compare-AppVersions $Candidate.Available $cur.Available
    $bestAvail = if ($availCmp -gt 0) { $Candidate.Available } else { $cur.Available }

    $mergedHasUpdate = Test-AppUpdateGenuine -InstalledVer $bestVer -AvailableVer $bestAvail
    if (-not $mergedHasUpdate) { $bestAvail = "" }

    $useCandIdentity = (-not $cur.HasUpdate -and $Candidate.HasUpdate) -or ($verCmp -gt 0)
    $baseObj = if ($useCandIdentity) { $Candidate } else { $cur }
    $Map[$Key] = [PSCustomObject]@{
        Name      = $baseObj.Name
        ID        = $baseObj.ID
        Version   = $bestVer
        Available = $bestAvail
        HasUpdate = $mergedHasUpdate
        CleanName = $baseObj.CleanName
        Source    = $baseObj.Source
    }
}

function Get-TargetAppMeta {
    param($TargetApp)
    $tId = [string]$TargetApp.ID
    $meta = $null
    if ($script:targetAppMetaCache.TryGetValue($tId, [ref]$meta)) {
        return $meta
    }

    $tName = [string]$TargetApp.Name
    $hasCsClean = ($null -ne ("DuckUtil.AppCatalogEngine" -as [type]))
    $cleanTarget = ""
    if (-not [string]::IsNullOrWhiteSpace($tName)) {
        if (-not $script:cleanNameCache.TryGetValue($tName, [ref]$cleanTarget)) {
            $cleanTarget = if ($hasCsClean) { [DuckUtil.AppCatalogEngine]::CleanCatalogAppName($tName) } else { Get-CleanAppName $tName }
            $script:cleanNameCache[$tName] = $cleanTarget
        }
    }
    $aliasEntries = [System.Collections.Generic.List[hashtable]]::new()
    $cleanAliases = [System.Collections.Generic.List[hashtable]]::new()
    $queryTokens  = [System.Collections.Generic.List[string]]::new()
    $seenTokens   = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

    if ($cleanTarget.Length -ge 4) {
        foreach ($qt in ([System.Text.RegularExpressions.Regex]::Split($cleanTarget, '[^a-zA-Z0-9+]+'))) {
            if ($qt.Length -ge 3 -and (-not $script:stopWordSet.Contains($qt)) -and $seenTokens.Add($qt)) {
                $queryTokens.Add($qt)
            }
        }
    }

    if ($TargetApp.Aliases) {
        foreach ($alias in $TargetApp.Aliases) {
            if ([string]::IsNullOrWhiteSpace($alias)) { continue }
            $cAl = ""
            if (-not $script:cleanNameCache.TryGetValue($alias, [ref]$cAl)) {
                $cAl = if ($hasCsClean) { [DuckUtil.AppCatalogEngine]::CleanCatalogAppName($alias) } else { Get-CleanAppName $alias }
                $script:cleanNameCache[$alias] = $cAl
            }
            $cleanAliases.Add(@{ Raw = $alias; Clean = $cAl })
            if ($alias.Length -ge 4) {
                $aliasEntries.Add(@{
                    Raw     = $alias
                    Pattern = "(?<![a-zA-Z0-9])" + [System.Text.RegularExpressions.Regex]::Escape($alias) + "(?![a-zA-Z0-9])"
                })
                foreach ($qt in ([System.Text.RegularExpressions.Regex]::Split($alias, '[^a-zA-Z0-9+]+'))) {
                    if ($qt.Length -ge 3 -and (-not $script:stopWordSet.Contains($qt)) -and $seenTokens.Add($qt)) {
                        $queryTokens.Add($qt)
                    }
                }
            }
        }
    }

    $patternClean = if ($cleanTarget.Length -ge 4) {
        "(?<![a-zA-Z0-9])" + [System.Text.RegularExpressions.Regex]::Escape($cleanTarget) + "(?![a-zA-Z0-9])"
    } else { "" }

    $reqPy = ""
    if ($tId -match '^Python\.Python\.(\d+\.\d+)$') {
        $reqPy = [regex]::Escape($Matches[1])
    }
    $reqJava = ""
    if ($tId -match '\.(Temurin|Corretto)\.(\d+)\.') {
        $reqJava = $Matches[2]
    }
    $reqDnRaw = ""
    $reqDnEsc = ""
    if ($tId -match '^Microsoft\.DotNet\.DesktopRuntime\.(\d+(?:_\d+)?)(?:\.|$)') {
        $reqDnRaw = $Matches[1]
        $reqDnEsc = $Matches[1].Replace('_', '\.')
    }
    $reqYear = ""
    if ($tId -match '^Microsoft\.VCRedist\.(\d{4})\.') {
        $reqYear = $Matches[1]
    }

    $tNameNoParens = ([regex]::Replace($tName, '(?i)\((?!x64|x86|arm64).*?\)', '')).Trim()
    $aliasIdSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    if (-not [string]::IsNullOrWhiteSpace($tId)) { [void]$aliasIdSet.Add($tId) }
    if ($TargetApp.Aliases) {
        foreach ($al in $TargetApp.Aliases) {
            if (-not [string]::IsNullOrWhiteSpace($al)) { [void]$aliasIdSet.Add($al) }
        }
    }
    $tIdSegs = if ($tId) { $tId.Split('.') } else { @() }
    $pubPref = if ($tIdSegs.Count -ge 2) { $tIdSegs[0] } else { "" }
    $secSeg  = if ($tIdSegs.Count -ge 2) { $tIdSegs[1] } else { "" }
    $hasThreePlus = ($tIdSegs.Count -ge 3)

    $tArch = if ($tName -match '\(x64\)|\.x64' -or $tId -match '\.x64$') { "x64" }
             elseif ($tName -match '\(x86\)|\.x86' -or $tId -match '\.x86$') { "x86" }
             elseif ($tName -match '\(arm64\)|\.arm64' -or $tId -match '\.arm64$') { "arm64" }
             elseif ([Environment]::Is64BitOperatingSystem -and $TargetApp.Category -eq '.NET Runtimes' -and $tId -match 'DesktopRuntime') { "x64" }
             else { "" }

    $meta = [PSCustomObject]@{
        ID                  = $tId
        Name                = $tName
        CleanTarget         = $cleanTarget
        CleanAliases        = $cleanAliases
        AliasEntries        = $aliasEntries
        AliasIdSet          = $aliasIdSet
        PublisherPrefix     = $pubPref
        SecondSegment       = $secSeg
        HasThreePlusIdParts = $hasThreePlus
        PatternClean        = $patternClean
        QueryTokens         = $queryTokens
        AllowNoise          = ($tName -match '(?i)(Maintenance|Control Panel|Context Menu|AddOn|Installer|Agent)')
        IsPrev              = (($tNameNoParens -match '(?i)Preview') -or ($tId -match '(?i)Preview'))
        IsBeta              = (($tNameNoParens -match '(?i)\bBeta\b') -or ($tId -match '(?i)\.Beta(?:\.|$)'))
        IsCanary            = (($tNameNoParens -match '(?i)\bCanary\b') -or ($tId -match '(?i)\.Canary(?:\.|$)'))
        IsDevChannel        = (($tNameNoParens -match '(?i)\b(?:Dev|Developer\s*Edition)\b') -or ($tId -match '(?i)\.(?:Dev|DeveloperEdition)(?:\.|$)'))
        IsNightly           = (($tNameNoParens -match '(?i)\bNightly\b') -or ($tId -match '(?i)\.Nightly(?:\.|$)'))
        IsAlpha             = (($tNameNoParens -match '(?i)\bAlpha\b') -or ($tId -match '(?i)\.Alpha(?:\.|$)'))
        IsPtb               = (($tNameNoParens -match '(?i)\bPTB\b') -or ($tId -match '(?i)\.PTB(?:\.|$)'))
        IsEsr               = (($tNameNoParens -match '(?i)\bESR\b') -or ($tId -match '(?i)\.ESR(?:\.|$)'))
        IsInsiders          = (($tNameNoParens -match '(?i)\bInsiders?\b') -or ($tId -match '(?i)\.Insiders?(?:\.|$)'))
        IsVcRedist          = (($tId -match 'VCRedist') -or ($tName -match 'VC\+\+'))
        IsComm              = (($tNameNoParens -match '\bCommunity\b') -or ($tId -match '\.Community\b'))
        IsPro               = (($tNameNoParens -match '\b(Ultimate|Professional)\b') -or ($tId -match '\.(Ultimate|Professional)\b'))
        IsIde               = (($tNameNoParens -match '\bIDE\b') -or ($tId -match 'IDE$'))
        IsAntigravity       = ($tId -match 'Antigravity')
        IsCli               = (($tNameNoParens -match '\bCLI\b') -or ($tId -match '(\.cli|CLI)$'))
        IsBt                = (($tNameNoParens -match '(?i)Build Tools') -or ($tId -match '(?i)BuildTools'))
        IsVsc               = (($tId -match 'VisualStudioCode') -or ($tNameNoParens -match 'VS Code|Visual Studio Code'))
        IsVsAny             = ($tId -match 'VisualStudio')
        IsEtb               = (($tId -match 'EverythingToolbar') -or ($tName -match 'EverythingToolbar'))
        IsTemurin           = ($tId -match 'Temurin')
        IsOracleJava        = ($tId -match 'Oracle\.Java')
        IsCorretto          = ($tId -match 'Corretto')
        IsJdk               = (($tNameNoParens -match '\bJDK\b') -or ($tId -match '\.JDK$'))
        IsJre               = (($tNameNoParens -match '\bJRE\b') -or ($tId -match '\.(JRE|JavaRuntimeEnvironment)$'))
        ReqPy               = $reqPy
        ReqJava             = $reqJava
        ReqDnRaw            = $reqDnRaw
        ReqDnEsc            = $reqDnEsc
        ReqYear             = $reqYear
        Arch                = $tArch
    }
    $script:targetAppMetaCache[$tId] = $meta
    return $meta
}

function Test-MatchCompatible {
    param($TargetApp, $Item)
    if (-not $TargetApp -or -not $Item) { return $false }

    $meta          = Get-TargetAppMeta $TargetApp
    $tId           = $meta.ID
    $iName         = [string]$Item.Name
    $iNameNoParens = ([regex]::Replace($iName, '(?i)\((?!x64|x86|arm64).*?\)', '')).Trim()
    $iId           = [string]$Item.ID

    if (-not $meta.AllowNoise) {
        if ($iName -match '(?i)(Maintenance Service|Control Panels|Context Menu|SparseApp|SDK AddOn|CoreEditorFonts|Visual Studio Installer|Development Libraries|Standard Library|Test Suite|Tcl/Tk Support|pip Bootstrap)' -or
            $iId   -match '(?i)(MozillaMaintenanceService|ContextMenu|SparseApp|FigmaAgent)') {
            return $false
        }
    }

    if ($iId -eq 'Python.Launcher' -or $iName -match '^Python Launcher\b') {
        if ($tId -ne 'Python.Launcher') { return $false }
    }

    $iPrev = ($iNameNoParens.IndexOf('Preview', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) -or ($iId.IndexOf('Preview', [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
    if ($meta.IsPrev -ne $iPrev -and $tId -ne 'Microsoft.PowerToys') { return $false }

    if ($meta.IsBeta       -ne (($iNameNoParens -match '(?i)\bBeta\b') -or ($iId -match '(?i)\.Beta(?:\.|$)'))) { return $false }
    if ($meta.IsCanary     -ne (($iNameNoParens -match '(?i)\bCanary\b') -or ($iId -match '(?i)\.Canary(?:\.|$)'))) { return $false }
    if ($meta.IsDevChannel -ne (($iNameNoParens -match '(?i)\b(?:Dev|Developer\s*Edition)\b') -or ($iId -match '(?i)\.(?:Dev|DeveloperEdition)(?:\.|$)'))) { return $false }
    if ($meta.IsNightly    -ne (($iNameNoParens -match '(?i)\bNightly\b') -or ($iId -match '(?i)\.Nightly(?:\.|$)'))) { return $false }
    if ($meta.IsAlpha      -ne (($iNameNoParens -match '(?i)\bAlpha\b') -or ($iId -match '(?i)\.Alpha(?:\.|$)'))) { return $false }
    if ($meta.IsPtb        -ne (($iNameNoParens -match '(?i)\bPTB\b') -or ($iId -match '(?i)\.PTB(?:\.|$)'))) { return $false }
    if ($meta.IsEsr        -ne (($iNameNoParens -match '(?i)\bESR\b') -or ($iId -match '(?i)\.ESR(?:\.|$)'))) { return $false }
    if ($meta.IsInsiders   -ne (($iNameNoParens -match '(?i)\bInsiders?\b') -or ($iId -match '(?i)\.Insiders?(?:\.|$)'))) { return $false }

    if ($iId -notmatch '^(?i)(ARP|MSIX|LOCAL)\\' -and -not $meta.AliasIdSet.Contains($iId) -and -not $iId.StartsWith($tId + ".", [System.StringComparison]::OrdinalIgnoreCase)) {
        if ($tId.Equals('OpenJS.NodeJS.LTS', [System.StringComparison]::OrdinalIgnoreCase) -and $iId.StartsWith('OpenJS.NodeJS', [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
        if ($meta.PublisherPrefix.Length -ge 3 -and $iId.StartsWith($meta.PublisherPrefix + ".", [System.StringComparison]::OrdinalIgnoreCase)) {
            $iSegs = $iId.Split('.')
            if ($iSegs.Count -ge 2) {
                if (-not $iSegs[1].Equals($meta.SecondSegment, [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
                if ($meta.HasThreePlusIdParts) { return $false }
            }
        }
    }

    if ($meta.IsVcRedist -and ($iName -match '\bUWP\b' -or $iId -match 'VCLibs')) {
        return $false
    }

    if ($meta.IsComm -or $meta.IsPro) {
        $iComm = ($iName -match '\bCommunity\b') -or ($iId -match '\.Community\b')
        $iPro  = ($iName -match '\b(Ultimate|Professional)\b') -or ($iId -match '\.(Ultimate|Professional)\b')
        if (($meta.IsComm -and $iPro) -or ($meta.IsPro -and $iComm)) { return $false }
    }

    if ($meta.IsAntigravity -or $iId.IndexOf('Antigravity', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
        $iIde = ($iName -match '\bIDE\b') -or ($iId -match 'IDE$')
        if ($meta.IsIde -ne $iIde) { return $false }
    }

    $iCli = ($iName -match '\bCLI\b') -or ($iId -match '(\.cli|CLI)$')
    if ($meta.IsCli -ne $iCli) { return $false }

    $iBt = ($iName.IndexOf('Build Tools', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) -or ($iId.IndexOf('BuildTools', [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
    if ($meta.IsBt -ne $iBt) { return $false }

    if ($meta.IsVsAny -or $iId.IndexOf('VisualStudio', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
        $iVsc = ($iId -match 'VisualStudioCode') -or ($iName -match 'VS Code|Visual Studio Code')
        if ($meta.IsVsc -ne $iVsc) { return $false }
    }

    $iEtb = ($iId.IndexOf('EverythingToolbar', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) -or ($iName.IndexOf('EverythingToolbar', [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
    if ($meta.IsEtb -ne $iEtb) { return $false }

    if ($meta.IsTemurin -and ($iId -match 'Oracle|Corretto' -or $iName -match 'Corretto|^Java \d+ Update')) { return $false }
    if ($meta.IsOracleJava -and ($iId -match 'Temurin|Corretto' -or $iName -match 'Temurin|Corretto')) { return $false }
    if ($meta.IsCorretto -and ($iId -match 'Temurin|Oracle' -or $iName -match 'Temurin|^Java \d+ Update')) { return $false }

    if ($meta.IsJdk -or $meta.IsJre) {
        $iJdk = ($iName -match '\bJDK\b') -or ($iId -match '\.JDK$')
        $iJre = ($iName -match '\bJRE\b|^Java \d+ Update') -or ($iId -match '\.(JRE|JavaRuntimeEnvironment)$')
        if (($meta.IsJdk -and $iJre -and -not $iJdk) -or ($meta.IsJre -and $iJdk -and -not $iJre)) { return $false }
    }

    if ($meta.ReqPy) {
        $reqPy = $meta.ReqPy
        if ($iId -notmatch $reqPy -and $iName -notmatch $reqPy -and [string]$Item.Version -notmatch "^$reqPy(\.|$)") {
            return $false
        }
    }

    if ($meta.ReqJava) {
        $reqJava = $meta.ReqJava
        if ($iId -notmatch "\b$reqJava\b" -and $iName -notmatch "\b$reqJava\b" -and [string]$Item.Version -notmatch "^$reqJava(\.|$)") {
            return $false
        }
    }

    if ($meta.ReqDnRaw) {
        if ($iId -notmatch 'DesktopRuntime' -and $iName -notmatch '(?i)Desktop') {
            return $false
        }
        $reqDn = $meta.ReqDnEsc
        if ($iId -notmatch "DesktopRuntime\.$($meta.ReqDnRaw)(\.|$)" -and $iName -notmatch "\b$reqDn(\.\d+|\b)" -and [string]$Item.Version -notmatch "^$reqDn(\.|$)") {
            return $false
        }
    }

    if ($meta.ReqYear) {
        if ($iId.IndexOf($meta.ReqYear, [System.StringComparison]::OrdinalIgnoreCase) -lt 0 -and $iName.IndexOf($meta.ReqYear, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) {
            return $false
        }
    }

    if ($meta.Arch) {
        $idForArch = if ($iId -match '^(ARP|MSIX|LOCAL)\\') { "" } else { $iId }
        $iArch = if ($iName -match '(?<![a-zA-Z0-9])(x64|64-bit)(?![a-zA-Z0-9])' -or $idForArch -match '\.x64$') { "x64" }
                 elseif ($iName -match '(?<![a-zA-Z0-9])(x86|32-bit)(?![a-zA-Z0-9])' -or $idForArch -match '\.x86$') { "x86" }
                 elseif ($iName -match '(?<![a-zA-Z0-9])arm64(?![a-zA-Z0-9])' -or $idForArch -match '\.arm64$') { "arm64" }
                 else { "" }
        if ($iArch -and $iArch -ne $meta.Arch) { return $false }
    }

    return $true
}

$script:isScanningApps         = $false
$script:isAutoRefreshing       = $false
$script:cancelAutoScan         = $false
$script:pendingManualAppRefresh = $false
$script:autoScanGeneration     = 0
$script:activeAutoScanGen      = 0
$script:hasCompletedAppScan    = $false
$script:lastAppScanSignature   = ""
$script:lastLocalScanSig       = ""
$script:lastLocalInstalledCnt  = -1
$script:autoScanWingetProcess  = $null

function Stop-ActiveAutoScan {
    $script:autoScanGeneration++
    $script:cancelAutoScan = $true
    $pAuto = $script:autoScanWingetProcess
    $script:autoScanWingetProcess = $null
    if ($null -ne $pAuto) {
        try {
            $hasEx = try { $pAuto.HasExited } catch { $true }
            if (-not $hasEx) { $pAuto.Kill() }
        } catch {}
        try { $pAuto.Dispose() } catch {}
    }
}

function Stop-PreSpawnedWinget {
    $job = $script:preSpawnedWinget
    $script:preSpawnedWinget = $null
    if ($null -ne $job -and $null -ne $job.Process) {
        try {
            $hasExited = try { $job.Process.HasExited } catch { $true }
            if (-not $hasExited) { $job.Process.Kill() }
        } catch {}
        try { $job.Process.Dispose() } catch {}
    }
}

function Start-WingetBackgroundPreScan {
    if ($script:isWindowClosing -or $null -ne $script:preSpawnedWinget) { return }
    try {
        if (-not (Get-Command "winget" -ErrorAction SilentlyContinue)) { return }
        $pinfo = New-Object System.Diagnostics.ProcessStartInfo
        $pinfo.FileName = "winget"
        $pinfo.Arguments = "list --source winget --disable-interactivity --accept-source-agreements"
        $pinfo.RedirectStandardOutput = $true
        $pinfo.RedirectStandardError = $true
        $pinfo.StandardOutputEncoding = [System.Text.Encoding]::UTF8
        $pinfo.StandardErrorEncoding = [System.Text.Encoding]::UTF8
        $pinfo.UseShellExecute = $false
        $pinfo.CreateNoWindow = $true
        $p = [System.Diagnostics.Process]::Start($pinfo)
        if ($null -ne $p) {
            $script:preSpawnedWinget = [PSCustomObject]@{
                Process   = $p
                ReadTask  = $p.StandardOutput.ReadToEndAsync()
                ErrTask   = $p.StandardError.ReadToEndAsync()
                Stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
                Arguments = "list --source winget --disable-interactivity --accept-source-agreements"
            }
        }
    } catch {
        $script:preSpawnedWinget = $null
    }
}

function Invoke-WingetListCapture {
    param(
        [string]$Arguments = "list --disable-interactivity --accept-source-agreements",
        [int]$TimeoutSeconds = 35,
        [scriptblock]$CancelCheck = $null,
        [switch]$TrackAsAuto
    )

    $isCanceledNow = $script:isWindowClosing
    if (-not $isCanceledNow -and $CancelCheck) {
        try { $isCanceledNow = [bool](& $CancelCheck) } catch {}
    }
    if ($isCanceledNow) {
        Stop-PreSpawnedWinget
        return [PSCustomObject]@{
            Available   = $true
            TimedOut    = $true
            WasCanceled = $true
            ExitCode    = -1
            StdOut      = ""
            StdErr      = ""
        }
    }

    $p = $null
    $readTask = $null
    $errTask = $null
    $sw = $null
    $rawList = ""
    $errList = ""
    $timedOut = $false
    $wasCanceled = $false
    $exitCode = -1

    try {
        $canUsePreSpawned = (-not $TrackAsAuto -and -not $script:hasCompletedAppScan -and $null -ne $script:preSpawnedWinget -and $script:preSpawnedWinget.Arguments -eq $Arguments -and $script:preSpawnedWinget.Stopwatch.Elapsed.TotalSeconds -lt 30)
        if ($canUsePreSpawned) {
            $job = $script:preSpawnedWinget
            $script:preSpawnedWinget = $null
            $p = $job.Process
            $readTask = $job.ReadTask
            $errTask = $job.ErrTask
            $sw = $job.Stopwatch
        } else {
            if (-not $TrackAsAuto -and $null -ne $script:preSpawnedWinget) {
                Stop-PreSpawnedWinget
            }
            if (-not (Get-Command "winget" -ErrorAction SilentlyContinue)) {
                return [PSCustomObject]@{
                    Available   = $false
                    TimedOut    = $false
                    WasCanceled = $false
                    ExitCode    = -1
                    StdOut      = ""
                    StdErr      = ""
                }
            }

            $pinfo = New-Object System.Diagnostics.ProcessStartInfo
            $pinfo.FileName = "winget"
            $pinfo.Arguments = $Arguments
            $pinfo.RedirectStandardOutput = $true
            $pinfo.RedirectStandardError = $true
            $pinfo.StandardOutputEncoding = [System.Text.Encoding]::UTF8
            $pinfo.StandardErrorEncoding = [System.Text.Encoding]::UTF8
            $pinfo.UseShellExecute = $false
            $pinfo.CreateNoWindow = $true

            $p = [System.Diagnostics.Process]::Start($pinfo)
            if ($null -eq $p) {
                throw "Kh$([char]0x00F4)ng th$([char]0x1EC3) kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng ti$([char]0x1EBF)n tr$([char]0x00EC)nh winget."
            }
            if ($TrackAsAuto) {
                $script:autoScanWingetProcess = $p
            }
            $readTask = $p.StandardOutput.ReadToEndAsync()
            $errTask  = $p.StandardError.ReadToEndAsync()
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
        }

        if ((Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) -and $null -ne $readTask -and $null -ne $errTask) {
            $bothTask = [System.Threading.Tasks.Task]::WhenAll([System.Threading.Tasks.Task[]](@($readTask, $errTask)))
            $remSec = [Math]::Max(0.1, ($TimeoutSeconds - $sw.Elapsed.TotalSeconds))
            $completedOk = Wait-TaskNonBlocking -Task $bothTask -TimeoutSeconds $remSec -CancelCheck $CancelCheck
            $cancelHit = $script:isWindowClosing
            if (-not $cancelHit -and $CancelCheck) {
                try { $cancelHit = [bool](& $CancelCheck) } catch {}
            }
            if ($cancelHit) {
                $wasCanceled = $true
                $timedOut = $true
                try { if ($null -ne $p -and -not $p.HasExited) { $p.Kill() } } catch {}
            } elseif (-not $completedOk -or -not $readTask.IsCompleted -or -not $errTask.IsCompleted) {
                $timedOut = $true
                try { if ($null -ne $p -and -not $p.HasExited) { $p.Kill() } } catch {}
            }
        } else {
            while (-not $readTask.IsCompleted -or -not $errTask.IsCompleted) {
                $cancelHit = $script:isWindowClosing
                if (-not $cancelHit -and $CancelCheck) {
                    try { $cancelHit = [bool](& $CancelCheck) } catch {}
                }
                if ($cancelHit -or $sw.Elapsed.TotalSeconds -gt $TimeoutSeconds) {
                    $wasCanceled = $cancelHit
                    $timedOut = $true
                    try { if ($null -ne $p -and -not $p.HasExited) { $p.Kill() } } catch {}
                    break
                }
                try { [System.Windows.Forms.Application]::DoEvents() } catch {}
                Start-Sleep -Milliseconds 15
            }
        }

        if (-not $script:isWindowClosing -and -not $wasCanceled -and -not $timedOut -and $null -ne $p) {
            try {
                if (-not $p.HasExited) {
                    $deepTypeWg = "DuckUtil.DeepUninstallerEngine" -as [type]
                    if ($deepTypeWg -and $null -ne $deepTypeWg.GetMethod("WaitForProcessExitAsync") -and (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue)) {
                        $exitWaitTask = $deepTypeWg::WaitForProcessExitAsync($p)
                        [void](Wait-TaskNonBlocking -Task $exitWaitTask -TimeoutSeconds 5 -CancelCheck $CancelCheck)
                    } else {
                        $p.WaitForExit(5000) | Out-Null
                    }
                }
            } catch {}
        }
        if (-not $wasCanceled) {
            if ($null -ne $readTask -and $readTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                $rawList = $readTask.Result
            }
            if ($null -ne $errTask -and $errTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                $errList = $errTask.Result
            }
            $hasExited = try { $null -ne $p -and $p.HasExited } catch { $false }
            if ($hasExited) {
                $exitCode = try { $p.ExitCode } catch { -1 }
            }
        }
    } finally {
        if ($TrackAsAuto -and $script:autoScanWingetProcess -eq $p) {
            $script:autoScanWingetProcess = $null
        }
        if ($null -ne $p) {
            try { $p.Dispose() } catch {}
        }
    }

    return [PSCustomObject]@{
        Available   = $true
        TimedOut    = $timedOut
        WasCanceled = $wasCanceled
        ExitCode    = $exitCode
        StdOut      = $rawList
        StdErr      = $errList
    }
}

function ConvertFrom-WingetListOutput {
    param(
        [string]$RawText,
        [bool]$AllowHeaderless = $false
    )

    if ([string]::IsNullOrWhiteSpace($RawText)) {
        return [PSCustomObject]@{ HasTable = $false; Items = [System.Collections.Generic.List[object]]::new() }
    }

    if ("DuckUtil.AppCatalogEngine" -as [type]) {
        $hasTable = $false
        $items = [DuckUtil.AppCatalogEngine]::ParseWingetListOutput($RawText, $AllowHeaderless, [ref]$hasTable)
        return [PSCustomObject]@{ HasTable = $hasTable; Items = $items }
    }

    $parsed = [System.Collections.Generic.List[object]]::new()

    $rawLines = $RawText -split "`n"
    $lines = [System.Collections.Generic.List[string]]::new($rawLines.Count)
    foreach ($rl in $rawLines) {
        $cleanLine = $rl.TrimEnd("`r")
        if ($cleanLine.Contains("`r")) { $cleanLine = ($cleanLine -split "`r")[-1] }
        if ($cleanLine.Contains([char]0x1B)) {
            $cleanLine = [System.Text.RegularExpressions.Regex]::Replace($cleanLine, '\x1B\[[0-9;?]*[A-Za-z]', '')
        }
        $lines.Add($cleanLine)
    }

    $separatorIndex = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -match '^\s*-{10,}') {
            $separatorIndex = $i
            break
        }
    }

    if ($separatorIndex -gt 0) {
        $separatorLine = $lines[$separatorIndex]
        $headerLine    = $lines[$separatorIndex - 1]
        $knownHdrTokens = [System.Collections.Generic.HashSet[string]]::new([string[]]@("Name", "Id", "Version", "Available", "Source", "Match", "Tag", "Command", "Moniker"), [System.StringComparer]::OrdinalIgnoreCase)

        $colOffsets = @()
        if ($separatorLine -match '---+\s+---+') {
            $dashMatches = [System.Text.RegularExpressions.Regex]::Matches($separatorLine, '-+')
            foreach ($dm in $dashMatches) { $colOffsets += $dm.Index }
        } elseif ($headerLine) {
            $singleTokens = [System.Text.RegularExpressions.Regex]::Matches($headerLine, '\S+')
            $allKnown = ($singleTokens.Count -ge 3)
            if ($allKnown) {
                foreach ($st in $singleTokens) {
                    if (-not $knownHdrTokens.Contains($st.Value)) { $allKnown = $false; break }
                }
            }
            if ($allKnown) {
                foreach ($st in $singleTokens) { $colOffsets += (Get-StringDisplayWidth -Text $headerLine -EndIndex $st.Index) }
            } else {
                $groupedMatches = [System.Text.RegularExpressions.Regex]::Matches($headerLine, '\S+(?:\s\S+)*')
                foreach ($gm in $groupedMatches) {
                    $subTokens = [System.Text.RegularExpressions.Regex]::Matches($gm.Value, '\S+')
                    for ($k = 0; $k -lt $subTokens.Count; $k++) {
                        if ($k -eq 0 -or $knownHdrTokens.Contains($subTokens[$k].Value) -or $knownHdrTokens.Contains($subTokens[$k - 1].Value)) {
                            $colOffsets += (Get-StringDisplayWidth -Text $headerLine -EndIndex ($gm.Index + $subTokens[$k].Index))
                        }
                    }
                }
                if ($colOffsets.Count -lt 3 -and $singleTokens.Count -ge 3) {
                    $colOffsets = @()
                    foreach ($st in $singleTokens) { $colOffsets += (Get-StringDisplayWidth -Text $headerLine -EndIndex $st.Index) }
                }
            }
        }

        $idIdx    = if ($colOffsets.Count -ge 2) { $colOffsets[1] } else { -1 }
        $verIdx   = if ($colOffsets.Count -ge 3) { $colOffsets[2] } else { -1 }
        $availIdx = if ($colOffsets.Count -ge 4) { $colOffsets[3] } else { -1 }
        $srcIdx   = if ($colOffsets.Count -ge 5) { $colOffsets[4] } else { -1 }

        for ($j = $separatorIndex + 1; $j -lt $lines.Count; $j++) {
            $line = $lines[$j]
            if ([string]::IsNullOrWhiteSpace($line)) { continue }

            $appName = ""; $appId = ""; $version = ""; $avail = ""; $srcCol = ""

            if ($colOffsets.Count -ge 3) {
                if ($line -match '[^\x00-\x7F]') {
                    $sliced = Get-SliceByDisplayWidth -Line $line -Offsets $colOffsets
                    $appName = $sliced[0]; $appId = $sliced[1]; $version = $sliced[2]; $avail = $sliced[3]; $srcCol = $sliced[4]
                } else {
                    $sliced = Slice-WingetRowColumnsByPositions -Line $line -CId $idIdx -CVer $verIdx -CAvail $availIdx -CSrc $srcIdx
                    $appName = $sliced[0]; $appId = $sliced[1]; $version = $sliced[2]; $avail = $sliced[3]; $srcCol = $sliced[4]
                }
            }

            if ([string]::IsNullOrEmpty($appId) -or $appId.IndexOf(' ') -ge 0) {
                $tailCols = $null
                if (-not [string]::IsNullOrEmpty($appName) -and $colOffsets.Count -ge 3) {
                    $nameEnd = $line.IndexOf($appName, [System.StringComparison]::Ordinal)
                    $searchFrom = if ($nameEnd -ge 0) { $nameEnd + $appName.Length } else { 0 }
                    while ($searchFrom -lt $line.Length -and [char]::IsWhiteSpace($line[$searchFrom])) { $searchFrom++ }
                    if ($searchFrom -lt $line.Length) {
                        $tCols = [System.Text.RegularExpressions.Regex]::Split($line.Substring($searchFrom).Trim(), '\s{2,}')
                        if ($tCols.Count -ge 1 -and -not [string]::IsNullOrWhiteSpace($tCols[0])) {
                            $tailCols = $tCols
                        }
                    }
                }
                if ($null -ne $tailCols) {
                    $appId   = $tailCols[0].Trim()
                    $version = if ($tailCols.Count -ge 2) { $tailCols[1].Trim() } else { "" }
                    $c3      = if ($tailCols.Count -ge 3) { $tailCols[2].Trim() } else { "" }
                    $c4      = if ($tailCols.Count -ge 4) { $tailCols[3].Trim() } else { "" }
                    if ($c3 -match '^(?i)(winget|msstore)$' -and [string]::IsNullOrEmpty($c4)) {
                        $srcCol = $c3
                        $avail  = ""
                    } else {
                        $avail = $c3
                        if (-not [string]::IsNullOrEmpty($c4)) { $srcCol = $c4 }
                    }
                } else {
                    $cols = [System.Text.RegularExpressions.Regex]::Split($line.Trim(), '\s{2,}')
                    if ($cols.Count -ge 2) {
                        $appName = $cols[0].Trim()
                        $appId   = $cols[1].Trim()
                        $version = if ($cols.Count -ge 3) { $cols[2].Trim() } else { "" }
                        $c3      = if ($cols.Count -ge 4) { $cols[3].Trim() } else { "" }
                        $c4      = if ($cols.Count -ge 5) { $cols[4].Trim() } else { "" }
                        if ($c3 -match '^(?i)(winget|msstore)$' -and [string]::IsNullOrEmpty($c4)) {
                            $srcCol = $c3
                            $avail  = ""
                        } else {
                            $avail = $c3
                            if (-not [string]::IsNullOrEmpty($c4)) { $srcCol = $c4 }
                        }
                    }
                }
            }

            if (-not [string]::IsNullOrEmpty($appName) -and -not [string]::IsNullOrEmpty($appId)) {
                if ($appId.StartsWith("MSIX\NotepadPlusPlus_", [System.StringComparison]::OrdinalIgnoreCase)) { continue }
                if ($avail -match '^(?i)(winget|msstore)$') {
                    $srcCol = $avail
                    $avail  = ""
                }
                $hasUpdate = Test-AppUpdateGenuine -InstalledVer $version -AvailableVer $avail
                $clean = Get-CleanAppName $appName
                $rowSrc = if ($colOffsets.Count -lt 5 -and [string]::IsNullOrWhiteSpace($srcCol)) { "winget" } else { Resolve-WingetRowSource -AppId $appId -SrcCol $srcCol }
                $parsed.Add([PSCustomObject]@{
                    Name      = $appName
                    ID        = $appId
                    Version   = $version
                    Available = $(if ($hasUpdate) { $avail } else { "" })
                    HasUpdate = $hasUpdate
                    CleanName = $clean
                    Source    = $rowSrc
                })
            }
        }
    } elseif ($AllowHeaderless) {
        foreach ($line in $lines) {
            if (-not [string]::IsNullOrWhiteSpace($line) -and -not ($line.Trim().StartsWith("---"))) {
                $cols = [System.Text.RegularExpressions.Regex]::Split($line.Trim(), '\s{2,}')
                if ($cols.Count -ge 2) {
                    $appName = $cols[0].Trim()
                    $appId   = $cols[1].Trim()
                    if ($appId -notmatch '^(ARP|MSIX)\\|\S+\.\S+') { continue }
                    if ($appId.StartsWith("MSIX\NotepadPlusPlus_", [System.StringComparison]::OrdinalIgnoreCase)) { continue }
                    $version = if ($cols.Count -ge 3) { $cols[2].Trim() } else { "" }
                    $c3      = if ($cols.Count -ge 4) { $cols[3].Trim() } else { "" }
                    $c4      = if ($cols.Count -ge 5) { $cols[4].Trim() } else { "" }
                    $srcCol  = ""
                    $avail   = ""
                    if ($c3 -match '^(?i)(winget|msstore)$' -and [string]::IsNullOrEmpty($c4)) {
                        $srcCol = $c3
                    } else {
                        $avail = $c3
                        if (-not [string]::IsNullOrEmpty($c4)) { $srcCol = $c4 }
                    }
                    $hasUpdate = Test-AppUpdateGenuine -InstalledVer $version -AvailableVer $avail
                    $clean = Get-CleanAppName $appName
                    $rowSrc = Resolve-WingetRowSource -AppId $appId -SrcCol $srcCol

                    $parsed.Add([PSCustomObject]@{
                        Name      = $appName
                        ID        = $appId
                        Version   = $version
                        Available = $(if ($hasUpdate) { $avail } else { "" })
                        HasUpdate = $hasUpdate
                        CleanName = $clean
                        Source    = $rowSrc
                    })
                }
            }
        }
    }

    return [PSCustomObject]@{ HasTable = ($separatorIndex -gt 0); Items = $parsed }
}

function Test-RegistryEntryIsBrokenOrphan {
    param([string]$UninstallString, [string]$InstallLocation, [string]$DisplayIcon)
    if (-not [string]::IsNullOrWhiteSpace($InstallLocation)) {
        $loc = $InstallLocation.Trim().Trim('"')
        if ($loc.Length -ge 3 -and $loc -match '^[a-zA-Z]:\\') {
            if (-not [System.IO.Directory]::Exists($loc)) {
                return $true
            }
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($UninstallString) -and $UninstallString -notmatch '(?i)msiexec') {
        $u = $UninstallString.Trim()
        $exePath = ""
        if ($u.StartsWith('"')) {
            $q = $u.IndexOf('"', 1)
            if ($q -gt 1) { $exePath = $u.Substring(1, $q - 1) }
        } elseif ($u -match '(?i)^([a-zA-Z]:\\[^"]*?\.exe)\b') {
            $exePath = $Matches[1]
        }
        if (-not [string]::IsNullOrWhiteSpace($exePath) -and $exePath -match '^[a-zA-Z]:\\') {
            if (-not [System.IO.File]::Exists($exePath)) {
                return $true
            }
        }
    }
    return $false
}

function Get-ExecutableCleanVersion {
    param([string]$FilePath)
    if ([string]::IsNullOrWhiteSpace($FilePath) -or -not [System.IO.File]::Exists($FilePath)) { return "Installed" }
    try {
        $fvi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($FilePath)
        foreach ($cand in @($fvi.ProductVersion, $fvi.FileVersion)) {
            if (-not [string]::IsNullOrWhiteSpace($cand)) {
                $clean = ($cand -split '\+')[0].Trim()
                if ($clean -match '\d' -and $clean -notmatch '^0(\.0)+$') {
                    return $clean
                }
            }
        }
    } catch {}
    return "Installed"
}

function Get-LocalInstalledEntries {
    param(
        [switch]$SkipAppx,
        [scriptblock]$CancelCheck = $null
    )
    if ("DuckUtil.AppCatalogEngine" -as [type]) {
        try {
            $csType = [DuckUtil.AppCatalogEngine]
            if ($null -ne $csType.GetMethod("ScanCatalogSensorsAsync") -and (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue)) {
                $scanTask = $csType::ScanCatalogSensorsAsync()
                if (Wait-TaskNonBlocking -Task $scanTask -TimeoutSeconds 30 -CancelCheck $CancelCheck) {
                    if ($scanTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                        return $scanTask.Result
                    }
                }
                $canceledNow = $script:isWindowClosing
                if (-not $canceledNow -and $CancelCheck) { try { $canceledNow = [bool](& $CancelCheck) } catch {} }
                if ($canceledNow) { return @() }
            }
            return [DuckUtil.AppCatalogEngine]::ScanCatalogSensors()
        } catch {}
    }

    $localItems = [System.Collections.Generic.List[object]]::new()
    $regConfigs = @(
        @{ Hive = [Microsoft.Win32.Registry]::LocalMachine; SubKey = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall';             Prefix = 'ARP\Machine\X64\' },
        @{ Hive = [Microsoft.Win32.Registry]::LocalMachine; SubKey = 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'; Prefix = 'ARP\Machine\X86\' },
        @{ Hive = [Microsoft.Win32.Registry]::CurrentUser;  SubKey = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall';             Prefix = 'ARP\User\X64\' },
        @{ Hive = [Microsoft.Win32.Registry]::CurrentUser;  SubKey = 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'; Prefix = 'ARP\User\X86\' }
    )

    foreach ($cfg in $regConfigs) {
        $baseKey = $null
        try {
            $baseKey = $cfg.Hive.OpenSubKey($cfg.SubKey, $false)
            if ($null -eq $baseKey) { continue }
            foreach ($subName in $baseKey.GetSubKeyNames()) {
                $subKey = $null
                try {
                    $subKey = $baseKey.OpenSubKey($subName, $false)
                    if ($null -eq $subKey) { continue }
                    $dispName = [string]$subKey.GetValue('DisplayName', '')
                    if ([string]::IsNullOrWhiteSpace($dispName)) { continue }
                    $sysComp = $subKey.GetValue('SystemComponent', 0)
                    if ($sysComp -eq 1) { continue }
                    $relType = [string]$subKey.GetValue('ReleaseType', '')
                    if (-not [string]::IsNullOrWhiteSpace($relType) -and $relType -match '(?i)Update|Hotfix') { continue }
                    if ($dispName -match 'Additional Runtime|Minimum Runtime|Debug Runtime|IntelliSense|Language Pack') { continue }

                    $uninstStr  = [string]$subKey.GetValue('UninstallString', '')
                    $installLoc = [string]$subKey.GetValue('InstallLocation', '')
                    $dispIcon   = [string]$subKey.GetValue('DisplayIcon', '')
                    if (Test-RegistryEntryIsBrokenOrphan -UninstallString $uninstStr -InstallLocation $installLoc -DisplayIcon $dispIcon) {
                        continue
                    }

                    $dispVer = [string]$subKey.GetValue('DisplayVersion', '')
                    $localItems.Add([PSCustomObject]@{
                        Name      = $dispName.Trim()
                        ID        = ($cfg.Prefix + $subName)
                        Version   = $dispVer
                        Available = ""
                        HasUpdate = $false
                        CleanName = (Get-CleanAppName $dispName)
                        Source    = "local"
                    })
                } catch {} finally {
                    if ($null -ne $subKey) { $subKey.Dispose() }
                }
            }
        } catch {} finally {
            if ($null -ne $baseKey) { $baseKey.Dispose() }
        }
    }

    try {
        $ndpKey = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full', $false)
        if ($ndpKey) {
            try {
                $release = [int]$ndpKey.GetValue('Release', 0)
                $ndpVer  = [string]$ndpKey.GetValue('Version', '4.8.1')
                if ($release -ge 533320) {
                    $localItems.Add([PSCustomObject]@{
                        Name      = "Microsoft .NET Framework 4.8.1 Runtime"
                        ID        = "Microsoft.DotNet.Framework.Runtime"
                        Version   = $ndpVer
                        Available = ""
                        HasUpdate = $false
                        CleanName = "microsoft .net framework 4.8.1 runtime"
                        Source    = "local"
                    })
                }
            } finally {
                $ndpKey.Dispose()
            }
        }
    } catch {}

    $pf64Dn = if ($env:ProgramW6432) { $env:ProgramW6432 } else { [Environment]::GetFolderPath('ProgramFiles') }
    $pf86Dn = if (${env:ProgramFiles(x86)}) { ${env:ProgramFiles(x86)} } else { [Environment]::GetFolderPath('ProgramFilesX86') }
    $dotnetSharedConfigs = @()
    if ($pf64Dn) { $dotnetSharedConfigs += @{ Path = (Join-Path $pf64Dn "dotnet\shared\Microsoft.WindowsDesktop.App"); Suffix = ""; ArchLabel = "(x64)" } }
    if ($pf86Dn) { $dotnetSharedConfigs += @{ Path = (Join-Path $pf86Dn "dotnet\shared\Microsoft.WindowsDesktop.App"); Suffix = ".x86"; ArchLabel = "(x86)" } }
    foreach ($dnCfg in $dotnetSharedConfigs) {
        if ([System.IO.Directory]::Exists($dnCfg.Path)) {
            try {
                $verDirs = [System.IO.Directory]::GetDirectories($dnCfg.Path)
                $byMajor = @{}
                foreach ($vd in $verDirs) {
                    $vName = [System.IO.Path]::GetFileName($vd)
                    if ($vName -match '^(\d+)\.(\d+)\.') {
                        $maj = $Matches[1]
                        $min = $Matches[2]
                        $trackKey = if ($maj -eq "3" -and $min -eq "1") { "3_1" } elseif ($vName -match 'preview|rc|alpha|beta') { "Preview" } else { $maj }
                        if (-not $byMajor.ContainsKey($trackKey) -or (Compare-AppVersions $vName $byMajor[$trackKey]) -gt 0) {
                            $byMajor[$trackKey] = $vName
                        }
                    }
                }
                foreach ($tk in $byMajor.Keys) {
                    if ($dnCfg.Suffix -eq ".x86" -and $tk -notin @("6", "7", "8")) { continue }
                    $bestV = $byMajor[$tk]
                    $synId = "Microsoft.DotNet.DesktopRuntime.$tk$($dnCfg.Suffix)"
                    $localItems.Add([PSCustomObject]@{
                        Name      = "Microsoft Windows Desktop Runtime - $bestV $($dnCfg.ArchLabel)"
                        ID        = $synId
                        Version   = $bestV
                        Available = ""
                        HasUpdate = $false
                        CleanName = "microsoft windows runtime $bestV"
                        Source    = "local"
                    })
                }
            } catch {}
        }
    }

    $pathDirs = [System.Collections.Generic.List[string]]::new()
    foreach ($rawDir in ($env:PATH -split ';')) {
        if (-not [string]::IsNullOrWhiteSpace($rawDir)) {
            $cleanD = $rawDir.Trim().Trim('"')
            if ($cleanD.Length -gt 2 -and [System.IO.Directory]::Exists($cleanD)) {
                $pathDirs.Add($cleanD)
            }
        }
    }

    $pyScriptsYtdlp = [System.Collections.Generic.List[string]]::new()
    try {
        $pyRoot = "$env:LOCALAPPDATA\Programs\Python"
        if ([System.IO.Directory]::Exists($pyRoot)) {
            foreach ($pyDir in [System.IO.Directory]::GetDirectories($pyRoot, "Python3*")) {
                $pyScriptsYtdlp.Add((Join-Path $pyDir "Scripts\yt-dlp.exe"))
            }
        }
    } catch {}
    $neovimRoot = if ($env:ProgramW6432) { $env:ProgramW6432 } elseif ($env:ProgramFiles) { $env:ProgramFiles } else { "C:\Program Files" }

    $cliProbes = @(
        @{ ID = "Google.AntigravityCLI";     Name = "Antigravity CLI";       Cmd = "agy.exe";         Paths = @("$env:LOCALAPPDATA\agy\bin\agy.exe") },
        @{ ID = "astral-sh.uv";              Name = "uv (Python Manager)";   Cmd = "uv.exe";          Paths = @("$env:USERPROFILE\.local\bin\uv.exe", "$env:USERPROFILE\.cargo\bin\uv.exe") },
        @{ ID = "yt-dlp.yt-dlp";             Name = "yt-dlp";                Cmd = "yt-dlp.exe";      Paths = @($pyScriptsYtdlp) },
        @{ ID = "Gyan.FFmpeg";               Name = "FFmpeg";                Cmd = "ffmpeg.exe";      Paths = @() },
        @{ ID = "aria2.aria2";               Name = "aria2";                 Cmd = "aria2c.exe";      Paths = @() },
        @{ ID = "Rclone.Rclone";             Name = "Rclone";                Cmd = "rclone.exe";      Paths = @() },
        @{ ID = "Oven-sh.Bun";               Name = "Bun";                   Cmd = "bun.exe";         Paths = @("$env:USERPROFILE\.bun\bin\bun.exe") },
        @{ ID = "pnpm.pnpm";                 Name = "pnpm";                  Cmd = "pnpm.exe";        Paths = @("$env:LOCALAPPDATA\pnpm\pnpm.exe", "$env:APPDATA\npm\pnpm.cmd") },
        @{ ID = "Yarn.Yarn";                 Name = "Yarn";                  Cmd = "yarn.cmd";        Paths = @("$env:APPDATA\npm\yarn.cmd") },
        @{ ID = "Fastfetch-cli.Fastfetch";   Name = "Fastfetch";             Cmd = "fastfetch.exe";   Paths = @() },
        @{ ID = "JanDeDobbeleer.OhMyPosh";   Name = "Oh My Posh";            Cmd = "oh-my-posh.exe";  Paths = @("$env:LOCALAPPDATA\Programs\oh-my-posh\bin\oh-my-posh.exe") },
        @{ ID = "Neovim.Neovim";             Name = "Neovim";                Cmd = "nvim.exe";        Paths = @("$neovimRoot\Neovim\bin\nvim.exe") },
        @{ ID = "Google.PlatformTools";      Name = "ADB & Fastboot";        Cmd = "adb.exe";         Paths = @("$env:LOCALAPPDATA\Android\Sdk\platform-tools\adb.exe") },
        @{ ID = "Gitleaks.Gitleaks";         Name = "Gitleaks";              Cmd = "gitleaks.exe";    Paths = @() }
    )
    foreach ($probe in $cliProbes) {
        $foundBin = ""
        foreach ($fixedP in $probe.Paths) {
            if (-not [string]::IsNullOrWhiteSpace($fixedP) -and [System.IO.File]::Exists($fixedP)) {
                $foundBin = $fixedP
                break
            }
        }
        if ([string]::IsNullOrWhiteSpace($foundBin)) {
            foreach ($pd in $pathDirs) {
                $candP = Join-Path $pd $probe.Cmd
                if ([System.IO.File]::Exists($candP)) {
                    $foundBin = $candP
                    break
                }
            }
        }
        if (-not [string]::IsNullOrWhiteSpace($foundBin)) {
            $binVer = Get-ExecutableCleanVersion -FilePath $foundBin
            $localItems.Add([PSCustomObject]@{
                Name      = $probe.Name
                ID        = $probe.ID
                Version   = $binVer
                Available = ""
                HasUpdate = $false
                CleanName = (Get-CleanAppName $probe.Name)
                Source    = "local"
            })
        }
    }

    $llPaths = @(
        (Join-Path $env:APPDATA ".tlauncher\legacy\Minecraft\TL.exe"),
        (Join-Path $env:APPDATA ".tlauncher\legacy"),
        (Join-Path $env:APPDATA ".minecraft\LLauncher.exe"),
        (Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs\Legacy Launcher.lnk")
    )
    foreach ($lp in $llPaths) {
        if (($lp -and [System.IO.File]::Exists($lp)) -or ($lp -and [System.IO.Directory]::Exists($lp))) {
            $localItems.Add([PSCustomObject]@{
                Name      = "Legacy Launcher"
                ID        = "LegacyLauncher.LegacyLauncher"
                Version   = "Installed"
                Available = ""
                HasUpdate = $false
                CleanName = "legacylauncher"
                Source    = "local"
            })
            break
        }
    }

    if (-not $SkipAppx) {
        if ($script:isWindowClosing) { return [object[]]@($localItems.ToArray()) }
        try { [System.Windows.Forms.Application]::DoEvents() } catch {}
        if ($script:isWindowClosing) { return [object[]]@($localItems.ToArray()) }
        try {
            foreach ($pkg in (Get-AppxPackage -ErrorAction SilentlyContinue)) {
                if ($pkg.IsFramework -or [string]::IsNullOrWhiteSpace($pkg.Name)) { continue }
                $pkgName = [string]$pkg.Name
                if ($pkgName -match '^(Microsoft\.Windows\.|MicrosoftWindows\.|Windows\.|Microsoft\.UI\.Xaml|Microsoft\.VCLibs|Microsoft\.NET\.Native|Microsoft\.WinAppRuntime|Microsoft\.Services\.Store)') {
                    continue
                }
                $localItems.Add([PSCustomObject]@{
                    Name      = $pkgName
                    ID        = "MSIX\" + [string]$pkg.PackageFullName
                    Version   = [string]$pkg.Version
                    Available = ""
                    HasUpdate = $false
                    CleanName = (Get-CleanAppName $pkgName)
                    Source    = "local"
                })
            }
        } catch {}
    }

    return $localItems
}

$script:cachedCatalogMatchTargets = $null
$script:cachedCatalogMatchCount   = -1

function Get-CatalogMatchTargetsCached {
    if (-not $allItemBorders -or $allItemBorders.Count -eq 0) { return [DuckUtil.CatalogMatchTarget[]]@() }
    if ($null -ne $script:cachedCatalogMatchTargets -and $script:cachedCatalogMatchCount -eq $allItemBorders.Count) {
        return $script:cachedCatalogMatchTargets
    }
    $n = $allItemBorders.Count
    $arr = [DuckUtil.CatalogMatchTarget[]]::new($n)
    for ($i = 0; $i -lt $n; $i++) {
        $app = $allItemBorders[$i].Tag.App
        $t = [DuckUtil.CatalogMatchTarget]::new()
        $t.ID = [string]$app.ID
        $t.Name = [string]$app.Name
        $t.Category = [string]$app.Category
        if ($app.Aliases) {
            $t.Aliases = [string[]]@($app.Aliases)
        } else {
            $t.Aliases = [string[]]@()
        }
        $arr[$i] = $t
    }
    $script:cachedCatalogMatchTargets = $arr
    $script:cachedCatalogMatchCount = $n
    return $arr
}

function Apply-InstalledDatabaseToRows {
    param(
        $IdMap,
        $NameMap,
        $CleanNameMap,
        $InstalledList,
        [scriptblock]$CancelCheck = $null,
        [switch]$PreserveOutdatedOnLocalFallback
    )

    $prevOutdatedSnapshot = $null
    if ($PreserveOutdatedOnLocalFallback -and $allItemBorders -and $allItemBorders.Count -gt 0) {
        $prevOutdatedSnapshot = @{}
        for ($pi = 0; $pi -lt $allItemBorders.Count; $pi++) {
            $pt = $allItemBorders[$pi].Tag
            if ($pt -and $pt.Status -eq "OUTDATED") {
                $prevAv = ""
                if ($pt.UpdateText -and -not [string]::IsNullOrWhiteSpace($pt.UpdateText.Text)) {
                    $rawAv = [string]$pt.UpdateText.Text
                    if ($rawAv.StartsWith("$([char]0x2191) ") -and $rawAv -ne "$([char]0x2191) M$([char]0x1EDB)i") {
                        $prevAv = $rawAv.Substring(2).Trim()
                    }
                }
                $prevOutdatedSnapshot[$pi] = @{
                    Version   = [string]$pt.InstalledVersion
                    Available = $prevAv
                }
            }
        }
    }

    $countInstalled = 0
    $countLatest = 0
    $countOutdated = 0

    $csMatchType = "DuckUtil.AppCatalogEngine" -as [type]
    if ($csMatchType -and $null -ne $csMatchType.GetMethod("MatchCatalogApps")) {
        $targets = Get-CatalogMatchTargetsCached
        $instCount = if ($InstalledList) { $InstalledList.Count } else { 0 }
        $sensorArr = [DuckUtil.CatalogSensorItem[]]::new($instCount)
        for ($si = 0; $si -lt $instCount; $si++) {
            $item = $InstalledList[$si]
            if ($item -is [DuckUtil.CatalogSensorItem]) {
                $sensorArr[$si] = $item
            } elseif ($null -ne $item) {
                $obj = [DuckUtil.CatalogSensorItem]::new()
                $obj.Name      = [string]$item.Name
                $obj.ID        = [string]$item.ID
                $obj.Version   = [string]$item.Version
                $obj.Available = [string]$item.Available
                $obj.HasUpdate = [bool]$item.HasUpdate
                $obj.CleanName = [string]$item.CleanName
                $obj.Source    = [string]$item.Source
                $sensorArr[$si] = $obj
            }
        }

        $matchedArr = $null
        if ($null -ne $csMatchType.GetMethod("MatchCatalogAppsAsync") -and (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) -and $window -and $window.Dispatcher -and $window.Dispatcher.CheckAccess()) {
            $mTask = [DuckUtil.AppCatalogEngine]::MatchCatalogAppsAsync($targets, $sensorArr)
            [void](Wait-TaskNonBlocking -Task $mTask -TimeoutSeconds 15 -CancelCheck $CancelCheck)
            $canceledApply = $script:isWindowClosing
            if (-not $canceledApply -and $CancelCheck) { try { $canceledApply = [bool](& $CancelCheck) } catch {} }
            if ($canceledApply) {
                return [PSCustomObject]@{ Installed = 0; Latest = 0; Outdated = 0; Canceled = $true }
            }
            if ($mTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                $matchedArr = $mTask.Result
            }
        }
        if ($null -eq $matchedArr) {
            $matchedArr = [DuckUtil.AppCatalogEngine]::MatchCatalogApps($targets, $sensorArr)
        }

        $rowCount = $allItemBorders.Count
        for ($ri = 0; $ri -lt $rowCount; $ri++) {
            $row = $allItemBorders[$ri]
            $tag = $row.Tag
            $app = $tag.App
            $tb  = $tag.NameText
            $updateBadge = $tag.UpdateBadge
            $updateText  = $tag.UpdateText
            $idnPrefix = if ($app.IDn) { "[#$($app.IDn)] " } else { "" }
            $info = if ($matchedArr -and $ri -lt $matchedArr.Length) { $matchedArr[$ri] } else { $null }

            if ($null -ne $info) {
                $countInstalled++
                $effectiveHasUpdate = [bool]($info.HasUpdate -eq $true)
                $effectiveAvailable = [string]$info.Available
                if (-not $effectiveHasUpdate -and $prevOutdatedSnapshot -and $prevOutdatedSnapshot.ContainsKey($ri)) {
                    $snapOut = $prevOutdatedSnapshot[$ri]
                    $stillOut = if (-not [string]::IsNullOrWhiteSpace($snapOut.Available)) {
                        [DuckUtil.AppCatalogEngine]::TestAppUpdateGenuine([string]$info.Version, [string]$snapOut.Available)
                    } else {
                        [string]$info.Version -eq $snapOut.Version
                    }
                    if ($stillOut) {
                        $effectiveHasUpdate = $true
                        $effectiveAvailable = $snapOut.Available
                    }
                }

                $prevStatus = $tag.Status
                $prevVer = $tag.InstalledVersion
                $prevDet = $tag.DetectedId
                $tag.DetectedId = $info.ID
                $tag.InstalledVersion = $info.Version
                if ($tag.PSObject.Properties['AvailableVersion']) {
                    $tag.AvailableVersion = if ($effectiveHasUpdate) { $effectiveAvailable } else { $null }
                } else {
                    Add-Member -InputObject $tag -NotePropertyName AvailableVersion -NotePropertyValue $(if ($effectiveHasUpdate) { $effectiveAvailable } else { $null }) -Force
                }

                if ($effectiveHasUpdate) {
                    $countOutdated++
                    $newBadgeTxt = if ($effectiveAvailable) { "$([char]0x2191) $effectiveAvailable" } else { "$([char]0x2191) M$([char]0x1EDB)i" }
                    if ($prevStatus -ne "OUTDATED" -or $prevVer -ne $info.Version -or $prevDet -ne $info.ID -or ($updateText -and $updateText.Text -ne $newBadgeTxt)) {
                        $tag.Status = "OUTDATED"
                        if ($tb) {
                            $tb.Foreground = $script:brushOutdatedFg
                            $tb.Text = $app.Name
                            $tb.TextDecorations = $null
                        }
                        if ($updateBadge -and $updateText) {
                            $updateText.Text = $newBadgeTxt
                            $updateBadge.Visibility = [System.Windows.Visibility]::Visible
                        }
                        $row.ToolTip = "$idnPrefix$($app.Name)`n$([char]0x0110)ang c$([char]0x00E0)i: $($info.Version)`nC$([char]0x00F3) b$([char]0x1EA3)n m$([char]0x1EDB)i: $effectiveAvailable`nID ph$([char]0x00E1)t hi$([char]0x1EC7)n: $($info.ID)"
                    }
                } else {
                    $countLatest++
                    $badgeStillShown = ($updateBadge -and $updateBadge.Visibility -ne [System.Windows.Visibility]::Collapsed)
                    if ($prevStatus -ne "LATEST" -or $prevVer -ne $info.Version -or $prevDet -ne $info.ID -or $badgeStillShown) {
                        $tag.Status = "LATEST"
                        if ($tb) {
                            $tb.Foreground = $script:brushLatestFg
                            $tb.Text = $app.Name
                            $tb.TextDecorations = $null
                        }
                        if ($badgeStillShown) {
                            $updateBadge.Visibility = [System.Windows.Visibility]::Collapsed
                        }
                        $row.ToolTip = "$idnPrefix$($app.Name)`nPhi$([char]0x00EA)n b$([char]0x1EA3)n: $($info.Version) (M$([char]0x1EDB)i nh$([char]0x1EA5)t)`nID ph$([char]0x00E1)t hi$([char]0x1EC7)n: $($info.ID)"
                    }
                }
            } else {
                $prevStatus = $tag.Status
                $tag.DetectedId = $null
                $tag.InstalledVersion = $null
                if ($tag.PSObject.Properties['AvailableVersion']) { $tag.AvailableVersion = $null }
                $badgeStillShown = ($updateBadge -and $updateBadge.Visibility -ne [System.Windows.Visibility]::Collapsed)
                if ($prevStatus -ne "NONE" -or $badgeStillShown) {
                    $tag.Status = "NONE"
                    if ($tb) {
                        $tb.Foreground = $script:brushNoneFg
                        $tb.Text = $app.Name
                        $tb.TextDecorations = $null
                    }
                    if ($badgeStillShown) {
                        $updateBadge.Visibility = [System.Windows.Visibility]::Collapsed
                    }
                    $row.ToolTip = "$idnPrefix$($app.Name)`nTr$([char]0x1EA1)ng th$([char]0x00E1)i: Ch$([char]0x01B0)a c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t`nID: $($app.ID)"
                }
            }
        }

        return [PSCustomObject]@{
            Installed = $countInstalled
            Latest    = $countLatest
            Outdated  = $countOutdated
        }
    }

    $lookupCache = [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $tokenIndex  = [System.Collections.Generic.Dictionary[string, System.Collections.Generic.List[object]]]::new([System.StringComparer]::OrdinalIgnoreCase)

    foreach ($instItem in $InstalledList) {
        $rawText = "$($instItem.ID) $($instItem.Name) $($instItem.CleanName)"
        $tokens = [System.Text.RegularExpressions.Regex]::Split($rawText, '[^a-zA-Z0-9+]+')
        $seenTokens = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($tk in $tokens) {
            if ($tk.Length -ge 3 -and $seenTokens.Add($tk)) {
                $bucket = $null
                if (-not $tokenIndex.TryGetValue($tk, [ref]$bucket)) {
                    $bucket = [System.Collections.Generic.List[object]]::new()
                    $tokenIndex[$tk] = $bucket
                }
                $bucket.Add($instItem)
            }
        }
    }

    function Find-InstalledAppFast {
        param($targetApp)

        $targetId = $targetApp.ID
        $cachedMatch = $null
        if ($lookupCache.TryGetValue($targetId, [ref]$cachedMatch)) {
            return $cachedMatch
        }

        $meta = Get-TargetAppMeta $targetApp
        $match = $null
        if ($IdMap.TryGetValue($targetId, [ref]$match) -and (Test-MatchCompatible $targetApp $match)) {
            $lookupCache[$targetId] = $match
            return $match
        }

        foreach ($alPair in $meta.CleanAliases) {
            $alias = $alPair.Raw
            if ($IdMap.TryGetValue($alias, [ref]$match) -and (Test-MatchCompatible $targetApp $match)) {
                $lookupCache[$targetId] = $match
                return $match
            }
        }

        if ($targetApp.Name -and $NameMap.TryGetValue($targetApp.Name, [ref]$match) -and (Test-MatchCompatible $targetApp $match)) {
            $lookupCache[$targetId] = $match
            return $match
        }

        foreach ($alPair in $meta.CleanAliases) {
            $alias = $alPair.Raw
            if ($NameMap.TryGetValue($alias, [ref]$match) -and (Test-MatchCompatible $targetApp $match)) {
                $lookupCache[$targetId] = $match
                return $match
            }
            $cleanAlias = $alPair.Clean
            if ($cleanAlias.Length -ge 2 -and $CleanNameMap.TryGetValue($cleanAlias, [ref]$match) -and (Test-MatchCompatible $targetApp $match)) {
                $lookupCache[$targetId] = $match
                return $match
            }
        }

        $cleanTarget = $meta.CleanTarget
        if ($cleanTarget.Length -ge 2 -and $CleanNameMap.TryGetValue($cleanTarget, [ref]$match) -and (Test-MatchCompatible $targetApp $match)) {
            $lookupCache[$targetId] = $match
            return $match
        }

        $candidatePool = [System.Collections.Generic.List[object]]::new()
        $seenCand = [System.Collections.Generic.HashSet[object]]::new()

        foreach ($qt in $meta.QueryTokens) {
            $bucket = $null
            if ($tokenIndex.TryGetValue($qt, [ref]$bucket)) {
                foreach ($bItem in $bucket) {
                    if ($seenCand.Add($bItem)) {
                        $candidatePool.Add($bItem)
                    }
                }
            }
        }

        if ($candidatePool.Count -eq 0) {
            $lookupCache[$targetId] = $null
            return $null
        }

        $bestCandidate = $null
        $bestScore = 0
        $aliasEntries = $meta.AliasEntries
        $patternClean = $meta.PatternClean

        foreach ($item in $candidatePool) {
            $score = 0
            foreach ($ae in $aliasEntries) {
                $rawAl = $ae.Raw
                if ($item.ID.IndexOf($rawAl, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -and $item.ID -match $ae.Pattern) {
                    $score = 780
                    break
                }
                if ($item.Name.IndexOf($rawAl, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -and $item.Name -match $ae.Pattern) {
                    $lenRatio = [Math]::Min(40, [int](($cleanTarget.Length * 40) / [Math]::Max(1, $item.Name.Length)))
                    $candScore = 700 + $lenRatio
                    if ($candScore -gt $score) { $score = $candScore }
                }
            }
            if ($score -eq 0 -and $patternClean -and $item.CleanName.IndexOf($cleanTarget, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -and $item.CleanName -match $patternClean) {
                $lenRatio = [Math]::Min(40, [int](($cleanTarget.Length * 40) / [Math]::Max(1, $item.CleanName.Length)))
                $score = 650 + $lenRatio
            }
            if ($score -gt 0) {
                if ($item.HasUpdate) { $score += 15 }
                if ($item.ID -notmatch '^(ARP|MSIX|LOCAL)\\') { $score += 10 }
                if ($score -gt $bestScore -and (Test-MatchCompatible $targetApp $item)) {
                    $bestScore = $score
                    $bestCandidate = $item
                }
            }
        }

        $lookupCache[$targetId] = $bestCandidate
        return $bestCandidate
    }

    $countInstalled = 0
    $countLatest = 0
    $countOutdated = 0

    for ($ri = 0; $ri -lt $allItemBorders.Count; $ri++) {
        $row = $allItemBorders[$ri]
        $app = $row.Tag.App
        $grid = $row.Child
        $tb = if ($row.Tag.NameText) { $row.Tag.NameText } elseif ($grid -and $grid.Children.Count -gt 2) { $grid.Children[2] } else { $null }
        $updateBadge = $row.Tag.UpdateBadge
        $updateText  = $row.Tag.UpdateText
        $idnPrefix = if ($app.IDn) { "[#$($app.IDn)] " } else { "" }

        $info = Find-InstalledAppFast $app

        if ($info) {
            $countInstalled++
            $effHasUpd = [bool]($info.HasUpdate -eq $true)
            $effAvail = [string]$info.Available
            if (-not $effHasUpd -and $prevOutdatedSnapshot -and $prevOutdatedSnapshot.ContainsKey($ri)) {
                $snapOutPs = $prevOutdatedSnapshot[$ri]
                $stillOutPs = if (-not [string]::IsNullOrWhiteSpace($snapOutPs.Available)) {
                    Test-AppUpdateGenuine -InstalledVer ([string]$info.Version) -AvailableVer ([string]$snapOutPs.Available)
                } else {
                    [string]$info.Version -eq $snapOutPs.Version
                }
                if ($stillOutPs) {
                    $effHasUpd = $true
                    $effAvail = $snapOutPs.Available
                }
            }
            $row.Tag.DetectedId = $info.ID
            $row.Tag.InstalledVersion = $info.Version
            if ($row.Tag.PSObject.Properties['AvailableVersion']) {
                $row.Tag.AvailableVersion = if ($effHasUpd) { $effAvail } else { $null }
            } else {
                Add-Member -InputObject $row.Tag -NotePropertyName AvailableVersion -NotePropertyValue $(if ($effHasUpd) { $effAvail } else { $null }) -Force
            }

            if ($effHasUpd) {
                $countOutdated++
                $row.Tag.Status = "OUTDATED"
                if ($tb) {
                    $tb.Foreground = $script:brushOutdatedFg
                    $tb.Text = $app.Name
                    $tb.TextDecorations = $null
                }
                if ($updateBadge -and $updateText) {
                    $updateText.Text = if ($effAvail) { "$([char]0x2191) $effAvail" } else { "$([char]0x2191) M$([char]0x1EDB)i" }
                    $updateBadge.Visibility = [System.Windows.Visibility]::Visible
                }
                $tip = "$idnPrefix$($app.Name)`n$([char]0x0110)ang c$([char]0x00E0)i: $($info.Version)`nC$([char]0x00F3) b$([char]0x1EA3)n m$([char]0x1EDB)i: $effAvail`nID ph$([char]0x00E1)t hi$([char]0x1EC7)n: $($info.ID)"
                $row.ToolTip = $tip
            } else {
                $countLatest++
                $row.Tag.Status = "LATEST"
                if ($tb) {
                    $tb.Foreground = $script:brushLatestFg
                    $tb.Text = $app.Name
                    $tb.TextDecorations = $null
                }
                if ($updateBadge -and $updateBadge.Visibility -ne [System.Windows.Visibility]::Collapsed) {
                    $updateBadge.Visibility = [System.Windows.Visibility]::Collapsed
                }
                $tip = "$idnPrefix$($app.Name)`nPhi$([char]0x00EA)n b$([char]0x1EA3)n: $($info.Version) (M$([char]0x1EDB)i nh$([char]0x1EA5)t)`nID ph$([char]0x00E1)t hi$([char]0x1EC7)n: $($info.ID)"
                $row.ToolTip = $tip
            }
        } else {
            $prevStatus = $row.Tag.Status
            $row.Tag.DetectedId = $null
            $row.Tag.InstalledVersion = $null
            if ($row.Tag.PSObject.Properties['AvailableVersion']) { $row.Tag.AvailableVersion = $null }
            if ($prevStatus -ne "NONE") {
                $row.Tag.Status = "NONE"
                if ($tb) {
                    $tb.Foreground = $script:brushNoneFg
                    $tb.Text = $app.Name
                    $tb.TextDecorations = $null
                }
                if ($updateBadge -and $updateBadge.Visibility -ne [System.Windows.Visibility]::Collapsed) {
                    $updateBadge.Visibility = [System.Windows.Visibility]::Collapsed
                }
                $tip = "$idnPrefix$($app.Name)`nTr$([char]0x1EA1)ng th$([char]0x00E1)i: Ch$([char]0x01B0)a c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t`nID: $($app.ID)"
                $row.ToolTip = $tip
            }
        }
    }

    return [PSCustomObject]@{
        Installed = $countInstalled
        Latest    = $countLatest
        Outdated  = $countOutdated
    }
}

function Scan-And-ColorizeApps {
    param(
        [switch]$Quiet,
        [switch]$ForceSourceRefresh
    )
    if ($script:isWindowClosing) { return }
    if ($Quiet) {
        if ($script:isScanningApps -or $script:isActionRunning -or $script:isUpdatingUninstaller -or $script:isUninstallingQueue -or $script:isAutoRefreshing) {
            return
        }
        $script:isAutoRefreshing = $true
        $script:cancelAutoScan = $false
        $script:autoScanGeneration++
        $script:activeAutoScanGen = $script:autoScanGeneration
    } else {
        if ($script:isAutoRefreshing -and (Get-Command "Stop-ActiveAutoScan" -ErrorAction SilentlyContinue)) {
            Stop-ActiveAutoScan
            $script:isAutoRefreshing = $false
            $script:cancelAutoScan = $false
        }
        if ($script:isScanningApps) {
            Log-Text "[!] Ti$([char]0x1EBF)n tr$([char]0x00EC)nh qu$([char]0x00E9)t $([char]0x1EE9)ng d$([char]0x1EE5)ng $([char]0x0111)ang ch$([char]0x1EA1)y, b$([char]0x1ECF) qua y$([char]0x00EA)u c$([char]0x1EA7)u tr$([char]0x00F9)ng l$([char]0x1EB7)p."
            return
        }
    }

    $cancelBlock = if ($Quiet) {
        { $script:isWindowClosing -or $script:cancelAutoScan -or ($script:autoScanGeneration -ne $script:activeAutoScanGen) }
    } else {
        { $script:isWindowClosing }
    }

    $script:isScanningApps = $true
    try {
        if (-not $Quiet) {
            Log-Text "[SCAN] $([char]0x0110)ang qu$([char]0x00E9)t h$([char]0x1EC7) th$([char]0x1ED1)ng (Registry, Runtimes, CLI & WinGet)..."
            if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)ang qu$([char]0x00E9)t h$([char]0x1EC7) th$([char]0x1ED1)ng..." }
            if ($btnScanInstalled) {
                $btnScanInstalled.Content = "$([char]0x0110)ang l$([char]0x00E0)m m$([char]0x1EDB)i..."
                $btnScanInstalled.IsEnabled = $false
            }
            if ($progressBar) {
                $progressBar.Value = 0
                $progressBar.IsIndeterminate = $true
            }
            if ($ForceSourceRefresh) {
                Stop-PreSpawnedWinget
                if (-not $script:isUpdatingUninstaller) {
                    $script:cachedUninstallerApps = @()
                }
                if ($script:uninstallerLoadedOnce) {
                    $script:uninstallerStale = $true
                }
                $srcUpd = Invoke-WingetListCapture -Arguments "source update --disable-interactivity" -TimeoutSeconds 12 -CancelCheck $cancelBlock
                if ($srcUpd.WasCanceled -or (& $cancelBlock)) { return }
            }
        }
        if (& $cancelBlock) { return }

        $localItems = Get-LocalInstalledEntries -SkipAppx -CancelCheck $cancelBlock
        if (& $cancelBlock) { return }
        $useCsFastMatcher = ($null -ne ("DuckUtil.AppCatalogEngine" -as [type])) -and ($null -ne ([DuckUtil.AppCatalogEngine].GetMethod("MatchCatalogApps")))
        $idMap        = if (-not $useCsFastMatcher) { [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::OrdinalIgnoreCase) } else { $null }
        $nameMap      = if (-not $useCsFastMatcher) { [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::OrdinalIgnoreCase) } else { $null }
        $cleanNameMap = if (-not $useCsFastMatcher) { [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::OrdinalIgnoreCase) } else { $null }
        $installedList = [System.Collections.Generic.List[object]]::new()

        foreach ($locObj in $localItems) {
            $installedList.Add($locObj)
            if (-not $useCsFastMatcher) {
                if ($locObj.ID -and -not $idMap.ContainsKey($locObj.ID)) { $idMap[$locObj.ID] = $locObj } else { Set-PreferredMapEntry $idMap $locObj.ID $locObj }
                if ($locObj.Name -and -not $nameMap.ContainsKey($locObj.Name)) { $nameMap[$locObj.Name] = $locObj } else { Set-PreferredMapEntry $nameMap $locObj.Name $locObj }
                if ($locObj.CleanName.Length -ge 2) {
                    if (-not $cleanNameMap.ContainsKey($locObj.CleanName)) { $cleanNameMap[$locObj.CleanName] = $locObj } else { Set-PreferredMapEntry $cleanNameMap $locObj.CleanName $locObj }
                }
            }
        }

        $localSigParts = [System.Collections.Generic.List[string]]::new($installedList.Count)
        foreach ($locS in $installedList) {
            $localSigParts.Add("$($locS.ID)=$($locS.Version)")
        }
        $localSigParts.Sort([System.StringComparer]::OrdinalIgnoreCase)
        $localFingerprint = ($localSigParts -join ';')
        $localChanged = ($localFingerprint -ne $script:lastLocalScanSig)
        if ($localChanged) {
            if (-not $script:isUpdatingUninstaller) {
                $script:cachedUninstallerApps = @()
            }
            if ($script:uninstallerLoadedOnce) {
                $script:uninstallerStale = $true
            }
        }

        if (-not $Quiet -and $allItemBorders -and $allItemBorders.Count -gt 0 -and -not $script:hasCompletedAppScan) {
            $preStats = Apply-InstalledDatabaseToRows -IdMap $idMap -NameMap $nameMap -CleanNameMap $cleanNameMap -InstalledList $installedList -CancelCheck $cancelBlock
            if (& $cancelBlock) { return }
            if ($txtStatus) {
                $txtStatus.Text = "T$([char]0x00EC)m th$([char]0x1EA5)y $($preStats.Installed) $([char]0x1EE9)ng d$([char]0x1EE5)ng $([char]0x2022) $([char]0x0111)ang ki$([char]0x1EC3)m tra c$([char]0x1EAD)p nh$([char]0x1EAD)t..."
            }
        }

        $wingetItems = [System.Collections.Generic.List[object]]::new()
        $wingetOk = $false
        $wingetMissing = $false

        try {
            $wgTimeout = if ($Quiet) { 22 } else { 35 }
            $primary = Invoke-WingetListCapture -Arguments "list --source winget --disable-interactivity --accept-source-agreements" -TimeoutSeconds $wgTimeout -CancelCheck $cancelBlock -TrackAsAuto:$Quiet
            if ($primary.WasCanceled -or (& $cancelBlock)) { return }
            if (-not $primary.Available) {
                $wingetMissing = $true
                if (-not $Quiet) { Log-Text "[WARN] Ch$([char]0x01B0)a c$([char]0x00F3) WinGet; chuy$([char]0x1EC3)n sang qu$([char]0x00E9)t c$([char]0x1EE5)c b$([char]0x1ED9) qua Registry, Runtimes & Appx." }
            } else {
                $parsedPrimary = ConvertFrom-WingetListOutput -RawText $primary.StdOut -AllowHeaderless ($primary.ExitCode -eq 0 -and -not $primary.TimedOut)
                if (-not $primary.TimedOut -and (($primary.ExitCode -eq 0 -and $parsedPrimary.Items.Count -gt 0) -or ($parsedPrimary.HasTable -and $parsedPrimary.Items.Count -gt 0))) {
                    $wingetItems = $parsedPrimary.Items
                    $wingetOk = $true
                } elseif (-not $Quiet) {
                    if ($primary.TimedOut) {
                        Log-Text "[WARN] WinGet (--source winget) qu$([char]0x00E1) th$([char]0x1EDD)i gian ch$([char]0x1EDD) (35s); $([char]0x0111)ang th$([char]0x1EED) l$([char]0x1EA1)i to$([char]0x00E0)n ngu$([char]0x1ED3)n..."
                    } else {
                        Log-Text "[WARN] WinGet (--source winget) tr$([char]0x1EA3) v$([char]0x1EC1) m$([char]0x00E3) $($primary.ExitCode) ($($parsedPrimary.Items.Count) d$([char]0x00F2)ng); $([char]0x0111)ang th$([char]0x1EED) l$([char]0x1EA1)i to$([char]0x00E0)n ngu$([char]0x1ED3)n..."
                        if (-not [string]::IsNullOrWhiteSpace($primary.StdErr)) {
                            Log-Text "[stderr] $($primary.StdErr.Trim())"
                        }
                    }

                    if (& $cancelBlock) { return }
                    $fallbackWg = Invoke-WingetListCapture -Arguments "list --disable-interactivity --accept-source-agreements" -TimeoutSeconds 25 -CancelCheck $cancelBlock -TrackAsAuto:$Quiet
                    if ($fallbackWg.WasCanceled -or (& $cancelBlock)) { return }
                    $parsedFallback = ConvertFrom-WingetListOutput -RawText $fallbackWg.StdOut -AllowHeaderless ($fallbackWg.ExitCode -eq 0 -and -not $fallbackWg.TimedOut)

                    if (-not $fallbackWg.TimedOut -and $fallbackWg.ExitCode -eq 0 -and $parsedFallback.Items.Count -gt 0) {
                        $wingetItems = $parsedFallback.Items
                        $wingetOk = $true
                    } elseif ($parsedPrimary.HasTable -and $parsedPrimary.Items.Count -gt $parsedFallback.Items.Count) {
                        $wingetItems = $parsedPrimary.Items
                        $wingetOk = $true
                    } elseif ($parsedFallback.HasTable -and $parsedFallback.Items.Count -gt 0) {
                        $wingetItems = $parsedFallback.Items
                        $wingetOk = $true
                    }
                }

                if ($wingetOk -and -not (& $cancelBlock)) {
                    $msStoreCap = Invoke-WingetListCapture -Arguments "list --source msstore --disable-interactivity --accept-source-agreements" -TimeoutSeconds 10 -CancelCheck $cancelBlock -TrackAsAuto:$Quiet
                    if ($msStoreCap.WasCanceled -or (& $cancelBlock)) { return }
                    if ($msStoreCap.Available -and -not $msStoreCap.TimedOut -and -not [string]::IsNullOrWhiteSpace($msStoreCap.StdOut)) {
                        $parsedStore = ConvertFrom-WingetListOutput -RawText $msStoreCap.StdOut -AllowHeaderless ($msStoreCap.ExitCode -eq 0)
                        if ($parsedStore -and $parsedStore.Items.Count -gt 0) {
                            $seenWgIds = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
                            foreach ($wgi in $wingetItems) {
                                if ($wgi -and -not [string]::IsNullOrWhiteSpace($wgi.ID)) { [void]$seenWgIds.Add($wgi.ID) }
                            }
                            foreach ($stItem in $parsedStore.Items) {
                                if ($stItem -and -not [string]::IsNullOrWhiteSpace($stItem.ID) -and $seenWgIds.Add($stItem.ID)) {
                                    $wingetItems.Add($stItem)
                                }
                            }
                        }
                    }
                }
            }
        } catch {
            if (-not $Quiet) { Log-Text "[!] L$([char]0x1ED7)i khi g$([char]0x1ECD)i WinGet: $($_.Exception.Message)" }
        }

        if (& $cancelBlock) { return }

        if ($Quiet -and -not $wingetOk -and -not $localChanged -and $script:hasCompletedAppScan) {
            return
        }

        if ((-not $wingetOk -or $wingetItems.Count -lt 5) -and -not ("DuckUtil.AppCatalogEngine" -as [type])) {
            $appxItems = Get-LocalInstalledEntries
            if (& $cancelBlock) { return }
            foreach ($ax in $appxItems) {
                $installedList.Add($ax)
                Set-PreferredMapEntry $idMap $ax.ID $ax
                Set-PreferredMapEntry $nameMap $ax.Name $ax
                if ($ax.CleanName.Length -ge 2) { Set-PreferredMapEntry $cleanNameMap $ax.CleanName $ax }
            }
        }

        foreach ($itemObj in $wingetItems) {
            if ($itemObj.ID -eq "Microsoft.VisualStudioCode" -and $itemObj.Name -match '\(User\)' -and -not [System.IO.Directory]::Exists("$env:LOCALAPPDATA\Programs\Microsoft VS Code")) {
                continue
            }
            $installedList.Add($itemObj)
            if (-not $useCsFastMatcher) {
                if ($itemObj.ID -and -not $idMap.ContainsKey($itemObj.ID)) { $idMap[$itemObj.ID] = $itemObj } else { Set-PreferredMapEntry $idMap $itemObj.ID $itemObj }
                if ($itemObj.Name -and -not $nameMap.ContainsKey($itemObj.Name)) { $nameMap[$itemObj.Name] = $itemObj } else { Set-PreferredMapEntry $nameMap $itemObj.Name $itemObj }
                if ($itemObj.CleanName.Length -ge 2) {
                    if (-not $cleanNameMap.ContainsKey($itemObj.CleanName)) { $cleanNameMap[$itemObj.CleanName] = $itemObj } else { Set-PreferredMapEntry $cleanNameMap $itemObj.CleanName $itemObj }
                }

                if ($itemObj.ID -eq "Microsoft.VisualStudio.Community.Insiders") {
                    Set-PreferredMapEntry $idMap "Microsoft.VisualStudio.2022.Community" $itemObj
                }
            }
        }

        if ($installedList.Count -eq 0 -and -not $wingetOk) {
            if (-not $Quiet) {
                Log-Text "[!] Kh$([char]0x00F4)ng nh$([char]0x1EAD)n $([char]0x0111)$([char]0x01B0)$([char]0x1EE3)c danh s$([char]0x00E1)ch $([char]0x1EE9)ng d$([char]0x1EE5)ng t$([char]0x1EEB) c$([char]0x1EA3) WinGet l$([char]0x1EAB)n c$([char]0x1EE5)c b$([char]0x1ED9). Gi$([char]0x1EEF) nguy$([char]0x00EA)n tr$([char]0x1EA1)ng th$([char]0x00E1)i hi$([char]0x1EC7)n t$([char]0x1EA1)i."
                if ($txtStatus -and -not $script:hasCompletedAppScan) {
                    $txtStatus.Text = if ($wingetMissing) { "Thi$([char]0x1EBF)u WinGet | Qu$([char]0x00E9)t th$([char]0x1EA5)t b$([char]0x1EA1)i" } else { "L$([char]0x1ED7)i qu$([char]0x00E9)t WinGet | H$([char]0x00E3)y th$([char]0x1EED) Qu$([char]0x00E9)t l$([char]0x1EA1)i m$([char]0x00E1)y" }
                }
            }
            return
        }

        if (& $cancelBlock) { return }
        $preserveOutdated = [bool]((-not $wingetOk) -and (-not $ForceSourceRefresh) -and $script:hasCompletedAppScan)
        $finalStats = Apply-InstalledDatabaseToRows -IdMap $idMap -NameMap $nameMap -CleanNameMap $cleanNameMap -InstalledList $installedList -CancelCheck $cancelBlock -PreserveOutdatedOnLocalFallback:$preserveOutdated
        if (($finalStats.PSObject.Properties['Canceled'] -and $finalStats.Canceled) -or (& $cancelBlock)) { return }
        if (-not $Quiet -and $progressBar) {
            $progressBar.IsIndeterminate = $false
            $progressBar.Value = 0
        }

        $script:lastLocalScanSig = $localFingerprint
        $prevInstalledCnt = $script:lastLocalInstalledCnt
        $script:lastLocalInstalledCnt = [int]$finalStats.Installed
        $newSig = "$($finalStats.Installed)|$($finalStats.Latest)|$($finalStats.Outdated)|$wingetOk"
        $sigChanged = ($newSig -ne $script:lastAppScanSignature)
        $script:lastAppScanSignature = $newSig

        if ($prevInstalledCnt -ge 0 -and $prevInstalledCnt -ne $finalStats.Installed) {
            $script:uninstallerStale = $true
        }

        $script:hasCompletedAppScan = $true
        if (Get-Command "Try-EnableCompletedCardCaches" -ErrorAction SilentlyContinue) {
            try { Try-EnableCompletedCardCaches } catch {}
        }
        $modeTag = if (-not $wingetOk) {
            if ($preserveOutdated) { " [WinGet l$([char]0x1ED7)i - gi$([char]0x1EEF) tr$([char]0x1EA1)ng th$([char]0x00E1)i c$([char]0x1EAD)p nh$([char]0x1EAD)t tr$([char]0x01B0)$([char]0x1EDB)c $([char]0x0111)$([char]0x00F3)]" } else { " [D$([char]0x1EF1) ph$([char]0x00F2)ng Registry/Appx]" }
        } else { "" }
        $summary = "$([char]0x0110)$([char]0x00E3) qu$([char]0x00E9)t xong: $($finalStats.Installed) $([char]0x0111)$([char]0x00E3) c$([char]0x00E0)i ($($finalStats.Latest) m$([char]0x1EDB)i nh$([char]0x1EA5)t, $($finalStats.Outdated) c$([char]0x1EA7)n c$([char]0x1EAD)p nh$([char]0x1EAD)t)$modeTag"
        if (-not $Quiet) {
            if (-not $wingetOk -and -not $wingetMissing) {
                Log-Text "[WARN] $summary"
            } else {
                Log-Text "[OK] $summary"
            }
        } elseif ($sigChanged) {
            Log-Text "[AUTO] L$([char]0x00E0)m m$([char]0x1EDB)i: $($finalStats.Installed) $([char]0x0111)$([char]0x00E3) c$([char]0x00E0)i ($($finalStats.Latest) m$([char]0x1EDB)i nh$([char]0x1EA5)t, $($finalStats.Outdated) c$([char]0x1EA7)n c$([char]0x1EAD)p nh$([char]0x1EAD)t)$modeTag"
        }
        if ($txtStatus -and (-not $Quiet -or $sigChanged -or -not $script:isActionRunning)) {
            $txtStatus.Text = "$($finalStats.Installed) $([char]0x0111)$([char]0x00E3) c$([char]0x00E0)i $([char]0x2022) $($finalStats.Latest) m$([char]0x1EDB)i nh$([char]0x1EA5)t $([char]0x2022) $($finalStats.Outdated) c$([char]0x1EA7)n c$([char]0x1EAD)p nh$([char]0x1EAD)t" + $(if (-not $wingetOk) { " [D$([char]0x1EF1) ph$([char]0x00F2)ng]" } else { "" })
        }
    } finally {
        $autoWasPreempted = $Quiet -and ($script:autoScanGeneration -ne $script:activeAutoScanGen)
        if (-not $autoWasPreempted) {
            $script:isScanningApps = $false
        }
        if ($Quiet) {
            if (-not $autoWasPreempted) {
                $script:isAutoRefreshing = $false
                $script:cancelAutoScan = $false
            }
        } else {
            $keepWaitingLabel = ($script:pendingManualAppRefresh -and -not $script:isWindowClosing -and -not $script:isActionRunning)
            if ($btnScanInstalled) {
                $btnScanInstalled.Content = if ($keepWaitingLabel) { "$([char]0x0110)ang ch$([char]0x1EDD)..." } else { "L$([char]0x00E0)m m$([char]0x1EDB)i" }
                $btnScanInstalled.IsEnabled = (-not $keepWaitingLabel)
            }
            if ($progressBar) {
                $progressBar.IsIndeterminate = $false
                $progressBar.Value = 0
            }
        }
        if (-not $script:isWindowClosing -and -not $autoWasPreempted -and (Get-Command "Reset-AutoAppRefreshTimer" -ErrorAction SilentlyContinue)) {
            try { Reset-AutoAppRefreshTimer -FromAutoTick:$Quiet } catch {}
        }
        if (-not $script:isWindowClosing -and (Get-Command "Flush-PendingIconCache" -ErrorAction SilentlyContinue)) {
            Flush-PendingIconCache
        }
        if ($script:pendingManualAppRefresh -and -not $script:isWindowClosing -and -not $script:isScanningApps -and $window -and $window.Dispatcher) {
            $window.Dispatcher.BeginInvoke(
                [System.Windows.Threading.DispatcherPriority]::Background,
                [Action]{
                    if ($script:isWindowClosing) {
                        $script:pendingManualAppRefresh = $false
                        return
                    }
                    if (-not $script:isActionRunning -and -not $script:isScanningApps) {
                        $script:pendingManualAppRefresh = $false
                        Invoke-GuardedAction "Qu$([char]0x00E9)t $([char]0x1EE9)ng d$([char]0x1EE5)ng" -DeferExpand -AllowDuringUninstallerLoad {
                            Scan-And-ColorizeApps -ForceSourceRefresh
                        }
                    } else {
                        $script:pendingManualAppRefresh = $false
                        if ($btnScanInstalled) {
                            $btnScanInstalled.Content = "L$([char]0x00E0)m m$([char]0x1EDB)i"
                            $btnScanInstalled.IsEnabled = $true
                        }
                    }
                }
            ) | Out-Null
        }
    }
}

Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction SilentlyContinue

if (-not ("DuckUtil.DeepUninstallerEngine" -as [type])) {
    try {
        $csCandidates = @(
            (Join-Path $PSScriptRoot "..\..\csharp\DeepUninstallerEngine.cs"),
            (Join-Path $PSScriptRoot "..\csharp\DeepUninstallerEngine.cs"),
            (Join-Path $PSScriptRoot "csharp\DeepUninstallerEngine.cs")
        )
        foreach ($cand in $csCandidates) {
            if (Test-Path -LiteralPath $cand) {
                $deepUninstCs = Get-Content -Raw -Encoding utf8 $cand
                Add-Type -TypeDefinition $deepUninstCs -ErrorAction SilentlyContinue
                break
            }
        }
    } catch {}
}

if ("DuckUtil.DeepUninstallerEngine" -as [type]) {
    try {
        $deepEngType = "DuckUtil.DeepUninstallerEngine" -as [type]
        if ($null -ne $deepEngType.GetField("CustomElevationPidProvider")) {
            [DuckUtil.DeepUninstallerEngine]::CustomElevationPidProvider = [DuckUtil.DeepUninstallerEngine+ElevationPidProvider]{
                param([bool]$wantInstaller)
                try {
                    if (-not $wantInstaller) {
                        $sp = Get-Process -Name "winlogon", "spoolsv" -ErrorAction SilentlyContinue | Select-Object -First 1
                        if ($sp) { return [int]$sp.Id }
                        return 0
                    }
                    $tiProc = Get-Process -Name "TrustedInstaller" -ErrorAction SilentlyContinue | Select-Object -First 1
                    if (-not $tiProc) {
                        Start-Service -Name "TrustedInstaller" -ErrorAction SilentlyContinue
                        $tiProc = Get-Process -Name "TrustedInstaller" -ErrorAction SilentlyContinue | Select-Object -First 1
                    }
                    if ($tiProc) { return [int]$tiProc.Id }
                } catch {}
                return 0
            }
        }
    } catch {}
}

function Resolve-PathSafe {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
    try {
        return (Resolve-Path -LiteralPath $Path -ErrorAction Stop).Path.TrimEnd('\')
    } catch {
        return $null
    }
}

function Get-DirectoriesSafe {
    param([string]$RootPath)
    if ([string]::IsNullOrWhiteSpace($RootPath)) { return @() }
    try {
        return [System.IO.Directory]::GetDirectories($RootPath)
    } catch {
        return @()
    }
}

function Get-FilesRecursiveSafe {
    param(
        [string]$RootPath,
        [string]$SearchPattern = "*"
    )
    $results = [System.Collections.Generic.List[string]]::new()
    if ([string]::IsNullOrWhiteSpace($RootPath) -or -not (Test-Path -LiteralPath $RootPath)) {
        return @()
    }
    $queue = [System.Collections.Generic.Queue[string]]::new()
    $queue.Enqueue($RootPath)
    while ($queue.Count -gt 0) {
        if ($script:isWindowClosing) { break }
        $dir = $queue.Dequeue()
        try {
            foreach ($f in [System.IO.Directory]::GetFiles($dir, $SearchPattern, [System.IO.SearchOption]::TopDirectoryOnly)) {
                $results.Add($f)
            }
        } catch {}
        try {
            foreach ($sub in [System.IO.Directory]::GetDirectories($dir)) {
                $isReparse = try {
                    ([System.IO.File]::GetAttributes($sub) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0
                } catch { $true }
                if (-not $isReparse) {
                    $queue.Enqueue($sub)
                }
            }
        } catch {}
    }
    return @($results)
}

function Get-SystemInstalledAppsFast {
    $apps = [DuckUtil.DeepUninstallerEngine]::GetInstalledApps()
    return @($apps | Sort-Object -Property @{ Expression = { $_.IsBrokenOrphan }; Descending = $true }, @{ Expression = { $_.DisplayName }; Descending = $false })
}

function Test-SafeAppDirectoryForCleanup {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)]$AppEntry,
        [Parameter(Mandatory = $false)][string[]]$Keywords = @(),
        [Parameter(Mandatory = $false)]$AllInstalledApps = $null
    )

    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    $rawTrim = $Path.Trim()
    if ($rawTrim.StartsWith("\\")) { return $false }
    if ($rawTrim -notmatch '^[A-Za-z]:\\') { return $false }
    $norm = try { [System.IO.Path]::GetFullPath($rawTrim).TrimEnd('\') } catch { return $false }
    if ($norm -match '^[A-Za-z]:$') { return $false }
    if ($norm -match '^[A-Za-z]:\\Users\\[^\\]+$') { return $false }

    $protectedRaw = @(
        $env:USERPROFILE,
        $env:PUBLIC,
        (Join-Path $env:SystemDrive "Users\Default"),
        $env:LOCALAPPDATA,
        $env:APPDATA,
        $env:ProgramData,
        $(if ($env:ProgramData) { Join-Path $env:ProgramData "Microsoft" } else { "" }),
        $env:SystemRoot,
        $env:ProgramFiles,
        ${env:ProgramFiles(x86)},
        ${env:CommonProgramFiles},
        ${env:CommonProgramFiles(x86)},
        $env:TEMP
    )
    foreach ($pr in $protectedRaw) {
        if (-not [string]::IsNullOrWhiteSpace($pr)) {
            $prNorm = try { [System.IO.Path]::GetFullPath($pr).TrimEnd('\') } catch { $pr.Trim().TrimEnd('\') }
            if ($norm.Equals($prNorm, [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
        }
    }

    $parts = @($norm -split '\\' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($parts.Count -lt 2) { return $false }

    $genericContainers = @(
        'Windows', 'System32', 'SysWOW64', 'Program Files', 'Program Files (x86)',
        'ProgramData', 'Programs', 'Users', 'Public', 'Default', 'Microsoft', 'AppData', 'Local', 'Roaming', 'LocalLow',
        'Common Files', 'WindowsApps', 'ModifiableWindowsApps', 'Package Cache', 'Packages',
        'Temp', 'Apps', 'Applications', 'Games', 'Game', 'Software', 'Softwares', 'Tools',
        'Downloads', 'Desktop', 'Documents', 'Pictures', 'Music', 'Videos', 'OneDrive',
        'Steam', 'SteamLibrary', 'steamapps', 'common', 'Epic Games', 'GOG Galaxy', 'Riot Games'
    )

    $leafName = $parts[$parts.Count - 1]
    foreach ($gc in $genericContainers) {
        if ($leafName.Equals($gc, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    if ($Keywords -and $Keywords.Count -gt 0) {
        $parentName = if ($parts.Count -ge 3) { $parts[$parts.Count - 2] } else { "" }
        $matchedOwner = $false
        foreach ($kw in $Keywords) {
            if ([string]::IsNullOrWhiteSpace($kw)) { continue }
            $isCjk = $kw -match '[\u4E00-\u9FFF\u3040-\u30FF\uAC00-\uD7AF]'
            if ((-not $isCjk) -and $kw.Length -lt 3) { continue }
            if ($isCjk -and $kw.Length -lt 2) { continue }
            if ($leafName.IndexOf($kw, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -or
                ($parentName -and $parentName.IndexOf($kw, [System.StringComparison]::OrdinalIgnoreCase) -ge 0)) {
                $matchedOwner = $true
                break
            }
        }
        if (-not $matchedOwner) {
            $matchedOwner = [DuckUtil.DeepUninstallerEngine]::VerifyDirectoryExeOwnership($norm, $Keywords)
        }
        if (-not $matchedOwner -and $AppEntry.InstallLocation) {
            $regLoc = $AppEntry.InstallLocation.Trim().TrimEnd('\')
            if ($regLoc.Equals($norm, [System.StringComparison]::OrdinalIgnoreCase) -and $parts.Count -ge 3) {
                $matchedOwner = $true
            }
        }
        if (-not $matchedOwner -and $AppEntry.PSObject.Properties['DataLocation'] -and $AppEntry.DataLocation) {
            $dataRegLoc = $AppEntry.DataLocation.Trim().TrimEnd('\')
            if ($dataRegLoc.Equals($norm, [System.StringComparison]::OrdinalIgnoreCase) -and $parts.Count -ge 2) {
                $matchedOwner = $true
            }
        }
        if (-not $matchedOwner) { return $false }
    }

    if ($AllInstalledApps) {
        $normWithSlash = $norm + "\"
        foreach ($other in $AllInstalledApps) {
            if ($null -eq $other -or $other.Id -eq $AppEntry.Id) { continue }
            if ($other.IsBrokenOrphan) { continue }
            $otherLoc = if ($other.InstallLocation) { $other.InstallLocation.Trim().TrimEnd('\') } else { "" }
            if ($otherLoc) {
                if ($otherLoc.Equals($norm, [System.StringComparison]::OrdinalIgnoreCase) -or
                    $otherLoc.StartsWith($normWithSlash, [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
            $otherDataLoc = if ($other.PSObject.Properties['DataLocation'] -and $other.DataLocation) { $other.DataLocation.Trim().TrimEnd('\') } else { "" }
            if ($otherDataLoc) {
                if ($otherDataLoc.Equals($norm, [System.StringComparison]::OrdinalIgnoreCase) -or
                    $otherDataLoc.StartsWith($normWithSlash, [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
        }
    }

    return $true
}

function Get-NormalizedAppIdentity {
    param([string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name)) { return "" }
    $s = $Name -replace '\((?i:user|system|machine|64-bit|32-bit|x64|x86|arm64|lts|preview|portable)[^)]*\)', ''
    $s = $s -replace '\b(?i:x64|x86|arm64|64-bit|32-bit|user\s+installer|system\s+installer)\b', ''
    $s = $s -replace '\b\d+(?:\.\d+)+\b', ''
    $s = ($s -replace '[^a-zA-Z0-9\u4E00-\u9FFF\u3040-\u30FF\uAC00-\uD7AF]+', ' ').Trim().ToLowerInvariant()
    return $s
}

function Test-PathClaimedByActiveApp {
    param(
        [string]$CandidateName,
        $ActiveApps
    )
    if ([string]::IsNullOrWhiteSpace($CandidateName) -or -not $ActiveApps) { return $false }
    $candNorm = Get-NormalizedAppIdentity $CandidateName
    $candTrim = $CandidateName.Trim()
    foreach ($act in $ActiveApps) {
        if ($null -eq $act) { continue }
        $actNorm = Get-NormalizedAppIdentity $act.DisplayName
        if ($candNorm -and $actNorm) {
            if ($actNorm.Equals($candNorm, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
            if ($candNorm.Length -ge 3 -and $actNorm -match ('(?i)(?:^|\s)' + [regex]::Escape($candNorm) + '(?:\s|$)')) { return $true }
        }
        if ($act.InstallLocation) {
            $actLocLeaf = [System.IO.Path]::GetFileName($act.InstallLocation.Trim().TrimEnd('\'))
            if ($actLocLeaf -and $actLocLeaf.Equals($candTrim, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
        }
        if ($act.Publisher) {
            $pubNorm = Get-NormalizedAppIdentity $act.Publisher
            if ($candNorm -and $pubNorm) {
                if ($pubNorm.Equals($candNorm, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
                if ($candNorm.Length -ge 3 -and $pubNorm -match ('(?i)(?:^|\s)' + [regex]::Escape($candNorm) + '(?:\s|$)')) { return $true }
            }
        }
    }
    return $false
}

function Convert-DeepResidualArtifactToLeftoverItem {
    param(
        [Parameter(Mandatory = $true)]$Artifact,
        [Parameter(Mandatory = $false)][string]$FallbackAppName = "",
        [switch]$BracketBadge
    )
    $typeLabel = switch ([string]$Artifact.ArtifactKind) {
        "ResidualAppDir"     { "Th$([char]0x01B0) m$([char]0x1EE5)c c$([char]0x00F2)n s$([char]0x00F3)t" }
        "HollowDir"          { "Th$([char]0x01B0) m$([char]0x1EE5)c r$([char]0x1ED7)ng" }
        "OrphanAppData"      { "Th$([char]0x01B0) m$([char]0x1EE5)c r$([char]0x00E1)c AppData" }
        "DeadDriver"         { "Driver h$([char]0x1EC7) th$([char]0x1ED1)ng c$([char]0x00F2)n s$([char]0x00F3)t" }
        "RogueDriverReg"     { "Driver h$([char]0x1EC7) th$([char]0x1ED1)ng c$([char]0x00F2)n s$([char]0x00F3)t" }
        "RogueDriverFile"    { "Driver h$([char]0x1EC7) th$([char]0x1ED1)ng c$([char]0x00F2)n s$([char]0x00F3)t" }
        "DeadService"        { "Service c$([char]0x00F2)n s$([char]0x00F3)t" }
        "DeadTask"           { "Task c$([char]0x00F2)n s$([char]0x00F3)t" }
        "ScheduledTask"      { "Task c$([char]0x00F2)n s$([char]0x00F3)t" }
        "DeadStartup"        { "Startup c$([char]0x00F2)n s$([char]0x00F3)t" }
        "DeadShortcut"       { "Shortcut h$([char]0x1ECF)ng" }
        "EmptyStartMenuDir"  { "Start Menu r$([char]0x1ED7)ng" }
        "DeadAppPath"        { "App Path h$([char]0x1ECF)ng" }
        "RegistryAppPath"    { "App Path c$([char]0x00F2)n s$([char]0x00F3)t" }
        "FirewallRuleGroup"  { "Firewall rule r$([char]0x00E1)c" }
        "ContextMenu"        { "Context Menu r$([char]0x00E1)c" }
        "RegistryCache"      { "Registry Cache r$([char]0x00E1)c" }
        "RegistryCacheGroup" { "Registry Cache r$([char]0x00E1)c" }
        default              { "Registry c$([char]0x00F2)n s$([char]0x00F3)t" }
    }
    if ($BracketBadge) { $typeLabel = "[$typeLabel]" }

    $confLabel = switch ([string]$Artifact.ConfidenceTier) {
        "Check" { "N$([char]0x00EA)n ki$([char]0x1EC3)m tra" }
        "High"  { "Tin c$([char]0x1EAD)y cao" }
        default { "An to$([char]0x00E0)n 100%" }
    }

    $appDisplay = if ($Artifact.PSObject.Properties['AppName'] -and -not [string]::IsNullOrWhiteSpace($Artifact.AppName)) {
        [string]$Artifact.AppName
    } else {
        $FallbackAppName
    }
    $valNames = if ($Artifact.PSObject.Properties['RegistryValueNames'] -and $null -ne $Artifact.RegistryValueNames -and $Artifact.RegistryValueNames.Count -gt 0) {
        [string[]]@($Artifact.RegistryValueNames)
    } else {
        $null
    }
    $isTask = ($Artifact.ArtifactKind -eq "ScheduledTask" -or $Artifact.ArtifactKind -eq "DeadTask")
    return [PSCustomObject]@{
        Type               = $typeLabel
        Confidence         = $confLabel
        AppName            = $appDisplay
        Path               = [string]$Artifact.Path
        SizeBytes          = [long]$Artifact.SizeBytes
        SizeMB             = [math]::Round(([long]$Artifact.SizeBytes) / 1MB, 2)
        IsRegistry         = [bool]$Artifact.IsRegistry
        RegistryValueName  = if ($Artifact.IsRegistry) { [string]$Artifact.RegistryValueName } else { "" }
        RegistryValueNames = $valNames
        TaskName           = if ($isTask) { [string]$Artifact.RegistryValueName } else { "" }
        Details            = if ($Artifact.PSObject.Properties['Details']) { [string]$Artifact.Details } else { "" }
    }
}

function Find-AppLeftovers {
    param(
        [Parameter(Mandatory = $true)]$AppEntry,
        [Parameter(Mandatory = $false)]$AllInstalledApps = $null,
        [Parameter(Mandatory = $false)]$PreloadedServices = $null
    )

    $leftovers = [System.Collections.Generic.List[object]]::new()
    $seenPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

    if ($AppEntry -and $AppEntry.PSObject.Properties['OrphanArtifacts'] -and $null -ne $AppEntry.OrphanArtifacts -and $AppEntry.OrphanArtifacts.Count -gt 0) {
        foreach ($oa in $AppEntry.OrphanArtifacts) {
            if ($null -eq $oa -or [string]::IsNullOrWhiteSpace($oa.Path)) { continue }
            $oaDedup = if ($oa.IsRegistry -and $oa.RegistryValueName) { "$($oa.Path)->$($oa.RegistryValueName)" } else { [string]$oa.Path }
            if ($seenPaths.Add($oaDedup)) {
                $leftovers.Add((Convert-DeepResidualArtifactToLeftoverItem -Artifact $oa -FallbackAppName $AppEntry.DisplayName))
            }
        }
        if ($AppEntry.Id -like 'ORPHAN\*') {
            return @($leftovers)
        }
    }

    $exclusions = @(
        'Microsoft', 'Windows', 'Intel', 'AMD', 'NVIDIA', 'Google', 'Common Files',
        'WindowsApps', 'Package Cache', 'Packages', 'Temp', 'System32', 'Explorer', 'Internet Explorer'
    )

    $rawName = $AppEntry.DisplayName
    if ([string]::IsNullOrWhiteSpace($rawName)) { return @() }

    $selfNorm = Get-NormalizedAppIdentity $rawName
    $activeApps = [System.Collections.Generic.List[object]]::new()
    $hasActiveSameIdentity = $false
    if ($AllInstalledApps) {
        foreach ($other in $AllInstalledApps) {
            if ($null -eq $other -or $other.IsBrokenOrphan) { continue }
            if ($other.Id -eq $AppEntry.Id -and $other.RegistryPath -eq $AppEntry.RegistryPath) { continue }
            $activeApps.Add($other)
            $otherNorm = Get-NormalizedAppIdentity $other.DisplayName
            if ($selfNorm -and $otherNorm -and $selfNorm.Equals($otherNorm, [System.StringComparison]::OrdinalIgnoreCase)) {
                $hasActiveSameIdentity = $true
            }
        }
    }

    if ($hasActiveSameIdentity) {
        if ($AppEntry.RegistryPath -and (Test-Path -LiteralPath $AppEntry.RegistryPath)) {
            if ($seenPaths.Add($AppEntry.RegistryPath)) {
                $leftovers.Add([PSCustomObject]@{
                    Type              = "Registry b$([char]0x1ECB) l$([char]0x1ED7)i"
                    Confidence        = "An to$([char]0x00E0)n 100%"
                    AppName           = $AppEntry.DisplayName
                    Path              = $AppEntry.RegistryPath
                    SizeBytes         = 0L
                    SizeMB            = 0.0
                    IsRegistry        = $true
                    RegistryValueName = ""
                })
            }
        }
        return @($leftovers)
    }

    $genericStopWords = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($sw in @(
        'visual', 'studio', 'code', 'desktop', 'client', 'server', 'runtime', 'manager',
        'player', 'viewer', 'editor', 'reader', 'writer', 'updater', 'helper', 'launcher',
        'installer', 'setup', 'portable', 'pro', 'plus', 'lite', 'home', 'enterprise',
        'community', 'edition', 'ultimate', 'express', 'standard', 'core', 'tool', 'tools',
        'app', 'apps', 'program', 'programs', 'software', 'game', 'games', 'system',
        'windows', 'microsoft', 'google', 'adobe', 'apple', 'intel', 'nvidia', 'oracle',
        'python', 'java', 'dotnet', 'assistant', 'companion', 'service', 'services',
        'driver', 'drivers', 'agent', 'remote', 'connect', 'sync', 'cloud', 'workplace',
        'browser', 'terminal', 'console', 'shell', 'data', 'files', 'media', 'audio',
        'video', 'photo', 'image', 'chat', 'mail', 'note', 'notes', 'office', 'suite',
        'free', 'open', 'auto', 'smart', 'fast', 'easy', 'mini', 'super', 'ultra', 'mega',
        'beta', 'alpha', 'preview', 'nightly', 'user', 'machine', '64-bit', '32-bit', 'x64', 'x86'
    )) {
        $genericStopWords.Add($sw) | Out-Null
    }

    $cleanName = ($rawName -replace '\(.*?\)', '').Trim()
    $cleanName = ($cleanName -replace '[0-9]+(\.[0-9]+)+', '').Trim()

    $cnAliasMap = @{
        "$([char]0x817E)$([char]0x8BAF)" = @("Tencent", "QQ")
        "$([char]0x5FAE)$([char]0x4FE1)" = @("WeChat", "Tencent")
        "$([char]0x767E)$([char]0x5EA6)" = @("Baidu", "BaiduNetdisk")
        "$([char]0x7F51)$([char]0x6613)" = @("NetEase", "CloudMusic")
        "$([char]0x8FC5)$([char]0x96F7)" = @("Thunder", "Xunlei", "Thunder Network")
        "$([char]0x5947)$([char]0x864E)" = @("Qihoo360", "360Safe", "360se6")
        "360"                            = @("360Safe", "Qihoo360", "360se6")
        "$([char]0x91D1)$([char]0x5C71)" = @("Kingsoft", "WPS Office", "kingsoft")
        "$([char]0x641C)$([char]0x72D7)" = @("Sogou", "SogouInput", "SogouPY")
        "$([char]0x54D4)$([char]0x54E9)" = @("Bilibili", "Bililive")
        "$([char]0x6296)$([char]0x97F3)" = @("Douyin", "ByteDance")
        "$([char]0x5B57)$([char]0x8282)" = @("ByteDance", "Douyin")
        "$([char]0x9489)$([char]0x9489)" = @("DingTalk", "Alibaba", "AliWorkbench")
        "$([char]0x963F)$([char]0x91CC)" = @("Alibaba", "AliWorkbench", "DingTalk")
        "$([char]0x7231)$([char]0x5947)$([char]0x827A)" = @("IQIYI", "QyClient")
        "$([char]0x4F18)$([char]0x9177)" = @("Youku", "YoukuClient")
        "$([char]0x9177)$([char]0x72D7)" = @("KuGou", "KuGouMusic")
        "$([char]0x9177)$([char]0x6211)" = @("Kuwo", "kwmusic")
        "$([char]0x9C81)$([char]0x5927)$([char]0x5E08)" = @("LuDaShi", "ComputerZ")
        "$([char]0x96F7)$([char]0x7535)" = @("LDPlayer", "XuanZhi", "leidian", "dnplayer")
        "$([char]0x84DD)$([char]0x53E0)" = @("BlueStacks", "BlueStacks_nxt")
        "2345"                           = @("2345Soft", "2345Pic", "2345Explorer")
        "$([char]0x864E)$([char]0x7259)" = @("Huya", "HuyaClient")
        "$([char]0x6597)$([char]0x9C7C)" = @("Douyu", "DouyuClient")
    }

    $candidateTokens = [System.Collections.Generic.List[string]]::new()
    $isFullCjk = $cleanName -match '[\u4E00-\u9FFF\u3040-\u30FF\uAC00-\uD7AF]'
    if (($isFullCjk -and $cleanName.Length -ge 2) -or ((-not $isFullCjk) -and $cleanName.Length -ge 4)) {
        if ($exclusions -notcontains $cleanName -and -not $genericStopWords.Contains($cleanName)) {
            $candidateTokens.Add($cleanName)
        }
    }
    $rawSubTokens = @($cleanName -split '\s+' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($rawSubTokens.Count -gt 1) {
        foreach ($tk in $rawSubTokens) {
            $isCjk = $tk -match '[\u4E00-\u9FFF\u3040-\u30FF\uAC00-\uD7AF]'
            if (($isCjk -and $tk.Length -ge 2) -or ((-not $isCjk) -and $tk.Length -ge 5)) {
                if ($exclusions -notcontains $tk -and -not $genericStopWords.Contains($tk)) {
                    $candidateTokens.Add($tk)
                }
            }
        }
    }

    if ($AppEntry.Id -and $AppEntry.Id -notmatch '^\{?[0-9A-Fa-f\-]{12,}\}?$' -and $AppEntry.Id -notmatch '^MSI') {
        $cleanId = ($AppEntry.Id -replace '_is1$', '').Trim()
        if ($cleanId.Length -ge 3 -and $exclusions -notcontains $cleanId) {
            $candidateTokens.Add($cleanId)
        }
    }

    if ($AppEntry.InstallLocation) {
        $locTrim = $AppEntry.InstallLocation.Trim().TrimEnd('\')
        $locLeaf = [System.IO.Path]::GetFileName($locTrim)
        $genericFolders = @('Program Files', 'Program Files (x86)', 'Programs', 'Apps', 'Games', 'Software', 'Tools', 'Common Files', 'bin', 'Client')
        if ($locLeaf -and $locLeaf.Length -ge 3 -and $genericFolders -notcontains $locLeaf -and $exclusions -notcontains $locLeaf) {
            $candidateTokens.Add($locLeaf)
        }
    }

    $deepTypeLo = "DuckUtil.DeepUninstallerEngine" -as [type]
    $canWaitLo = ($null -ne (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue))
    $hasSizeAsyncLo = ($canWaitLo -and $null -ne $deepTypeLo -and $null -ne $deepTypeLo.GetMethod("GetDirectorySizeFastAsync"))
    $hasBinTokAsyncLo = ($canWaitLo -and $null -ne $deepTypeLo -and $null -ne $deepTypeLo.GetMethod("ExtractBinaryAndCertTokensAsync"))
    $hasAppScAsyncLo = ($canWaitLo -and $null -ne $deepTypeLo -and $null -ne $deepTypeLo.GetMethod("ScanAppShortcutsAsync"))

    $binTokens = $null
    if ($hasBinTokAsyncLo) {
        $btTask = $deepTypeLo::ExtractBinaryAndCertTokensAsync($AppEntry.InstallLocation, $AppEntry.UninstallString, "")
        [void](Wait-TaskNonBlocking -Task $btTask -TimeoutSeconds 15)
        if ($btTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) { $binTokens = $btTask.Result }
    } else {
        $binTokens = [DuckUtil.DeepUninstallerEngine]::ExtractBinaryAndCertTokens($AppEntry.InstallLocation, $AppEntry.UninstallString, "")
    }
    if ($script:isWindowClosing) { return @() }
    if ($binTokens) {
        foreach ($bt in $binTokens) {
            if ($bt -and $bt.Length -ge 3 -and $exclusions -notcontains $bt) {
                $candidateTokens.Add($bt)
            }
        }
    }

    $combinedSource = "$rawName | $($AppEntry.Publisher) | $($AppEntry.InstallLocation) | $($AppEntry.UninstallString)"
    $vendorFolders = [System.Collections.Generic.List[string]]::new()
    foreach ($cnKey in $cnAliasMap.Keys) {
        if ($combinedSource.IndexOf($cnKey, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
            foreach ($mapped in $cnAliasMap[$cnKey]) {
                $candidateTokens.Add($mapped)
                $vendorFolders.Add($mapped)
            }
        }
    }

    $nameKeywords = @($candidateTokens | Select-Object -Unique)
    if ($nameKeywords.Count -eq 0) { return @() }

    $ownerKeywords = [System.Collections.Generic.List[string]]::new()
    foreach ($nk in $nameKeywords) { $ownerKeywords.Add($nk) }
    if (-not [string]::IsNullOrWhiteSpace($AppEntry.Publisher)) {
        $pubClean = ($AppEntry.Publisher -replace '\(.*?\)', '').Trim()
        foreach ($pk in ($pubClean -split '\s+')) {
            $isPkCjk = $pk -match '[\u4E00-\u9FFF\u3040-\u30FF\uAC00-\uD7AF]'
            if ((($isPkCjk -and $pk.Length -ge 2) -or ($pk.Length -ge 3)) -and $exclusions -notcontains $pk) {
                $ownerKeywords.Add($pk)
            }
        }
    }

    if ($AppEntry.InstallLocation -and (Test-Path -LiteralPath $AppEntry.InstallLocation)) {
        $loc = try { (Resolve-Path -LiteralPath $AppEntry.InstallLocation).Path.TrimEnd('\') } catch { $AppEntry.InstallLocation.Trim().TrimEnd('\') }
        $isSafe = $true
        foreach ($ex in $exclusions) {
            if ($loc -like "*\$ex\*" -or $loc -like "*\$ex") { $isSafe = $false; break }
        }
        if ($isSafe -and (Test-SafeAppDirectoryForCleanup -Path $loc -AppEntry $AppEntry -Keywords $ownerKeywords.ToArray() -AllInstalledApps $AllInstalledApps)) {
            if ($seenPaths.Add($loc)) {
                $dirSize = 0L
                if ($hasSizeAsyncLo) {
                    $szTask1 = $deepTypeLo::GetDirectorySizeFastAsync($loc, 4)
                    [void](Wait-TaskNonBlocking -Task $szTask1 -TimeoutSeconds 20)
                    if ($szTask1.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) { $dirSize = [long]$szTask1.Result }
                } elseif (-not $script:isWindowClosing) {
                    $dirSize = [DuckUtil.DeepUninstallerEngine]::GetDirectorySizeFast($loc, 4)
                }
                $leftovers.Add([PSCustomObject]@{
                    Type              = "Th$([char]0x01B0) m$([char]0x1EE5)c c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t"
                    Confidence        = "An to$([char]0x00E0)n 100%"
                    AppName           = $AppEntry.DisplayName
                    Path              = $loc
                    SizeBytes         = [long]$dirSize
                    SizeMB            = [math]::Round($dirSize / 1MB, 2)
                    IsRegistry        = $false
                    RegistryValueName = ""
                })
            }
        }
    }

    if ($AppEntry.PSObject.Properties['DataLocation'] -and $AppEntry.DataLocation -and (Test-Path -LiteralPath $AppEntry.DataLocation)) {
        $dataLoc = try { (Resolve-Path -LiteralPath $AppEntry.DataLocation).Path.TrimEnd('\') } catch { $AppEntry.DataLocation.Trim().TrimEnd('\') }
        $isDataSafe = $true
        foreach ($ex in $exclusions) {
            if ($dataLoc -like "*\$ex\*" -or $dataLoc -like "*\$ex") { $isDataSafe = $false; break }
        }
        if ($isDataSafe -and (Test-SafeAppDirectoryForCleanup -Path $dataLoc -AppEntry $AppEntry -Keywords $ownerKeywords.ToArray() -AllInstalledApps $AllInstalledApps)) {
            if ($seenPaths.Add($dataLoc)) {
                $dataSize = 0L
                if ($hasSizeAsyncLo) {
                    $szTask2 = $deepTypeLo::GetDirectorySizeFastAsync($dataLoc, 4)
                    [void](Wait-TaskNonBlocking -Task $szTask2 -TimeoutSeconds 20)
                    if ($szTask2.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) { $dataSize = [long]$szTask2.Result }
                } elseif (-not $script:isWindowClosing) {
                    $dataSize = [DuckUtil.DeepUninstallerEngine]::GetDirectorySizeFast($dataLoc, 4)
                }
                $leftovers.Add([PSCustomObject]@{
                    Type              = "Th$([char]0x01B0) m$([char]0x1EE5)c d$([char]0x1EEF) li$([char]0x1EC7)u Game/App"
                    Confidence        = "An to$([char]0x00E0)n 100%"
                    AppName           = $AppEntry.DisplayName
                    Path              = $dataLoc
                    SizeBytes         = [long]$dataSize
                    SizeMB            = [math]::Round($dataSize / 1MB, 2)
                    IsRegistry        = $false
                    RegistryValueName = ""
                })
            }
        }
    }

    $localLowRoot = if ($env:USERPROFILE) { Join-Path $env:USERPROFILE "AppData\LocalLow" } else { "" }
    $progDataRoot = if ($env:ProgramData) { $env:ProgramData } else { "" }
    $folderRoots = [System.Collections.Generic.List[string]]::new()
    foreach ($baseRoot in @($env:APPDATA, $env:LOCALAPPDATA, $localLowRoot, $(if ($env:LOCALAPPDATA) { Join-Path $env:LOCALAPPDATA "Programs" } else { "" }), $progDataRoot)) {
        if ($baseRoot -and (Test-Path -LiteralPath $baseRoot)) {
            $folderRoots.Add($baseRoot)
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($AppEntry.Publisher)) {
        $pubClean = ($AppEntry.Publisher -replace '\(.*?\)', '' -replace '(?i)\b(Inc\.?|LLC|Ltd\.?|Corp\.?|Corporation|GmbH|Co\.?)\b', '').Trim(' ', ',', '.')
        if ($pubClean.Length -ge 2 -and $exclusions -notcontains $pubClean) {
            $vendorFolders.Add($pubClean)
        }
    }
    foreach ($vf in ($vendorFolders | Select-Object -Unique)) {
        foreach ($baseRoot in @($env:APPDATA, $env:LOCALAPPDATA, $localLowRoot, $progDataRoot)) {
            if ($baseRoot) {
                $pubSub = Join-Path $baseRoot $vf
                if (Test-Path -LiteralPath $pubSub) {
                    $isPubReparse = $false
                    try {
                        if (([System.IO.File]::GetAttributes($pubSub) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $isPubReparse = $true }
                    } catch {}
                    if (-not $isPubReparse) { $folderRoots.Add($pubSub) }
                }
            }
        }
    }

    foreach ($root in $folderRoots) {
        if ($script:isWindowClosing) { break }
        if (-not (Test-Path -LiteralPath $root)) { continue }
        foreach ($kw in $nameKeywords) {
            if ($script:isWindowClosing) { break }
            if ($genericStopWords.Contains($kw)) { continue }
            if (Test-PathClaimedByActiveApp -CandidateName $kw -ActiveApps $activeApps) { continue }
            $candidatePath = Join-Path $root $kw
            if (Test-Path -LiteralPath $candidatePath) {
                $isRawReparse = $false
                try {
                    if (([System.IO.File]::GetAttributes($candidatePath) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $isRawReparse = $true }
                } catch {}
                if ($isRawReparse) { continue }
                $fullPath = Resolve-PathSafe -Path $candidatePath
                if (-not $fullPath) { continue }
                $isReparseCand = $false
                try {
                    if (([System.IO.File]::GetAttributes($fullPath) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $isReparseCand = $true }
                } catch {}
                if ($isReparseCand) { continue }
                $isSafe = $true
                foreach ($ex in $exclusions) {
                    if ($fullPath -like "*\$ex\*" -or $fullPath -like "*\$ex") { $isSafe = $false; break }
                }
                if ($isSafe -and $seenPaths.Add($fullPath)) {
                    $dirSize = 0L
                    if ($hasSizeAsyncLo) {
                        $szTask3 = $deepTypeLo::GetDirectorySizeFastAsync($fullPath, 4)
                        [void](Wait-TaskNonBlocking -Task $szTask3 -TimeoutSeconds 20)
                        if ($szTask3.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) { $dirSize = [long]$szTask3.Result }
                    } elseif (-not $script:isWindowClosing) {
                        $dirSize = [DuckUtil.DeepUninstallerEngine]::GetDirectorySizeFast($fullPath, 4)
                    }
                    $folderConf = if ($kw.Equals($cleanName, [System.StringComparison]::OrdinalIgnoreCase) -or ($root -ne $env:APPDATA -and $root -ne $env:LOCALAPPDATA -and $root -ne $localLowRoot -and $root -ne $progDataRoot)) {
                        "An to$([char]0x00E0)n 100%"
                    } elseif ($kw.Length -ge 6) {
                        "Tin c$([char]0x1EAD)y cao"
                    } else {
                        "N$([char]0x00EA)n ki$([char]0x1EC3)m tra"
                    }
                    $leftovers.Add([PSCustomObject]@{
                        Type              = "Th$([char]0x01B0) m$([char]0x1EE5)c r$([char]0x00E1)c AppData"
                        Confidence        = $folderConf
                        AppName           = $AppEntry.DisplayName
                        Path              = $fullPath
                        SizeBytes         = [long]$dirSize
                        SizeMB            = [math]::Round($dirSize / 1MB, 2)
                        IsRegistry        = $false
                        RegistryValueName = ""
                    })
                }
            }
        }
    }

    $crashDumpDir = Join-Path $env:LOCALAPPDATA "CrashDumps"
    if (Test-Path -LiteralPath $crashDumpDir) {
        foreach ($kw in $nameKeywords) {
            try {
                $dumps = [System.IO.Directory]::GetFiles($crashDumpDir, "*$kw*.dmp", [System.IO.SearchOption]::TopDirectoryOnly)
                foreach ($dmp in $dumps) {
                    if ($seenPaths.Add($dmp)) {
                        $dmpSize = (Get-Item -LiteralPath $dmp -ErrorAction SilentlyContinue).Length
                        $leftovers.Add([PSCustomObject]@{
                            Type              = "Crash Dump r$([char]0x00E1)c"
                            Confidence        = "An to$([char]0x00E0)n 100%"
                            AppName           = $AppEntry.DisplayName
                            Path              = $dmp
                            SizeBytes         = [long]$dmpSize
                            SizeMB            = [math]::Round($dmpSize / 1MB, 2)
                            IsRegistry        = $false
                            RegistryValueName = ""
                        })
                    }
                }
            } catch {}
        }
    }

    $shortcutDirs = [string[]]@(
        [Environment]::GetFolderPath('Desktop'),
        [Environment]::GetFolderPath('CommonDesktopDirectory'),
        [Environment]::GetFolderPath('Programs'),
        [Environment]::GetFolderPath('CommonPrograms')
    )
    $targetLocPrefix = if ($AppEntry.InstallLocation) { $AppEntry.InstallLocation.Trim().TrimEnd('\') + "\" } else { "" }
    $isSafeTargetLoc = $false
    if ($targetLocPrefix) {
        $locNoSlash = $targetLocPrefix.TrimEnd('\')
        $isSafeTargetLoc = (Test-SafeAppDirectoryForCleanup -Path $locNoSlash -AppEntry $AppEntry -Keywords $ownerKeywords.ToArray() -AllInstalledApps $AllInstalledApps)
    }
    $hasDeepResidualsAsync = ($canWaitLo -and $null -ne $deepTypeLo -and $null -ne $deepTypeLo.GetMethod("ScanDeepAppResidualsFastAsync"))
    $resTask = $null
    if ($isSafeTargetLoc -and $hasDeepResidualsAsync) {
        try {
            $resTask = $deepTypeLo::ScanDeepAppResidualsFastAsync($targetLocPrefix)
        } catch { $resTask = $null }
    }

    if ($hasAppScAsyncLo) {
        try {
            $scTask = $deepTypeLo::ScanAppShortcutsAsync($shortcutDirs, $targetLocPrefix, $cleanName)
            [void](Wait-TaskNonBlocking -Task $scTask -TimeoutSeconds 15)
            if ($scTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion -and $null -ne $scTask.Result) {
                foreach ($lnk in $scTask.Result) {
                    if ($seenPaths.Add($lnk)) {
                        $leftovers.Add([PSCustomObject]@{
                            Type              = "Shortcut h$([char]0x1ECF)ng"
                            Confidence        = "An to$([char]0x00E0)n 100%"
                            AppName           = $AppEntry.DisplayName
                            Path              = $lnk
                            SizeBytes         = 0L
                            SizeMB            = 0.0
                            IsRegistry        = $false
                            RegistryValueName = ""
                        })
                    }
                }
            }
        } catch {}
    } else {
        $wsh = $null
        try {
            $wsh = New-Object -ComObject WScript.Shell
            foreach ($sDir in $shortcutDirs) {
                if ($script:isWindowClosing) { break }
                if (-not $sDir -or -not (Test-Path -LiteralPath $sDir)) { continue }
                $lnks = Get-FilesRecursiveSafe -RootPath $sDir -SearchPattern "*.lnk"
                foreach ($lnk in $lnks) {
                    try {
                        $lnkName = [System.IO.Path]::GetFileNameWithoutExtension($lnk)
                        $sc = $wsh.CreateShortcut($lnk)
                        $tPath = $sc.TargetPath
                        $matchesApp = $false
                        if ($targetLocPrefix -and $tPath -and $tPath.StartsWith($targetLocPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                            $matchesApp = $true
                        } elseif ($lnkName.Equals($cleanName, [System.StringComparison]::OrdinalIgnoreCase) -and $tPath -and -not (Test-Path -LiteralPath $tPath)) {
                            $matchesApp = $true
                        }
                        if ($matchesApp -and $seenPaths.Add($lnk)) {
                            $leftovers.Add([PSCustomObject]@{
                                Type              = "Shortcut h$([char]0x1ECF)ng"
                                Confidence        = "An to$([char]0x00E0)n 100%"
                                AppName           = $AppEntry.DisplayName
                                Path              = $lnk
                                SizeBytes         = 0L
                                SizeMB            = 0.0
                                IsRegistry        = $false
                                RegistryValueName = ""
                            })
                        }
                    } catch {}
                }
            }
        } catch {} finally {
            if ($null -ne $wsh) {
                try { [System.Runtime.InteropServices.Marshal]::ReleaseComObject($wsh) | Out-Null } catch {}
                $wsh = $null
            }
        }
    }

    $runKeys = @(
        "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run",
        "HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce",
        "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
        "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce",
        "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run"
    )
    $locPrefixForRun = if ($AppEntry.InstallLocation) { $AppEntry.InstallLocation.Trim().TrimEnd('\') + "\" } else { "" }
    foreach ($rk in $runKeys) {
        if (-not (Test-Path -LiteralPath $rk)) { continue }
        try {
            $props = Get-ItemProperty -LiteralPath $rk -ErrorAction SilentlyContinue
            if ($null -eq $props) { continue }
            foreach ($p in $props.PSObject.Properties) {
                if ($p.Name -in @('PSPath', 'PSParentPath', 'PSChildName', 'PSDrive', 'PSProvider')) { continue }
                $valStr = [string]$p.Value
                if ([string]::IsNullOrWhiteSpace($valStr)) { continue }
                $isAppRun = $false
                if ($locPrefixForRun -and $valStr.IndexOf($locPrefixForRun, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                    $isAppRun = $true
                } elseif ($p.Name.Equals($cleanName, [System.StringComparison]::OrdinalIgnoreCase)) {
                    $isAppRun = $true
                }
                if ($isAppRun) {
                    $runDisplayPath = "$rk -> [$($p.Name)]"
                    if ($seenPaths.Add($runDisplayPath)) {
                        $leftovers.Add([PSCustomObject]@{
                            Type              = "Startup c$([char]0x00F2)n s$([char]0x00F3)t"
                            Confidence        = "An to$([char]0x00E0)n 100%"
                            AppName           = $AppEntry.DisplayName
                            Path              = $rk
                            SizeBytes         = 0L
                            SizeMB            = 0.0
                            IsRegistry        = $true
                            RegistryValueName = $p.Name
                        })
                    }
                }
            }
        } catch {}
    }

    $regRoots = @(
        "HKCU:\Software",
        "HKLM:\SOFTWARE",
        "HKLM:\SOFTWARE\WOW6432Node"
    )

    foreach ($regRoot in $regRoots) {
        if (-not (Test-Path -LiteralPath $regRoot)) { continue }
        foreach ($kw in $nameKeywords) {
            if ($genericStopWords.Contains($kw)) { continue }
            if (Test-PathClaimedByActiveApp -CandidateName $kw -ActiveApps $activeApps) { continue }
            $regPath = Join-Path $regRoot $kw
            if (Test-Path -LiteralPath $regPath) {
                $isSafe = $true
                foreach ($ex in $exclusions) {
                    if ($kw -eq $ex) { $isSafe = $false; break }
                }
                if ($isSafe -and $seenPaths.Add($regPath)) {
                    $regConf = if ($kw.Equals($cleanName, [System.StringComparison]::OrdinalIgnoreCase) -or $kw.Length -ge 6) {
                        "Tin c$([char]0x1EAD)y cao"
                    } else {
                        "N$([char]0x00EA)n ki$([char]0x1EC3)m tra"
                    }
                    $leftovers.Add([PSCustomObject]@{
                        Type              = "Registry c$([char]0x00F2)n s$([char]0x00F3)t"
                        Confidence        = $regConf
                        AppName           = $AppEntry.DisplayName
                        Path              = $regPath
                        SizeBytes         = 0L
                        SizeMB            = 0.0
                        IsRegistry        = $true
                        RegistryValueName = ""
                    })
                }
            }
        }
    }

    if ($AppEntry.RegistryPath -and (Test-Path -LiteralPath $AppEntry.RegistryPath)) {
        if ($seenPaths.Add($AppEntry.RegistryPath)) {
            $leftovers.Add([PSCustomObject]@{
                Type              = "Registry b$([char]0x1ECB) l$([char]0x1ED7)i"
                Confidence        = "An to$([char]0x00E0)n 100%"
                AppName           = $AppEntry.DisplayName
                Path              = $AppEntry.RegistryPath
                SizeBytes         = 0L
                SizeMB            = 0.0
                IsRegistry        = $true
                RegistryValueName = ""
            })
        }
    }

    if ($resTask -or ($isSafeTargetLoc -and $null -ne $deepTypeLo -and $null -ne $deepTypeLo.GetMethod("ScanDeepAppResidualsFast"))) {
        try {
            $deepArtifacts = $null
            if ($resTask) {
                [void](Wait-TaskNonBlocking -Task $resTask -TimeoutSeconds 15)
                if ($resTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                    $deepArtifacts = $resTask.Result
                }
            } elseif (-not $script:isWindowClosing) {
                $deepArtifacts = [DuckUtil.DeepUninstallerEngine]::ScanDeepAppResidualsFast($targetLocPrefix)
            }
            if ($null -ne $deepArtifacts) {
                foreach ($art in $deepArtifacts) {
                    $artDedup = if ($art.IsRegistry -and $art.RegistryValueName) { "$($art.Path)->$($art.RegistryValueName)" } else { $art.Path }
                    if ($seenPaths.Add($artDedup)) {
                        $leftovers.Add((Convert-DeepResidualArtifactToLeftoverItem -Artifact $art -FallbackAppName $AppEntry.DisplayName))
                    }
                }
            }
        } catch {}
    }

    if ($isSafeTargetLoc -and ($null -ne $deepTypeLo)) {
        try {
            $svcListApp = $PreloadedServices
            if ($null -eq $svcListApp) {
                if ($canWaitLo -and $deepTypeLo.GetMethod("ScanServicesAndDriversAsync")) {
                    $sTaskApp = $deepTypeLo::ScanServicesAndDriversAsync()
                    [void](Wait-TaskNonBlocking -Task $sTaskApp -TimeoutSeconds 15)
                    if ($sTaskApp.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) { $svcListApp = $sTaskApp.Result }
                } elseif ($deepTypeLo.GetMethod("ScanServicesAndDrivers")) {
                    $svcListApp = $deepTypeLo::ScanServicesAndDrivers()
                }
            }
            if ($null -ne $svcListApp) {
                foreach ($se in $svcListApp) {
                    if ($script:isWindowClosing) { break }
                    if ($se.IsKernelDriver) { continue }
                    $img = $se.ResolvedImagePath
                    if ([string]::IsNullOrWhiteSpace($img)) { continue }
                    if ($img.StartsWith($targetLocPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                        $regSvcPath = "HKLM:\SYSTEM\CurrentControlSet\Services\$($se.ServiceName)"
                        if ($seenPaths.Add($regSvcPath)) {
                            $leftovers.Add([PSCustomObject]@{
                                Type              = "Service c$([char]0x00F2)n s$([char]0x00F3)t"
                                Confidence        = "An to$([char]0x00E0)n 100%"
                                AppName           = $AppEntry.DisplayName
                                Path              = $regSvcPath
                                SizeBytes         = 0L
                                SizeMB            = 0.0
                                IsRegistry        = $true
                                RegistryValueName = ""
                            })
                        }
                    }
                }
                $PreloadedServices = $svcListApp
            }
        } catch {}
    }

    $appHint = "$($AppEntry.DisplayName) $($AppEntry.Publisher) $($AppEntry.InstallLocation)"
    $vendorFam = ""
    if ($appHint -match '(?i)(360|Qihu|Qihoo|ZhuDong)') { $vendorFam = "360" }
    elseif ($appHint -match '(?i)2345') { $vendorFam = "2345" }
    elseif ($appHint -match '(?i)Kingsoft') { $vendorFam = "Kingsoft" }
    elseif ($appHint -match '(?i)Baidu') { $vendorFam = "Baidu" }

    if ($vendorFam -and ("DuckUtil.DeepUninstallerEngine" -as [type]) -and ([DuckUtil.DeepUninstallerEngine].GetMethod("IsVerifiedRogueKernelDriverFile"))) {
        try {
            $svcList = $PreloadedServices
            if ($null -eq $svcList) {
                if ([DuckUtil.DeepUninstallerEngine].GetMethod("ScanServicesAndDriversAsync") -and (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue)) {
                    $svcTask = [DuckUtil.DeepUninstallerEngine]::ScanServicesAndDriversAsync()
                    [void](Wait-TaskNonBlocking -Task $svcTask -TimeoutSeconds 15)
                    if ($svcTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                        $svcList = $svcTask.Result
                    }
                } elseif ([DuckUtil.DeepUninstallerEngine].GetMethod("ScanServicesAndDrivers")) {
                    $svcList = [DuckUtil.DeepUninstallerEngine]::ScanServicesAndDrivers()
                }
            }

            if ($null -ne $svcList) {
                foreach ($se in $svcList) {
                    if ($script:isWindowClosing) { break }
                    if (-not $se.IsKernelDriver) { continue }
                    $img = $se.ResolvedImagePath
                    if ([string]::IsNullOrWhiteSpace($img)) { continue }
                    if ([System.IO.File]::Exists($img) -and [DuckUtil.DeepUninstallerEngine]::IsVerifiedRogueKernelDriverFile($img)) {
                        $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($img)
                        $meta = "$([System.IO.Path]::GetFileName($img)) $($vi.CompanyName) $($vi.ProductName) $($vi.FileDescription)"
                        $isVendorMatch = ($meta.IndexOf($vendorFam, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) -or ($vendorFam -eq "360" -and $meta -match '(?i)(Qihu|Qihoo)')
                        if ($isVendorMatch) {
                            $regSvcPath = "HKLM:\SYSTEM\CurrentControlSet\Services\$($se.ServiceName)"
                            if ($seenPaths.Add($regSvcPath)) {
                                $leftovers.Add([PSCustomObject]@{
                                    Type              = "Driver h$([char]0x1EC7) th$([char]0x1ED1)ng c$([char]0x00F2)n s$([char]0x00F3)t"
                                    Confidence        = "An to$([char]0x00E0)n 100%"
                                    AppName           = $AppEntry.DisplayName
                                    Path              = $regSvcPath
                                    SizeBytes         = 0L
                                    SizeMB            = 0.0
                                    IsRegistry        = $true
                                    RegistryValueName = ""
                                })
                            }
                            if ($seenPaths.Add($img)) {
                                $fLen = try { (Get-Item -LiteralPath $img -Force).Length } catch { 0L }
                                $leftovers.Add([PSCustomObject]@{
                                    Type              = "Driver h$([char]0x1EC7) th$([char]0x1ED1)ng c$([char]0x00F2)n s$([char]0x00F3)t"
                                    Confidence        = "An to$([char]0x00E0)n 100%"
                                    AppName           = $AppEntry.DisplayName
                                    Path              = $img
                                    SizeBytes         = [long]$fLen
                                    SizeMB            = [math]::Round($fLen / 1MB, 2)
                                    IsRegistry        = $false
                                    RegistryValueName = ""
                                })
                            }
                        }
                    }
                }
            }
        } catch {}
    }

    if ($AppEntry.Id -and $AppEntry.Id -like 'MSIX\*' -and $env:LOCALAPPDATA) {
        try {
            $pkgFullMsix = $AppEntry.Id.Substring(5)
            $pkgParts = $pkgFullMsix -split '_'
            if ($pkgParts.Count -ge 2) {
                $pfnCand = "$($pkgParts[0])_$($pkgParts[$pkgParts.Count - 1])"
                $pfnDir = Join-Path (Join-Path $env:LOCALAPPDATA "Packages") $pfnCand
                if ((Test-Path -LiteralPath $pfnDir) -and $seenPaths.Add($pfnDir)) {
                    $pfnSz = [DuckUtil.DeepUninstallerEngine]::GetDirectorySizeFast($pfnDir, 4)
                    $leftovers.Add([PSCustomObject]@{
                        Type              = "Th$([char]0x01B0) m$([char]0x1EE5)c r$([char]0x00E1)c AppData"
                        Confidence        = "An to$([char]0x00E0)n 100%"
                        AppName           = $AppEntry.DisplayName
                        Path              = $pfnDir
                        SizeBytes         = [long]$pfnSz
                        SizeMB            = [math]::Round($pfnSz / 1MB, 2)
                        IsRegistry        = $false
                        RegistryValueName = ""
                    })
                }
            }
        } catch {}
    }

    return @($leftovers)
}

function Find-SystemOrphanLeftovers {
    param(
        [Parameter(Mandatory = $false)]$InstalledApps,
        [Parameter(Mandatory = $false)]$CatalogApps,
        [switch]$AllowCancel
    )

    $engType = "DuckUtil.DeepUninstallerEngine" -as [type]
    $canWaitOrph = ($null -ne (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue))
    $cancelCbOrph = if ($AllowCancel) { { [bool]$script:cancelRequested } } else { $null }

    if ($null -eq $InstalledApps -or $InstalledApps.Count -eq 0) {
        if ($canWaitOrph -and $null -ne $engType -and $null -ne $engType.GetMethod("GetInstalledAppsAsync")) {
            $iaTask = $engType::GetInstalledAppsAsync()
            [void](Wait-TaskNonBlocking -Task $iaTask -TimeoutSeconds 45 -CancelCheck $cancelCbOrph)
            if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return @() }
            if ($iaTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion -and $null -ne $iaTask.Result) {
                $InstalledApps = @($iaTask.Result)
            } else {
                $InstalledApps = @(Get-SystemInstalledAppsFast)
            }
        } else {
            $InstalledApps = @(Get-SystemInstalledAppsFast)
        }
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return @() }

    $orphans = [System.Collections.Generic.List[object]]::new()
    $seenPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

    $exclusions = [string[]]@(
        'Microsoft', 'Windows', 'Intel', 'AMD', 'NVIDIA', 'Google', 'Common', 'Common Files',
        'WindowsApps', 'ModifiableWindowsApps', 'Internet Explorer', 'Windows Defender',
        'Windows Mail', 'Windows Media Player', 'Windows NT', 'Windows Photo Viewer',
        'Windows Portable Devices', 'Windows Security', 'Windows Sidebar', 'WindowsPowerShell',
        'PowerShell', 'dotnet', 'Reference Assemblies', 'MSBuild', 'Package Cache',
        'Packages', 'Temp', 'System32', 'Uninstall Information'
    )

    $baseInstalledList = [System.Collections.Generic.List[DuckUtil.InstalledAppInfo]]::new()
    $activeApps = [System.Collections.Generic.List[object]]::new()
    $activeNormIdentities = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $activeInstallLocs = [System.Collections.Generic.List[string]]::new()
    foreach ($ia in $InstalledApps) {
        if ($null -eq $ia) { continue }
        if ($ia.Id -like 'ORPHAN\*') { continue }
        if ($ia -is [DuckUtil.InstalledAppInfo]) { $baseInstalledList.Add($ia) }
        if (-not $ia.IsBrokenOrphan) {
            $activeApps.Add($ia)
            $normIa = Get-NormalizedAppIdentity $ia.DisplayName
            if ($normIa) { $activeNormIdentities.Add($normIa) | Out-Null }
            if (-not [string]::IsNullOrWhiteSpace($ia.InstallLocation)) {
                $activeInstallLocs.Add($ia.InstallLocation.Trim().TrimEnd('\'))
            }
            if ($ia.PSObject.Properties['DataLocation'] -and -not [string]::IsNullOrWhiteSpace($ia.DataLocation)) {
                $activeInstallLocs.Add($ia.DataLocation.Trim().TrimEnd('\'))
            }
        }
    }

    # 1. Run Comprehensive Parallel C# Forensic Orphan Scanner (non-blocking)
    $usedComprehensive = $false
    if ($null -ne $engType -and $null -ne $engType.GetMethod("ScanSystemOrphansComprehensiveAsync")) {
        try {
            $compTask = $engType::ScanSystemOrphansComprehensiveAsync($baseInstalledList, $true)
            if ($canWaitOrph) {
                [void](Wait-TaskNonBlocking -Task $compTask -TimeoutSeconds 45 -CancelCheck $cancelCbOrph)
            } else {
                try { [void]$compTask.Wait(45000) } catch {}
            }
            if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return @() }
            if ($compTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion -and $null -ne $compTask.Result) {
                $usedComprehensive = $true
                foreach ($art in $compTask.Result.Artifacts) {
                    if ($null -eq $art -or [string]::IsNullOrWhiteSpace($art.Path)) { continue }
                    $artDedup = if ($art.IsRegistry -and $art.RegistryValueName) { "$($art.Path)->$($art.RegistryValueName)" } else { [string]$art.Path }
                    if ($seenPaths.Add($artDedup)) {
                        $orphans.Add((Convert-DeepResidualArtifactToLeftoverItem -Artifact $art -BracketBadge))
                    }
                }
            }
        } catch {}
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return @() }

    # 2. Broken ARP / MSI / MSIX Uninstall Registry Entries + their specific leftovers
    foreach ($app in $InstalledApps) {
        if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { break }
        if ($null -eq $app -or -not $app.IsBrokenOrphan) { continue }
        if ($app.Id -like 'ORPHAN\*') { continue }

        if ($app.RegistryPath -and (Test-Path -LiteralPath $app.RegistryPath)) {
            if ($seenPaths.Add($app.RegistryPath)) {
                $orphans.Add([PSCustomObject]@{
                    Type              = "[Registry b$([char]0x1ECB) l$([char]0x1ED7)i]"
                    Confidence        = "An to$([char]0x00E0)n 100%"
                    AppName           = $app.DisplayName
                    Path              = $app.RegistryPath
                    SizeBytes         = 0L
                    SizeMB            = 0.0
                    IsRegistry        = $true
                    RegistryValueName = ""
                })
            }
        }

        $brokenNorm = Get-NormalizedAppIdentity $app.DisplayName
        if ($brokenNorm -and $activeNormIdentities.Contains($brokenNorm)) { continue }

        $appLeftovers = Find-AppLeftovers -AppEntry $app -AllInstalledApps $InstalledApps
        foreach ($lo in $appLeftovers) {
            $dedupKey = if ($lo.RegistryValueName) { "$($lo.Path)->$($lo.RegistryValueName)" } else { $lo.Path }
            if ($seenPaths.Add($dedupKey)) {
                $badgeType = if ($lo.Type -like '[*') { [string]$lo.Type } else { "[$($lo.Type)]" }
                $orphans.Add([PSCustomObject]@{
                    Type               = $badgeType
                    Confidence         = if ($lo.Confidence) { $lo.Confidence } else { "An to$([char]0x00E0)n 100%" }
                    AppName            = $app.DisplayName
                    Path               = $lo.Path
                    SizeBytes          = [long]$lo.SizeBytes
                    SizeMB             = [double]$lo.SizeMB
                    IsRegistry         = [bool]$lo.IsRegistry
                    RegistryValueName  = [string]$lo.RegistryValueName
                    RegistryValueNames = if ($lo.PSObject.Properties['RegistryValueNames']) { $lo.RegistryValueNames } else { $null }
                    TaskName           = if ($lo.PSObject.Properties['TaskName']) { [string]$lo.TaskName } else { "" }
                })
            }
        }
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return @() }

    # 3. Uninstalled Catalog AppData / ProgramData leftovers (catches uninstalled catalog apps even with no dead firewall/service trace!)
    $candAppDataPaths = [System.Collections.Generic.List[string]]::new()
    $candAppDataNames = [System.Collections.Generic.List[string]]::new()
    if ($CatalogApps) {
        $installedNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        $installedIds = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($ia in $activeApps) {
            $installedNames.Add($ia.DisplayName) | Out-Null
            if ($ia.Id) { $installedIds.Add($ia.Id) | Out-Null }
        }

        $catalogInstalledIds = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        $uiBorders = Get-Variable -Name allItemBorders -Scope Script -ValueOnly -ErrorAction SilentlyContinue
        if ($uiBorders) {
            foreach ($b in $uiBorders) {
                if ($b.Tag -and $b.Tag.Status -in @("LATEST", "OUTDATED") -and $b.Tag.App) {
                    if ($b.Tag.App.ID) { $catalogInstalledIds.Add($b.Tag.App.ID) | Out-Null }
                    if ($b.Tag.DetectedId) { $catalogInstalledIds.Add($b.Tag.DetectedId) | Out-Null }
                }
            }
        }

        $localLowR = if ($env:USERPROFILE) { Join-Path $env:USERPROFILE "AppData\LocalLow" } else { "" }
        $appDataRoots = @($env:APPDATA, $env:LOCALAPPDATA, $localLowR, $env:ProgramData)
        $candPathSeen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($catApp in $CatalogApps) {
            if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { break }
            if ($catApp.ID -and $catalogInstalledIds.Contains($catApp.ID)) { continue }

            $catName = ($catApp.Name -replace '\(.*?\)', '').Trim()
            if ($catName.Length -lt 5) { continue }
            if ($exclusions -contains $catName) { continue }

            $candidateDirs = $null
            foreach ($ar in $appDataRoots) {
                if ([string]::IsNullOrWhiteSpace($ar)) { continue }
                $cand = [System.IO.Path]::Combine($ar, $catName)
                if ([System.IO.Directory]::Exists($cand)) {
                    if ($null -eq $candidateDirs) { $candidateDirs = [System.Collections.Generic.List[string]]::new() }
                    $candidateDirs.Add($cand)
                }
            }
            if ($null -eq $candidateDirs) { continue }

            $catNorm = Get-NormalizedAppIdentity $catApp.Name
            $isInstalled = $false
            if ($catNorm -and $activeNormIdentities.Contains($catNorm)) { $isInstalled = $true }
            if (-not $isInstalled -and $catApp.ID -and $installedIds.Contains($catApp.ID)) { $isInstalled = $true }
            if (-not $isInstalled) {
                foreach ($inName in $installedNames) {
                    if ($inName.IndexOf($catName, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                        $isInstalled = $true
                        break
                    }
                }
            }
            if (-not $isInstalled -and $catApp.Aliases) {
                foreach ($al in $catApp.Aliases) {
                    if ([string]::IsNullOrWhiteSpace($al)) { continue }
                    $alNorm = Get-NormalizedAppIdentity $al
                    if ($alNorm -and $activeNormIdentities.Contains($alNorm)) {
                        $isInstalled = $true
                        break
                    }
                    foreach ($inName in $installedNames) {
                        if ($inName.IndexOf($al, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                            $isInstalled = $true
                            break
                        }
                    }
                    if ($isInstalled) { break }
                }
            }
            if (-not $isInstalled -and (Test-PathClaimedByActiveApp -CandidateName $catName -ActiveApps $activeApps)) {
                $isInstalled = $true
            }
            if (-not $isInstalled) {
                foreach ($cand in $candidateDirs) {
                    $full = Resolve-PathSafe -Path $cand
                    if ($full -and -not $seenPaths.Contains($full) -and $candPathSeen.Add($full)) {
                        $candAppDataPaths.Add($full)
                        $candAppDataNames.Add($catApp.Name)
                    }
                }
            }
        }
    }

    if ($candAppDataPaths.Count -gt 0 -and -not $script:isWindowClosing -and -not ($AllowCancel -and $script:cancelRequested)) {
        if ($null -ne $engType -and $null -ne $engType.GetMethod("ScanHollowPathsWithSizesAsync")) {
            $hollowAppDataTask = $engType::ScanHollowPathsWithSizesAsync($candAppDataPaths.ToArray(), $candAppDataNames.ToArray())
            if ($canWaitOrph) {
                [void](Wait-TaskNonBlocking -Task $hollowAppDataTask -TimeoutSeconds 30 -CancelCheck $cancelCbOrph)
            } else {
                try { [void]$hollowAppDataTask.Wait(30000) } catch {}
            }
            if ($hollowAppDataTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion -and $null -ne $hollowAppDataTask.Result) {
                foreach ($hr in $hollowAppDataTask.Result) {
                    if ($hr -and $hr.Path -and $seenPaths.Add($hr.Path)) {
                        $confCat = if ([long]$hr.SizeBytes -gt 104857600L) { "N$([char]0x00EA)n ki$([char]0x1EC3)m tra" } else { "Tin c$([char]0x1EAD)y cao" }
                        $orphans.Add([PSCustomObject]@{
                            Type              = "[Th$([char]0x01B0) m$([char]0x1EE5)c r$([char]0x00E1)c AppData]"
                            Confidence        = $confCat
                            AppName           = $hr.AppName
                            Path              = $hr.Path
                            SizeBytes         = [long]$hr.SizeBytes
                            SizeMB            = [math]::Round($hr.SizeBytes / 1MB, 2)
                            IsRegistry        = $false
                            RegistryValueName = ""
                        })
                    }
                }
            }
        }
    }

    # Sort cleanly: Safe100 -> High -> Check, largest SizeBytes first within each tier
    $sortedOrphans = @($orphans | Sort-Object -Property `
        @{ Expression = { if ($_.Confidence -like '*ki*m tra*') { 2 } elseif ($_.Confidence -like '*cao*') { 1 } else { 0 } }; Ascending = $true }, `
        @{ Expression = { [long]$_.SizeBytes }; Descending = $true }, `
        @{ Expression = { [string]$_.AppName }; Ascending = $true })
    return $sortedOrphans
}

function Invoke-ForceStopPathLockers {
    param(
        [Parameter(Mandatory = $true)][string]$TargetPath,
        [bool]$IncludeServicesAndTasks = $true,
        [switch]$AllowCancel
    )

    $resObj = [PSCustomObject]@{
        KilledCount          = 0
        ServicesStoppedCount = 0
        TasksRemovedCount    = 0
        AccessDeniedCount    = 0
        ClosedHandlesCount   = 0
        KilledNames          = @()
        AccessDeniedNames    = @()
        SkippedSystemLockers = @()
        ClosedHandleNames    = @()
    }
    if ([string]::IsNullOrWhiteSpace($TargetPath)) { return $resObj }

    $deepType = "DuckUtil.DeepUninstallerEngine" -as [type]
    if (-not $deepType) { return $resObj }

    if ($null -ne $deepType.GetMethod("PrewarmElevationCacheAsync") -and ($null -ne (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue))) {
        try {
            $pwTask = $deepType::PrewarmElevationCacheAsync()
            $pwCancel = if ($AllowCancel) { { [bool]$script:cancelRequested } } else { $null }
            [void](Wait-TaskNonBlocking -Task $pwTask -TimeoutSeconds 4 -CancelCheck $pwCancel)
        } catch {}
    } elseif ($null -ne $deepType.GetMethod("PrewarmElevationCache")) {
        try { [DuckUtil.DeepUninstallerEngine]::PrewarmElevationCache() } catch {}
    }

    $hasForceStopAsync = ($null -ne $deepType.GetMethod("ForceStopDirectoryLockersAsync")) -and ($null -ne (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue))
    $hasForceStop = @($deepType.GetMethods() | Where-Object { $_.Name -eq "ForceStopDirectoryLockers" -and $_.GetParameters().Count -eq 2 }).Count -gt 0
    if ($hasForceStopAsync) {
        $fsTask = $deepType::ForceStopDirectoryLockersAsync($TargetPath, $IncludeServicesAndTasks)
        $fsCancelCb = if ($AllowCancel) { { [bool]$script:cancelRequested } } else { $null }
        [void](Wait-TaskNonBlocking -Task $fsTask -TimeoutSeconds 45 -CancelCheck $fsCancelCb)
        $rpt = if ($fsTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
            $fsTask.Result
        } elseif ($hasForceStop -and -not $script:isWindowClosing -and -not ($AllowCancel -and $script:cancelRequested)) {
            $deepType::ForceStopDirectoryLockers($TargetPath, $IncludeServicesAndTasks)
        } else { $null }
    } elseif ($hasForceStop) {
        $rpt = $deepType::ForceStopDirectoryLockers($TargetPath, $IncludeServicesAndTasks)
    }
    if ($hasForceStopAsync -or $hasForceStop) {
        if ($rpt) {
            $resObj.KilledCount          = [int]$rpt.KilledCount
            $resObj.ServicesStoppedCount = [int]$rpt.ServicesStoppedCount
            $resObj.TasksRemovedCount    = [int]$rpt.TasksRemovedCount
            $resObj.AccessDeniedCount    = [int]$rpt.AccessDeniedCount
            $resObj.KilledNames          = @($rpt.KilledNames)
            $resObj.AccessDeniedNames    = @($rpt.AccessDeniedNames)
            $resObj.SkippedSystemLockers = @($rpt.SkippedSystemLockers)
            if ($rpt.PSObject.Properties["ClosedHandlesCount"]) {
                $resObj.ClosedHandlesCount = [int]$rpt.ClosedHandlesCount
            }
            if ($rpt.PSObject.Properties["ClosedHandleNames"]) {
                $resObj.ClosedHandleNames = @($rpt.ClosedHandleNames)
            }
        }
    } else {
        if ($IncludeServicesAndTasks) {
            $resObj.ServicesStoppedCount = [int]$deepType::DisableAndRemoveServicesInDirectory($TargetPath)
            $resObj.TasksRemovedCount    = [int]$deepType::RemoveScheduledTasksInDirectory($TargetPath)
        }
        $resObj.KilledCount = [int]$deepType::StopProcessesInDirectory($TargetPath)
    }

    if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
        if ($resObj.KilledCount -gt 0 -or $resObj.ServicesStoppedCount -gt 0 -or $resObj.TasksRemovedCount -gt 0) {
            Log-Text "[FORCE-STOP] $([char]0x0110)$([char]0x00E3) bu$([char]0x1ED9)c d$([char]0x1EEB)ng $($resObj.KilledCount) ti$([char]0x1EBF)n tr$([char]0x00EC)nh $([char]0x0111)ang kh$([char]0x00F3)a, $($resObj.ServicesStoppedCount) d$([char]0x1ECB)ch v$([char]0x1EE5), $($resObj.TasksRemovedCount) t$([char]0x00E1)c v$([char]0x1EE5) t$([char]0x1EA1)i: $TargetPath"
        }
        if ($resObj.ClosedHandlesCount -gt 0) {
            Log-Text "[HANDLE-UNLOCK] $([char]0x0110)$([char]0x00E3) th$([char]0x00E1)o $($resObj.ClosedHandlesCount) handle $([char]0x0111)ang gi$([char]0x1EEF) t$([char]0x1EC7)p/th$([char]0x01B0) m$([char]0x1EE5)c t$([char]0x1EEB) xa: $($resObj.ClosedHandleNames -join ', ')"
        }
        if ($resObj.AccessDeniedCount -gt 0) {
            Log-Text "[!] T$([char]0x1EEB) ch$([char]0x1ED1)i quy$([char]0x1EC1)n (Self-Defense / Driver b$([char]0x1EA3)o v$([char]0x1EC7)): $($resObj.AccessDeniedNames -join ', ')"
        }
        if ($resObj.SkippedSystemLockers.Count -gt 0) {
            Log-Text "[!] H$([char]0x1EC7) th$([char]0x1ED1)ng $([char]0x0111)ang gi$([char]0x1EEF) handle: $($resObj.SkippedSystemLockers -join ', ')"
        }
    }
    return $resObj
}

function Restart-WindowsExplorerForUnlock {
    param([scriptblock]$OnUnlockedCallback = $null)

    if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
        Log-Text "[*] $([char]0x0110)ang kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i nhanh Windows Explorer $([char]0x0111)$([char]0x1EC3) nh$([char]0x1EA3) kh$([char]0x00F3)a t$([char]0x1EC7)p..."
    }
    try {
        Get-Process -Name "explorer" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        Start-Sleep -Milliseconds 350
        if ($null -ne $OnUnlockedCallback) {
            & $OnUnlockedCallback
        }
    } finally {
        $waitDeadline = [DateTime]::UtcNow.AddMilliseconds(1500)
        $explorerBack = $false
        while ([DateTime]::UtcNow -lt $waitDeadline) {
            $exProcs = @(Get-Process -Name "explorer" -ErrorAction SilentlyContinue)
            if ($exProcs.Count -gt 0) {
                $explorerBack = $true
                break
            }
            Start-Sleep -Milliseconds 150
        }
        if (-not $explorerBack) {
            try {
                Start-Process (Join-Path $env:WINDIR "explorer.exe") | Out-Null
            } catch {}
        }
    }
    if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
        Log-Text "[OK] Windows Explorer $([char]0x0111)$([char]0x00E3) kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i; ti$([char]0x1EBF)p t$([char]0x1EE5)c x$([char]0x00F3)a m$([char]0x1EE5)c $([char]0x0111)ang gi$([char]0x1EEF) kh$([char]0x00F3)a..."
    }
}

function Show-LeftoverReviewDialog {
    param(
        [Parameter(Mandatory = $false)]$OwnerWindow,
        [Parameter(Mandatory = $true)][object[]]$Items,
        [Parameter(Mandatory = $false)][string]$Title = "Duy$([char]0x1EC7)t & D$([char]0x1ECD)n S$([char]0x1EA1)ch R$([char]0x00E1)c T$([char]0x1ED3)n D$([char]0x01B0)",
        [bool]$ForceStopByDefault = $true
    )

    if ($script:isWindowClosing -or $null -eq $Items -or $Items.Count -eq 0) {
        return [PSCustomObject]@{ Confirmed = $false; RemovedCount = 0; FreedBytes = 0L; RebootScheduled = 0; AccessDeniedCount = 0 }
    }

    $dialog = New-Object System.Windows.Window
    $dialog.Title = $Title
    $dialog.Width = 940
    $dialog.Height = 590
    $dialog.MinWidth = 780
    $dialog.MinHeight = 460
    $dialog.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterScreen
    $canAttachOwner = $false
    if ($OwnerWindow -and ($OwnerWindow -is [System.Windows.Window]) -and -not $script:isWindowClosing) {
        try {
            if ($OwnerWindow.IsLoaded -and $OwnerWindow.IsVisible) {
                $src = [System.Windows.PresentationSource]::FromVisual($OwnerWindow)
                $hwndSrc = $src -as [System.Windows.Interop.HwndSource]
                $ownerHwnd = (New-Object System.Windows.Interop.WindowInteropHelper($OwnerWindow)).Handle
                if ($null -ne $hwndSrc -and (-not $hwndSrc.IsDisposed) -and $ownerHwnd -ne [IntPtr]::Zero) {
                    $canAttachOwner = $true
                }
            }
        } catch {
            $canAttachOwner = $false
        }
    }
    if ($canAttachOwner) {
        try {
            $dialog.Owner = $OwnerWindow
            $dialog.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterOwner
        } catch {
            try { $dialog.Owner = $null } catch {}
            $dialog.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterScreen
        }
    }
    if (-not $script:loDialogPalette) {
        $bcCache = New-Object System.Windows.Media.BrushConverter
        $mkC = {
            param([string]$hex)
            $br = $bcCache.ConvertFromString($hex)
            if ($br -and $br.CanFreeze) { $br.Freeze() }
            return $br
        }
        $script:loDialogPalette = @{
            Bg           = & $mkC "#0A0E15"
            Fg           = & $mkC "#F1F5F9"
            TitleFg      = & $mkC "#38BDF8"
            ItemBg       = & $mkC "#101520"
            ItemBorder   = & $mkC "#1E293B"
            White        = & $mkC "#FFFFFF"
            ConfBg       = & $mkC "#064E3B"
            ConfBorder   = & $mkC "#059669"
            ConfFg       = & $mkC "#6EE7B7"
            ConfHighBg   = & $mkC "#0C4A6E"
            ConfHighBdr  = & $mkC "#0284C7"
            ConfHighFg   = & $mkC "#7DD3FC"
            ConfChkBg    = & $mkC "#451A03"
            ConfChkBdr   = & $mkC "#D97706"
            ConfChkFg    = & $mkC "#FCD34D"
            ItemTitleFg  = & $mkC "#E2E8F0"
            PathFg       = & $mkC "#64748B"
            SizeRegFg    = & $mkC "#94A3B8"
            SizeFileFg   = & $mkC "#38BDF8"
            BtnBg        = & $mkC "#1E293B"
            BtnFg        = & $mkC "#CBD5E1"
            BottomBg     = & $mkC "#0D121B"
            WarnFg       = & $mkC "#FBBF24"
            DelBg        = & $mkC "#7F1D1D"
            DelFg        = & $mkC "#FEE2E2"
            DelBorder    = & $mkC "#991B1B"
            BadgeMap     = @{
                "Ring0"    = (& $mkC "#7F1D1D")
                "Service"  = (& $mkC "#B45309")
                "Task"     = (& $mkC "#C2410C")
                "Registry" = (& $mkC "#991B1B")
                "Startup"  = (& $mkC "#9F1239")
                "Firewall" = (& $mkC "#0E7490")
                "AppPath"  = (& $mkC "#9A3412")
                "AppData"  = (& $mkC "#B45309")
                "Hollow"   = (& $mkC "#1D4ED8")
                "Shortcut" = (& $mkC "#6D28D9")
                "Dump"     = (& $mkC "#7E22CE")
                "Default"  = (& $mkC "#0F766E")
            }
        }
    }
    $pal = $script:loDialogPalette

    $dialog.Background = $pal.Bg
    $dialog.Foreground = $pal.Fg
    $dialog.FontFamily = New-Object System.Windows.Media.FontFamily("Segoe UI")
    [System.Windows.Media.TextOptions]::SetTextFormattingMode($dialog, [System.Windows.Media.TextFormattingMode]::Display)
    [System.Windows.Media.TextOptions]::SetTextRenderingMode($dialog, [System.Windows.Media.TextRenderingMode]::ClearType)
    $dialog.WindowStyle = [System.Windows.WindowStyle]::SingleBorderWindow
    $dialog.UseLayoutRounding = $true
    $dialog.SnapsToDevicePixels = $true
    $dialog.Add_SourceInitialized({
        if ('DuckUtil.ConsoleHelper' -as [type]) {
            try {
                $hDlg = (New-Object System.Windows.Interop.WindowInteropHelper($dialog)).Handle
                [DuckUtil.ConsoleHelper]::EnableDarkTitleBar($hDlg)
            } catch {}
        }
    })

    try {
        if (-not $script:loDialogResources) {
            $rdXaml = @'
<ResourceDictionary xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
    <Style TargetType="{x:Type CheckBox}">
        <Setter Property="SnapsToDevicePixels" Value="True"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type CheckBox}">
                    <StackPanel Orientation="Horizontal" Background="Transparent" VerticalAlignment="Center">
                        <Border x:Name="box" Width="15" Height="15" CornerRadius="1" Background="#131B29" BorderBrush="#42536D" BorderThickness="1" VerticalAlignment="Center">
                            <Path x:Name="checkMark" Visibility="Collapsed" Data="M 2.2,6.2 L 5.2,9.2 L 10.8,3.2" Stroke="#FFFFFF" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ContentPresenter x:Name="cp" Visibility="Collapsed" Margin="7,0,0,0" VerticalAlignment="Center"/>
                    </StackPanel>
                    <ControlTemplate.Triggers>
                        <Trigger Property="HasContent" Value="True">
                            <Setter TargetName="cp" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="box" Property="BorderBrush" Value="#38BDF8"/>
                            <Setter TargetName="box" Property="Background" Value="#192335"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="box" Property="Background" Value="#0284C7"/>
                            <Setter TargetName="box" Property="BorderBrush" Value="#38BDF8"/>
                            <Setter TargetName="checkMark" Property="Visibility" Value="Visible"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style TargetType="{x:Type Button}">
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="BorderBrush" Value="#2F3E57"/>
        <Setter Property="HorizontalContentAlignment" Value="Center"/>
        <Setter Property="VerticalContentAlignment" Value="Center"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type Button}">
                    <Border x:Name="b" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="2" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
                        <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="{TemplateBinding VerticalContentAlignment}"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="b" Property="Opacity" Value="0.88"/>
                            <Setter TargetName="b" Property="BorderBrush" Value="#38BDF8"/>
                        </Trigger>
                        <Trigger Property="IsPressed" Value="True">
                            <Setter TargetName="b" Property="Opacity" Value="0.72"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter TargetName="b" Property="Opacity" Value="0.45"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
</ResourceDictionary>
'@
            $script:loDialogResources = [System.Windows.Markup.XamlReader]::Parse($rdXaml)
        }
        if ($script:loDialogResources) {
            $dialog.Resources = $script:loDialogResources
        }
    } catch {}

    $rootGrid = New-Object System.Windows.Controls.Grid
    $rowTop = New-Object System.Windows.Controls.RowDefinition; $rowTop.Height = [System.Windows.GridLength]::Auto
    $rowList = New-Object System.Windows.Controls.RowDefinition; $rowList.Height = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
    $rowBottom = New-Object System.Windows.Controls.RowDefinition; $rowBottom.Height = [System.Windows.GridLength]::Auto
    $rootGrid.RowDefinitions.Add($rowTop) | Out-Null
    $rootGrid.RowDefinitions.Add($rowList) | Out-Null
    $rootGrid.RowDefinitions.Add($rowBottom) | Out-Null

    $headerPanel = New-Object System.Windows.Controls.StackPanel
    $headerPanel.Margin = New-Object System.Windows.Thickness(18, 14, 18, 10)
    $titleBlock = New-Object System.Windows.Controls.TextBlock
    $titleBlock.Text = $Title
    $titleBlock.FontSize = 15
    $titleBlock.FontWeight = [System.Windows.FontWeights]::Bold
    $titleBlock.Foreground = $pal.TitleFg
    $headerPanel.Children.Add($titleBlock) | Out-Null

    $safeCntHdr = 0
    $chkCntHdr = 0
    [long]$totBytesHdr = 0L
    foreach ($itH in $Items) {
        if ($itH.SizeBytes) { $totBytesHdr += [long]$itH.SizeBytes }
        if ($itH.Confidence -like "*ki$([char]0x1EC3)m tra*") { $chkCntHdr++ } else { $safeCntHdr++ }
    }
    $totMbHdr = [math]::Round($totBytesHdr / 1MB, 2)
    $subHeaderBlock = New-Object System.Windows.Controls.TextBlock
    $subHeaderBlock.Text = "T$([char]0x1ED5)ng $($Items.Count) m$([char]0x1EE5)c ($safeCntHdr an to$([char]0x00E0)n/tin c$([char]0x1EAD)y cao $([char]0x2022) $chkCntHdr n$([char]0x00EA)n ki$([char]0x1EC3)m tra $([char]0x2022) ~$totMbHdr MB). M$([char]0x1EE5)c 'N$([char]0x00EA)n ki$([char]0x1EC3)m tra' m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh b$([char]0x1ECF) ch$([char]0x1ECD)n $([char]0x0111)$([char]0x1EC3) b$([char]0x1EA3)o v$([char]0x1EC7) d$([char]0x1EEF) li$([char]0x1EC7)u."
    $subHeaderBlock.FontSize = 11.5
    $subHeaderBlock.Foreground = $pal.SizeRegFg
    $subHeaderBlock.Margin = New-Object System.Windows.Thickness(0, 3, 0, 0)
    $headerPanel.Children.Add($subHeaderBlock) | Out-Null

    [System.Windows.Controls.Grid]::SetRow($headerPanel, 0)
    $rootGrid.Children.Add($headerPanel) | Out-Null

    $scrollViewer = New-Object System.Windows.Controls.ScrollViewer
    $scrollViewer.VerticalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Auto
    $scrollViewer.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Disabled
    $scrollViewer.CanContentScroll = $false
    $scrollViewer.Margin = New-Object System.Windows.Thickness(18, 0, 18, 10)
    if ("DuckUtil.SmoothScrollController" -as [type]) {
        try { $null = [DuckUtil.SmoothScrollController]::Attach($scrollViewer) } catch {}
    }

    $itemsStack = New-Object System.Windows.Controls.StackPanel
    [System.Windows.Controls.Grid]::SetIsSharedSizeScope($itemsStack, $true)
    $itemCheckBoxes = [System.Collections.Generic.List[System.Windows.Controls.CheckBox]]::new()

    $brLoItemBg     = $pal.ItemBg
    $brLoItemBorder = $pal.ItemBorder
    $brLoWhite      = $pal.White
    $brLoConfBg     = $pal.ConfBg
    $brLoConfBorder = $pal.ConfBorder
    $brLoConfFg     = $pal.ConfFg
    $brLoTitleFg    = $pal.ItemTitleFg
    $brLoPathFg     = $pal.PathFg
    $brLoSizeRegFg  = $pal.SizeRegFg
    $brLoSizeFileFg = $pal.SizeFileFg
    $brLoBtnBg      = $pal.BtnBg
    $brLoBtnFg      = $pal.BtnFg
    $brLoBadgeMap   = $pal.BadgeMap

    $itemsStack.AddHandler(
        [System.Windows.Controls.Primitives.ButtonBase]::ClickEvent,
        [System.Windows.RoutedEventHandler]{
            param($sender, $e)
            $btn = $e.OriginalSource -as [System.Windows.Controls.Button]
            if (-not $btn) { return }
            $tg = $btn.Tag
            if ($null -eq $tg) { return }
            try {
                if ($tg.IsRegistry) {
                    $rawKey = $tg.Path -replace '^HKCU:\\', 'HKEY_CURRENT_USER\' -replace '^HKLM:\\', 'HKEY_LOCAL_MACHINE\' -replace '^HKCR:\\', 'HKEY_CLASSES_ROOT\'
                    $regApplet = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Applets\Regedit"
                    if (-not (Test-Path -LiteralPath $regApplet)) {
                        New-Item -Path $regApplet -Force | Out-Null
                    }
                    Set-ItemProperty -LiteralPath $regApplet -Name "LastKey" -Value "Computer\$rawKey" -ErrorAction SilentlyContinue
                    Start-Process "regedit.exe"
                } else {
                    if (Test-Path -LiteralPath $tg.Path) {
                        Start-Process "explorer.exe" -ArgumentList "/select,`"$($tg.Path)`""
                    }
                }
            } catch {}
        }
    )

    $pipeLoType = "DuckUtil.UiAssetPipeline" -as [type]
    $hasFastLoRow = ($null -ne $pipeLoType) -and ($null -ne $pipeLoType.GetMethod("CreateLeftoverItemRow"))

    foreach ($item in $Items) {
        $badgeKey = switch -Wildcard ($item.Type) {
            "*Driver*" { "Ring0" }
            "*Service*" { "Service" }
            "*Task*" { "Task" }
            "*Firewall*" { "Firewall" }
            "*App Path*" { "AppPath" }
            "*Context*" { "Shortcut" }
            "*Registry*" { "Registry" }
            "*Startup*" { "Startup" }
            "*R$([char]0x00E1)c AppData*" { "AppData" }
            "*Th$([char]0x01B0) m$([char]0x1EE5)c c$([char]0x00F2)n s$([char]0x00F3)t*" { "AppData" }
            "*Th$([char]0x01B0) m$([char]0x1EE5)c r$([char]0x1ED7)ng*" { "Hollow" }
            "*Start Menu*" { "Hollow" }
            "*V$([char]0x1ECF) th$([char]0x01B0) m$([char]0x1EE5)c*" { "Hollow" }
            "*Shortcut*" { "Shortcut" }
            "*Crash Dump*" { "Dump" }
            default { "Default" }
        }
        $badgeBrush = $brLoBadgeMap[$badgeKey]
        $displayPathText = if ($item.RegistryValueName) { "$($item.Path) [Value: $($item.RegistryValueName)]" } else { [string]$item.Path }
        $safeSizeMb = if ($null -ne $item.SizeMB) { try { [double]$item.SizeMB } catch { 0.0 } } else { 0.0 }
        $sizeLabel = if ($item.IsRegistry) { "Registry" } else { "$([string]::Format('{0:N2}', $safeSizeMb)) MB" }
        $confLabel = if ($item.Confidence) { [string]$item.Confidence } else { "An to$([char]0x00E0)n 100%" }
        $isConfCheck = ($confLabel -like "*ki$([char]0x1EC3)m tra*")
        $isConfHigh = (-not $isConfCheck) -and ($confLabel -like "*cao*")
        $rowConfBg = if ($isConfCheck -and $pal.ConfChkBg) { $pal.ConfChkBg } elseif ($isConfHigh -and $pal.ConfHighBg) { $pal.ConfHighBg } else { $brLoConfBg }
        $rowConfBdr = if ($isConfCheck -and $pal.ConfChkBdr) { $pal.ConfChkBdr } elseif ($isConfHigh -and $pal.ConfHighBdr) { $pal.ConfHighBdr } else { $brLoConfBorder }
        $rowConfFg = if ($isConfCheck -and $pal.ConfChkFg) { $pal.ConfChkFg } elseif ($isConfHigh -and $pal.ConfHighFg) { $pal.ConfHighFg } else { $brLoConfFg }
        $defChecked = (-not $isConfCheck)

        if ($hasFastLoRow) {
            $outCb = $null
            $outBtn = $null
            $itemBorder = [DuckUtil.UiAssetPipeline]::CreateLeftoverItemRow(
                $item,
                [string]$item.Type,
                $confLabel,
                [string]$item.AppName,
                $displayPathText,
                $sizeLabel,
                [bool]$item.IsRegistry,
                $brLoItemBg,
                $brLoItemBorder,
                $badgeBrush,
                $brLoWhite,
                $rowConfBg,
                $rowConfBdr,
                $rowConfFg,
                $brLoTitleFg,
                $brLoPathFg,
                $brLoSizeRegFg,
                $brLoSizeFileFg,
                $brLoBtnBg,
                $brLoBtnFg,
                [ref]$outCb,
                [ref]$outBtn
            )
            if ($outCb -and -not $defChecked) { $outCb.IsChecked = $false }
            $itemCheckBoxes.Add($outCb)
            $itemsStack.Children.Add($itemBorder) | Out-Null
            continue
        }

        $itemBorder = New-Object System.Windows.Controls.Border
        $itemBorder.Background = $brLoItemBg
        $itemBorder.BorderBrush = $brLoItemBorder
        $itemBorder.BorderThickness = New-Object System.Windows.Thickness(1)
        $itemBorder.CornerRadius = New-Object System.Windows.CornerRadius(2)
        $itemBorder.Margin = New-Object System.Windows.Thickness(0, 0, 0, 6)
        $itemBorder.Padding = New-Object System.Windows.Thickness(10, 8, 10, 8)

        $itemGrid = New-Object System.Windows.Controls.Grid
        $c0 = New-Object System.Windows.Controls.ColumnDefinition; $c0.Width = [System.Windows.GridLength]::Auto
        $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c1.Width = [System.Windows.GridLength]::Auto
        $c2 = New-Object System.Windows.Controls.ColumnDefinition; $c2.Width = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
        $c3 = New-Object System.Windows.Controls.ColumnDefinition; $c3.Width = [System.Windows.GridLength]::Auto
        $c4 = New-Object System.Windows.Controls.ColumnDefinition; $c4.Width = [System.Windows.GridLength]::Auto
        $itemGrid.ColumnDefinitions.Add($c0) | Out-Null
        $itemGrid.ColumnDefinitions.Add($c1) | Out-Null
        $itemGrid.ColumnDefinitions.Add($c2) | Out-Null
        $itemGrid.ColumnDefinitions.Add($c3) | Out-Null
        $itemGrid.ColumnDefinitions.Add($c4) | Out-Null

