    $btnDelete = New-Object System.Windows.Controls.Button
    $btnDelete.Content = "X$([char]0x00F3)a S$([char]0x1EA1)ch M$([char]0x1EE5)c $([char]0x0110)$([char]0x00E3) Ch$([char]0x1ECD)n"
    $btnDelete.Height = 32
    $btnDelete.Padding = New-Object System.Windows.Thickness(16, 0, 16, 1)
    $btnDelete.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $btnDelete.VerticalContentAlignment = [System.Windows.VerticalAlignment]::Center
    $btnDelete.Background = $pal.DelBg
    $btnDelete.Foreground = $pal.DelFg
    $btnDelete.BorderBrush = $pal.DelBorder
    $btnDelete.FontWeight = [System.Windows.FontWeights]::SemiBold
    $btnDelete.Add_Click({
        $checkedItems = @($itemCheckBoxes | Where-Object { $_.IsChecked } | ForEach-Object { $_.Tag })
        if ($checkedItems.Count -eq 0) {
            if (Get-Command "Show-OwnedMessageBox" -ErrorAction SilentlyContinue) {
                Show-OwnedMessageBox -Text "B$([char]0x1EA1)n ch$([char]0x01B0)a ch$([char]0x1ECD)n m$([char]0x1EE5)c n$([char]0x00E0)o $([char]0x0111)$([char]0x1EC3) d$([char]0x1ECD)n s$([char]0x1EA1)ch." -Caption "Th$([char]0x00F4)ng b$([char]0x00E1)o" -Buttons ([System.Windows.Forms.MessageBoxButtons]::OK) -Icon ([System.Windows.Forms.MessageBoxIcon]::Information) -OwnerWindowOverride $dialog | Out-Null
            } else {
                [System.Windows.MessageBox]::Show($dialog, "B$([char]0x1EA1)n ch$([char]0x01B0)a ch$([char]0x1ECD)n m$([char]0x1EE5)c n$([char]0x00E0)o $([char]0x0111)$([char]0x1EC3) d$([char]0x1ECD)n s$([char]0x1EA1)ch.", "Th$([char]0x00F4)ng b$([char]0x00E1)o", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
            }
            return
        }

        $useRecycle = [bool]$chkRecycleBin.IsChecked
        $useForceStop = [bool]$chkForceStop.IsChecked
        $removed = 0
        $freed = 0L
        $rebootTotal = 0
        $accessDeniedTotal = 0

        $dialogBusyState.IsDeleting = $true
        $btnDelete.IsEnabled = $false
        if ($btnCancel) { $btnCancel.IsEnabled = $false }
        if ($btnSelectAll) { $btnSelectAll.IsEnabled = $false }
        if ($btnDeselectAll) { $btnDeselectAll.IsEnabled = $false }
        try {
            $deepType = "DuckUtil.DeepUninstallerEngine" -as [type]
            $canWaitAsync = ($null -ne (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue))
            if ($deepType -and $canWaitAsync -and $null -ne $deepType.GetMethod("PrewarmElevationCacheAsync")) {
                try {
                    $pwTaskDlg = $deepType::PrewarmElevationCacheAsync()
                    [void](Wait-TaskNonBlocking -Task $pwTaskDlg -TimeoutSeconds 4)
                } catch {}
            } elseif ($deepType -and $null -ne $deepType.GetMethod("PrewarmElevationCache")) {
                try { [DuckUtil.DeepUninstallerEngine]::PrewarmElevationCache() } catch {}
            }
            $hasSilentRecycle = ($null -ne $deepType -and $null -ne $deepType.GetMethod("MoveToRecycleBinSilently"))
            $hasSilentRecycleAsync = ($canWaitAsync -and $null -ne $deepType -and $null -ne $deepType.GetMethod("MoveToRecycleBinSilentlyAsync"))
            $hasNeutralizeAsync = ($canWaitAsync -and $null -ne $deepType -and $null -ne $deepType.GetMethod("NeutralizeSingleServiceOrDriverAsync"))
            $hasForceDelAsync = ($canWaitAsync -and $null -ne $deepType -and $null -ne $deepType.GetMethod("ForceDeleteDirectoryAsync"))
            $hasBatchStopAsync = ($canWaitAsync -and $null -ne $deepType -and $null -ne $deepType.GetMethod("ForceStopBatchDirectoriesAsync"))
            $hasBatchStopSync = ($null -ne $deepType -and $null -ne $deepType.GetMethod("ForceStopBatchDirectories"))

            $batchExplorerLock = $false
            $usedBatchForceStop = $false
            if ($useForceStop) {
                $existingPaths = @($checkedItems | Where-Object { -not $_.IsRegistry -and (Test-Path -LiteralPath $_.Path) } | ForEach-Object { [string]$_.Path } | Select-Object -Unique)
                if ($existingPaths.Count -gt 0 -and ($hasBatchStopAsync -or $hasBatchStopSync)) {
                    $usedBatchForceStop = $true
                    if ($summaryText) {
                        $summaryText.Text = "$([char]0x0110)ang gi$([char]0x1EA3)i ph$([char]0x00F3)ng ti$([char]0x1EBF)n tr$([char]0x00EC)nh/handle kh$([char]0x00F3)a ($($existingPaths.Count) m$([char]0x1EE5)c)..."
                    }
                    $batchRpt = $null
                    if ($hasBatchStopAsync) {
                        $bTask = $deepType::ForceStopBatchDirectoriesAsync([string[]]$existingPaths, $true)
                        [void](Wait-TaskNonBlocking -Task $bTask -TimeoutSeconds 60)
                        if ($bTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) { $batchRpt = $bTask.Result }
                    } else {
                        $batchRpt = $deepType::ForceStopBatchDirectories([string[]]$existingPaths, $true)
                    }
                    if ($batchRpt) {
                        $accessDeniedTotal += [int]$batchRpt.AccessDeniedCount
                        $batchExplorerLock = (@($batchRpt.SkippedSystemLockers | Where-Object { $_ -match '^explorer\b' }).Count -gt 0)
                        if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                            if ($batchRpt.KilledCount -gt 0 -or $batchRpt.ServicesStoppedCount -gt 0 -or $batchRpt.TasksRemovedCount -gt 0) {
                                Log-Text "[FORCE-STOP] $([char]0x0110)$([char]0x00E3) bu$([char]0x1ED9)c d$([char]0x1EEB)ng $($batchRpt.KilledCount) ti$([char]0x1EBF)n tr$([char]0x00EC)nh, $($batchRpt.ServicesStoppedCount) d$([char]0x1ECB)ch v$([char]0x1EE5), $($batchRpt.TasksRemovedCount) t$([char]0x00E1)c v$([char]0x1EE5) cho $($existingPaths.Count) m$([char]0x1EE5)c."
                            }
                            if ($batchRpt.ClosedHandlesCount -gt 0) {
                                Log-Text "[HANDLE-UNLOCK] $([char]0x0110)$([char]0x00E3) th$([char]0x00E1)o $($batchRpt.ClosedHandlesCount) handle t$([char]0x1EEB) xa: $($batchRpt.ClosedHandleNames -join ', ')"
                            }
                            if ($batchRpt.AccessDeniedCount -gt 0) {
                                Log-Text "[!] T$([char]0x1EEB) ch$([char]0x1ED1)i quy$([char]0x1EC1)n: $($batchRpt.AccessDeniedNames -join ', ')"
                            }
                            if (@($batchRpt.SkippedSystemLockers).Count -gt 0) {
                                Log-Text "[!] H$([char]0x1EC7) th$([char]0x1ED1)ng $([char]0x0111)ang gi$([char]0x1EEF) handle: $($batchRpt.SkippedSystemLockers -join ', ')"
                            }
                        }
                    }
                }
            }

            $explorerRestartDecision = $null
            $stepIdx = 0
            foreach ($ci in $checkedItems) {
                if ($script:isWindowClosing) { break }
                $stepIdx++
                if ($summaryText) {
                    $summaryText.Text = "$([char]0x0110)ang d$([char]0x1ECD)n $stepIdx / $($checkedItems.Count): $($ci.AppName)"
                }
                try {
                    if ($ci.IsRegistry) {
                        $psRegPath = if ($ci.Path -match '^HKCR:\\') {
                            "Registry::HKEY_CLASSES_ROOT\" + $ci.Path.Substring(6)
                        } else {
                            [string]$ci.Path
                        }
                        $hasMultiVals = ($ci.PSObject.Properties['RegistryValueNames'] -and $null -ne $ci.RegistryValueNames -and $ci.RegistryValueNames.Count -gt 0)
                        if ($hasMultiVals) {
                            $delValCount = 0
                            $valArr = [string[]]@($ci.RegistryValueNames)
                            if ($canWaitAsync -and $null -ne $deepType -and $null -ne $deepType.GetMethod("ForceDeleteRegistryValuesAsync")) {
                                $rvTask = $deepType::ForceDeleteRegistryValuesAsync([string]$ci.Path, $valArr)
                                [void](Wait-TaskNonBlocking -Task $rvTask -TimeoutSeconds 20)
                                if ($rvTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                                    $delValCount = [int]$rvTask.Result
                                }
                            } elseif ($null -ne $deepType -and $null -ne $deepType.GetMethod("ForceDeleteRegistryValues")) {
                                $delValCount = [int]$deepType::ForceDeleteRegistryValues([string]$ci.Path, $valArr)
                            } else {
                                foreach ($vn in $valArr) {
                                    try {
                                        Remove-ItemProperty -LiteralPath $psRegPath -Name $vn -Force -ErrorAction Stop
                                        $delValCount++
                                    } catch {}
                                }
                            }
                            if ($delValCount -gt 0) {
                                $removed++
                                if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                                    Log-Text "[D$([char]0x1ECC)N R$([char]0x00C1)C] $([char]0x0110)$([char]0x00E3) x$([char]0x00F3)a $delValCount gi$([char]0x00E1) tr$([char]0x1ECB) Registry ($($ci.AppName)): $($ci.Path)"
                                }
                            }
                        } elseif ($ci.RegistryValueName) {
                            if (Test-Path -LiteralPath $psRegPath) {
                                $valDelOk = $false
                                try {
                                    Remove-ItemProperty -LiteralPath $psRegPath -Name $ci.RegistryValueName -Force -ErrorAction Stop
                                    $valDelOk = $true
                                } catch {
                                    if ($null -ne $deepType -and $null -ne $deepType.GetMethod("ForceDeleteRegistryValues")) {
                                        $valDelOk = ([int]$deepType::ForceDeleteRegistryValues([string]$ci.Path, [string[]]@([string]$ci.RegistryValueName)) -gt 0)
                                    }
                                    if (-not $valDelOk) { throw }
                                }
                                if ($valDelOk) {
                                    $removed++
                                    if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                                        Log-Text "[D$([char]0x1ECC)N R$([char]0x00C1)C] $([char]0x0110)$([char]0x00E3) x$([char]0x00F3)a Registry Value: $($ci.Path) [$($ci.RegistryValueName)]"
                                    }
                                }
                            }
                        } elseif (Test-Path -LiteralPath $psRegPath) {
                            $neutralizedSvc = $false
                            if ($ci.Path -match '(?i)^HKLM:\\SYSTEM\\CurrentControlSet\\Services\\([^\\]+)$') {
                                $svcTargetName = $Matches[1]
                                if ($hasNeutralizeAsync) {
                                    $nTask = $deepType::NeutralizeSingleServiceOrDriverAsync($svcTargetName)
                                    [void](Wait-TaskNonBlocking -Task $nTask -TimeoutSeconds 25)
                                    if ($nTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                                        $neutralizedSvc = [bool]$nTask.Result
                                    }
                                } elseif ($null -ne $deepType -and $null -ne $deepType.GetMethod("NeutralizeSingleServiceOrDriver")) {
                                    $neutralizedSvc = [bool]$deepType::NeutralizeSingleServiceOrDriver($svcTargetName)
                                }
                            }
                            $usedElevatedRegDel = $false
                            if (Test-Path -LiteralPath $psRegPath) {
                                if ($neutralizedSvc) {
                                    Remove-Item -LiteralPath $psRegPath -Recurse -Force -ErrorAction SilentlyContinue
                                } else {
                                    $regErr = $null
                                    try {
                                        Remove-Item -LiteralPath $psRegPath -Recurse -Force -ErrorAction Stop
                                    } catch {
                                        $regErr = $_
                                    }
                                    if ($null -ne $regErr -and (Test-Path -LiteralPath $psRegPath)) {
                                        $elevOk = $false
                                        if ($canWaitAsync -and $null -ne $deepType -and $null -ne $deepType.GetMethod("ForceDeleteRegistryKeyAsync")) {
                                            $regTask = $deepType::ForceDeleteRegistryKeyAsync([string]$ci.Path)
                                            [void](Wait-TaskNonBlocking -Task $regTask -TimeoutSeconds 15)
                                            if ($regTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                                                $elevOk = [bool]$regTask.Result
                                            }
                                        } elseif ($null -ne $deepType -and $null -ne $deepType.GetMethod("ForceDeleteRegistryKey")) {
                                            $elevOk = [bool]$deepType::ForceDeleteRegistryKey([string]$ci.Path)
                                        }
                                        if ($elevOk -or -not (Test-Path -LiteralPath $psRegPath)) {
                                            $usedElevatedRegDel = $true
                                        } else {
                                            throw $regErr
                                        }
                                    }
                                }
                            }
                            $removed++
                            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                                $elevTag = if ($usedElevatedRegDel) { " (TrustedInstaller)" } else { "" }
                                Log-Text "[D$([char]0x1ECC)N R$([char]0x00C1)C] $([char]0x0110)$([char]0x00E3) x$([char]0x00F3)a Registry${elevTag}: $($ci.Path)"
                            }
                        }
                    } elseif (Test-Path -LiteralPath $ci.Path) {
                        if ($ci.PSObject.Properties['TaskName'] -and -not [string]::IsNullOrWhiteSpace($ci.TaskName)) {
                            $safeTaskName = ($ci.TaskName -replace '"', '')
                            try {
                                $psiTask = New-Object System.Diagnostics.ProcessStartInfo
                                $psiTask.FileName = "schtasks.exe"
                                $psiTask.Arguments = "/Delete /TN `"$safeTaskName`" /F"
                                $psiTask.UseShellExecute = $false
                                $psiTask.CreateNoWindow = $true
                                $pTask = [System.Diagnostics.Process]::Start($psiTask)
                                if ($pTask) {
                                    if ($canWaitAsync -and $null -ne $deepType -and $null -ne $deepType.GetMethod("WaitForProcessExitAsync")) {
                                        $tWaitTask = $deepType::WaitForProcessExitAsync($pTask)
                                        [void](Wait-TaskNonBlocking -Task $tWaitTask -TimeoutSeconds 5)
                                    } else {
                                        [void]$pTask.WaitForExit(5000)
                                    }
                                    $pTask.Dispose()
                                }
                            } catch {}
                            if (-not (Test-Path -LiteralPath $ci.Path)) {
                                $removed++
                                if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                                    Log-Text "[D$([char]0x1ECC)N R$([char]0x00C1)C] $([char]0x0110)$([char]0x00E3) x$([char]0x00F3)a Scheduled Task: $($ci.TaskName)"
                                }
                                continue
                            }
                        }
                        $hasExplorerLock = $batchExplorerLock
                        if ($useForceStop -and -not $usedBatchForceStop) {
                            $stopInfo = Invoke-ForceStopPathLockers -TargetPath $ci.Path -IncludeServicesAndTasks:$true
                            $accessDeniedTotal += [int]$stopInfo.AccessDeniedCount
                            $hasExplorerLock = ($null -ne $stopInfo -and @($stopInfo.SkippedSystemLockers | Where-Object { $_ -match '^explorer\b' }).Count -gt 0)
                        }

                        $deletedOk = $false
                        if ($useRecycle) {
                            if ($hasSilentRecycleAsync) {
                                $rTask = $deepType::MoveToRecycleBinSilentlyAsync($ci.Path)
                                [void](Wait-TaskNonBlocking -Task $rTask -TimeoutSeconds 30)
                                if ($rTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
                                    $deletedOk = [bool]$rTask.Result
                                }
                            } elseif ($hasSilentRecycle) {
                                $deletedOk = [DuckUtil.DeepUninstallerEngine]::MoveToRecycleBinSilently($ci.Path)
                            } elseif (-not $useForceStop) {
                                try {
                                    $itemObj = Get-Item -LiteralPath $ci.Path -Force -ErrorAction Stop
                                    if ($itemObj.PSIsContainer) {
                                        [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory($ci.Path, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin)
                                    } else {
                                        [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile($ci.Path, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin)
                                    }
                                    $deletedOk = $true
                                } catch {
                                    $deletedOk = $false
                                }
                            }
                        }

                        $shouldTryExplorerRestart = $useForceStop -and $hasExplorerLock -and (-not $deletedOk)
                        if ($shouldTryExplorerRestart) {
                            if ($null -eq $explorerRestartDecision) {
                                $msgPrompt = "Windows Explorer $([char]0x0111)ang n$([char]0x1EA1)p t$([char]0x1EC7)p m$([char]0x1EDF) r$([char]0x1ED9)ng (Shell Extension DLL) trong th$([char]0x01B0) m$([char]0x1EE5)c c$([char]0x1EA7)n x$([char]0x00F3)a:`n$($ci.Path)`n`nB$([char]0x1EA1)n c$([char]0x00F3) mu$([char]0x1ED1)n kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i nhanh Windows Explorer (~1 gi$([char]0x00E2)y) $([char]0x0111)$([char]0x1EC3) nh$([char]0x1EA3) kh$([char]0x00F3)a v$([char]0x00E0) x$([char]0x00F3)a s$([char]0x1EA1)ch ngay m$([char]0x00E0) kh$([char]0x00F4)ng c$([char]0x1EA7)n kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i m$([char]0x00E1)y?"
                                $capPrompt = "Windows Explorer $([char]0x0111)ang gi$([char]0x1EEF) t$([char]0x1EC7)p"
                                if (Get-Command "Show-OwnedMessageBox" -ErrorAction SilentlyContinue) {
                                    $ansExp = Show-OwnedMessageBox `
                                        -Text $msgPrompt `
                                        -Caption $capPrompt `
                                        -Buttons ([System.Windows.Forms.MessageBoxButtons]::YesNo) `
                                        -Icon ([System.Windows.Forms.MessageBoxIcon]::Warning) `
                                        -PrimaryText "Kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i Explorer" `
                                        -SecondaryText "B$([char]0x1ECF) qua ($([char]0x0110)$([char]0x1EB7)t l$([char]0x1ECB)ch MoveFileEx)" `
                                        -ModeBadgeText "$([char]0x0110)$([char]0x00F3)ng & m$([char]0x1EDF) l$([char]0x1EA1)i nhanh Taskbar/Desktop $([char]0x0111)$([char]0x1EC3) nh$([char]0x1EA3) kh$([char]0x00F3)a DLL" `
                                        -ModeBadgeKind "Info" `
                                        -OwnerWindowOverride $dialog
                                    $explorerRestartDecision = ($ansExp -eq [System.Windows.Forms.DialogResult]::Yes)
                                } else {
                                    $ansWpf = [System.Windows.MessageBox]::Show($dialog, $msgPrompt, $capPrompt, [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
                                    $explorerRestartDecision = ($ansWpf -eq [System.Windows.MessageBoxResult]::Yes)
                                }
                            }

                            if ($explorerRestartDecision) {
                                $script:_loExpUnlockPath = [string]$ci.Path
                                $script:_loExpUnlockUseRecycle = [bool]($useRecycle -and $hasSilentRecycle)
                                $script:_loExpUnlockDeleted = $false
                                $script:_loExpUnlockReboot = 0
                                Restart-WindowsExplorerForUnlock -OnUnlockedCallback {
                                    if ($script:_loExpUnlockUseRecycle) {
                                        $script:_loExpUnlockDeleted = [DuckUtil.DeepUninstallerEngine]::MoveToRecycleBinSilently($script:_loExpUnlockPath)
                                    }
                                    if (-not $script:_loExpUnlockDeleted) {
                                        $rbInner = 0
                                        $script:_loExpUnlockDeleted = [DuckUtil.DeepUninstallerEngine]::ForceDeleteDirectory($script:_loExpUnlockPath, [ref]$rbInner)
                                        $script:_loExpUnlockReboot = $rbInner
                                    }
                                }
                                $deletedOk = [bool]$script:_loExpUnlockDeleted
                                $rebootTotal += [int]$script:_loExpUnlockReboot
                            }
                        }

                        if (-not $deletedOk) {
                            $rbCount = 0
                            if ($hasForceDelAsync) {
                                $dTask = $deepType::ForceDeleteDirectoryAsync($ci.Path, (-not $useForceStop))
                                [void](Wait-TaskNonBlocking -Task $dTask -TimeoutSeconds 60)
                                if ($dTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion -and $null -ne $dTask.Result) {
                                    $deletedOk = [bool]$dTask.Result.Deleted
                                    $rbCount = [int]$dTask.Result.RebootScheduledCount
                                }
                            } else {
                                $hasFastForceDel = @([DuckUtil.DeepUninstallerEngine].GetMethods() | Where-Object { $_.Name -eq "ForceDeleteDirectory" -and $_.GetParameters().Count -eq 3 }).Count -gt 0
                                if ($hasFastForceDel) {
                                    $deletedOk = [DuckUtil.DeepUninstallerEngine]::ForceDeleteDirectory($ci.Path, (-not $useForceStop), [ref]$rbCount)
                                } else {
                                    $deletedOk = [DuckUtil.DeepUninstallerEngine]::ForceDeleteDirectory($ci.Path, [ref]$rbCount)
                                }
                            }
                            $rebootTotal += $rbCount
                        }

                        if ($deletedOk) {
                            $removed++
                            $freed += $ci.SizeBytes
                            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                                Log-Text "[D$([char]0x1ECC)N R$([char]0x00C1)C] $([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n s$([char]0x1EA1)ch: $($ci.Type) - $($ci.Path)"
                            }
                        }
                    }
                } catch {
                    if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                        Log-Text "[!] L$([char]0x1ED7)i khi x$([char]0x00F3)a $($ci.Path): $($_.Exception.Message)"
                    }
                }
            }

            if ($rebootTotal -gt 0 -and (Get-Command Log-Text -ErrorAction SilentlyContinue)) {
                Log-Text "[*] $([char]0x0110)$([char]0x00E3) $([char]0x0111)$([char]0x1EB7)t l$([char]0x1ECB)ch x$([char]0x00F3)a $rebootTotal file $([char]0x0111)ang b$([char]0x1ECB) kh$([char]0x00F3)a ngay khi Windows kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i (MoveFileEx)."
            }
            if (($accessDeniedTotal -gt 0 -or $rebootTotal -gt 0) -and (Get-Command Log-Text -ErrorAction SilentlyContinue)) {
                Log-Text "[!] L$([char]0x01B0)u $([char]0x00FD): T$([char]0x1EC7)p b$([char]0x1ECB) kh$([char]0x00F3)a b$([char]0x1EDF)i driver b$([char]0x1EA3)o v$([char]0x1EC7) c$([char]0x1EA5)p nh$([char]0x00E2)n (nh$([char]0x01B0) 360) kh$([char]0x00F4)ng th$([char]0x1EC3) t$([char]0x1EAF)t t$([char]0x1EEB) Windows th$([char]0x01B0)$([char]0x1EDD)ng; h$([char]0x00E3)y t$([char]0x1EAF)t T$([char]0x1EF1) b$([char]0x1EA3)o v$([char]0x1EC7) trong app, ch$([char]0x1EA1)y l$([char]0x1EA1)i trong Safe Mode ho$([char]0x1EB7)c kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i $([char]0x0111)$([char]0x1EC3) MoveFileEx d$([char]0x1ECD)n."
            }

            $dialogResult.Confirmed = $true
            $dialogResult.RemovedCount = $removed
            $dialogResult.FreedBytes = $freed
            $dialogResult.RebootScheduled = $rebootTotal
            $dialogResult.AccessDeniedCount = $accessDeniedTotal
            $dialogBusyState.IsDeleting = $false
            $dialog.Close()
        } finally {
            $dialogBusyState.IsDeleting = $false
            $btnDelete.IsEnabled = $true
            if ($btnCancel) { $btnCancel.IsEnabled = $true }
            if ($btnSelectAll) { $btnSelectAll.IsEnabled = $true }
            if ($btnDeselectAll) { $btnDeselectAll.IsEnabled = $true }
        }
    })
    $btnStack.Children.Add($btnDelete) | Out-Null

    [System.Windows.Controls.Grid]::SetColumn($btnStack, 1)
    $bottomGrid.Children.Add($btnStack) | Out-Null

    $bottomBar.Child = $bottomGrid
    [System.Windows.Controls.Grid]::SetRow($bottomBar, 2)
    $rootGrid.Children.Add($bottomBar) | Out-Null

    $dialog.Content = $rootGrid
    if (-not $script:isWindowClosing) {
        try {
            $null = $dialog.ShowDialog()
        } catch {} finally {
            try { $dialog.Owner = $null } catch {}
        }
    }

    return $dialogResult
}

function Resolve-SilentUninstallPlan {
    param(
        [Parameter(Mandatory = $true)]$AppEntry,
        [bool]$AutoSilent = $true
    )

    $hasExplicitQuiet = -not [string]::IsNullOrWhiteSpace($AppEntry.QuietUninstallString)
    $hasStandardUninstall = -not [string]::IsNullOrWhiteSpace($AppEntry.UninstallString)
    $usedExplicitQuietFallback = $false
    $rawCmd = if ($AutoSilent) {
        if ($hasExplicitQuiet) {
            $AppEntry.QuietUninstallString.Trim()
        } elseif ($hasStandardUninstall) {
            $AppEntry.UninstallString.Trim()
        } else {
            ""
        }
    } else {
        if ($hasStandardUninstall) {
            $AppEntry.UninstallString.Trim()
        } elseif ($hasExplicitQuiet) {
            $usedExplicitQuietFallback = $true
            $AppEntry.QuietUninstallString.Trim()
        } else {
            ""
        }
    }

    if ([string]::IsNullOrWhiteSpace($rawCmd)) {
        return [PSCustomObject]@{
            Mode                = "None"
            Exe                 = ""
            Args                = ""
            Framework           = ""
            AddedSilentFlags    = $false
            IsSilent            = $false
            IsLikelyDarkPattern = $false
        }
    }

    if ($rawCmd.IndexOf("msiexec", [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
        $msiId = if (Get-Command Get-MsiProductCodeFromCommand -ErrorAction SilentlyContinue) {
            Get-MsiProductCodeFromCommand -UninstallCommand $rawCmd -FallbackId $AppEntry.Id
        } else {
            $AppEntry.Id
        }
        $msiArgs = if ($AutoSilent) { "/x `"$msiId`" /qn /norestart" } else { "/x `"$msiId`"" }
        return [PSCustomObject]@{
            Mode                = "MSI"
            Exe                 = "msiexec.exe"
            Args                = $msiArgs
            MsiId               = $msiId
            Framework           = "MSI"
            AddedSilentFlags    = [bool]$AutoSilent
            IsSilent            = [bool]$AutoSilent
            IsLikelyDarkPattern = $false
        }
    }

    $cmdParts = if (Get-Command Split-CommandLineExecutableAndArgs -ErrorAction SilentlyContinue) {
        Split-CommandLineExecutableAndArgs -CommandLine $rawCmd
    } else {
        $spParts = $rawCmd -split '\s+', 2
        [PSCustomObject]@{ Exe = $spParts[0].Trim('"'); Args = if ($spParts.Count -gt 1) { $spParts[1] } else { "" } }
    }

    $exe = [string]$cmdParts.Exe
    $origArgs = if ($null -eq $cmdParts.Args) { "" } else { ([string]$cmdParts.Args).Trim() }
    $missingExe = ($exe -match '^[A-Za-z]:\\') -and (-not [System.IO.File]::Exists($exe))
    if ($missingExe) {
        return [PSCustomObject]@{
            Mode                = "MissingExe"
            Exe                 = $exe
            Args                = $origArgs
            Framework           = ""
            AddedSilentFlags    = $false
            IsSilent            = $false
            IsLikelyDarkPattern = $false
        }
    }

    $framework = ""
    $newArgs = $origArgs
    $addedFlags = $false
    $isSilent = $false

    if ($AutoSilent) {
        $deepType = "DuckUtil.DeepUninstallerEngine" -as [type]
        if ($deepType -and $null -ne $deepType.GetMethod("DetectInstallerFramework")) {
            $framework = [string]$deepType::DetectInstallerFramework($exe)
        }

        switch ($framework) {
            "InnoSetup" {
                if ($newArgs -match '(?i)(^|\s)/VERYSILENT(\s|$)') {
                    $isSilent = $true
                } elseif ($newArgs -match '(?i)(^|\s)/SILENT(\s|$)') {
                    $newArgs = [regex]::Replace($newArgs, '(?i)(?<=^|\s)/SILENT(?=\s|$)', '/VERYSILENT')
                    $addedFlags = $true
                    $isSilent = $true
                } else {
                    $newArgs = "$newArgs /VERYSILENT".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
                if ($newArgs -notmatch '(?i)(^|\s)/SUPPRESSMSGBOXES(\s|$)') {
                    $newArgs = "$newArgs /SUPPRESSMSGBOXES".Trim()
                    $addedFlags = $true
                }
                if ($newArgs -notmatch '(?i)(^|\s)/NORESTART(\s|$)') {
                    $newArgs = "$newArgs /NORESTART".Trim()
                    $addedFlags = $true
                }
            }
            "NSIS" {
                if ($newArgs -cmatch '(^|\s)/S(\s|$)' -or $newArgs -match '(?i)(^|\s)(--silent|/silent)(\s|$)') {
                    $isSilent = $true
                } elseif ($newArgs -cmatch '(^|\s)/s(\s|$)') {
                    $newArgs = [regex]::Replace($newArgs, '(?<=^|\s)/s(?=\s|$)', '/S')
                    $addedFlags = $true
                    $isSilent = $true
                } else {
                    $newArgs = "$newArgs /S".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            "WiX" {
                if ($newArgs -match '(?i)(^|\s)(/q|/quiet|/silent|/passive)(\s|$)') {
                    $isSilent = $true
                } else {
                    if ($newArgs -notmatch '(?i)(^|\s)(/uninstall|/x)(\s|$)') {
                        $newArgs = "$newArgs /uninstall".Trim()
                    }
                    $newArgs = "$newArgs /quiet /norestart".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            "BitRock" {
                if ($newArgs -match '(?i)(^|\s)--mode(\s|=)(unattended|minimal)(\s|$)') {
                    $isSilent = $true
                } elseif ($newArgs -notmatch '(?i)(^|\s)--mode(\s|=|$)') {
                    $newArgs = "$newArgs --mode unattended".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            "Squirrel" {
                if ($newArgs -match '(?i)(^|\s)(-s|--silent)(\s|$)') {
                    $isSilent = $true
                } elseif ($newArgs -match '(?i)--uninstall') {
                    $newArgs = "$newArgs -s".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            "InstallShield" {
                if ($newArgs -match '(?i)(^|\s)(/s|/quiet|/qn)(\s|$)') {
                    $isSilent = $true
                } else {
                    $newArgs = "$newArgs /s /v`"/qn /norestart`"".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            "AdvancedInstaller" {
                if ($newArgs -match '(?i)(^|\s)(/quiet|/qn|/exenoui)(\s|$)') {
                    $isSilent = $true
                } else {
                    $newArgs = "$newArgs /exenoui /qn /norestart".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            "QtIFW" {
                if ($newArgs -match '(?i)--confirm-command') {
                    $isSilent = $true
                } else {
                    $newArgs = "$newArgs --confirm-command".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            default {
                $exeBase = [System.IO.Path]::GetFileName($exe)
                if ($exeBase -ieq "setup.exe" -and $newArgs -match '(?i)--uninstall' -and $newArgs -notmatch '(?i)--force-uninstall') {
                    $framework = "ChromiumSetup"
                    $newArgs = "$newArgs --force-uninstall".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                } elseif ($hasExplicitQuiet -or ($newArgs -match '(?i)(^|\s)(/s|/silent|/verysilent|/quiet|/qn|--silent|--quiet|-silent|-s)(\s|$)')) {
                    $isSilent = $true
                }
            }
        }
    } else {
        if ($usedExplicitQuietFallback -or ($newArgs -match '(?i)(^|\s)(/s|/silent|/verysilent|/quiet|/qn|--silent|--quiet|-silent|-s)(\s|$)')) {
            $isSilent = $true
        }
    }

    $hintMeta = "$($AppEntry.DisplayName) $($AppEntry.Publisher) $exe"
    $isDark = ($hintMeta -match '(?i)\b(360Safe|360 Total|Qihu|2345|Kingsoft|Sogou|Baidu|Driver Booster|IObit)\b')

    return [PSCustomObject]@{
        Mode                = "Exe"
        Exe                 = $exe
        Args                = $newArgs
        Framework           = $framework
        AddedSilentFlags    = $addedFlags
        IsSilent            = $isSilent
        IsLikelyDarkPattern = $isDark
    }
}

function Invoke-DeepAppUninstall {
    param(
        [Parameter(Mandatory = $true)]$AppEntry,
        [Parameter(Mandatory = $false)]$OwnerWindow,
        [switch]$SkipVendorUninstaller,
        [switch]$ForceStopAndDelete,
        [bool]$AutoSilent = $true,
        [object[]]$AllInstalledApps = $null,
        [switch]$DeferLeftoverDialog,
        [System.Collections.Generic.List[object]]$CollectedLeftoversOut = $null,
        [switch]$AllowCancel
    )

    if ($ForceStopAndDelete) {
        $SkipVendorUninstaller = $true
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
        Log-Text "=========================================================="
        if ($ForceStopAndDelete) {
            Log-Text "B$([char]0x1EAE)T $([char]0x0110)$([char]0x1EA6)U BU$([char]0x1ED8)C D$([char]0x1EEA)NG & X$([char]0x00D3)A TR$([char]0x1EF0)C TI$([char]0x1EBE)P: $($AppEntry.DisplayName)"
        } else {
            Log-Text "B$([char]0x1EAE)T $([char]0x0110)$([char]0x1EA6)U G$([char]0x1EE0) C$([char]0x00C0)I $([char]0x0110)$([char]0x1EB6)T: $($AppEntry.DisplayName)"
        }
        Log-Text "=========================================================="
    }

    $canWaitNonBlocking = ($null -ne (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue))
    $deepEngT = "DuckUtil.DeepUninstallerEngine" -as [type]
    $prewarmTask = $null
    if ($deepEngT -and $canWaitNonBlocking -and $null -ne $deepEngT.GetMethod("PrewarmElevationCacheAsync")) {
        try { $prewarmTask = $deepEngT::PrewarmElevationCacheAsync() } catch {}
    } elseif ($deepEngT -and $null -ne $deepEngT.GetMethod("PrewarmElevationCache")) {
        try { [DuckUtil.DeepUninstallerEngine]::PrewarmElevationCache() } catch {}
    }

    $allInstalledNow = if ($AllInstalledApps -and $AllInstalledApps.Count -gt 0) {
        $AllInstalledApps
    } elseif ($canWaitNonBlocking -and $deepEngT -and $null -ne $deepEngT.GetMethod("GetInstalledAppsAsync")) {
        $appsTask = $deepEngT::GetInstalledAppsAsync()
        $appsCancelCb = if ($AllowCancel) { { [bool]$script:cancelRequested } } else { $null }
        [void](Wait-TaskNonBlocking -Task $appsTask -TimeoutSeconds 45 -CancelCheck $appsCancelCb)
        if ($appsTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
            @($appsTask.Result)
        } elseif (-not $script:isWindowClosing -and -not ($AllowCancel -and $script:cancelRequested)) {
            Get-SystemInstalledAppsFast
        } else {
            @()
        }
    } elseif (-not $script:isWindowClosing -and -not ($AllowCancel -and $script:cancelRequested)) {
        Get-SystemInstalledAppsFast
    } else {
        @()
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    $isResidualOrphanRow = ($AppEntry.Id -and $AppEntry.Id -like 'ORPHAN\*')
    $safeLoc = ""
    if (-not $isResidualOrphanRow -and $AppEntry.InstallLocation -and (Test-Path -LiteralPath $AppEntry.InstallLocation)) {
        $loc = try { (Resolve-Path -LiteralPath $AppEntry.InstallLocation).Path.TrimEnd('\') } catch { $AppEntry.InstallLocation.Trim().TrimEnd('\') }
        if (Test-SafeAppDirectoryForCleanup -Path $loc -AppEntry $AppEntry -AllInstalledApps $allInstalledNow) {
            $safeLoc = $loc
            [void](Invoke-ForceStopPathLockers -TargetPath $loc -IncludeServicesAndTasks:$true -AllowCancel:$AllowCancel)
        }
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    if (-not $AppEntry.IsBrokenOrphan) {
        if ($SkipVendorUninstaller) {
            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                Log-Text "[FORCE] B$([char]0x1ECF) qua tr$([char]0x00EC)nh g$([char]0x1EE1) c$([char]0x1EE7)a h$([char]0x00E3)ng ($([char]0x0111)$([char]0x00E3) t$([char]0x1EAF)t service/ti$([char]0x1EBF)n tr$([char]0x00EC)nh) -> qu$([char]0x00E9)t x$([char]0x00F3)a s$([char]0x1EA1)ch tr$([char]0x1EF1)c ti$([char]0x1EBF)p."
            }
        } else {
            $plan = Resolve-SilentUninstallPlan -AppEntry $AppEntry -AutoSilent:$AutoSilent
            if ($plan.Mode -eq "MSI") {
                if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                    if ($AutoSilent) {
                        Log-Text "[*] $([char]0x0110)ang g$([char]0x1ECD)i Windows Installer g$([char]0x1EE1) b$([char]0x1ECF) g$([char]0x00F3)i MSI: $($AppEntry.DisplayName) ($($plan.MsiId))..."
                    } else {
                        Log-Text "[*] $([char]0x0110)ang g$([char]0x1ECD)i Windows Installer g$([char]0x1EE1) b$([char]0x1ECF) g$([char]0x00F3)i MSI (giao di$([char]0x1EC7)n chu$([char]0x1EA9)n): $($AppEntry.DisplayName) ($($plan.MsiId))..."
                    }
                }
                if (Get-Command Run-CliStream -ErrorAction SilentlyContinue) {
                    $msiCode = Run-CliStream "msiexec.exe" $plan.Args -IsolateStdin:($AutoSilent -or $plan.IsSilent) -AllowCancel:$AllowCancel
                    if ($msiCode -eq 1618 -and -not ($AllowCancel -and $script:cancelRequested) -and -not $script:isWindowClosing) {
                        if ($canWaitNonBlocking) {
                            $cancelCb = if ($AllowCancel) { { [bool]$script:cancelRequested } } else { $null }
                            [void](Wait-TaskNonBlocking -Task ([System.Threading.Tasks.Task]::Delay(3000)) -TimeoutSeconds 5 -CancelCheck $cancelCb)
                        } else {
                            Start-Sleep -Seconds 3
                        }
                        if (-not $script:isWindowClosing -and -not ($AllowCancel -and $script:cancelRequested)) {
                            $null = Run-CliStream "msiexec.exe" $plan.Args -IsolateStdin:($AutoSilent -or $plan.IsSilent) -AllowCancel:$AllowCancel
                        }
                    }
                } else {
                    Start-Process "msiexec.exe" -ArgumentList $plan.Args -Wait -NoNewWindow
                }
            } elseif ($plan.Mode -eq "MissingExe") {
                if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                    Log-Text "[!] Kh$([char]0x00F4)ng t$([char]0x00EC)m th$([char]0x1EA5)y tr$([char]0x00EC)nh g$([char]0x1EE1) g$([char]0x1ED1)c t$([char]0x1EA1)i '$($plan.Exe)' - chuy$([char]0x1EC3)n sang qu$([char]0x00E9)t d$([char]0x1ECD)n s$([char]0x1EA1)ch tr$([char]0x1EF1)c ti$([char]0x1EBF)p."
                }
            } elseif ($plan.Mode -eq "Exe") {
                if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                    if ($AutoSilent -and $plan.AddedSilentFlags) {
                        Log-Text "[SILENT] Nh$([char]0x1EAD)n di$([char]0x1EC7)n [$($plan.Framework)], $([char]0x0111)$([char]0x00E3) g$([char]0x1EAF)n c$([char]0x1EDD) g$([char]0x1EE1) im l$([char]0x1EB7)ng: $($plan.Exe) $($plan.Args)"
                    } elseif (-not $AutoSilent) {
                        Log-Text "[*] $([char]0x0110)ang th$([char]0x1EF1)c thi tr$([char]0x00EC)nh g$([char]0x1EE1) b$([char]0x1ECF) ch$([char]0x00ED)nh th$([char]0x1EE9)c (t$([char]0x1EAF)t t$([char]0x1EF1) $([char]0x0111)$([char]0x1ED9)ng g$([char]0x1EAF)n c$([char]0x1EDD) im l$([char]0x1EB7)ng): $($plan.Exe) $($plan.Args)"
                    } else {
                        Log-Text "[*] $([char]0x0110)ang th$([char]0x1EF1)c thi tr$([char]0x00EC)nh g$([char]0x1EE1) b$([char]0x1ECF) ch$([char]0x00ED)nh th$([char]0x1EE9)c: $($plan.Exe) $($plan.Args)"
                        if (-not $plan.IsSilent) {
                            $hintText = if ($plan.IsLikelyDarkPattern) {
                                "[!] $([char]0x1EE8)ng d$([char]0x1EE5)ng n$([char]0x00E0)y hay c$([char]0x00F3) b$([char]0x1EA3)ng h$([char]0x1ECF)i gi$([char]0x1EEF) ch$([char]0x00E2)n; n$([char]0x1EBF)u popup hi$([char]0x1EC7)n l$([char]0x00EA)n, l$([char]0x1EA7)n sau h$([char]0x00E3)y b$([char]0x1EAD)t 'Bu$([char]0x1ED9)c d$([char]0x1EEB)ng & X$([char]0x00F3)a tr$([char]0x1EF1)c ti$([char]0x1EBF)p' trong h$([char]0x1ED9)p tho$([char]0x1EA1)i G$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t."
                            } else {
                                "[!] Kh$([char]0x00F4)ng r$([char]0x00F5) c$([char]0x1EDD) im l$([char]0x1EB7)ng chu$([char]0x1EA9)n cho tr$([char]0x00EC)nh g$([char]0x1EE1) n$([char]0x00E0)y; n$([char]0x1EBF)u c$([char]0x00F3) b$([char]0x1EA3)ng h$([char]0x1ECF)i l$([char]0x00E0)m phi$([char]0x1EC1)n, c$([char]0x00F3) th$([char]0x1EC3) b$([char]0x1EAD)t 'Bu$([char]0x1ED9)c d$([char]0x1EEB)ng & X$([char]0x00F3)a tr$([char]0x1EF1)c ti$([char]0x1EBF)p' trong h$([char]0x1ED9)p tho$([char]0x1EA1)i G$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t."
                            }
                            Log-Text $hintText
                        }
                    }
                }
                if (Get-Command Run-CliStream -ErrorAction SilentlyContinue) {
                    $null = Run-CliStream $plan.Exe $plan.Args -IsolateStdin:($AutoSilent -and $plan.IsSilent) -AllowCancel:$AllowCancel
                } else {
                    Start-Process $plan.Exe -ArgumentList $plan.Args -Wait -NoNewWindow
                }
            }
        }
    }

    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }
    if (-not $isResidualOrphanRow) {
        if ($canWaitNonBlocking) {
            $cancelCb2 = if ($AllowCancel) { { [bool]$script:cancelRequested } } else { $null }
            [void](Wait-TaskNonBlocking -Task ([System.Threading.Tasks.Task]::Delay(800)) -TimeoutSeconds 3 -CancelCheck $cancelCb2)
        } else {
            Start-Sleep -Milliseconds 800
        }
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    if ($safeLoc -and (Test-Path -LiteralPath $safeLoc)) {
        [void](Invoke-ForceStopPathLockers -TargetPath $safeLoc -IncludeServicesAndTasks:$true -AllowCancel:$AllowCancel)
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    $leftovers = Find-AppLeftovers -AppEntry $AppEntry -AllInstalledApps $allInstalledNow
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    if ($DeferLeftoverDialog) {
        if ($leftovers.Count -gt 0) {
            if ($null -ne $CollectedLeftoversOut) {
                foreach ($lo in $leftovers) { $CollectedLeftoversOut.Add($lo) }
            }
            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                Log-Text "[*] $([char]0x0110)$([char]0x00E3) ghi nh$([char]0x1EAD)n $($leftovers.Count) m$([char]0x1EE5)c r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0) c$([char]0x1EE7)a '$($AppEntry.DisplayName)' (s$([char]0x1EBD) m$([char]0x1EDF) h$([char]0x1ED9)p tho$([char]0x1EA1)i d$([char]0x1ECD)n cu$([char]0x1ED1)i h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i)."
            }
        } else {
            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                Log-Text "[OK] '$($AppEntry.DisplayName)' $([char]0x0111)$([char]0x00E3) s$([char]0x1EA1)ch s$([char]0x1EBD), kh$([char]0x00F4)ng ph$([char]0x00E1)t hi$([char]0x1EC7)n r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0)."
            }
        }
        return
    }

    if ($leftovers.Count -gt 0) {
        if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
            Log-Text "[*] Ph$([char]0x00E1)t hi$([char]0x1EC7)n $($leftovers.Count) m$([char]0x1EE5)c r$([char]0x00E1)c / Registry c$([char]0x00F2)n s$([char]0x00F3)t l$([char]0x1EA1)i sau khi g$([char]0x1EE1) b$([char]0x1ECF)."
        }
        $dialogTitle = "D$([char]0x1ECD)n r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0) sau khi g$([char]0x1EE1): $($AppEntry.DisplayName)"
        $res = Show-LeftoverReviewDialog -OwnerWindow $OwnerWindow -Items $leftovers -Title $dialogTitle -ForceStopByDefault:$true
        if ($res.Confirmed) {
            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                $freedMb = [math]::Round($res.FreedBytes / 1MB, 2)
                Log-Text "[OK] $([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n s$([char]0x1EA1)ch $($res.RemovedCount) m$([char]0x1EE5)c t$([char]0x1ED3)n d$([char]0x01B0) (~$freedMb MB)."
            }
        }
    } else {
        if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
            Log-Text "[OK] Tr$([char]0x00EC)nh g$([char]0x1EE1) b$([char]0x1ECF) $([char]0x0111)$([char]0x00E3) d$([char]0x1ECD)n d$([char]0x1EB9)p s$([char]0x1EA1)ch s$([char]0x1EBD), kh$([char]0x00F4)ng ph$([char]0x00E1)t hi$([char]0x1EC7)n r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0)."
        }
    }
}

function Find-FaultyPnpDevices {
    try {
        return @(Get-PnpDevice -ErrorAction Stop | Where-Object {
            $_.Present -eq $true -and ($_.Status -ne 'OK' -or ($null -ne $_.ConfigManagerErrorCode -and $_.ConfigManagerErrorCode -ne 0))
        })
    } catch {
        Log-Text "[!] L$([char]0x1ED7)i khi qu$([char]0x00E9)t danh s$([char]0x00E1)ch PnpDevice: $($_.Exception.Message)"
        return @()
    }
}

function Invoke-PnpDeviceRescan {
    $code = Run-CliStream "pnputil.exe" "/scan-devices"
    if ($code -eq 0) {
        Log-Text "[OK] Qu$([char]0x00E9)t l$([char]0x1EA1)i thi$([char]0x1EBF)t b$([char]0x1ECB) ph$([char]0x1EA7)n c$([char]0x1EE9)ng PnP th$([char]0x00E0)nh c$([char]0x00F4)ng (ExitCode: 0)."
    } else {
        Log-Text "[!] Qu$([char]0x00E9)t thi$([char]0x1EBF)t b$([char]0x1ECB) ph$([char]0x1EA7)n c$([char]0x1EE9)ng PnP th$([char]0x1EA5)t b$([char]0x1EA1)i ho$([char]0x1EB7)c g$([char]0x1EB7)p l$([char]0x1ED7)i (ExitCode: $code)."
    }
    return $code
}

function Invoke-PnpDriverStoreCleanup {
    Log-Text "[*] $([char]0x0110)ang ph$([char]0x00E2)n t$([char]0x00ED)ch danh s$([char]0x00E1)ch g$([char]0x00F3)i Driver OEM b$([char]0x00EA)n th$([char]0x1EE9) ba (pnputil /enum-drivers)..."
    $p = $null
    try {
        $pinfo = New-Object System.Diagnostics.ProcessStartInfo
        $pinfo.FileName = "pnputil.exe"
        $pinfo.Arguments = "/enum-drivers"
        $pinfo.RedirectStandardOutput = $true
        $pinfo.RedirectStandardError = $true
        $pinfo.UseShellExecute = $false
        $pinfo.CreateNoWindow = $true
        $p = [System.Diagnostics.Process]::Start($pinfo)
        $outTask = $p.StandardOutput.ReadToEndAsync()
        $errTask = $p.StandardError.ReadToEndAsync()
        $hasForms = ($null -ne ('System.Windows.Forms.Application' -as [type]))
        $enumDeadline = [DateTime]::UtcNow.AddSeconds(15)
        while (-not $p.WaitForExit(120)) {
            if ($hasForms) { try { [System.Windows.Forms.Application]::DoEvents() } catch {} }
            if ($script:isWindowClosing -or $script:cancelRequested -or [DateTime]::UtcNow -ge $enumDeadline) {
                try { $p.Kill() } catch {}
                Log-Text "[!] H$([char]0x1EBF)t th$([char]0x1EDD)i gian ho$([char]0x1EB7)c $([char]0x0111)$([char]0x00E3) h$([char]0x1EE7)y li$([char]0x1EC7)t k$([char]0x00EA) DriverStore (pnputil /enum-drivers)."
                return
            }
        }
        $raw = if ($outTask.Wait(1000)) { $outTask.Result } else { "" }

        $matches = [System.Text.RegularExpressions.Regex]::Matches($raw, '(?im)^\s*[^:\r\n]+:\s*(oem\d+\.inf)\b')
        $oemList = @($matches | ForEach-Object { $_.Groups[1].Value.ToLowerInvariant() } | Select-Object -Unique)

        if ($oemList.Count -eq 0) {
            Log-Text "[OK] Kh$([char]0x00F4)ng t$([char]0x00EC)m th$([char]0x1EA5)y g$([char]0x00F3)i driver OEM n$([char]0x00E0)o trong DriverStore."
            return
        }

        Log-Text "[*] T$([char]0x00EC)m th$([char]0x1EA5)y $($oemList.Count) g$([char]0x00F3)i driver OEM. B$([char]0x1EAF)t $([char]0x0111)$([char]0x1EA7)u d$([char]0x1ECD)n d$([char]0x1EB9)p an to$([char]0x00E0)n (kh$([char]0x00F4)ng x$([char]0x00F3)a driver $([char]0x0111)ang s$([char]0x1EED) d$([char]0x1EE5)ng)..."
        $deletedCount = 0
        $inUseCount = 0
        $errorCount = 0
        $userAborted = $false
        $hasForms = ($null -ne ('System.Windows.Forms.Application' -as [type]))

        foreach ($inf in $oemList) {
            if ($script:isWindowClosing -or $script:cancelRequested) { $userAborted = $true; break }
            $delP = $null
            try {
                $delPinfo = New-Object System.Diagnostics.ProcessStartInfo
                $delPinfo.FileName = "pnputil.exe"
                $delPinfo.Arguments = "/delete-driver $inf"
                $delPinfo.RedirectStandardOutput = $true
                $delPinfo.RedirectStandardError = $true
                $delPinfo.UseShellExecute = $false
                $delPinfo.CreateNoWindow = $true
                $delP = [System.Diagnostics.Process]::Start($delPinfo)

                $delOutTask = $delP.StandardOutput.ReadToEndAsync()
                $delErrTask = $delP.StandardError.ReadToEndAsync()
                $delDeadline = [DateTime]::UtcNow.AddSeconds(30)
                $timedOutDel = $false
                while (-not $delP.WaitForExit(150)) {
                    if ($hasForms) { try { [System.Windows.Forms.Application]::DoEvents() } catch {} }
                    if ($script:isWindowClosing -or $script:cancelRequested) {
                        $userAborted = $true
                        try { $delP.Kill() } catch {}
                        try { [void]$delP.WaitForExit(500) } catch {}
                        break
                    }
                    if ([DateTime]::UtcNow -ge $delDeadline) {
                        $timedOutDel = $true
                        try { $delP.Kill() } catch {}
                        try { [void]$delP.WaitForExit(500) } catch {}
                        break
                    }
                }
                if ($userAborted) { break }
                if ($timedOutDel) {
                    $errorCount++
                    Log-Text "   [WARN - Qu$([char]0x00E1) th$([char]0x1EDD)i gian x$([char]0x1EED) l$([char]0x00FD) g$([char]0x00F3)i $inf]"
                    continue
                }

                $delOut = if ($delOutTask.Wait(1000)) { $delOutTask.Result } else { "" }
                $delErr = if ($delErrTask.Wait(1000)) { $delErrTask.Result } else { "" }
                $combined = ($delOut + "`n" + $delErr).Trim()

                if ($delP.ExitCode -eq 0 -or $combined -match "deleted successfully|$([char]0x0111)$([char]0x00E3) x$([char]0x00F3)a th$([char]0x00E0)nh c$([char]0x00F4)ng") {
                    $deletedCount++
                    Log-Text "   [OK - $([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n] $inf"
                } elseif ($combined -match "installed using the specified INF|$([char]0x0111)ang $([char]0x0111)$([char]0x01B0)$([char]0x1EE3)c s$([char]0x1EED) d$([char]0x1EE5)ng|in use|b$([char]0x1ECB) t$([char]0x1EEB) ch$([char]0x1ED1)i") {
                    $inUseCount++
                } else {
                    $errorCount++
                    $errDetail = ($combined -split "`r?`n" | Where-Object { $_ -match "failed|l$([char]0x1ED7)i|error" } | Select-Object -First 1)
                    if (-not $errDetail) { $errDetail = "ExitCode $($delP.ExitCode)" }
                    Log-Text "   [WARN - L$([char]0x1ED7)i g$([char]0x00F3)i $inf] $errDetail"
                }
            } catch {
                $errorCount++
                Log-Text "   [!] L$([char]0x1ED7)i ngo$([char]0x1EA1)i l$([char]0x1EC7) khi x$([char]0x1EED) l$([char]0x00FD) ${inf}: $($_.Exception.Message)"
            } finally {
                if ($delP) { try { $delP.Dispose() } catch {} }
            }
            if ($hasForms) { try { [System.Windows.Forms.Application]::DoEvents() } catch {} }
        }

        if ($userAborted) {
            Log-Text "[!] $([char]0x0110)$([char]0x00E3) d$([char]0x1EEB)ng d$([char]0x1ECD)n d$([char]0x1EB9)p DriverStore theo y$([char]0x00EA)u c$([char]0x1EA7)u ($([char]0x0111)$([char]0x00E3) x$([char]0x00F3)a: $deletedCount, b$([char]0x1ECF) qua: $inUseCount, l$([char]0x1ED7)i: $errorCount)."
        } elseif ($deletedCount -gt 0) {
            Log-Text "[OK] Ho$([char]0x00E0)n t$([char]0x1EA5)t! $([char]0x0110)$([char]0x00E3) gi$([char]0x1EA3)i ph$([char]0x00F3)ng $deletedCount g$([char]0x00F3)i driver OEM c$([char]0x0169) kh$([char]0x00F4)ng c$([char]0x00F2)n s$([char]0x1EED) d$([char]0x1EE5)ng ($inUseCount g$([char]0x00F3)i $([char]0x0111)ang $([char]0x0111)$([char]0x01B0)$([char]0x1EE3)c ph$([char]0x1EA7)n c$([char]0x1EE9)ng s$([char]0x1EED) d$([char]0x1EE5)ng an to$([char]0x00E0)n)."
        } elseif ($errorCount -eq 0) {
            Log-Text "[OK] To$([char]0x00E0)n b$([char]0x1ED9) $($oemList.Count) g$([char]0x00F3)i driver OEM $([char]0x0111)$([char]0x1EC1)u $([char]0x0111)ang $([char]0x0111)$([char]0x01B0)$([char]0x1EE3)c c$([char]0x00E1)c thi$([char]0x1EBF)t b$([char]0x1ECB) ph$([char]0x1EA7)n c$([char]0x1EE9)ng s$([char]0x1EED) d$([char]0x1EE5)ng an to$([char]0x00E0)n."
        }
        if ($errorCount -gt 0 -and -not $userAborted) {
            Log-Text "[!] C$([char]0x00F3) $errorCount g$([char]0x00F3)i driver g$([char]0x1EB7)p l$([char]0x1ED7)i trong qu$([char]0x00E1) tr$([char]0x00EC)nh x$([char]0x1EED) l$([char]0x00FD)."
        }
    } catch {
        Log-Text "[!] L$([char]0x1ED7)i khi d$([char]0x1ECD)n d$([char]0x1EB9)p DriverStore: $($_.Exception.Message)"
    } finally {
        if ($p) { try { $p.Dispose() } catch {} }
    }
}

function Invoke-DismComponentCleanup {
    Log-Text "[WARN] C$([char]0x1EA2)NH B$([char]0x00C1)O: T$([char]0x00F9)y ch$([char]0x1ECD)n /ResetBase s$([char]0x1EBD) x$([char]0x00F3)a v$([char]0x0129)nh vi$([char]0x1EC5)n c$([char]0x00E1)c b$([char]0x1EA3)n c$([char]0x1EAD)p nh$([char]0x1EAD)t c$([char]0x0169) $([char]0x0111)$([char]0x00E3) b$([char]0x1ECB) thay th$([char]0x1EBF) trong WinSxS."
    Log-Text "[*] Sau khi ho$([char]0x00E0)n t$([char]0x1EA5)t thao t$([char]0x00E1)c n$([char]0x00E0)y, b$([char]0x1EA1)n S$([char]0x1EBC) KH$([char]0x00D4)NG TH$([char]0x1EC2) g$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t (rollback) c$([char]0x00E1)c b$([char]0x1EA3)n Windows Update hi$([char]0x1EC7)n t$([char]0x1EA1)i."
    Log-Text "[*] $([char]0x0110)ang ti$([char]0x1EBF)n h$([char]0x00E0)nh d$([char]0x1ECD)n d$([char]0x1EB9)p v$([char]0x00E0) n$([char]0x00E9)n kho linh ki$([char]0x1EC7)n WinSxS qua DISM..."
    $code = Run-CliStream "dism.exe" "/Online /Cleanup-Image /StartComponentCleanup /ResetBase"
    if ($code -eq 0) {
        Log-Text "[OK] D$([char]0x1ECD)n d$([char]0x1EB9)p kho linh ki$([char]0x1EC7)n WinSxS ho$([char]0x00E0)n t$([char]0x1EA5)t th$([char]0x00E0)nh c$([char]0x00F4)ng (ExitCode: 0)."
    } else {
        Log-Text "[!] D$([char]0x1ECD)n d$([char]0x1EB9)p kho linh ki$([char]0x1EC7)n WinSxS th$([char]0x1EA5)t b$([char]0x1EA1)i ho$([char]0x1EB7)c b$([char]0x1ECB) gi$([char]0x00E1)n $([char]0x0111)o$([char]0x1EA1)n (ExitCode: $code)."
    }
    return $code
}

function Export-SystemDriversBackup {
    param([string]$Destination = "C:\Backup_Drivers")

    if (-not (Test-Path -LiteralPath $Destination)) {
        try {
            New-Item -ItemType Directory -Path $Destination -Force -ErrorAction Stop | Out-Null
        } catch {
            Log-Text "[!] Kh$([char]0x00F4)ng th$([char]0x1EC3) t$([char]0x1EA1)o th$([char]0x01B0) m$([char]0x1EE5)c sao l$([char]0x01B0)u '$Destination': $($_.Exception.Message)"
            return $false
        }
    }

    try {
        Export-WindowsDriver -Online -Destination $Destination -ErrorAction Stop | Out-Null
        Log-Text "[OK] Sao l$([char]0x01B0)u to$([char]0x00E0)n b$([char]0x1ED9) driver th$([char]0x00E0)nh c$([char]0x00F4)ng qua Export-WindowsDriver."
        return $true
    } catch {
        Log-Text "[*] Export-WindowsDriver kh$([char]0x00F4)ng kh$([char]0x1EA3) d$([char]0x1EE5)ng ho$([char]0x1EB7)c b$([char]0x1ECB) t$([char]0x1EEB) ch$([char]0x1ED1)i, chuy$([char]0x1EC3)n sang pnputil.exe..."
        $exitCode = Run-CliStream "pnputil.exe" "/export-driver * `"$Destination`""
        if ($exitCode -eq 0) {
            Log-Text "[OK] Sao l$([char]0x01B0)u to$([char]0x00E0)n b$([char]0x1ED9) driver th$([char]0x00E0)nh c$([char]0x00F4)ng qua pnputil.exe (ExitCode: 0)."
            return $true
        } else {
            Log-Text "[!] Sao l$([char]0x01B0)u driver qua pnputil.exe th$([char]0x1EA5)t b$([char]0x1EA1)i (ExitCode: $exitCode)."
            return $false
        }
    }
}

function Get-StartupBackupDirectory {
    return (Join-Path $env:LOCALAPPDATA "AppDriver\StartupBackups")
}

function Get-StartupBackupsList {
    $dir = Get-StartupBackupDirectory
    if (-not [System.IO.Directory]::Exists($dir)) { return @() }
    return @(Get-ChildItem -LiteralPath $dir -Filter "batch_*.json" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending)
}

function Save-StartupGuardBatchBackup {
    param([Parameter(Mandatory = $true)]$Entries)
    $entryArr = @($Entries | Where-Object { $_ -and $_.CanDelete })
    if ($entryArr.Count -eq 0) { return "" }

    $dir = Get-StartupBackupDirectory
    if (-not [System.IO.Directory]::Exists($dir)) {
        [void][System.IO.Directory]::CreateDirectory($dir)
    }

    $items = [System.Collections.Generic.List[object]]::new()
    foreach ($e in $entryArr) {
        $apB64 = ""
        try {
            $apBytes = [DuckUtil.StartupManagerEngine]::ReadStartupApprovedBytes($e)
            if ($apBytes -and $apBytes.Length -gt 0) {
                $apB64 = [Convert]::ToBase64String($apBytes)
            }
        } catch {}

        $fileB64 = ""
        if (($e.SourceKind -eq "FolderUser" -or $e.SourceKind -eq "FolderAll") -and
            -not [string]::IsNullOrWhiteSpace([string]$e.FolderFilePath) -and
            (Test-Path -LiteralPath $e.FolderFilePath)) {
            try {
                $rawBytes = [System.IO.File]::ReadAllBytes($e.FolderFilePath)
                $fileB64 = [Convert]::ToBase64String($rawBytes)
            } catch {}
        }

        $taskXml = ""
        if ($e.SourceKind -eq "Task" -and -not [string]::IsNullOrWhiteSpace([string]$e.ScheduledTaskPath)) {
            try {
                $taskXml = [DuckUtil.StartupManagerEngine]::GetScheduledTaskXml([string]$e.ScheduledTaskPath)
            } catch {}
        }

        $svcMeta = $null
        if ($e.SourceKind -eq "Service" -and -not [string]::IsNullOrWhiteSpace([string]$e.ServiceName)) {
            try {
                $svcReg = "HKLM:\SYSTEM\CurrentControlSet\Services\$($e.ServiceName)"
                if (Test-Path -LiteralPath $svcReg) {
                    $sp = Get-ItemProperty -LiteralPath $svcReg -ErrorAction SilentlyContinue
                    if ($sp) {
                        $svcMeta = [PSCustomObject]@{
                            ServiceName      = [string]$e.ServiceName
                            DisplayName      = [string]$sp.DisplayName
                            ImagePath        = [string]$sp.ImagePath
                            Description      = [string]$sp.Description
                            ObjectName       = [string]$sp.ObjectName
                            Start            = if ($null -ne $sp.Start) { [int]$sp.Start } else { 3 }
                            Type             = if ($null -ne $sp.Type) { [int]$sp.Type } else { 16 }
                            ErrorControl     = if ($null -ne $sp.ErrorControl) { [int]$sp.ErrorControl } else { 1 }
                            DelayedAutostart = if ($null -ne $sp.DelayedAutostart) { [int]$sp.DelayedAutostart } else { 0 }
                        }
                    }
                }
            } catch {}
        }

        [void]$items.Add([PSCustomObject]@{
            Id                = [string]$e.Id
            Name              = [string]$e.Name
            DisplayName       = [string]$e.DisplayName
            SourceKind        = [string]$e.SourceKind
            RegistryHive      = [string]$e.RegistryHive
            RegistryPath      = [string]$e.RegistryPath
            RegistryValueName = [string]$e.RegistryValueName
            RawCommand        = [string]$e.RawCommand
            ApprovedHive      = [string]$e.ApprovedHive
            ApprovedPath      = [string]$e.ApprovedPath
            ApprovedValueName = [string]$e.ApprovedValueName
            ApprovedBase64    = $apB64
            FolderFilePath    = [string]$e.FolderFilePath
            FileContentBase64 = $fileB64
            ScheduledTaskPath = [string]$e.ScheduledTaskPath
            ScheduledTaskXml  = $taskXml
            ServiceMeta       = $svcMeta
        })
    }

    $stamp = Get-Date -Format "yyyyMMdd_HHmmss_fff"
    $uid = [Guid]::NewGuid().ToString("N").Substring(0, 8)
    $path = Join-Path $dir "batch_${stamp}_${uid}.json"

    $payload = [PSCustomObject]@{
        CreatedAt = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
        Count     = $items.Count
        Items     = @($items)
    }

    $json = $payload | ConvertTo-Json -Depth 6
    [System.IO.File]::WriteAllText($path, $json, [System.Text.UTF8Encoding]::new($false))
    Log-Text "[OK] StartupGuard: $([char]0x0110)$([char]0x00E3) sao l$([char]0x01B0)u l$([char]0x00F4) $($items.Count) m$([char]0x1EE5)c kh$([char]0x1EDF)i ch$([char]0x1EA1)y -> $([System.IO.Path]::GetFileName($path))"
    return $path
}

function Restore-LastStartupGuardBatch {
    $files = @(Get-StartupBackupsList)
    if ($files.Count -eq 0) {
        return [PSCustomObject]@{ Success = $false; Restored = 0; Failed = 0; Message = "Kh$([char]0x00F4)ng c$([char]0x00F3) b$([char]0x1EA3)n sao l$([char]0x01B0)u m$([char]0x1EE5)c $([char]0x0111)$([char]0x00E3) x$([char]0x00F3)a n$([char]0x00E0)o." }
    }
    $latest = $files[0]
    $restored = 0
    $failed = 0

    try {
        $raw = [System.IO.File]::ReadAllText($latest.FullName, [System.Text.Encoding]::UTF8)
        $obj = ConvertFrom-Json $raw
        if (-not $obj -or -not $obj.Items) {
            return [PSCustomObject]@{ Success = $false; Restored = 0; Failed = 1; Message = "T$([char]0x1EC7)p sao l$([char]0x01B0)u kh$([char]0x00F4)ng h$([char]0x1EE3)p l$([char]0x1EC7)." }
        }

        foreach ($it in @($obj.Items)) {
            $ok = $false
            $sk = [string]$it.SourceKind
            if ($sk -in @("RegUser", "RegUser32", "RegSystem", "RegWow32", "RegRunOnce", "RegPolicy")) {
                try {
                    $hiveEnum = if ($it.RegistryHive -eq "HKCU") { [Microsoft.Win32.RegistryHive]::CurrentUser } else { [Microsoft.Win32.RegistryHive]::LocalMachine }
                    $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($hiveEnum, [Microsoft.Win32.RegistryView]::Registry64)
                    try {
                        $subKey = $baseKey.CreateSubKey([string]$it.RegistryPath, [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree)
                        if ($subKey) {
                            try {
                                $subKey.SetValue([string]$it.RegistryValueName, [string]$it.RawCommand, [Microsoft.Win32.RegistryValueKind]::String)
                                $ok = $true
                            } finally { $subKey.Dispose() }
                        }
                    } finally { $baseKey.Dispose() }

                    if ($ok -and -not [string]::IsNullOrWhiteSpace([string]$it.ApprovedBase64)) {
                        $apBytes = [Convert]::FromBase64String([string]$it.ApprovedBase64)
                        [void][DuckUtil.StartupManagerEngine]::WriteStartupApprovedBytes([string]$it.ApprovedHive, [string]$it.ApprovedPath, [string]$it.ApprovedValueName, $apBytes)
                    }
                } catch {
                    Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) kh$([char]0x00F4)i ph$([char]0x1EE5)c m$([char]0x1EE5)c Registry '$($it.DisplayName)': $($_.Exception.Message)"
                }
            } elseif ($sk -eq "OrphanApproved") {
                try {
                    if (-not [string]::IsNullOrWhiteSpace([string]$it.ApprovedBase64)) {
                        $apBytes = [Convert]::FromBase64String([string]$it.ApprovedBase64)
                        $ok = [DuckUtil.StartupManagerEngine]::WriteStartupApprovedBytes([string]$it.ApprovedHive, [string]$it.ApprovedPath, [string]$it.ApprovedValueName, $apBytes)
                    }
                } catch {
                    Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) kh$([char]0x00F4)i ph$([char]0x1EE5)c kh$([char]0x00F3)a StartupApproved '$($it.DisplayName)': $($_.Exception.Message)"
                }
            } elseif ($sk -eq "FolderUser" -or $sk -eq "FolderAll") {
                try {
                    if (-not [string]::IsNullOrWhiteSpace([string]$it.FolderFilePath) -and -not [string]::IsNullOrWhiteSpace([string]$it.FileContentBase64)) {
                        $parent = Split-Path -Path $it.FolderFilePath -Parent
                        if (-not [System.IO.Directory]::Exists($parent)) {
                            [void][System.IO.Directory]::CreateDirectory($parent)
                        }
                        $bytes = [Convert]::FromBase64String([string]$it.FileContentBase64)
                        [System.IO.File]::WriteAllBytes([string]$it.FolderFilePath, $bytes)
                        $ok = $true
                        if (-not [string]::IsNullOrWhiteSpace([string]$it.ApprovedBase64)) {
                            $apBytes = [Convert]::FromBase64String([string]$it.ApprovedBase64)
                            [void][DuckUtil.StartupManagerEngine]::WriteStartupApprovedBytes([string]$it.ApprovedHive, [string]$it.ApprovedPath, [string]$it.ApprovedValueName, $apBytes)
                        }
                    }
                } catch {
                    Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) kh$([char]0x00F4)i ph$([char]0x1EE5)c t$([char]0x1EC7)p Startup '$($it.DisplayName)': $($_.Exception.Message)"
                }
            } elseif ($sk -eq "Task") {
                try {
                    if (-not [string]::IsNullOrWhiteSpace([string]$it.ScheduledTaskXml)) {
                        $regRes = [DuckUtil.StartupManagerEngine]::RegisterScheduledTaskFromXml([string]$it.ScheduledTaskPath, [string]$it.ScheduledTaskXml)
                        if ($regRes.Success) {
                            $ok = $true
                        } else {
                            Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) kh$([char]0x00F4)i ph$([char]0x1EE5)c t$([char]0x00E1)c v$([char]0x1EE5) '$($it.DisplayName)' (c$([char]0x00F3) th$([char]0x1EC3) y$([char]0x00EA)u c$([char]0x1EA7)u m$([char]0x1EAD)t kh$([char]0x1EA9)u t$([char]0x00E0)i kho$([char]0x1EA3)n TASK_LOGON_PASSWORD): $($regRes.Message)"
                        }
                    }
                } catch {
                    Log-Text "[WARN] L$([char]0x1ED7)i kh$([char]0x00F4)i ph$([char]0x1EE5)c t$([char]0x00E1)c v$([char]0x1EE5) '$($it.DisplayName)': $($_.Exception.Message)"
                }
            } elseif ($sk -eq "Service") {
                try {
                    $sm = $it.ServiceMeta
                    if ($sm -and -not [string]::IsNullOrWhiteSpace([string]$sm.ServiceName)) {
                        $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, [Microsoft.Win32.RegistryView]::Registry64)
                        try {
                            $subKey = $baseKey.CreateSubKey("SYSTEM\CurrentControlSet\Services\$($sm.ServiceName)", [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree)
                            if ($subKey) {
                                try {
                                    if ($sm.DisplayName) { $subKey.SetValue("DisplayName", [string]$sm.DisplayName, [Microsoft.Win32.RegistryValueKind]::String) }
                                    if ($sm.ImagePath)   { $subKey.SetValue("ImagePath", [string]$sm.ImagePath, [Microsoft.Win32.RegistryValueKind]::ExpandString) }
                                    if ($sm.Description) { $subKey.SetValue("Description", [string]$sm.Description, [Microsoft.Win32.RegistryValueKind]::String) }
                                    if ($sm.ObjectName)  { $subKey.SetValue("ObjectName", [string]$sm.ObjectName, [Microsoft.Win32.RegistryValueKind]::String) }
                                    $subKey.SetValue("Start", [int]$sm.Start, [Microsoft.Win32.RegistryValueKind]::DWord)
                                    $subKey.SetValue("Type", [int]$sm.Type, [Microsoft.Win32.RegistryValueKind]::DWord)
                                    $subKey.SetValue("ErrorControl", [int]$sm.ErrorControl, [Microsoft.Win32.RegistryValueKind]::DWord)
                                    if ([int]$sm.DelayedAutostart -eq 1) {
                                        $subKey.SetValue("DelayedAutostart", 1, [Microsoft.Win32.RegistryValueKind]::DWord)
                                    }
                                    $ok = $true
                                } finally { $subKey.Dispose() }
                            }
                        } finally { $baseKey.Dispose() }
                    }
                } catch {
                    Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) kh$([char]0x00F4)i ph$([char]0x1EE5)c d$([char]0x1ECB)ch v$([char]0x1EE5) '$($it.DisplayName)': $($_.Exception.Message)"
                }
            }

            if ($ok) { $restored++ } else { $failed++ }
        }

        $restoredDir = Join-Path (Get-StartupBackupDirectory) "Restored"
        if (-not [System.IO.Directory]::Exists($restoredDir)) {
            [void][System.IO.Directory]::CreateDirectory($restoredDir)
        }
        $destFile = Join-Path $restoredDir $latest.Name
        try {
            if (Test-Path -LiteralPath $destFile) { Remove-Item -LiteralPath $destFile -Force -ErrorAction SilentlyContinue }
            Move-Item -LiteralPath $latest.FullName -Destination $destFile -Force -ErrorAction SilentlyContinue
        } catch {}

        Log-Text "[OK] StartupGuard: $([char]0x0110)$([char]0x00E3) kh$([char]0x00F4)i ph$([char]0x1EE5)c $restored m$([char]0x1EE5)c kh$([char]0x1EDF)i ch$([char]0x1EA1)y t$([char]0x1EEB) b$([char]0x1EA3)n l$([char]0x01B0)u $($obj.CreatedAt) ($failed l$([char]0x1ED7)i)."
        return [PSCustomObject]@{ Success = ($restored -gt 0); Restored = $restored; Failed = $failed; Message = "$([char]0x0110)$([char]0x00E3) kh$([char]0x00F4)i ph$([char]0x1EE5)c $restored m$([char]0x1EE5)c ($failed l$([char]0x1ED7)i)." }
    } catch {
        Log-Text "[ERR] L$([char]0x1ED7)i kh$([char]0x00F4)i ph$([char]0x1EE5)c StartupGuard: $($_.Exception.Message)"
        return [PSCustomObject]@{ Success = $false; Restored = $restored; Failed = ($failed + 1); Message = $_.Exception.Message }
    }
}

function Get-StartupSourceLabel {
    param([string]$SourceKind)
    switch ($SourceKind) {
        "RegUser"        { return "Registry" }
        "RegUser32"      { return "Registry" }
        "RegSystem"      { return "Registry" }
        "RegWow32"       { return "Registry" }
        "RegRunOnce"     { return "RunOnce" }
        "RegPolicy"      { return "Policy" }
        "FolderUser"     { return "Th$([char]0x01B0) m$([char]0x1EE5)c" }
        "FolderAll"      { return "Th$([char]0x01B0) m$([char]0x1EE5)c" }
        "Store"          { return "Store" }
        "Task"           { return "Task" }
        "Service"        { return "D$([char]0x1ECB)ch v$([char]0x1EE5)" }
        "OrphanApproved" { return "R$([char]0x00E1)c Reg" }
        default          { return "Kh$([char]0x00E1)c" }
    }
}

function Get-StartupSourceDetail {
    param([string]$SourceKind, [string]$TriggerInfo = "")
    if (-not [string]::IsNullOrWhiteSpace($TriggerInfo)) {
        return $TriggerInfo
    }
    switch ($SourceKind) {
        "RegUser"        { return "Registry User (HKCU\Run)" }
        "RegUser32"      { return "Registry User 32-bit (HKCU\WOW6432Node\Run)" }
        "RegSystem"      { return "Registry System (HKLM\Run)" }
        "RegWow32"       { return "Registry System 32-bit (WOW6432Node\Run)" }
        "RegRunOnce"     { return "Registry RunOnce (Ch$([char]0x1EA1)y 1 l$([char]0x1EA7)n)" }
        "RegPolicy"      { return "Group Policy (Policies\Explorer\Run)" }
        "FolderUser"     { return "Th$([char]0x01B0) m$([char]0x1EE5)c Startup (User)" }
        "FolderAll"      { return "Th$([char]0x01B0) m$([char]0x1EE5)c Startup (All Users)" }
        "Store"          { return "$([char]0x1EE8)ng d$([char]0x1EE5)ng Microsoft Store (MSIX/UWP)" }
        "Task"           { return "Task Scheduler (@Logon / @Boot / @Unlock)" }
        "Service"        { return "D$([char]0x1ECB)ch v$([char]0x1EE5) Windows ch$([char]0x1EA1)y n$([char]0x1EC1)n (Auto-Start)" }
        "OrphanApproved" { return "Kh$([char]0x00F3)a r$([char]0x00E1)c StartupApproved" }
        default          { return "Kh$([char]0x1EDF)i ch$([char]0x1EA1)y Windows" }
    }
}

function Get-StartupImpactLabel {
    param([string]$ImpactLevel)
    switch ($ImpactLevel) {
        "High"   { return "N$([char]0x1EB7)ng" }
        "Medium" { return "Trung b$([char]0x00EC)nh" }
        default  { return "Nh$([char]0x1EB9)" }
    }
}

function Open-StartupEntryLocation {
    param($Entry)
    if (-not $Entry) { return }
    if ($Entry.SourceKind -eq "OrphanApproved") {
        Open-StartupEntryRegistry -Entry $Entry
        return
    }
    try {
        $candidates = @(
            [string]$Entry.SecondaryTargetPath,
            [string]$Entry.ResolvedExePath,
            [string]$Entry.FolderFilePath
        )
        $target = ""
        foreach ($c in $candidates) {
            if (-not [string]::IsNullOrWhiteSpace($c) -and (Test-Path -LiteralPath $c)) {
                $target = $c
                break
            }
        }
        if ([string]::IsNullOrWhiteSpace($target) -and -not [string]::IsNullOrWhiteSpace([string]$Entry.ResolvedExePath)) {
            $parentDir = Split-Path -Path ([string]$Entry.ResolvedExePath) -Parent -ErrorAction SilentlyContinue
            if (-not [string]::IsNullOrWhiteSpace($parentDir) -and (Test-Path -LiteralPath $parentDir -PathType Container)) {
                $target = $parentDir
            }
        }
        if ([string]::IsNullOrWhiteSpace($target)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$Entry.RegistryPath) -or $Entry.SourceKind -eq "Store" -or $Entry.SourceKind -eq "Service") {
                Open-StartupEntryRegistry -Entry $Entry
                return
            }
            Log-Text "[WARN] Kh$([char]0x00F4)ng t$([char]0x00EC)m th$([char]0x1EA5)y $([char]0x0111)$([char]0x01B0)$([char]0x1EDD)ng d$([char]0x1EAB)n t$([char]0x1EC7)p tr$([char]0x00EA)n $([char]0x1ED5) $([char]0x0111)$([char]0x0129)a $([char]0x0111)$([char]0x1EC3) m$([char]0x1EDF)."
            return
        }
        if (Test-Path -LiteralPath $target -PathType Container) {
            Start-Process "explorer.exe" -ArgumentList "`"$target`""
        } else {
            Start-Process "explorer.exe" -ArgumentList "/select,`"$target`""
        }
    } catch {
        Log-Text "[ERR] Kh$([char]0x00F4)ng th$([char]0x1EC3) m$([char]0x1EDF) th$([char]0x01B0) m$([char]0x1EE5)c t$([char]0x1EC7)p: $($_.Exception.Message)"
    }
}

function Open-StartupEntryRegistry {
    param($Entry)
    if (-not $Entry) { return }
    $regFull = ""
    if (-not [string]::IsNullOrWhiteSpace([string]$Entry.RegistryPath)) {
        $rootName = if ($Entry.RegistryHive -eq "HKCU") { "HKEY_CURRENT_USER" } else { "HKEY_LOCAL_MACHINE" }
        $regFull = "Computer\$rootName\$($Entry.RegistryPath)"
    } elseif ($Entry.SourceKind -eq "OrphanApproved" -and -not [string]::IsNullOrWhiteSpace([string]$Entry.ApprovedPath)) {
        $rootName = if ($Entry.ApprovedHive -eq "HKCU") { "HKEY_CURRENT_USER" } else { "HKEY_LOCAL_MACHINE" }
        $regFull = "Computer\$rootName\$($Entry.ApprovedPath)"
    } elseif ($Entry.SourceKind -eq "Store" -and -not [string]::IsNullOrWhiteSpace([string]$Entry.PackageFamilyName)) {
        $regFull = "Computer\HKEY_CURRENT_USER\Software\Classes\Local Settings\Software\Microsoft\Windows\CurrentVersion\AppModel\SystemAppData\$($Entry.PackageFamilyName)\$($Entry.TaskId)"
    } elseif ($Entry.SourceKind -eq "Service" -and -not [string]::IsNullOrWhiteSpace([string]$Entry.ServiceName)) {
        $regFull = "Computer\HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Services\$($Entry.ServiceName)"
    }
    if ([string]::IsNullOrWhiteSpace($regFull)) { return }
    try {
        $rePath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Applets\Regedit"
        if (-not (Test-Path -LiteralPath $rePath)) { [void](New-Item -Path $rePath -Force) }
        Set-ItemProperty -LiteralPath $rePath -Name "LastKey" -Value $regFull -Type String -ErrorAction SilentlyContinue
        Start-Process "regedit.exe" -ArgumentList "-m"
    } catch {
        Log-Text "[ERR] Kh$([char]0x00F4)ng th$([char]0x1EC3) m$([char]0x1EDF) Registry Editor: $($_.Exception.Message)"
    }
}

function Reset-WindowsUpdateEngine {
    Log-Text "[*] $([char]0x0110)ang d$([char]0x1EEB)ng c$([char]0x00E1)c d$([char]0x1ECB)ch v$([char]0x1EE5) Windows Update, BITS & DoSvc..."
    $services = @("wuauserv", "bits", "cryptsvc", "dosvc")
    foreach ($s in $services) {
        Stop-Service -Name $s -Force -ErrorAction SilentlyContinue
    }

    $sdRenamed = $false
    $crRenamed = $false
    try {
        $deadline = [DateTime]::UtcNow.AddMilliseconds(3000)
        $hasForms = ($null -ne ('System.Windows.Forms.Application' -as [type]))
        while ([DateTime]::UtcNow -lt $deadline) {
            if ($script:isWindowClosing) { break }
            $stillRunning = $false
            foreach ($s in $services) {
                try {
                    $svc = Get-Service -Name $s -ErrorAction SilentlyContinue
                    if ($svc -and "$($svc.Status)" -ne 'Stopped') {
                        $stillRunning = $true
                        break
                    }
                } catch {}
            }
            if (-not $stillRunning) { break }
            if ($hasForms) { try { [System.Windows.Forms.Application]::DoEvents() } catch {} }
            Start-Sleep -Milliseconds 120
        }

        if (-not $script:isWindowClosing) {
            Log-Text "[*] $([char]0x0110)ang l$([char]0x00E0)m m$([char]0x1EDB)i b$([char]0x1ED9) nh$([char]0x1EDB) $([char]0x0111)$([char]0x1EC7)m SoftwareDistribution v$([char]0x00E0) Catroot2..."
            $stamp = Get-Date -Format "yyyyMMdd_HHmmss"
            $winDir = if ($env:SystemRoot) { $env:SystemRoot } elseif ($env:WINDIR) { $env:WINDIR } else { "C:\Windows" }
            $sys32Dir = Join-Path $winDir "System32"

            $sdPath = Join-Path $winDir "SoftwareDistribution"
            $sdRenamed = $true
            if (Test-Path -LiteralPath $sdPath) {
                Get-ChildItem -LiteralPath $winDir -Filter "SoftwareDistribution.bak_*" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                    Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue
                }
                $backupSD = "SoftwareDistribution.bak_$stamp"
                Rename-Item -LiteralPath $sdPath -NewName $backupSD -Force -ErrorAction SilentlyContinue
                if (Test-Path -LiteralPath $sdPath) {
                    $sdRenamed = $false
                    Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) $([char]0x0111)$([char]0x1ED5)i t$([char]0x00EA)n SoftwareDistribution (t$([char]0x1EC7)p $([char]0x0111)ang b$([char]0x1ECB) kh$([char]0x00F3)a b$([char]0x1EDF)i ti$([char]0x1EBF)n tr$([char]0x00EC)nh kh$([char]0x00E1)c)."
                }
            }

            $crPath = Join-Path $sys32Dir "catroot2"
            $crRenamed = $true
            if (Test-Path -LiteralPath $crPath) {
                Get-ChildItem -LiteralPath $sys32Dir -Filter "catroot2.bak_*" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                    Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue
                }
                $backupCR = "catroot2.bak_$stamp"
                Rename-Item -LiteralPath $crPath -NewName $backupCR -Force -ErrorAction SilentlyContinue
                if (Test-Path -LiteralPath $crPath) {
                    $crRenamed = $false
                    Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) $([char]0x0111)$([char]0x1ED5)i t$([char]0x00EA)n catroot2 (t$([char]0x1EC7)p $([char]0x0111)ang b$([char]0x1ECB) kh$([char]0x00F3)a)."
                }
            }
        }
    } finally {
        Log-Text "[*] Kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i c$([char]0x00E1)c d$([char]0x1ECB)ch v$([char]0x1EE5) h$([char]0x1EC7) th$([char]0x1ED1)ng..."
        Start-Service -Name "cryptsvc" -ErrorAction SilentlyContinue
        Start-Service -Name "bits" -ErrorAction SilentlyContinue
        Start-Service -Name "wuauserv" -ErrorAction SilentlyContinue
        Start-Service -Name "dosvc" -ErrorAction SilentlyContinue
    }

    if ($script:isWindowClosing) { return }
    if ($sdRenamed -and $crRenamed) {
        Log-Text "[OK] $([char]0x0110)$([char]0x00E3) kh$([char]0x1EDF)i t$([char]0x1EA1)o l$([char]0x1EA1)i d$([char]0x1ECB)ch v$([char]0x1EE5) Windows Update v$([char]0x00E0) x$([char]0x00F3)a s$([char]0x1EA1)ch cache th$([char]0x00E0)nh c$([char]0x00F4)ng!"
    } else {
        Log-Text "[*] $([char]0x0110)$([char]0x00E3) $([char]0x0111)$([char]0x1EB7)t l$([char]0x1EA1)i d$([char]0x1ECB)ch v$([char]0x1EE5) Windows Update (m$([char]0x1ED9)t s$([char]0x1ED1) th$([char]0x01B0) m$([char]0x1EE5)c cache $([char]0x0111)ang $([char]0x0111)$([char]0x01B0)$([char]0x1EE3)c h$([char]0x1EC7) th$([char]0x1ED1)ng b$([char]0x1EA3)o v$([char]0x1EC7))."
    }
}

function Invoke-WindowsUpdateScan {
    Log-Text "[*] $([char]0x0110)ang g$([char]0x1EED)i t$([char]0x00ED)n hi$([char]0x1EC7)u y$([char]0x00EA)u c$([char]0x1EA7)u Windows t$([char]0x00EC)m ki$([char]0x1EBF)m b$([char]0x1EA3)n c$([char]0x1EAD)p nh$([char]0x1EAD)t m$([char]0x1EDB)i..."
    try {
        $au = New-Object -ComObject Microsoft.Update.AutoUpdate
        $au.DetectNow()
        Log-Text "[OK] $([char]0x0110)$([char]0x00E3) k$([char]0x00ED)ch ho$([char]0x1EA1)t Microsoft.Update.AutoUpdate.DetectNow() th$([char]0x00E0)nh c$([char]0x00F4)ng."
    } catch {
        Log-Text "[*] COM AutoUpdate kh$([char]0x00F4)ng ph$([char]0x1EA3)n h$([char]0x1ED3)i, m$([char]0x1EDF) trang c$([char]0x1EAD)p nh$([char]0x1EAD)t h$([char]0x1EC7) th$([char]0x1ED1)ng..."
    }

    try {
        Start-Process "ms-settings:windowsupdate-action" -ErrorAction SilentlyContinue
    } catch {}
}

