function Reset-NetworkInterfaceStack {
    $codeWinsock = Run-CliStream "netsh.exe" "winsock reset"
    $codeTcpIp = Run-CliStream "netsh.exe" "int ip reset"
    if ($codeWinsock -eq 0 -and $codeTcpIp -eq 0) {
        Log-Text "[OK] $([char]0x0110)$([char]0x1EB7)t l$([char]0x1EA1)i Winsock Catalog v$([char]0x00E0) TCP/IP Stack th$([char]0x00E0)nh c$([char]0x00F4)ng (ExitCode: 0). Khuy$([char]0x00EA)n b$([char]0x1EA1)n n$([char]0x00EA)n kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i m$([char]0x00E1)y."
    } else {
        Log-Text "[!] $([char]0x0110)$([char]0x1EB7)t l$([char]0x1EA1)i m$([char]0x1EA1)ng g$([char]0x1EB7)p l$([char]0x1ED7)i (Winsock ExitCode: $codeWinsock, TCP/IP ExitCode: $codeTcpIp)."
    }
    return ($codeWinsock -eq 0 -and $codeTcpIp -eq 0)
}

function Clear-SystemTempFiles {
    $winDir = if ($env:SystemRoot) { $env:SystemRoot } elseif ($env:WINDIR) { $env:WINDIR } else { "C:\Windows" }
    $tempPaths = @($env:TEMP, (Join-Path $winDir "Temp")) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique
    $removedCount = 0
    $skippedCount = 0
    foreach ($p in $tempPaths) {
        if (Test-Path -LiteralPath $p) {
            Get-ChildItem -LiteralPath $p -Force -ErrorAction SilentlyContinue | ForEach-Object {
                if (($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) {
                    $skippedCount++
                    return
                }
                try {
                    Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction Stop
                    $removedCount++
                } catch {
                    $skippedCount++
                }
            }
        }
    }
    Log-Text "[OK] $([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n $removedCount m$([char]0x1EE5)c t$([char]0x1EC7)p t$([char]0x1EA1)m h$([char]0x1EC7) th$([char]0x1ED1)ng ($skippedCount m$([char]0x1EE5)c $([char]0x0111)ang s$([char]0x1EED) d$([char]0x1EE5)ng/b$([char]0x1ECF) qua)."
}

function Clear-SystemEventLogs {
    Log-Text "[*] $([char]0x0110)ang qu$([char]0x00E9)t v$([char]0x00E0) d$([char]0x1ECD)n s$([char]0x1EA1)ch nh$([char]0x1EAD)t k$([char]0x00FD) s$([char]0x1EF1) ki$([char]0x1EC7)n Windows Event Logs..."
    Get-WinEvent -ListLog * -ErrorAction SilentlyContinue | ForEach-Object {
        try {
            [System.Diagnostics.Eventing.Reader.EventLogSession]::GlobalSession.ClearLog($_.LogName)
        } catch {}
    }
    Log-Text "[OK] To$([char]0x00E0)n b$([char]0x1ED9) Windows Event Logs $([char]0x0111)$([char]0x00E3) $([char]0x0111)$([char]0x01B0)$([char]0x1EE3)c l$([char]0x00E0)m s$([char]0x1EA1)ch."
}

function Get-OptimizerBackupDirectory {
    return (Join-Path $env:LOCALAPPDATA "AppDriver\OptimizerBackups")
}

function Get-OptimizerBackupsList {
    $dir = Get-OptimizerBackupDirectory
    if (-not [System.IO.Directory]::Exists($dir)) { return @() }
    $files = @(Get-ChildItem -LiteralPath $dir -Filter "snapshot_*.json" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending)
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($f in $files) {
        try {
            $raw = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8)
            $obj = ConvertFrom-Json $raw
            if ($obj) {
                $list.Add([PSCustomObject]@{
                    Path        = $f.FullName
                    FileName    = $f.Name
                    CreatedAt   = [string]$obj.CreatedAt
                    TweakCount  = if ($obj.TweakIds) { @($obj.TweakIds).Count } else { 0 }
                    TweakNames  = if ($obj.TweakNames) { @($obj.TweakNames) } else { @() }
                    RegCount    = if ($obj.Registry) { @($obj.Registry).Count } else { 0 }
                    SvcCount    = if ($obj.Services) { @($obj.Services).Count } else { 0 }
                })
            }
        } catch {}
    }
    return $list.ToArray()
}

function ConvertTo-RegTweakSpecs {
    param($TweakObjects)
    $list = [System.Collections.Generic.List[DuckUtil.RegTweakSpec]]::new()
    foreach ($tw in @($TweakObjects)) {
        if (-not $tw -or -not $tw.Registry) { continue }
        foreach ($r in @($tw.Registry)) {
            if (-not $r -or [string]::IsNullOrWhiteSpace([string]$r.Path)) { continue }
            $spec = [DuckUtil.RegTweakSpec]::new()
            $spec.Hive = if ([string]::IsNullOrWhiteSpace([string]$r.Hive)) { "HKLM" } else { [string]$r.Hive }
            $spec.Path = [string]$r.Path
            $spec.Name = [string]$r.Name
            $spec.ValueType = if ([string]::IsNullOrWhiteSpace([string]$r.ValueType)) { "DWord" } else { [string]$r.ValueType }
            $spec.ApplyValue = [string]$r.ApplyValue
            $spec.UndoValue = [string]$r.UndoValue
            [void]$list.Add($spec)
        }
    }
    return $list.ToArray()
}

function ConvertTo-ServiceTweakSpecs {
    param($TweakObjects)
    $list = [System.Collections.Generic.List[DuckUtil.ServiceTweakSpec]]::new()
    foreach ($tw in @($TweakObjects)) {
        if (-not $tw -or -not $tw.Services) { continue }
        foreach ($s in @($tw.Services)) {
            if (-not $s -or [string]::IsNullOrWhiteSpace([string]$s.Name)) { continue }
            $spec = [DuckUtil.ServiceTweakSpec]::new()
            $spec.Name = [string]$s.Name
            $spec.ApplyStart = [int]$s.ApplyStart
            $spec.UndoStart = [int]$s.UndoStart
            [void]$list.Add($spec)
        }
    }
    return $list.ToArray()
}

function Build-TweakProbeRequests {
    param($Tweaks)
    $reqs = [System.Collections.Generic.List[DuckUtil.TweakProbeRequest]]::new()
    foreach ($tw in @($Tweaks)) {
        if (-not $tw) { continue }
        $req = [DuckUtil.TweakProbeRequest]::new()
        $req.Id = [string]$tw.Id
        $req.ProbeKind = [string]$tw.ProbeKind
        $req.Registry = ConvertTo-RegTweakSpecs @($tw)
        $req.Services = ConvertTo-ServiceTweakSpecs @($tw)
        [void]$reqs.Add($req)
    }
    return $reqs.ToArray()
}

function New-OptimizerRestorePoint {
    $freqPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore"
    $hadFreq = $false
    $oldFreq = $null
    try {
        if (Test-Path -LiteralPath $freqPath) {
            $prop = Get-ItemProperty -LiteralPath $freqPath -Name "SystemRestorePointCreationFrequency" -ErrorAction SilentlyContinue
            if ($null -ne $prop -and $null -ne $prop.SystemRestorePointCreationFrequency) {
                $hadFreq = $true
                $oldFreq = $prop.SystemRestorePointCreationFrequency
            }
            Set-ItemProperty -LiteralPath $freqPath -Name "SystemRestorePointCreationFrequency" -Value 0 -Type DWord -ErrorAction SilentlyContinue
        }
        $desc = "App-Driver Optimizer " + (Get-Date -Format "yyyy-MM-dd HH:mm")
        $sysDrv = ($env:SystemDrive + "\").Replace("'", "''")
        $psCmd = "try { Enable-ComputerRestore -Drive '$sysDrv' -ErrorAction SilentlyContinue } catch {}; Checkpoint-Computer -Description '$desc' -RestorePointType 'MODIFY_SETTINGS' -ErrorAction Stop"
        $b64Cmd = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($psCmd))
        $code = Run-CliStream "powershell.exe" "-NoProfile -ExecutionPolicy Bypass -EncodedCommand $b64Cmd" -IsolateStdin -AllowCancel -CaptureOutput -TimeoutSeconds 90 -IdleTimeoutSeconds 60
        if ($code -eq 0) {
            Log-Text "[OK] $([char]0x0110)$([char]0x00E3) t$([char]0x1EA1)o $([char]0x0111)i$([char]0x1EC3)m kh$([char]0x00F4)i ph$([char]0x1EE5)c h$([char]0x1EC7) th$([char]0x1ED1)ng (System Restore Point)."
            return $true
        }
        Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) t$([char]0x1EA1)o Restore Point (m$([char]0x00E3) tho$([char]0x00E1)t $code - c$([char]0x00F3) th$([char]0x1EC3) System Protection $([char]0x0111)ang t$([char]0x1EAF)t ho$([char]0x1EB7)c m$([char]0x1EDB)i t$([char]0x1EA1)o g$([char]0x1EA7)n $([char]0x0111)$([char]0x00E2)y)."
        return $false
    } catch {
        Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) t$([char]0x1EA1)o Restore Point: $($_.Exception.Message)"
        return $false
    } finally {
        try {
            if (Test-Path -LiteralPath $freqPath) {
                if ($hadFreq) {
                    Set-ItemProperty -LiteralPath $freqPath -Name "SystemRestorePointCreationFrequency" -Value $oldFreq -Type DWord -ErrorAction SilentlyContinue
                } else {
                    Remove-ItemProperty -LiteralPath $freqPath -Name "SystemRestorePointCreationFrequency" -ErrorAction SilentlyContinue
                }
            }
        } catch {}
    }
}

function Get-ActivePowerSchemeGuid {
    try {
        $out = & powercfg.exe /getactivescheme 2>$null
        if ($out -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') {
            return $Matches[1]
        }
    } catch {}
    return ""
}

function Save-OptimizerGuardSnapshot {
    param(
        $Tweaks,
        $HardwareProfile = $null
    )
    if (-not ("DuckUtil.WindowsOptimizerEngine" -as [type])) { return $null }
    $regSpecs = ConvertTo-RegTweakSpecs $Tweaks
    $svcSpecs = ConvertTo-ServiceTweakSpecs $Tweaks

    $hasPowerTweak = $false
    $taskNames = [System.Collections.Generic.List[string]]::new()
    $tweakIds = [System.Collections.Generic.List[string]]::new()
    $tweakNames = [System.Collections.Generic.List[string]]::new()
    $needsExplorer = $false

    foreach ($tw in @($Tweaks)) {
        if (-not $tw) { continue }
        [void]$tweakIds.Add([string]$tw.Id)
        [void]$tweakNames.Add([string]$tw.Name)
        if ($tw.NeedsExplorerRestart) { $needsExplorer = $true }
        if ($tw.Action -eq "UltimatePerf") { $hasPowerTweak = $true }
        if ($tw.Tasks) {
            foreach ($tk in @($tw.Tasks)) {
                if (-not [string]::IsNullOrWhiteSpace([string]$tk) -and -not $taskNames.Contains([string]$tk)) {
                    [void]$taskNames.Add([string]$tk)
                }
            }
        }
    }

    if ($regSpecs.Length -eq 0 -and $svcSpecs.Length -eq 0 -and $taskNames.Count -eq 0 -and -not $hasPowerTweak) {
        return $null
    }

    $regSnaps = [DuckUtil.WindowsOptimizerEngine]::CaptureRegistrySnapshots($regSpecs)
    $svcSnaps = [DuckUtil.WindowsOptimizerEngine]::CaptureServiceSnapshots($svcSpecs)
    $powerGuid = if ($hasPowerTweak) { Get-ActivePowerSchemeGuid } else { "" }

    $dir = Get-OptimizerBackupDirectory
    if (-not [System.IO.Directory]::Exists($dir)) {
        [System.IO.Directory]::CreateDirectory($dir) | Out-Null
    }
    $stamp = (Get-Date -Format "yyyyMMdd_HHmmss_fff") + "_" + ([Guid]::NewGuid().ToString("N").Substring(0, 6))
    $snapPath = Join-Path $dir "snapshot_$stamp.json"

    $payload = [PSCustomObject]@{
        CreatedAt            = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
        HardwareSummary      = if ($HardwareProfile) { [string]$HardwareProfile.SummaryText } else { "" }
        TweakIds             = @($tweakIds)
        TweakNames           = @($tweakNames)
        NeedsExplorerRestart = $needsExplorer
        PowerSchemeGuid      = $powerGuid
        Tasks                = @($taskNames)
        Registry             = @($regSnaps)
        Services             = @($svcSnaps)
    }

    $json = $payload | ConvertTo-Json -Depth 6
    [System.IO.File]::WriteAllText($snapPath, $json, [System.Text.UTF8Encoding]::new($false))
    Log-Text "[OK] OptimizerGuard: $([char]0x0110)$([char]0x00E3) sao l$([char]0x01B0)u tr$([char]0x1EA1)ng th$([char]0x00E1)i g$([char]0x1ED1)c ($($regSnaps.Length) Registry, $($svcSnaps.Length) Service) -> $([System.IO.Path]::GetFileName($snapPath))"
    return $snapPath
}

function Restore-OptimizerGuardSnapshot {
    param([Parameter(Mandatory = $true)][string]$SnapshotPath)
    if (-not (Test-Path -LiteralPath $SnapshotPath)) {
        Log-Text "[ERR] Kh$([char]0x00F4)ng t$([char]0x00EC)m th$([char]0x1EA5)y t$([char]0x1EC7)p sao l$([char]0x01B0)u: $SnapshotPath"
        return $false
    }
    if (-not ("DuckUtil.WindowsOptimizerEngine" -as [type])) { return $false }
    try {
        $raw = [System.IO.File]::ReadAllText($SnapshotPath, [System.Text.Encoding]::UTF8)
        $obj = ConvertFrom-Json $raw
        if (-not $obj) { return $false }

        $regRestored = 0
        if ($obj.Registry) {
            $arr = [System.Collections.Generic.List[DuckUtil.RegistrySnapshotEntry]]::new()
            foreach ($r in @($obj.Registry)) {
                $e = [DuckUtil.RegistrySnapshotEntry]::new()
                $e.Hive = [string]$r.Hive
                $e.Path = [string]$r.Path
                $e.Name = [string]$r.Name
                $e.Existed = [bool]$r.Existed
                $e.KeyExisted = [bool]$r.KeyExisted
                $e.Kind = [string]$r.Kind
                $e.ValueData = [string]$r.ValueData
                [void]$arr.Add($e)
            }
            $regRestored = [DuckUtil.WindowsOptimizerEngine]::RestoreRegistrySnapshots($arr.ToArray())
        }

        $svcRestored = 0
        if ($obj.Services) {
            $arrS = [System.Collections.Generic.List[DuckUtil.ServiceSnapshotEntry]]::new()
            foreach ($s in @($obj.Services)) {
                $e = [DuckUtil.ServiceSnapshotEntry]::new()
                $e.Name = [string]$s.Name
                $e.Existed = [bool]$s.Existed
                $e.OriginalStart = [int]$s.OriginalStart
                [void]$arrS.Add($e)
            }
            $svcRestored = [DuckUtil.WindowsOptimizerEngine]::RestoreServiceSnapshots($arrS.ToArray())
        }

        if ($obj.Tasks) {
            $tkArr = @($obj.Tasks | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
            if ($tkArr.Count -gt 0 -and ("DuckUtil.WindowsOptimizerEngine" -as [type])) {
                $tkTask = [DuckUtil.WindowsOptimizerEngine]::SetScheduledTasksEnabledAsync([string[]]$tkArr, $true)
                if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
                    [void](Wait-TaskNonBlocking -Task $tkTask -TimeoutSeconds 20 -CancelCheck { [bool]$script:cancelRequested })
                } else { [void]$tkTask.Wait(20000) }
            }
        }

        if (-not [string]::IsNullOrWhiteSpace([string]$obj.PowerSchemeGuid)) {
            try { & powercfg.exe /setactive "$($obj.PowerSchemeGuid)" 2>$null | Out-Null } catch {}
        }

        if ($obj.NeedsExplorerRestart) {
            Restart-ExplorerSoft
        }

        Log-Text "[OK] OptimizerGuard: $([char]0x0110)$([char]0x00E3) kh$([char]0x00F4)i ph$([char]0x1EE5)c ho$([char]0x00E0)n ch$([char]0x1EC9)nh ($regRestored Registry, $svcRestored Service) t$([char]0x1EEB) b$([char]0x1EA3)n l$([char]0x01B0)u $($obj.CreatedAt)."
        return $true
    } catch {
        Log-Text "[ERR] L$([char]0x1ED7)i kh$([char]0x00F4)i ph$([char]0x1EE5)c b$([char]0x1EA3)n sao l$([char]0x01B0)u: $($_.Exception.Message)"
        return $false
    }
}

function Invoke-SafeBackgroundAppsTweak {
    param([ValidateSet("Apply", "Undo")][string]$Mode = "Apply")
    try {
        $isUndo = ($Mode -eq "Undo")
        $bgPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications"
        if (-not (Test-Path -LiteralPath $bgPath)) {
            [void](New-Item -Path $bgPath -Force -ErrorAction SilentlyContinue)
        }
        Set-ItemProperty -LiteralPath $bgPath -Name "GlobalUserDisabled" -Value 0 -Type DWord -ErrorAction SilentlyContinue
        if ($isUndo) {
            Remove-ItemProperty -LiteralPath $bgPath -Name "AppDriverSafeBgFilter" -ErrorAction SilentlyContinue
        } else {
            Set-ItemProperty -LiteralPath $bgPath -Name "AppDriverSafeBgFilter" -Value 1 -Type DWord -ErrorAction SilentlyContinue
        }

        $apPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy"
        if (Test-Path -LiteralPath $apPath) {
            Remove-ItemProperty -LiteralPath $apPath -Name "LetAppsRunInBackground" -ErrorAction SilentlyContinue
        }

        $oemAndSystemRegex = 'Lenovo|Vantage|Legion|ThinkPad|IdeaPad|ASUS|Armoury|ROG|MyASUS|ATK|Acer|Nitro|Predator|MSI|Dragon|MicroStar|Dell|Alienware|HP|OMEN|Victus|Gigabyte|AORUS|Razer|Logitech|Corsair|SteelSeries|Samsung|LG|Huawei|Xiaomi|Surface|NVIDIA|AMD|Radeon|Intel|Thunderbolt|Realtek|Dolby|Nahimic|DTS|Waves|SoundResearch|Synaptics|ELAN|Wacom|SecHealth|WindowsDefender|WindowsStore|DesktopAppInstaller|WindowsTerminal|ShellExperience|StartMenuExperience|Client\.CBS|LockApp|AAD\.Broker'
        $bloatAppRegex = 'BingNews|BingWeather|BingFinance|BingSports|Solitaire|FeedbackHub|WindowsMaps|ZuneVideo|ZuneMusic|People|GetHelp|Getstarted|Clipchamp|SkypeApp|MixedReality|3DViewer|MicrosoftOfficeHub|Cortana|549981C3F5F10'

        foreach ($sub in @(Get-ChildItem -LiteralPath $bgPath -ErrorAction SilentlyContinue)) {
            $pkgName = [string]$sub.PSChildName
            if ($pkgName -match $oemAndSystemRegex) {
                Set-ItemProperty -LiteralPath $sub.PSPath -Name "Disabled" -Value 0 -Type DWord -ErrorAction SilentlyContinue
                Set-ItemProperty -LiteralPath $sub.PSPath -Name "DisabledByUser" -Value 0 -Type DWord -ErrorAction SilentlyContinue
            } elseif ($pkgName -match $bloatAppRegex) {
                $targetVal = if ($isUndo) { 0 } else { 1 }
                Set-ItemProperty -LiteralPath $sub.PSPath -Name "Disabled" -Value $targetVal -Type DWord -ErrorAction SilentlyContinue
                Set-ItemProperty -LiteralPath $sub.PSPath -Name "DisabledByUser" -Value $targetVal -Type DWord -ErrorAction SilentlyContinue
            }
        }
        return $true
    } catch {
        return $false
    }
}

function Repair-OemPowerAndLegionThermalMode {
    param([switch]$Silent, [switch]$ResetPowerPlan)
    try {
        $bgPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications"
        if (Test-Path -LiteralPath $bgPath) {
            Set-ItemProperty -LiteralPath $bgPath -Name "GlobalUserDisabled" -Value 0 -Type DWord -ErrorAction SilentlyContinue
            $oemAndSystemRegex = 'Lenovo|Vantage|Legion|ThinkPad|IdeaPad|ASUS|Armoury|ROG|MyASUS|ATK|Acer|Nitro|Predator|MSI|Dragon|MicroStar|Dell|Alienware|HP|OMEN|Victus|Gigabyte|AORUS|Razer|Logitech|Corsair|SteelSeries|Samsung|LG|Huawei|Xiaomi|Surface|NVIDIA|AMD|Radeon|Intel|Thunderbolt|Realtek|Dolby|Nahimic|DTS|Waves|SoundResearch|Synaptics|ELAN|Wacom|SecHealth|WindowsDefender|WindowsStore|DesktopAppInstaller|WindowsTerminal|ShellExperience|StartMenuExperience|Client\.CBS|LockApp|AAD\.Broker'
            foreach ($sub in @(Get-ChildItem -LiteralPath $bgPath -ErrorAction SilentlyContinue)) {
                if ([string]$sub.PSChildName -match $oemAndSystemRegex) {
                    Set-ItemProperty -LiteralPath $sub.PSPath -Name "Disabled" -Value 0 -Type DWord -ErrorAction SilentlyContinue
                    Set-ItemProperty -LiteralPath $sub.PSPath -Name "DisabledByUser" -Value 0 -Type DWord -ErrorAction SilentlyContinue
                }
            }
        }
        $apPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy"
        if (Test-Path -LiteralPath $apPath) {
            Remove-ItemProperty -LiteralPath $apPath -Name "LetAppsRunInBackground" -ErrorAction SilentlyContinue
        }

        $smPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager"
        if (Test-Path -LiteralPath $smPath) {
            Remove-ItemProperty -LiteralPath $smPath -Name "DisableWpbtExecution" -ErrorAction SilentlyContinue
        }

        foreach ($legacyPol in @(
            @{ Path = "HKCU:\Software\Policies\Microsoft\Windows\Explorer"; Name = "DisableNotificationCenter" },
            @{ Path = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer"; Name = "HideRecommendedSection" },
            @{ Path = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\LocationAndSensors"; Name = "DisableLocation" },
            @{ Path = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DriverSearching"; Name = "DontPromptForWindowsUpdate" },
            @{ Path = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Device Metadata"; Name = "PreventDeviceMetadataFromNetwork" }
        )) {
            if (Test-Path -LiteralPath $legacyPol.Path) {
                Remove-ItemProperty -LiteralPath $legacyPol.Path -Name $legacyPol.Name -ErrorAction SilentlyContinue
            }
        }

        $ctrlPath = "HKLM:\SYSTEM\CurrentControlSet\Control"
        if (Test-Path -LiteralPath $ctrlPath) {
            $curSplit = (Get-ItemProperty -LiteralPath $ctrlPath -Name "SvcHostSplitThresholdInKB" -ErrorAction SilentlyContinue).SvcHostSplitThresholdInKB
            if (($curSplit -eq 3670016 -or $curSplit -eq 380000000) -and ("DuckUtil.WindowsOptimizerEngine" -as [type])) {
                $hw = [DuckUtil.WindowsOptimizerEngine]::DetectHardwareProfile()
                if ($hw -and $hw.TotalRamGb -gt 4) {
                    $ramKb = [int]($hw.TotalRamGb * 1048576)
                    Set-ItemProperty -LiteralPath $ctrlPath -Name "SvcHostSplitThresholdInKB" -Value $ramKb -Type DWord -ErrorAction SilentlyContinue
                }
            }
        }

        if ($ResetPowerPlan) {
            $curScheme = (& powercfg.exe /getactivescheme 2>$null) -join " "
            if ($curScheme -match 'Ultimate Performance|e9a42b02-d5df-448d-aa00-03f14749eb61') {
                $balGuid = "381b4222-f694-41f0-9685-ff5bb260df2e"
                try { & powercfg.exe /setactive $balGuid 2>$null | Out-Null } catch {}
            }
        }
        $psRoot = "HKLM:\SYSTEM\CurrentControlSet\Control\Power\User\PowerSchemes"
        if (Test-Path -LiteralPath $psRoot) {
            $curOv = (Get-ItemProperty -LiteralPath $psRoot -Name "ActiveOverlayAcPowerScheme" -ErrorAction SilentlyContinue).ActiveOverlayAcPowerScheme
            if ($curOv -eq "961cc777-2547-4f9d-8174-7d86181b8a7a") {
                Set-ItemProperty -LiteralPath $psRoot -Name "ActiveOverlayAcPowerScheme" -Value "00000000-0000-0000-0000-000000000000" -ErrorAction SilentlyContinue
            }
        }

        $coreAutoServices = @("WpnService", "ShellHWDetection", "CDPSvc", "DPS", "FontCache", "iphlpsvc", "PcaSvc", "SysMain", "TrkWks")
        foreach ($sn in $coreAutoServices) {
            $svcReg = "HKLM:\SYSTEM\CurrentControlSet\Services\$sn"
            if (Test-Path -LiteralPath $svcReg) {
                $curSt = (Get-ItemProperty -LiteralPath $svcReg -Name "Start" -ErrorAction SilentlyContinue).Start
                if ($curSt -eq 3 -or $curSt -eq 4) {
                    Set-ItemProperty -LiteralPath $svcReg -Name "Start" -Value 2 -Type DWord -ErrorAction SilentlyContinue
                }
                if ($sn -in @("WpnService", "ShellHWDetection", "SysMain", "PcaSvc")) {
                    try { Start-Service -Name $sn -ErrorAction SilentlyContinue } catch {}
                }
            }
        }
        foreach ($sn in @("HidServ", "MsKeyboardFilter", "DialogBlockingService", "AppVClient", "tzautoupdate")) {
            $svcReg = "HKLM:\SYSTEM\CurrentControlSet\Services\$sn"
            if (Test-Path -LiteralPath $svcReg) {
                $curSt = (Get-ItemProperty -LiteralPath $svcReg -Name "Start" -ErrorAction SilentlyContinue).Start
                if ($curSt -eq 4) {
                    Set-ItemProperty -LiteralPath $svcReg -Name "Start" -Value 3 -Type DWord -ErrorAction SilentlyContinue
                }
                if ($sn -eq "HidServ") {
                    try { Start-Service -Name $sn -ErrorAction SilentlyContinue } catch {}
                }
            }
        }

        $oemPattern = '^(Lenovo|Legion|ImController|IBMPMSVC|LITSSVC|TPHK|LZService|ASUS|Armoury|ROG|Aura|ATK|LightingService|AsHidSrv|AsSysCtrlService|MSI|Micro Star|DragonCenter|Mystic_Light|Acer|Nitro|Predator|PSService|PSAgent|accSvc|QAAdminAgent|Dell|Alienware|AWCC|DPMService|DDV|HP|Omen|Gigabyte|Aorus|GCC|GvBios|Razer|RzAction|NVDisplay|NvContainer|AMD|AmdPpkgSvc|RtkAudio|Dolby|DAX3|Nahimic)'
        foreach ($sv in @(Get-Service -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $oemPattern })) {
            $svcReg = "HKLM:\SYSTEM\CurrentControlSet\Services\$($sv.Name)"
            $curSt = (Get-ItemProperty -LiteralPath $svcReg -Name "Start" -ErrorAction SilentlyContinue).Start
            if ($curSt -eq 4) {
                Set-ItemProperty -LiteralPath $svcReg -Name "Start" -Value 2 -Type DWord -ErrorAction SilentlyContinue
            }
            if ($sv.Status -ne 'Running' -and ($curSt -eq 2 -or $sv.Name -match 'LenovoFn|LenovoVantage|Armoury|AsusSystemControl|ATKGFNEX|MSI_Center|NitroSense|PredatorSense|AWCC|HPOmenCap')) {
                try { Start-Service -Name $sv.Name -ErrorAction SilentlyContinue } catch {}
            }
        }

        $hasLegion = (Test-Path -LiteralPath "HKLM:\SOFTWARE\Lenovo\VantageService") -or ($null -ne (Get-Service -Name "LenovoVantageService" -ErrorAction SilentlyContinue))
        if ($hasLegion) {
            try {
                $wmiOther = Get-CimInstance -Namespace "root\WMI" -ClassName "LENOVO_OTHER_METHOD" -ErrorAction SilentlyContinue
                if ($wmiOther) {
                    [void](Invoke-CimMethod -InputObject $wmiOther -MethodName "SetFeatureValue" -Arguments @{ IDs = [int]1048576; value = [int]1 } -ErrorAction SilentlyContinue)
                }
            } catch {}
            foreach ($svcName in @("LenovoFnAndFunctionKeys", "LenovoVantageService")) {
                $sv = Get-Service -Name $svcName -ErrorAction SilentlyContinue
                if ($sv) {
                    try { Set-Service -Name $svcName -StartupType Automatic -ErrorAction SilentlyContinue } catch {}
                    try {
                        if (-not $Silent) {
                            Restart-Service -Name $svcName -Force -ErrorAction SilentlyContinue
                        } elseif ($sv.Status -ne 'Running') {
                            Start-Service -Name $svcName -ErrorAction SilentlyContinue
                        }
                    } catch {}
                }
            }
            if (-not $Silent) {
                Log-Text "[OK] $([char]0x0110)$([char]0x00E3) $([char]0x0111)$([char]0x1ED3)ng b$([char]0x1ED9) l$([char]0x1EA1)i d$([char]0x1ECB)ch v$([char]0x1EE5) ph$([char]0x00ED)m n$([char]0x00F3)ng h$([char]0x00E3)ng & b$([char]0x1EAD)t l$([char]0x1EA1)i ch$([char]0x1EBF) $([char]0x0111)$([char]0x1ED9) Custom trong v$([char]0x00F2)ng l$([char]0x1EB7)p Fn+Q."
            }
        }
    } catch {}
}

function Restore-AllOptimizerGuardSnapshots {
    param([string[]]$FilterTweakIds = $null)
    if (-not ("DuckUtil.WindowsOptimizerEngine" -as [type])) { return $false }
    $isFullRestore = (-not $FilterTweakIds -or $FilterTweakIds.Count -eq 0)
    $dir = Get-OptimizerBackupDirectory
    if (-not [System.IO.Directory]::Exists($dir)) {
        if ($isFullRestore) { Repair-OemPowerAndLegionThermalMode -ResetPowerPlan }
        return $true
    }
    $files = @(Get-ChildItem -LiteralPath $dir -Filter "snapshot_*.json" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime)
    if ($files.Count -eq 0) {
        if ($isFullRestore) { Repair-OemPowerAndLegionThermalMode -ResetPowerPlan }
        return $true
    }

    $earliestReg = @{}
    $earliestSvc = @{}
    $allTasks = [System.Collections.Generic.List[string]]::new()
    $needsExplorer = $false

    foreach ($f in $files) {
        try {
            $raw = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8)
            $obj = ConvertFrom-Json $raw
            if (-not $obj) { continue }
            if ($FilterTweakIds -and $FilterTweakIds.Count -gt 0 -and $obj.TweakIds) {
                $hasMatch = $false
                foreach ($tid in @($obj.TweakIds)) {
                    if ($FilterTweakIds -contains [string]$tid) { $hasMatch = $true; break }
                }
                if (-not $hasMatch) { continue }
            }
            if ($obj.NeedsExplorerRestart) { $needsExplorer = $true }
            if ($obj.Tasks) {
                foreach ($tk in @($obj.Tasks)) {
                    if (-not [string]::IsNullOrWhiteSpace([string]$tk) -and -not $allTasks.Contains([string]$tk)) {
                        [void]$allTasks.Add([string]$tk)
                    }
                }
            }
            if ($obj.Registry) {
                foreach ($r in @($obj.Registry)) {
                    $dedup = "$($r.Hive)|$($r.Path)|$($r.Name)"
                    if (-not $earliestReg.ContainsKey($dedup)) {
                        $e = [DuckUtil.RegistrySnapshotEntry]::new()
                        $e.Hive = [string]$r.Hive
                        $e.Path = [string]$r.Path
                        $e.Name = [string]$r.Name
                        $e.Existed = [bool]$r.Existed
                        $e.KeyExisted = [bool]$r.KeyExisted
                        $e.Kind = [string]$r.Kind
                        $e.ValueData = [string]$r.ValueData
                        $earliestReg[$dedup] = $e
                    }
                }
            }
            if ($obj.Services) {
                foreach ($s in @($obj.Services)) {
                    $sn = [string]$s.Name
                    if (-not $earliestSvc.ContainsKey($sn)) {
                        $e = [DuckUtil.ServiceSnapshotEntry]::new()
                        $e.Name = $sn
                        $e.Existed = [bool]$s.Existed
                        $e.OriginalStart = [int]$s.OriginalStart
                        $earliestSvc[$sn] = $e
                    }
                }
            }
        } catch {}
    }

    $regArr = [System.Collections.Generic.List[DuckUtil.RegistrySnapshotEntry]]::new()
    foreach ($v in $earliestReg.Values) { [void]$regArr.Add($v) }
    $regRestored = if ($regArr.Count -gt 0) { [DuckUtil.WindowsOptimizerEngine]::RestoreRegistrySnapshots($regArr.ToArray()) } else { 0 }

    $svcArr = [System.Collections.Generic.List[DuckUtil.ServiceSnapshotEntry]]::new()
    foreach ($v in $earliestSvc.Values) { [void]$svcArr.Add($v) }
    $svcRestored = if ($svcArr.Count -gt 0) { [DuckUtil.WindowsOptimizerEngine]::RestoreServiceSnapshots($svcArr.ToArray()) } else { 0 }

    if ($allTasks.Count -gt 0 -and ("DuckUtil.WindowsOptimizerEngine" -as [type])) {
        $tkTaskAll = [DuckUtil.WindowsOptimizerEngine]::SetScheduledTasksEnabledAsync([string[]]$allTasks.ToArray(), $true)
        if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
            [void](Wait-TaskNonBlocking -Task $tkTaskAll -TimeoutSeconds 25 -CancelCheck { [bool]$script:cancelRequested })
        } else { [void]$tkTaskAll.Wait(25000) }
    }

    if ($isFullRestore) {
        Repair-OemPowerAndLegionThermalMode -ResetPowerPlan
    }

    if ("DuckUtil.WindowsOptimizerEngine" -as [type]) {
        $bTask = [DuckUtil.WindowsOptimizerEngine]::BroadcastSettingsChangeAsync()
        if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
            [void](Wait-TaskNonBlocking -Task $bTask -TimeoutSeconds 3)
        } else { [void]$bTask.Wait(3000) }
    }

    if ($needsExplorer) {
        Restart-ExplorerSoft
    }

    Log-Text "[OK] OptimizerGuard: $([char]0x0110)$([char]0x00E3) kh$([char]0x00F4)i ph$([char]0x1EE5)c ho$([char]0x00E0)n ch$([char]0x1EC9)nh tr$([char]0x1EA1)ng th$([char]0x00E1)i g$([char]0x1ED1)c ban $([char]0x0111)$([char]0x1EA7)u ($regRestored Registry, $svcRestored Service, $($allTasks.Count) Task) t$([char]0x1EEB) $($files.Count) b$([char]0x1EA3)n l$([char]0x01B0)u."
    return $true
}

function Restart-ExplorerSoft {
    try {
        Log-Text "[*] $([char]0x0110)ang kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i nhanh Windows Explorer $([char]0x0111)$([char]0x1EC3) $([char]0x00E1)p d$([char]0x1EE5)ng thay $([char]0x0111)$([char]0x1ED5)i giao di$([char]0x1EC7)n..."
        if ("DuckUtil.WindowsOptimizerEngine" -as [type]) {
            $tExp = [DuckUtil.WindowsOptimizerEngine]::RestartExplorerSoftAsync()
            if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
                [void](Wait-TaskNonBlocking -Task $tExp -TimeoutSeconds 5)
            } else {
                [void]$tExp.Wait(5000)
            }
            return
        }
        Stop-Process -Name "explorer" -Force -ErrorAction SilentlyContinue
        Start-Sleep -Milliseconds 600
        if (-not (Get-Process -Name "explorer" -ErrorAction SilentlyContinue)) {
            Start-Process "explorer.exe"
        }
    } catch {}
}

function Invoke-OptimizerSpecialAction {
    param(
        [Parameter(Mandatory = $true)][string]$Action,
        [ValidateSet("Apply", "Undo")][string]$Mode = "Apply",
        [string]$ComboValue = ""
    )
    $isUndo = ($Mode -eq "Undo")
    switch ($Action) {
        "RestorePoint" {
            if ($isUndo) { return $true }
            return (New-OptimizerRestorePoint)
        }
        "DeleteTempFiles" {
            if ($isUndo) { return $true }
            $removed = 0
            foreach ($dir in @($env:TEMP, (Join-Path $env:SystemRoot "Temp"))) {
                if ([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir)) { continue }
                Get-ChildItem -LiteralPath $dir -Force -ErrorAction SilentlyContinue | ForEach-Object {
                    if (($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { return }
                    try {
                        Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction Stop
                        $removed++
                    } catch {}
                }
            }
            Log-Text "[OK] $([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n $removed m$([char]0x1EE5)c t$([char]0x1EC7)p r$([char]0x00E1)c t$([char]0x1EA1)m."
            return $true
        }
        "DiskCleanup" {
            if ($isUndo) { return $true }
            try {
                Start-Process "cleanmgr.exe" -ArgumentList "/d $($env:SystemDrive) /VERYLOWDISK" -WindowStyle Hidden -ErrorAction Stop
                Log-Text "[OK] $([char]0x0110)$([char]0x00E3) kh$([char]0x1EDF)i ch$([char]0x1EA1)y Disk Cleanup d$([char]0x1ECD)n $([char]0x1ED5) $($env:SystemDrive)."
                return $true
            } catch {
                Log-Text "[WARN] Kh$([char]0x00F4)ng th$([char]0x1EC3) ch$([char]0x1EA1)y cleanmgr.exe: $($_.Exception.Message)"
                return $false
            }
        }
        "Hibernation" {
            $arg = if ($isUndo) { "/hibernate on" } else { "/hibernate off" }
            $code = Run-CliStream "powercfg.exe" $arg -IsolateStdin -AllowCancel -CaptureOutput -TimeoutSeconds 30 -IdleTimeoutSeconds 20
            return ($code -eq 0)
        }
        "SafeDisableBgApps" {
            return (Invoke-SafeBackgroundAppsTweak -Mode $Mode)
        }
        "UltimatePerf" {
            if ($isUndo) {
                $balGuid = "381b4222-f694-41f0-9685-ff5bb260df2e"
                $cUndo = Run-CliStream "powercfg.exe" "/setactive $balGuid" -IsolateStdin -AllowCancel -CaptureOutput -TimeoutSeconds 15 -IdleTimeoutSeconds 10
                return ($cUndo -eq 0)
            }
            $listRun = Run-CliStream "powercfg.exe" "/list" -IsolateStdin -AllowCancel -CaptureOutput -ReturnResult -TimeoutSeconds 15 -IdleTimeoutSeconds 10
            $listOut = if ($listRun) { [string]$listRun.StdOut } else { "" }
            $ultGuid = ""
            if ($listOut -match "([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s*\([^)]*(?:Ultimate Performance|Hi$([char]0x1EC7)u su$([char]0x1EA5)t t$([char]0x1ED1)i $([char]0x0111)a|Hi$([char]0x1EC7)u n$([char]0x0103)ng t$([char]0x1ED1)i $([char]0x0111)a)[^)]*\)") {
                $ultGuid = $Matches[1]
            } else {
                $dupRun = Run-CliStream "powercfg.exe" "-duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61" -IsolateStdin -AllowCancel -CaptureOutput -ReturnResult -TimeoutSeconds 15 -IdleTimeoutSeconds 10
                $dupOut = if ($dupRun) { [string]$dupRun.StdOut } else { "" }
                if ($dupOut -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') {
                    $ultGuid = $Matches[1]
                }
            }
            if ([string]::IsNullOrWhiteSpace($ultGuid)) {
                Log-Text "[WARN] Kh$([char]0x00F4)ng t$([char]0x00EC)m th$([char]0x1EA5)y ho$([char]0x1EB7)c kh$([char]0x00F4)ng h$([char]0x1ED7) tr$([char]0x1EE3) g$([char]0x00F3)i ngu$([char]0x1ED3)n Ultimate Performance tr$([char]0x00EA)n thi$([char]0x1EBF)t b$([char]0x1ECB) n$([char]0x00E0)y."
                return $false
            }
            $c = Run-CliStream "powercfg.exe" "/setactive $ultGuid" -IsolateStdin -AllowCancel -CaptureOutput -TimeoutSeconds 15 -IdleTimeoutSeconds 10
            return ($c -eq 0)
        }
        "ReservedStorage" {
            $stateArg = if ($isUndo) { "Enabled" } else { "Disabled" }
            $code = Run-CliStream "dism.exe" "/Online /Set-ReservedStorageState /State:$stateArg" -IsolateStdin -AllowCancel -CaptureOutput -TimeoutSeconds 120 -IdleTimeoutSeconds 60
            return ($code -eq 0)
        }
        "DnsApply" {
            $dnsChoice = if ($isUndo) { "M$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh (DHCP)" } else { $ComboValue }
            $primaryDns = ""
            $secondaryDns = ""
            $resetDhcp = $true
            switch -Regex ($dnsChoice) {
                'Cloudflare|1\.1\.1\.1' { $primaryDns = "1.1.1.1"; $secondaryDns = "1.0.0.1"; $resetDhcp = $false }
                'AdGuard|94\.140'       { $primaryDns = "94.140.14.14"; $secondaryDns = "94.140.15.15"; $resetDhcp = $false }
                'Google|8\.8\.8\.8'     { $primaryDns = "8.8.8.8"; $secondaryDns = "8.8.4.4"; $resetDhcp = $false }
                'Quad9|9\.9\.9\.9'      { $primaryDns = "9.9.9.9"; $secondaryDns = "149.112.112.112"; $resetDhcp = $false }
                default                 { $primaryDns = ""; $secondaryDns = ""; $resetDhcp = $true }
            }
            try {
                if ("DuckUtil.WindowsOptimizerEngine" -as [type]) {
                    $dnsTask = [DuckUtil.WindowsOptimizerEngine]::ApplyDnsAsync($primaryDns, $secondaryDns, $resetDhcp)
                    if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
                        [void](Wait-TaskNonBlocking -Task $dnsTask -TimeoutSeconds 25 -CancelCheck { [bool]$script:cancelRequested })
                    } else {
                        [void]$dnsTask.Wait(25000)
                    }
                    $okDns = ($dnsTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) -and [bool]$dnsTask.Result
                    if ($okDns) {
                        Log-Text "[OK] $([char]0x0110)$([char]0x00E3) c$([char]0x1EAD)p nh$([char]0x1EAD)t DNS ($dnsChoice) v$([char]0x00E0) l$([char]0x00E0)m m$([char]0x1EDB)i DNS cache."
                        return $true
                    }
                    Log-Text "[ERR] Kh$([char]0x00F4)ng th$([char]0x1EC3) $([char]0x00E1)p d$([char]0x1EE5)ng DNS ($dnsChoice) $([char]0x2014) ki$([char]0x1EC3)m tra quy$([char]0x1EC1)n Administrator v$([char]0x00E0) k$([char]0x1EBF)t n$([char]0x1ED1)i m$([char]0x1EA1)ng."
                    return $false
                }
                return $false
            } catch {
                Log-Text "[ERR] L$([char]0x1ED7)i $([char]0x0111)$([char]0x1ED5)i DNS: $($_.Exception.Message)"
                return $false
            }
        }
        "NagleDisable" {
            try {
                $ifRoot = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"
                if (Test-Path -LiteralPath $ifRoot) {
                    foreach ($sub in Get-ChildItem -LiteralPath $ifRoot -ErrorAction SilentlyContinue) {
                        $props = Get-ItemProperty -LiteralPath $sub.PSPath -ErrorAction SilentlyContinue
                        if (-not $props) { continue }
                        $dhIp = [string]$props.DhcpIPAddress
                        $stIp = if ($props.IPAddress -is [array] -and $props.IPAddress.Count -gt 0) { [string]$props.IPAddress[0] } else { [string]$props.IPAddress }
                        $hasIp = (-not [string]::IsNullOrWhiteSpace($dhIp) -and $dhIp -ne "0.0.0.0") -or (-not [string]::IsNullOrWhiteSpace($stIp) -and $stIp -ne "0.0.0.0")
                        if (-not $hasIp) { continue }
                        if ($isUndo) {
                            Remove-ItemProperty -LiteralPath $sub.PSPath -Name "TcpAckFrequency" -ErrorAction SilentlyContinue
                            Remove-ItemProperty -LiteralPath $sub.PSPath -Name "TCPNoDelay" -ErrorAction SilentlyContinue
                        } else {
                            Set-ItemProperty -LiteralPath $sub.PSPath -Name "TcpAckFrequency" -Value 1 -Type DWord -ErrorAction SilentlyContinue
                            Set-ItemProperty -LiteralPath $sub.PSPath -Name "TCPNoDelay" -Value 1 -Type DWord -ErrorAction SilentlyContinue
                        }
                    }
                }
                return $true
            } catch {
                return $false
            }
        }
        "RemoveWidgets" {
            return $true
        }
        "RemoveOneDrive" {
            if ($isUndo) {
                Log-Text "[INFO] $([char]0x0110)$([char]0x00E3) b$([char]0x1ECF) ch$([char]0x00ED)nh s$([char]0x00E1)ch kh$([char]0x00F3)a OneDrive (c$([char]0x00F3) th$([char]0x1EC3) c$([char]0x00E0)i l$([char]0x1EA1)i OneDrive t$([char]0x1EEB) tab $([char]0x1EE8)ng d$([char]0x1EE5)ng n$([char]0x1EBF)u c$([char]0x1EA7)n)."
                return $true
            }
            try {
                Stop-Process -Name "OneDrive" -Force -ErrorAction SilentlyContinue
                foreach ($odSetup in @(
                    (Join-Path $env:SystemRoot "System32\OneDriveSetup.exe"),
                    (Join-Path $env:SystemRoot "SysWOW64\OneDriveSetup.exe")
                )) {
                    if (Test-Path -LiteralPath $odSetup) {
                        [void](Run-CliStream $odSetup "/uninstall" -IsolateStdin -AllowCancel -TimeoutSeconds 120 -IdleTimeoutSeconds 60)
                        break
                    }
                }
                return $true
            } catch {
                return $false
            }
        }
        "RemoveEdge" {
            if ($isUndo) {
                Log-Text "[INFO] N$([char]0x1EBF)u c$([char]0x1EA7)n c$([char]0x00E0)i l$([char]0x1EA1)i Edge, b$([char]0x1EA1)n c$([char]0x00F3) th$([char]0x1EC3) c$([char]0x00E0)i tr$([char]0x1EF1)c ti$([char]0x1EBF)p $([char]0x1EDF) tab $([char]0x1EE8)ng d$([char]0x1EE5)ng."
                return $true
            }
            try {
                Stop-Process -Name "msedge" -Force -ErrorAction SilentlyContinue
                foreach ($base in @(${env:ProgramFiles(x86)}, $env:ProgramFiles)) {
                    if ([string]::IsNullOrWhiteSpace($base)) { continue }
                    $instRoot = Join-Path $base "Microsoft\Edge\Application"
                    if (-not (Test-Path -LiteralPath $instRoot)) { continue }
                    $setupExe = Get-ChildItem -LiteralPath $instRoot -Filter "setup.exe" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
                    if ($setupExe) {
                        [void](Run-CliStream $setupExe.FullName "--uninstall --system-level --verbose-logging --force-uninstall" -IsolateStdin -AllowCancel -TimeoutSeconds 120 -IdleTimeoutSeconds 60)
                        return $true
                    }
                }
                Log-Text "[WARN] Kh$([char]0x00F4)ng t$([char]0x00EC)m th$([char]0x1EA5)y tr$([char]0x00EC)nh g$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t Microsoft Edge tr$([char]0x00EA)n m$([char]0x00E1)y."
                return $false
            } catch {
                return $false
            }
        }
        "AdobeBlock" {
            $hostsPath = Join-Path $env:SystemRoot "System32\drivers\etc\hosts"
            $markerStart = "# AppDriver-AdobeBlock-Start"
            $markerEnd = "# AppDriver-AdobeBlock-End"
            try {
                $existing = if (Test-Path -LiteralPath $hostsPath) { [System.IO.File]::ReadAllText($hostsPath, [System.Text.Encoding]::UTF8) } else { "" }
                $cleaned = [regex]::Replace($existing, "(?s)\r?\n?$([regex]::Escape($markerStart)).*?$([regex]::Escape($markerEnd))\r?\n?", "")
                if ($isUndo) {
                    [System.IO.File]::WriteAllText($hostsPath, $cleaned.TrimEnd() + "`r`n", [System.Text.Encoding]::UTF8)
                    return $true
                }
                $domains = @(
                    "0.0.0.0 ic.adobe.io",
                    "0.0.0.0 cc-api-data.adobe.io",
                    "0.0.0.0 p13n.adobe.io",
                    "0.0.0.0 genuine.adobe.com",
                    "0.0.0.0 prod.adobegenuine.com",
                    "0.0.0.0 lmlicenses.wip4.adobe.com",
                    "0.0.0.0 lm.licenses.adobe.com",
                    "0.0.0.0 na1r.services.adobe.com",
                    "0.0.0.0 hlrcv.stage.adobe.com",
                    "0.0.0.0 practivate.adobe.com"
                )
                $block = "`r`n$markerStart`r`n" + ($domains -join "`r`n") + "`r`n$markerEnd`r`n"
                [System.IO.File]::WriteAllText($hostsPath, $cleaned.TrimEnd() + $block, [System.Text.Encoding]::UTF8)
                return $true
            } catch {
                Log-Text "[ERR] Kh$([char]0x00F4)ng th$([char]0x1EC3) ghi file hosts: $($_.Exception.Message)"
                return $false
            }
        }
        "DisableBitLocker" {
            if ($isUndo) { return $true }
            try {
                $code = Run-CliStream "manage-bde.exe" "-off $($env:SystemDrive)" -IsolateStdin -AllowCancel -CaptureOutput -TimeoutSeconds 60 -IdleTimeoutSeconds 30
                return ($code -eq 0 -or $code -eq -2147024891)
            } catch {
                return $false
            }
        }
        "PauseWindowsUpdate35d" {
            $uxPath = "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings"
            try {
                if (-not (Test-Path -LiteralPath $uxPath)) { New-Item -Path $uxPath -Force | Out-Null }
                if ($isUndo) {
                    foreach ($vn in @("PauseFeatureUpdatesStartTime","PauseFeatureUpdatesEndTime","PauseQualityUpdatesStartTime","PauseQualityUpdatesEndTime","PauseUpdatesExpiryTime")) {
                        Remove-ItemProperty -LiteralPath $uxPath -Name $vn -ErrorAction SilentlyContinue
                    }
                    return $true
                }
                $nowIso = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
                $endIso = (Get-Date).AddDays(35).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseFeatureUpdatesStartTime" -Value $nowIso -Type String
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseFeatureUpdatesEndTime" -Value $endIso -Type String
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseQualityUpdatesStartTime" -Value $nowIso -Type String
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseQualityUpdatesEndTime" -Value $endIso -Type String
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseUpdatesExpiryTime" -Value $endIso -Type String
                return $true
            } catch {
                return $false
            }
        }
        "DisableWindowsUpdateAll" {
            $uxPath = "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings"
            try {
                if (-not (Test-Path -LiteralPath $uxPath)) { New-Item -Path $uxPath -Force | Out-Null }
                if ($isUndo) {
                    foreach ($vn in @("FlightSettingsMaxPauseDays","PauseFeatureUpdatesStartTime","PauseFeatureUpdatesEndTime","PauseQualityUpdatesStartTime","PauseQualityUpdatesEndTime","PauseUpdatesExpiryTime")) {
                        Remove-ItemProperty -LiteralPath $uxPath -Name $vn -ErrorAction SilentlyContinue
                    }
                    return $true
                }
                $nowIso = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
                $endIso = "2099-12-31T23:59:59Z"
                Set-ItemProperty -LiteralPath $uxPath -Name "FlightSettingsMaxPauseDays" -Value 36500 -Type DWord -ErrorAction SilentlyContinue
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseFeatureUpdatesStartTime" -Value $nowIso -Type String
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseFeatureUpdatesEndTime" -Value $endIso -Type String
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseQualityUpdatesStartTime" -Value $nowIso -Type String
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseQualityUpdatesEndTime" -Value $endIso -Type String
                Set-ItemProperty -LiteralPath $uxPath -Name "PauseUpdatesExpiryTime" -Value $endIso -Type String
                return $true
            } catch {
                return $false
            }
        }
        "ResetWindowsUpdateDefault" {
            try {
                $wuPol = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
                if (Test-Path -LiteralPath $wuPol) {
                    Remove-Item -LiteralPath $wuPol -Recurse -Force -ErrorAction SilentlyContinue
                }
                $uxPath = "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings"
                if (Test-Path -LiteralPath $uxPath) {
                    foreach ($vn in @("FlightSettingsMaxPauseDays","PauseFeatureUpdatesStartTime","PauseFeatureUpdatesEndTime","PauseQualityUpdatesStartTime","PauseQualityUpdatesEndTime","PauseUpdatesExpiryTime")) {
                        Remove-ItemProperty -LiteralPath $uxPath -Name $vn -ErrorAction SilentlyContinue
                    }
                }
                return $true
            } catch {
                return $false
            }
        }
    }
    return $true
}

function Test-OptimizerTweakRequiresAdmin {
    param($Tweak)
    if (-not $Tweak) { return $false }
    if ($Tweak.Services -and @($Tweak.Services).Count -gt 0) { return $true }
    if ($Tweak.Tasks -and @($Tweak.Tasks).Count -gt 0) { return $true }
    if ($Tweak.Registry) {
        foreach ($r in @($Tweak.Registry)) {
            $hv = if ([string]::IsNullOrWhiteSpace([string]$r.Hive)) { "HKLM" } else { [string]$r.Hive }
            if ($hv -ieq "HKLM" -or $hv -ieq "HKCR") { return $true }
            if ([string]$r.Path -match '(?i)^Software\\Policies\\') { return $true }
        }
    }
    $act = [string]$Tweak.Action
    if ($act -in @("RestorePoint","Hibernation","UltimatePerf","ReservedStorage","DnsApply","NagleDisable","RemoveEdge","AdobeBlock","DisableBitLocker","PauseWindowsUpdate35d","DisableWindowsUpdateAll","ResetWindowsUpdateDefault")) {
        return $true
    }
    return $false
}

function Invoke-SingleOptimizerTweak {
    param(
        [Parameter(Mandatory = $true)]$Tweak,
        [ValidateSet("Apply", "Undo")][string]$Mode = "Apply",
        [string]$ComboValue = ""
    )
    $ok = $true
    $isUndo = ($Mode -eq "Undo")
    $errList = [System.Collections.Generic.List[string]]::new()

    $regSpecs = ConvertTo-RegTweakSpecs @($Tweak)
    if ($regSpecs.Length -gt 0 -and ("DuckUtil.WindowsOptimizerEngine" -as [type])) {
        $regTask = [DuckUtil.WindowsOptimizerEngine]::ApplyRegistrySpecsDetailedAsync($regSpecs, $isUndo)
        if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
            [void](Wait-TaskNonBlocking -Task $regTask -TimeoutSeconds 15 -CancelCheck { [bool]$script:cancelRequested })
        } else { [void]$regTask.Wait(15000) }
        if ($regTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion -and $regTask.Result) {
            $rr = $regTask.Result
            if ($rr.OkCount -lt $rr.TotalCount) {
                $ok = $false
                foreach ($er in @($rr.Errors)) {
                    if (-not [string]::IsNullOrWhiteSpace($er)) { [void]$errList.Add($er) }
                }
            }
        } else {
            $ok = $false
            [void]$errList.Add("Ghi Registry h$([char]0x1EBF)t th$([char]0x1EDD)i gian ch$([char]0x1EDD) ho$([char]0x1EB7)c b$([char]0x1ECB) gi$([char]0x00E1)n $([char]0x0111)o$([char]0x1EA1)n")
        }
    }

    $svcSpecs = ConvertTo-ServiceTweakSpecs @($Tweak)
    if ($svcSpecs.Length -gt 0 -and ("DuckUtil.WindowsOptimizerEngine" -as [type])) {
        $svcTask = [DuckUtil.WindowsOptimizerEngine]::ApplyServiceSpecsAsync($svcSpecs, $isUndo)
        if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
            [void](Wait-TaskNonBlocking -Task $svcTask -TimeoutSeconds 15 -CancelCheck { [bool]$script:cancelRequested })
        } else { [void]$svcTask.Wait(15000) }
    }

    if ($Tweak.Tasks) {
        $tkArr = @($Tweak.Tasks | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
        if ($tkArr.Count -gt 0 -and ("DuckUtil.WindowsOptimizerEngine" -as [type])) {
            $tkTask = [DuckUtil.WindowsOptimizerEngine]::SetScheduledTasksEnabledAsync([string[]]$tkArr, $isUndo)
            if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
                [void](Wait-TaskNonBlocking -Task $tkTask -TimeoutSeconds 20 -CancelCheck { [bool]$script:cancelRequested })
            } else { [void]$tkTask.Wait(20000) }
        }
    }

    if (-not [string]::IsNullOrWhiteSpace([string]$Tweak.Action)) {
        $actOk = Invoke-OptimizerSpecialAction -Action ([string]$Tweak.Action) -Mode $Mode -ComboValue $ComboValue
        if (-not $actOk) {
            $ok = $false
            [void]$errList.Add("T$([char]0x00E1)c v$([char]0x1EE5) '$($Tweak.Action)' tr$([char]0x1EA3) v$([char]0x1EC1) th$([char]0x1EA5)t b$([char]0x1EA1)i")
        }
    }

    return [PSCustomObject]@{
        Success = $ok
        Errors  = @($errList)
    }
}

function Invoke-SingleOptimizerToggle {
    param(
        [Parameter(Mandatory = $true)]$Tweak,
        [Parameter(Mandatory = $true)][bool]$TargetEnabled,
        [string]$ComboValue = "",
        $HardwareProfile = $null
    )
    $isAdmin = if ("DuckUtil.WindowsOptimizerEngine" -as [type]) { [DuckUtil.WindowsOptimizerEngine]::IsCurrentProcessAdmin() } else { $true }
    if ((Test-OptimizerTweakRequiresAdmin -Tweak $Tweak) -and -not $isAdmin) {
        return [PSCustomObject]@{
            Success        = $false
            NeedsAdmin     = $true
            VerifiedState  = if ($TargetEnabled) { "Default" } else { "Applied" }
            VerifiedDetail = ""
            Errors         = @("Y$([char]0x00EA)u c$([char]0x1EA7)u quy$([char]0x1EC1)n Administrator")
        }
    }

    $mode = if ($TargetEnabled) { "Apply" } else { "Undo" }
    if ($TargetEnabled) {
        [void](Save-OptimizerGuardSnapshot -Tweaks @($Tweak) -HardwareProfile $HardwareProfile)
    }

    $execRes = Invoke-SingleOptimizerTweak -Tweak $Tweak -Mode $mode -ComboValue $ComboValue

    if ($execRes.Success -and ("DuckUtil.WindowsOptimizerEngine" -as [type])) {
        $bTask = [DuckUtil.WindowsOptimizerEngine]::BroadcastSettingsChangeAsync()
        if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
            [void](Wait-TaskNonBlocking -Task $bTask -TimeoutSeconds 3)
        } else { [void]$bTask.Wait(3000) }

        if ($Tweak.NeedsExplorerRestart -and ([string]$Tweak.Id -in @("opt_classic_context_menu","opt_dark_mode","opt_disable_bing_search","opt_start_recommendations","opt_explorer_this_pc"))) {
            Restart-ExplorerSoft
        }
    }

    $vState = if ($execRes.Success) { if ($TargetEnabled) { "Applied" } else { "Default" } } else { if ($TargetEnabled) { "Default" } else { "Applied" } }
    $vDetail = ""
    if ("DuckUtil.WindowsOptimizerEngine" -as [type]) {
        try {
            $reqArr = Build-TweakProbeRequests @($Tweak)
            $pTask = [DuckUtil.WindowsOptimizerEngine]::ProbeTweaksStateAsync($reqArr)
            if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
                [void](Wait-TaskNonBlocking -Task $pTask -TimeoutSeconds 5)
            } else { [void]$pTask.Wait(5000) }
            if ($pTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion -and $pTask.Result -and $pTask.Result.Length -gt 0) {
                $vState = [string]$pTask.Result[0].State
                $vDetail = [string]$pTask.Result[0].Detail
            }
        } catch {}
    }

    $verifiedMatch = if ($TargetEnabled) { ($vState -eq "Applied") } else { ($vState -ne "Applied") }
    $finalOk = $execRes.Success -and $verifiedMatch
    $errs = [System.Collections.Generic.List[string]]::new()
    foreach ($er in @($execRes.Errors)) { [void]$errs.Add($er) }
    if ($execRes.Success -and -not $verifiedMatch) {
        [void]$errs.Add("Windows kh$([char]0x00F4)ng gi$([char]0x1EEF) l$([char]0x1EA1)i thay $([char]0x0111)$([char]0x1ED5)i sau khi ghi (tr$([char]0x1EA1)ng th$([char]0x00E1)i th$([char]0x1EF1)c t$([char]0x1EBF): $vState)")
    }

    return [PSCustomObject]@{
        Success        = $finalOk
        NeedsAdmin     = $false
        VerifiedState  = $vState
        VerifiedDetail = $vDetail
        Errors         = @($errs)
    }
}

function Invoke-OptimizerBatch {
    param(
        [Parameter(Mandatory = $true)]$Tweaks,
        [ValidateSet("Apply", "Undo")][string]$Mode = "Apply",
        [hashtable]$ComboSelections = @{},
        $HardwareProfile = $null,
        [scriptblock]$ProgressCallback = $null
    )
    $tweakList = @($Tweaks)
    if ($tweakList.Count -eq 0) {
        return [PSCustomObject]@{ Applied = 0; Failed = 0; NeedsExplorerRestart = $false; NeedsReboot = $false; SnapshotPath = "" }
    }

    $snapPath = Save-OptimizerGuardSnapshot -Tweaks $tweakList -HardwareProfile $HardwareProfile

    $applied = 0
    $failed = 0
    $needsExplorer = $false
    $needsReboot = $false
    $total = $tweakList.Count
    $idx = 0
    $isUndo = ($Mode -eq "Undo")

    foreach ($tw in $tweakList) {
        if ($script:cancelRequested -or $script:isWindowClosing) { break }
        $idx++
        if ($ProgressCallback) {
            try { & $ProgressCallback $idx $total ([string]$tw.Name) } catch {}
        }
        if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
            [void](Wait-TaskNonBlocking -Task ([System.Threading.Tasks.Task]::Delay(10)) -TimeoutSeconds 1 -CancelCheck { [bool]$script:cancelRequested })
        }

        $comboVal = if ($ComboSelections -and $ComboSelections.ContainsKey([string]$tw.Id)) { [string]$ComboSelections[[string]$tw.Id] } else { "" }
        $resOne = Invoke-SingleOptimizerTweak -Tweak $tw -Mode $Mode -ComboValue $comboVal

        if ($resOne.Success) {
            $applied++
            if ($tw.NeedsExplorerRestart) { $needsExplorer = $true }
            if ($tw.NeedsReboot) { $needsReboot = $true }
            $actLabel = if ($isUndo) { "$([char]0x0110)$([char]0x00E3) ho$([char]0x00E0)n t$([char]0x00E1)c" } else { "$([char]0x0110)$([char]0x00E3) $([char]0x00E1)p d$([char]0x1EE5)ng" }
            Log-Text "   [OK] ${actLabel}: $($tw.Name)"
        } else {
            $failed++
            $errDetail = if ($resOne.Errors -and $resOne.Errors.Count -gt 0) { " ($($resOne.Errors[0]))" } else { "" }
            Log-Text "   [ERR] Kh$([char]0x00F4)ng th$([char]0x1EC3) x$([char]0x1EED) l$([char]0x00FD): $($tw.Name)$errDetail"
        }
    }

    if ($applied -gt 0 -and ("DuckUtil.WindowsOptimizerEngine" -as [type]) -and -not $script:isWindowClosing) {
        $bTask = [DuckUtil.WindowsOptimizerEngine]::BroadcastSettingsChangeAsync()
        if (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue) {
            [void](Wait-TaskNonBlocking -Task $bTask -TimeoutSeconds 3)
        } else { [void]$bTask.Wait(3000) }
    }

    if ($needsExplorer -and -not $script:cancelRequested -and -not $script:isWindowClosing) {
        Restart-ExplorerSoft
    }

    if ($needsReboot) {
        Log-Text "[WARN] M$([char]0x1ED9)t s$([char]0x1ED1) t$([char]0x00F9)y ch$([char]0x1EC9)nh y$([char]0x00EA)u c$([char]0x1EA7)u kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i Windows $([char]0x0111)$([char]0x1EC3) c$([char]0x00F3) hi$([char]0x1EC7)u l$([char]0x1EF1)c ho$([char]0x00E0)n to$([char]0x00E0)n."
    }

    return [PSCustomObject]@{
        Applied              = $applied
        Failed               = $failed
        NeedsExplorerRestart = $needsExplorer
        NeedsReboot          = $needsReboot
        SnapshotPath         = $snapPath
    }
}

