function Get-UninstallerAppQueueKey {
    param($App)
    if (-not $App) { return "" }
    if ($App.PSObject.Properties["RawRegPath"] -and -not [string]::IsNullOrWhiteSpace($App.RawRegPath)) {
        return "REG:" + [string]$App.RawRegPath
    }
    if ($App.PSObject.Properties["Id"] -and -not [string]::IsNullOrWhiteSpace($App.Id)) {
        return "ID:" + [string]$App.Id + "|" + [string]$App.DisplayName
    }
    return "NAME:" + [string]$App.DisplayName + "|" + [string]$App.InstallLocation
}

function Update-UninstallQueueUiState {
    if ($script:isWindowClosing) { return }
    if ($borderQueueBadge -and $txtQueueBadge) {
        if ($script:isUninstallingQueue) {
            $borderQueueBadge.Visibility = [System.Windows.Visibility]::Visible
            if ($script:uninstallQueue.Count -gt 0) {
                $txtQueueBadge.Text = "H$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i: +$($script:uninstallQueue.Count)"
            } else {
                $txtQueueBadge.Text = "$([char]0x0110)ang g$([char]0x1EE1)..."
            }
        } else {
            $borderQueueBadge.Visibility = [System.Windows.Visibility]::Collapsed
            $txtQueueBadge.Text = ""
        }
    }
    if ($btnCancelAction) {
        if ($script:isUninstallingQueue -or $script:isActionRunning) {
            $btnCancelAction.Visibility = [System.Windows.Visibility]::Visible
        } else {
            $btnCancelAction.Visibility = [System.Windows.Visibility]::Collapsed
            $btnCancelAction.IsEnabled = $true
            $btnCancelAction.Content = "D$([char]0x1EEB)ng t$([char]0x00E1)c v$([char]0x1EE5)"
        }
    }
}

if ($btnCancelAction) {
    $btnCancelAction.Add_Click({
        $script:cancelRequested = $true
        $btnCancelAction.IsEnabled = $false
        $btnCancelAction.Content = "$([char]0x0110)ang d$([char]0x1EEB)ng..."
        if ($script:uninstallQueue) { $script:uninstallQueue.Clear() }
        if ($script:uninstallQueuedKeys) { $script:uninstallQueuedKeys.Clear() }
        if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)ang d$([char]0x1EEB)ng t$([char]0x00E1)c v$([char]0x1EE5) theo y$([char]0x00EA)u c$([char]0x1EA7)u..." }
        Log-Text "[STOP] $([char]0x0110)$([char]0x00E3) nh$([char]0x1EAD)n y$([char]0x00EA)u c$([char]0x1EA7)u d$([char]0x1EEB)ng t$([char]0x00E1)c v$([char]0x1EE5) & x$([char]0x00F3)a h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i!"
        try { if ($script:activePrefetchCts) { $script:activePrefetchCts.Cancel() } } catch {}
        try { if ($script:activeDirectDlCts) { $script:activeDirectDlCts.Cancel() } } catch {}
        try { Stop-ActiveChildProcess } catch {}
        try { Stop-ActiveWaitFrames } catch {}
    })
}

function Add-ItemsToUninstallQueue {
    param(
        [object[]]$Items,
        [bool]$SkipVendor = $false,
        [bool]$ForceStop = $false,
        [bool]$AutoSilent = $true
    )
    $added = 0
    $addedKeys = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($it in $Items) {
        if (-not $it) { continue }
        $k = Get-UninstallerAppQueueKey $it
        if ([string]::IsNullOrWhiteSpace($k) -or $script:uninstallQueuedKeys.Contains($k)) { continue }
        [void]$script:uninstallQueuedKeys.Add($k)
        [void]$addedKeys.Add($k)
        $script:uninstallQueue.Add([PSCustomObject]@{
            App        = $it
            SkipVendor = $SkipVendor
            ForceStop  = $ForceStop
            AutoSilent = $AutoSilent
            Key        = $k
        })
        $added++
    }
    if ($added -gt 0) {
        if ($script:uninstallerVirtualView) {
            $script:uninstallerVirtualView.MarkQueuedByKeys($addedKeys)
        } else {
            $script:suppressUninstallerSelectionCount = $true
            try {
                foreach ($entry in $script:uninstallerRowEntries) {
                    $rk = Get-UninstallerAppQueueKey $entry.App
                    if ($addedKeys.Contains($rk)) {
                        $entry.IsSelected = $false
                        $entry.IsQueued = $true
                        if ($entry.CheckBox) { $entry.CheckBox.IsChecked = $false }
                        if ($entry.Row) { $entry.Row.Opacity = 0.52 }
                    }
                }
            } finally {
                $script:suppressUninstallerSelectionCount = $false
            }
            Update-UninstallerSelectionCount
        }
    }
    Update-UninstallQueueUiState
    return $added
}

function Start-UninstallQueueExecution {
    $script:isUninstallingQueue = $true
    $script:cancelRequested = $false
    if ($btnCancelAction) {
        $btnCancelAction.Content = "D$([char]0x1EEB)ng t$([char]0x00E1)c v$([char]0x1EE5)"
        $btnCancelAction.IsEnabled = $true
        $btnCancelAction.Visibility = [System.Windows.Visibility]::Visible
    }
    if ($progressBar) { $progressBar.IsIndeterminate = $true }
    Update-UninstallQueueUiState

    $collectedLeftovers = [System.Collections.Generic.List[object]]::new()
    $completedApps = 0
    try {
        while ($script:uninstallQueue.Count -gt 0 -and -not $script:isWindowClosing -and -not $script:cancelRequested) {
            $qItem = $script:uninstallQueue[0]
            $script:uninstallQueue.RemoveAt(0)
            $totalCurrent = $completedApps + 1 + $script:uninstallQueue.Count
            if ($txtStatus) {
                $txtStatus.Text = "[$($completedApps + 1)/$totalCurrent] $([char]0x0110)ang g$([char]0x1EE1): $($qItem.App.DisplayName)..."
            }
            Update-UninstallQueueUiState

            if (Get-Command "Invoke-DeepAppUninstall" -ErrorAction SilentlyContinue) {
                Invoke-DeepAppUninstall `
                    -AppEntry $qItem.App `
                    -OwnerWindow $window `
                    -SkipVendorUninstaller:$qItem.SkipVendor `
                    -ForceStopAndDelete:$qItem.ForceStop `
                    -AutoSilent:$qItem.AutoSilent `
                    -AllInstalledApps $script:cachedUninstallerApps `
                    -DeferLeftoverDialog `
                    -CollectedLeftoversOut $collectedLeftovers `
                    -AllowCancel
            }

            if ($script:isWindowClosing -or $script:cancelRequested) { break }
            $completedApps++
            $removedAnyRow = $false
            if ($script:uninstallerVirtualView) {
                $removedAnyRow = [bool]$script:uninstallerVirtualView.MarkRemovedByKey($qItem.Key)
            } else {
                foreach ($entry in $script:uninstallerRowEntries) {
                    if ((Get-UninstallerAppQueueKey $entry.App) -eq $qItem.Key) {
                        $entry.IsRemoved = $true
                        $entry.IsSelected = $false
                        $entry.IsQueued = $false
                        if ($entry.CheckBox) { $entry.CheckBox.IsChecked = $false }
                        if ($entry.Row) { $entry.Row.Visibility = [System.Windows.Visibility]::Collapsed }
                        $removedAnyRow = $true
                    }
                }
            }
            if ($removedAnyRow) { Apply-UninstallerFilter } else { Update-UninstallerSelectionCount }
        }

        if (-not $script:isWindowClosing -and -not $script:cancelRequested -and $collectedLeftovers.Count -gt 0) {
            $dedupLeftovers = [System.Collections.Generic.List[object]]::new()
            $seenLo = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
            foreach ($lo in $collectedLeftovers) {
                if (-not $lo) { continue }
                $dKey = if ($lo.RegistryValueName) { "$($lo.Path)->$($lo.RegistryValueName)" } else { [string]$lo.Path }
                if ($seenLo.Add($dKey)) { $dedupLeftovers.Add($lo) }
            }
            if ($dedupLeftovers.Count -gt 0 -and (Get-Command "Show-LeftoverReviewDialog" -ErrorAction SilentlyContinue)) {
                Log-Text "[*] T$([char]0x1ED5)ng h$([char]0x1EE3)p $($dedupLeftovers.Count) m$([char]0x1EE5)c r$([char]0x00E1)c / Registry c$([char]0x00F2)n s$([char]0x00F3)t sau khi g$([char]0x1EE1) $completedApps $([char]0x1EE9)ng d$([char]0x1EE5)ng."
                if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)ang ch$([char]0x1EDD) x$([char]0x00E1)c nh$([char]0x1EAD)n d$([char]0x1ECD)n $($dedupLeftovers.Count) m$([char]0x1EE5)c r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0)..." }
                $dialogTitle = if ($completedApps -gt 1) { "D$([char]0x1ECD)n r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0) sau khi g$([char]0x1EE1) ($completedApps $([char]0x1EE9)ng d$([char]0x1EE5)ng)" } else { "D$([char]0x1ECD)n r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0) sau khi g$([char]0x1EE1)" }
                $res = Show-LeftoverReviewDialog -OwnerWindow $window -Items @($dedupLeftovers) -Title $dialogTitle -ForceStopByDefault:$true
                if ($res.Confirmed) {
                    $freedMb = [math]::Round($res.FreedBytes / 1MB, 2)
                    Log-Text "[OK] $([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n s$([char]0x1EA1)ch $($res.RemovedCount) m$([char]0x1EE5)c t$([char]0x1ED3)n d$([char]0x01B0) (~$freedMb MB)."
                }
            }
        }
    } finally {
        $wasCanceled = [bool]$script:cancelRequested
        $script:isUninstallingQueue = $false
        $script:uninstallQueue.Clear()
        $script:uninstallQueuedKeys.Clear()
        if ($script:uninstallerVirtualView) {
            $script:uninstallerVirtualView.ClearAllQueued()
        } else {
            foreach ($entry in $script:uninstallerRowEntries) {
                $entry.IsQueued = $false
                if ($entry.Row -and -not $entry.IsRemoved) {
                    $entry.Row.Opacity = 1.0
                }
            }
        }
        if ($progressBar) { $progressBar.IsIndeterminate = $false }
        Update-UninstallQueueUiState
        if ($txtStatus -and -not $script:isWindowClosing) {
            $txtStatus.Text = if ($wasCanceled) { "$([char]0x0110)$([char]0x00E3) d$([char]0x1EEB)ng h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i g$([char]0x1EE1) ($completedApps $([char]0x0111)$([char]0x00E3) xong)" } else { "G$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t ho$([char]0x00E0)n t$([char]0x1EA5)t ($completedApps $([char]0x1EE9)ng d$([char]0x1EE5)ng)!" }
        }
    }

    if (-not $script:isWindowClosing -and $completedApps -gt 0) {
        Update-UninstallerList -Force
        if (-not $script:isWindowClosing -and $window -and $window.Dispatcher) {
            $window.Dispatcher.BeginInvoke(
                [System.Windows.Threading.DispatcherPriority]::Background,
                [Action]{
                    if (-not $script:isWindowClosing -and (Get-Command "Scan-And-ColorizeApps" -ErrorAction SilentlyContinue)) {
                        Scan-And-ColorizeApps -Quiet
                    }
                    if (-not $script:isWindowClosing -and (Get-Command "Schedule-AutoAppRefresh" -ErrorAction SilentlyContinue)) {
                        Schedule-AutoAppRefresh -DelaySeconds 12 -FollowUpPasses 2 -Reason "uninstall"
                    }
                }
            ) | Out-Null
        }
    }
}

function Get-SelectedUninstallerApps {
    return @($script:uninstallerRowEntries | Where-Object {
        -not $_.IsRemoved -and ($_.IsSelected -or ($_.CheckBox -and $_.CheckBox.IsChecked -eq $true))
    } | ForEach-Object { $_.App })
}

function Confirm-UnifiedUninstallSelection {
    param(
        [Parameter(Mandatory = $true)][object[]]$Items,
        [switch]$IsQueueAppend
    )
    if (-not $Items -or $Items.Count -eq 0 -or $script:isWindowClosing) { return $null }

    $appLines = @($Items | ForEach-Object {
        $vPart = if (-not [string]::IsNullOrWhiteSpace($_.DisplayVersion)) { " ($($_.DisplayVersion))" } else { "" }
        "$([char]0x2022) $($_.DisplayName)$vPart"
    })
    $allBrokenOrphan = (@($Items | Where-Object { -not $_.IsBrokenOrphan }).Count -eq 0)
    $hasDarkPattern = $false
    foreach ($it in $Items) {
        $meta = "$($it.DisplayName) $($it.Publisher) $($it.UninstallString) $($it.QuietUninstallString)"
        if ($meta -match '(?i)\b(360Safe|360 Total|Qihu|2345|Kingsoft|Sogou|Baidu|Driver Booster|IObit)\b') {
            $hasDarkPattern = $true
            break
        }
    }

    $count = $Items.Count
    $normalPrimary = if ($IsQueueAppend) { "Th$([char]0x00EA)m v$([char]0x00E0)o h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i ($count)" } else { "G$([char]0x1EE1) ngay ($count)" }
    $forcePrimary  = if ($IsQueueAppend) { "+ Bu$([char]0x1ED9)c d$([char]0x1EEB)ng v$([char]0x00E0)o h$([char]0x00E0)ng ($count)" } else { "Bu$([char]0x1ED9)c d$([char]0x1EEB)ng & X$([char]0x00F3)a ($count)" }
    $secondaryText = if ($IsQueueAppend) { "B$([char]0x1ECF) qua" } else { "H$([char]0x1EE7)y b$([char]0x1ECF)" }

    if ($allBrokenOrphan) {
        $msgText = if ($IsQueueAppend) {
            "H$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i $([char]0x0111)ang ch$([char]0x1EA1)y. Th$([char]0x00EA)m $count $([char]0x1EE9)ng d$([char]0x1EE5)ng l$([char]0x1ED7)i / c$([char]0x00F2)n s$([char]0x00F3)t v$([char]0x00E0)o h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i qu$([char]0x00E9)t x$([char]0x00F3)a tr$([char]0x1EF1)c ti$([char]0x1EBF)p?"
        } else {
            "$([char]0x00C9)p d$([char]0x1EEB)ng ti$([char]0x1EBF)n tr$([char]0x00EC)nh/d$([char]0x1ECB)ch v$([char]0x1EE5) $([char]0x0111)ang kh$([char]0x00F3)a (n$([char]0x1EBF)u c$([char]0x00F2)n) v$([char]0x00E0) qu$([char]0x00E9)t x$([char]0x00F3)a s$([char]0x1EA1)ch $count m$([char]0x1EE5)c l$([char]0x1ED7)i / c$([char]0x00F2)n s$([char]0x00F3)t $([char]0x0111)$([char]0x00E3) ch$([char]0x1ECD)n?"
        }
        $captionText = if ($IsQueueAppend) { "Th$([char]0x00EA)m v$([char]0x00E0)o H$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i G$([char]0x1EE1)" } else { "X$([char]0x00E1)c nh$([char]0x1EAD)n G$([char]0x1EE1) & D$([char]0x1ECD)n s$([char]0x1EA1)ch" }
        $confirm = Show-OwnedMessageBox `
            -Text $msgText `
            -Caption $captionText `
            -Buttons ([System.Windows.Forms.MessageBoxButtons]::YesNo) `
            -Icon ([System.Windows.Forms.MessageBoxIcon]::Warning) `
            -PrimaryText $normalPrimary `
            -SecondaryText $secondaryText `
            -DetailItems $appLines `
            -ModeBadgeText "$([char]0x1EE8)ng d$([char]0x1EE5)ng b$([char]0x1ECB) l$([char]0x1ED7)i / thi$([char]0x1EBF)u tr$([char]0x00EC)nh g$([char]0x1EE1) $([char]0x2014) T$([char]0x1EF1) $([char]0x0111)$([char]0x1ED9)ng $([char]0x00E9)p d$([char]0x1EEB)ng & qu$([char]0x00E9)t x$([char]0x00F3)a tr$([char]0x1EF1)c ti$([char]0x1EBF)p" `
            -ModeBadgeKind "Warn"
        if ($confirm -ne [System.Windows.Forms.DialogResult]::Yes -or $script:isWindowClosing) { return $null }
        return [PSCustomObject]@{ SkipVendor = $true; ForceStop = $true; AutoSilent = $false }
    }

    $defaultBadgeText = if ($hasDarkPattern) {
        "Ph$([char]0x00E1)t hi$([char]0x1EC7)n app hay c$([char]0x00F3) popup gi$([char]0x1EEF) ch$([char]0x00E2)n $([char]0x2014) n$([char]0x00EA)n b$([char]0x1EAD)t 'Bu$([char]0x1ED9)c d$([char]0x1EEB)ng & X$([char]0x00F3)a tr$([char]0x1EF1)c ti$([char]0x1EBF)p' b$([char]0x00EA)n d$([char]0x01B0)$([char]0x1EDB)i"
    } elseif ($IsQueueAppend) {
        "Ch$([char]0x1EA1)y n$([char]0x1ED1)i ti$([char]0x1EBF)p v$([char]0x00E0) g$([char]0x1ED9)p b$([char]0x1EA3)ng d$([char]0x1ECD)n r$([char]0x00E1)c cu$([char]0x1ED1)i l$([char]0x01B0)$([char]0x1EE3)t"
    } else {
        ""
    }
    $defaultBadgeKind = if ($hasDarkPattern) { "Warn" } else { "Info" }

    $forceToggleState = @{
        Checked        = $false
        Label          = "Bu$([char]0x1ED9)c d$([char]0x1EEB)ng & X$([char]0x00F3)a tr$([char]0x1EF1)c ti$([char]0x1EBF)p (b$([char]0x1ECF) qua tr$([char]0x00EC)nh g$([char]0x1EE1) h$([char]0x00E3)ng)"
        HintOn         = "$([char]0x00C9)p t$([char]0x1EAF)t ti$([char]0x1EBF)n tr$([char]0x00EC)nh/service/task/handle, b$([char]0x1ECF) qua tr$([char]0x00EC)nh g$([char]0x1EE1) g$([char]0x1ED1)c r$([char]0x1ED3)i x$([char]0x00F3)a tr$([char]0x1EF1)c ti$([char]0x1EBF)p"
        HintOff        = "T$([char]0x1EAE)T: Ch$([char]0x1EA1)y tr$([char]0x00EC)nh g$([char]0x1EE1) chu$([char]0x1EA9)n c$([char]0x1EE7)a h$([char]0x00E3)ng tr$([char]0x01B0)$([char]0x1EDB)c (v$([char]0x1EAB)n t$([char]0x1EF1) $([char]0x0111)$([char]0x00F3)ng ti$([char]0x1EBF)n tr$([char]0x00EC)nh kh$([char]0x00F3)a file)"
        BadgeOn        = "Restart Manager + NtSuspend + Kill Tree + MoveFileEx (b$([char]0x1ECF) qua tr$([char]0x00EC)nh g$([char]0x1EE1) h$([char]0x00E3)ng)"
        BadgeKindOn    = "Danger"
        PrimaryTextOn  = $forcePrimary
        PrimaryTextOff = $normalPrimary
    }
    $autoSilentToggleState = @{
        Checked = [bool]$script:autoSilentUninstall
        Label   = "T$([char]0x1EF1) $([char]0x0111)$([char]0x1ED9)ng g$([char]0x1EAF)n c$([char]0x1EDD) g$([char]0x1EE1) im l$([char]0x1EB7)ng theo b$([char]0x1ED9) c$([char]0x00E0)i"
        HintOn  = "T$([char]0x1EF1) nh$([char]0x1EAD)n di$([char]0x1EC7)n b$([char]0x1ED9) c$([char]0x00E0)i (Inno, NSIS, WiX, InstallShield, MSI...) v$([char]0x00E0) g$([char]0x1EAF)n c$([char]0x1EDD) ch$([char]0x1EA1)y ng$([char]0x1EA7)m"
        HintOff = "M$([char]0x1EDF) tr$([char]0x00EC)nh g$([char]0x1EE1) g$([char]0x1ED1)c c$([char]0x1EE7)a h$([char]0x00E3)ng nh$([char]0x01B0) b$([char]0x00EC)nh th$([char]0x01B0)$([char]0x1EDD)ng (t$([char]0x1EAF)t g$([char]0x1EAF)n c$([char]0x1EDD) im l$([char]0x1EB7)ng)"
    }

    $msgText = if ($IsQueueAppend) {
        "H$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i g$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t $([char]0x0111)ang ch$([char]0x1EA1)y. Th$([char]0x00EA)m $count $([char]0x1EE9)ng d$([char]0x1EE5)ng m$([char]0x1EDB)i v$([char]0x00E0)o h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i?"
    } else {
        "B$([char]0x1EA1)n c$([char]0x00F3) ch$([char]0x1EAF)c ch$([char]0x1EAF)n mu$([char]0x1ED1)n g$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t $count $([char]0x1EE9)ng d$([char]0x1EE5)ng $([char]0x0111)$([char]0x00E3) ch$([char]0x1ECD)n?"
    }
    $captionText = if ($IsQueueAppend) { "Th$([char]0x00EA)m v$([char]0x00E0)o H$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i G$([char]0x1EE1)" } else { "X$([char]0x00E1)c nh$([char]0x1EAD)n G$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t" }
    $confirm = Show-OwnedMessageBox `
        -Text $msgText `
        -Caption $captionText `
        -Buttons ([System.Windows.Forms.MessageBoxButtons]::YesNo) `
        -Icon ([System.Windows.Forms.MessageBoxIcon]::Warning) `
        -PrimaryText $normalPrimary `
        -SecondaryText $secondaryText `
        -DetailItems $appLines `
        -ModeBadgeText $defaultBadgeText `
        -ModeBadgeKind $defaultBadgeKind `
        -ForceToggleState $forceToggleState `
        -ToggleState $autoSilentToggleState
    if ($confirm -ne [System.Windows.Forms.DialogResult]::Yes -or $script:isWindowClosing) { return $null }

    $useForce = [bool]$forceToggleState.Checked
    $useAutoSilent = if ($useForce) { $false } else { [bool]$autoSilentToggleState.Checked }
    if (-not $useForce -and -not $script:isWindowClosing) {
        $script:autoSilentUninstall = $useAutoSilent
    }
    return [PSCustomObject]@{
        SkipVendor = $useForce
        ForceStop  = $useForce
        AutoSilent = $useAutoSilent
    }
}

if ($btnDeepUninstall) {
    $btnDeepUninstall.Add_Click({
        $selectedItems = Get-SelectedUninstallerApps
        if ($selectedItems.Count -eq 0 -or $script:isWindowClosing) { return }

        if ($script:isUninstallingQueue) {
            $newItems = @($selectedItems | Where-Object { -not $script:uninstallQueuedKeys.Contains((Get-UninstallerAppQueueKey $_)) })
            if ($newItems.Count -eq 0) {
                Log-Text "[WARN] C$([char]0x00E1)c $([char]0x1EE9)ng d$([char]0x1EE5)ng $([char]0x0111)$([char]0x00E3) ch$([char]0x1ECD)n hi$([char]0x1EC7)n $([char]0x0111)$([char]0x00E3) n$([char]0x1EB1)m trong h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i g$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t."
                return
            }
            $planChoice = Confirm-UnifiedUninstallSelection -Items $newItems -IsQueueAppend
            if ($null -ne $planChoice -and $script:isUninstallingQueue -and -not $script:isWindowClosing) {
                $nAdded = Add-ItemsToUninstallQueue -Items $newItems -SkipVendor:$planChoice.SkipVendor -ForceStop:$planChoice.ForceStop -AutoSilent:$planChoice.AutoSilent
                if ($nAdded -gt 0) {
                    if ($planChoice.ForceStop) {
                        Log-Text "[QUEUE] $([char]0x0110)$([char]0x00E3) th$([char]0x00EA)m +$nAdded $([char]0x1EE9)ng d$([char]0x1EE5)ng (Bu$([char]0x1ED9)c d$([char]0x1EEB)ng & X$([char]0x00F3)a) v$([char]0x00E0)o h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i."
                    } else {
                        Log-Text "[QUEUE] $([char]0x0110)$([char]0x00E3) th$([char]0x00EA)m +$nAdded $([char]0x1EE9)ng d$([char]0x1EE5)ng v$([char]0x00E0)o h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i g$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t."
                    }
                }
            }
            return
        }

        Invoke-GuardedAction "G$([char]0x1EE1) c$([char]0x00E0)i $([char]0x0111)$([char]0x1EB7)t $([char]0x1EE9)ng d$([char]0x1EE5)ng" -DeferExpand -AllowDuringUninstallerLoad {
            $selectedNow = Get-SelectedUninstallerApps
            $planChoice = Confirm-UnifiedUninstallSelection -Items $selectedNow
            if ($null -eq $planChoice) { return }

            [void](Add-ItemsToUninstallQueue -Items $selectedNow -SkipVendor:$planChoice.SkipVendor -ForceStop:$planChoice.ForceStop -AutoSilent:$planChoice.AutoSilent)
            Start-UninstallQueueExecution
        }
    })
}

$script:runSystemOrphanScanAction = {
    Invoke-GuardedAction "Qu$([char]0x00E9)t t$([char]0x1EC7)p r$([char]0x00E1)c & d$([char]0x1EEF) li$([char]0x1EC7)u c$([char]0x00F2)n s$([char]0x00F3)t" -DeferExpand -AllowDuringUninstallerLoad {
        if ($script:isWindowClosing) { return }
        $script:cancelRequested = $false
        if ($btnCancelAction) {
            $btnCancelAction.Content = "D$([char]0x1EEB)ng qu$([char]0x00E9)t"
            $btnCancelAction.IsEnabled = $true
            $btnCancelAction.Visibility = [System.Windows.Visibility]::Visible
        }
        if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)ang qu$([char]0x00E9)t s$([char]0x00E2)u app l$([char]0x1ED7)i, th$([char]0x01B0) m$([char]0x1EE5)c r$([char]0x00E1)c, Service, Task, Firewall & Registry..." }
        if ($progressBar) { $progressBar.IsIndeterminate = $true }
        try {
            if (Get-Command "Find-SystemOrphanLeftovers" -ErrorAction SilentlyContinue) {
                $orphans = @(Find-SystemOrphanLeftovers -InstalledApps $script:cachedUninstallerApps -CatalogApps $AppCatalog -AllowCancel)
                if ($progressBar) { $progressBar.IsIndeterminate = $false }
                if ($script:isWindowClosing) { return }
                if ($script:cancelRequested) {
                    if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)$([char]0x00E3) h$([char]0x1EE7)y qu$([char]0x00E9)t t$([char]0x1EC7)p r$([char]0x00E1)c & d$([char]0x1EEF) li$([char]0x1EC7)u c$([char]0x00F2)n s$([char]0x00F3)t" }
                    return
                }
                if ($orphans.Count -eq 0) {
                    if ($txtStatus) { $txtStatus.Text = "Kh$([char]0x00F4)ng ph$([char]0x00E1)t hi$([char]0x1EC7)n d$([char]0x1EEF) li$([char]0x1EC7)u r$([char]0x00E1)c c$([char]0x00F2)n s$([char]0x00F3)t" }
                    Show-OwnedMessageBox `
                        -Text "Kh$([char]0x00F4)ng ph$([char]0x00E1)t hi$([char]0x1EC7)n t$([char]0x1EC7)p r$([char]0x00E1)c, Registry, Service hay $([char]0x1EE9)ng d$([char]0x1EE5)ng n$([char]0x00E0)o b$([char]0x1ECB) l$([char]0x1ED7)i/c$([char]0x00F2)n s$([char]0x00F3)t tr$([char]0x00EA)n h$([char]0x1EC7) th$([char]0x1ED1)ng!" `
                        -Caption "Qu$([char]0x00E9)t T$([char]0x1EC7)p R$([char]0x00E1)c & D$([char]0x1EEF) Li$([char]0x1EC7)u C$([char]0x00F2)n S$([char]0x00F3)t" `
                        -Buttons ([System.Windows.Forms.MessageBoxButtons]::OK) `
                        -Icon ([System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
                } else {
                    $totalOrphMb = [math]::Round((($orphans | Measure-Object -Property SizeBytes -Sum).Sum) / 1MB, 1)
                    if ($txtStatus) { $txtStatus.Text = "Ph$([char]0x00E1)t hi$([char]0x1EC7)n $($orphans.Count) m$([char]0x1EE5)c d$([char]0x1EEF) li$([char]0x1EC7)u c$([char]0x00F2)n s$([char]0x00F3)t (~$totalOrphMb MB)" }
                    $dlgRes = $null
                    if (-not $script:isWindowClosing -and (Get-Command "Show-LeftoverReviewDialog" -ErrorAction SilentlyContinue)) {
                        $dlgRes = Show-LeftoverReviewDialog -OwnerWindow $window -Items $orphans -Title "Qu$([char]0x00E9)t T$([char]0x1EC7)p R$([char]0x00E1)c & D$([char]0x1EEF) Li$([char]0x1EC7)u C$([char]0x00F2)n S$([char]0x00F3)t"
                    }
                    if (-not $script:isWindowClosing -and $dlgRes -and $dlgRes.Confirmed -and $dlgRes.RemovedCount -gt 0) {
                        $freedMb = [math]::Round($dlgRes.FreedBytes / 1MB, 2)
                        Log-Text "[OK] $([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n s$([char]0x1EA1)ch $($dlgRes.RemovedCount) m$([char]0x1EE5)c t$([char]0x1ED3)n d$([char]0x01B0) (~$freedMb MB)."
                        if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n $($dlgRes.RemovedCount) m$([char]0x1EE5)c t$([char]0x1ED3)n d$([char]0x01B0) (~$freedMb MB) $([char]0x2014) $([char]0x0110)ang l$([char]0x00E0)m m$([char]0x1EDB)i..." }
                        Update-UninstallerList -Force
                    }
                }
            }
        } finally {
            if ($progressBar) { $progressBar.IsIndeterminate = $false }
            if ($btnCancelAction) {
                $btnCancelAction.Visibility = [System.Windows.Visibility]::Collapsed
                $btnCancelAction.IsEnabled = $true
                $btnCancelAction.Content = "D$([char]0x1EEB)ng t$([char]0x00E1)c v$([char]0x1EE5)"
            }
            if ($txtStatus -and -not $script:isWindowClosing -and $txtStatus.Text -like "$([char]0x0110)ang qu$([char]0x00E9)t*") {
                $txtStatus.Text = "S$([char]0x1EB5)n s$([char]0x00E0)ng"
            }
        }
    }
}

if ($btnScanOrphans) {
    $btnScanOrphans.Add_Click($script:runSystemOrphanScanAction)
}
if ($btnUninstEmptyScan) {
    $btnUninstEmptyScan.Add_Click($script:runSystemOrphanScanAction)
}

