function Get-OptimizerCatalogItems {
    if ($TweakCatalog -and $TweakCatalog.Count -gt 0) {
        return @($TweakCatalog)
    }
    try {
        $jsonPath = Join-Path $PSScriptRoot "..\config\tweaks.json"
        if (Test-Path -LiteralPath $jsonPath) {
            $loaded = ConvertFrom-Json ([System.IO.File]::ReadAllText($jsonPath, [System.Text.Encoding]::UTF8))
            $script:TweakCatalog = $loaded
            return @($loaded)
        }
    } catch {}
    return @()
}

function Set-OptimizerSubTab {
    param([int]$SubIndex)
    if ($script:isWindowClosing) { return }
    $script:optSubTabIndex = $SubIndex
    if ($script:optPageCustomize) {
        $script:optPageCustomize.Visibility = if ($SubIndex -eq 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
        $script:optPageCustomize.IsHitTestVisible = ($SubIndex -eq 0)
    }
    if ($script:optPageResources) {
        $script:optPageResources.Visibility = if ($SubIndex -eq 1) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
        $script:optPageResources.IsHitTestVisible = ($SubIndex -eq 1)
    }
    if ($script:optPageStartup) {
        $script:optPageStartup.Visibility = if ($SubIndex -eq 2) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
        $script:optPageStartup.IsHitTestVisible = ($SubIndex -eq 2)
    }
    if ($script:optSubBtnCustomize) {
        $script:optSubBtnCustomize.Foreground = if ($SubIndex -eq 0) { $script:brushNavActive } else { $script:brushNavInactive }
        $script:optSubBtnCustomize.BorderBrush = if ($SubIndex -eq 0) { $script:brushNavActive } else { $script:brushTransparent }
    }
    if ($script:optSubBtnResources) {
        $script:optSubBtnResources.Foreground = if ($SubIndex -eq 1) { $script:brushNavActive } else { $script:brushNavInactive }
        $script:optSubBtnResources.BorderBrush = if ($SubIndex -eq 1) { $script:brushNavActive } else { $script:brushTransparent }
    }
    if ($script:optSubBtnStartup) {
        $script:optSubBtnStartup.Foreground = if ($SubIndex -eq 2) { $script:brushNavActive } else { $script:brushNavInactive }
        $script:optSubBtnStartup.BorderBrush = if ($SubIndex -eq 2) { $script:brushNavActive } else { $script:brushTransparent }
    }
    if ($SubIndex -eq 1 -and (Get-Command "Initialize-ResourcesTabIfNeeded" -ErrorAction SilentlyContinue)) {
        Initialize-ResourcesTabIfNeeded
    }
    if ($SubIndex -eq 2 -and (Get-Command "Initialize-StartupTabIfNeeded" -ErrorAction SilentlyContinue)) {
        Initialize-StartupTabIfNeeded
    }
    Update-OptimizerSelectionCount
}

function Update-OptimizerSelectionCount {
    if ($script:isWindowClosing) { return }
    $isTab4Visible = $script:tabPages -and $script:tabPages.Count -gt 4 -and $script:tabPages[4] -and $script:tabPages[4].Visibility -eq [System.Windows.Visibility]::Visible
    if (-not $isTab4Visible -or -not $txtSelectionCount) { return }
    if ($script:optSubTabIndex -eq 1) {
        if (Get-Command "Update-ResourcesSummary" -ErrorAction SilentlyContinue) {
            Update-ResourcesSummary
        } else {
            $txtSelectionCount.Text = ""
        }
        return
    }
    if ($script:optSubTabIndex -eq 2) {
        if (Get-Command "Update-StartupFooterSummary" -ErrorAction SilentlyContinue) {
            Update-StartupFooterSummary
        } else {
            $txtSelectionCount.Text = ""
        }
        return
    }
    if ($script:optSubTabIndex -ne 0) {
        $txtSelectionCount.Text = ""
        return
    }
    $cbCnt = 0
    foreach ($ent in $script:optEntries) {
        if (-not $ent.CheckBox) { continue }
        if (-not $ent.IsToggle -and $ent.CheckBox.IsChecked -eq $true) {
            $cbCnt++
        }
    }
    $txtSelectionCount.Text = "$cbCnt t$([char]0x00F9)y ch$([char]0x1EC9)nh ch$([char]0x1EDD) l$([char]0x01B0)u"
    $txtSelectionCount.Foreground = if ($cbCnt -gt 0) { $script:brushSelActive } else { $script:brushNavActive }
}

function Set-OptimizerEntryVisualState {
    param($Entry, [string]$State, [string]$Detail = "")
    if (-not $Entry) { return }
    $Entry.State = $State
    $titleTb = $Entry.TitleText
    switch ($State) {
        "Applied" {
            if ($titleTb) { $titleTb.Foreground = $script:brushOptRiskSafeFg }
            $stateDesc = if (-not [string]::IsNullOrWhiteSpace($Detail) -and $Entry.ComboBox) { "Tr$([char]0x1EA1)ng th$([char]0x00E1)i: $([char]0x0110)ang b$([char]0x1EAD)t ($Detail)" } else { "Tr$([char]0x1EA1)ng th$([char]0x00E1)i: $([char]0x0110)ang b$([char]0x1EAD)t" }
        }
        "Partial" {
            if ($titleTb) { $titleTb.Foreground = $script:brushOptRiskModFg }
            $stateDesc = "Tr$([char]0x1EA1)ng th$([char]0x00E1)i: B$([char]0x1EAD)t 1 ph$([char]0x1EA7)n (m$([char]0x1ED9)t s$([char]0x1ED1) kh$([char]0x00F3)a $([char]0x0111)$([char]0x00E3) kh$([char]0x1EDB)p s$([char]0x1EB5)n)"
        }
        "Action" {
            if ($titleTb) { $titleTb.Foreground = $script:brushTextWhite }
            $stateDesc = "Tr$([char]0x1EA1)ng th$([char]0x00E1)i: T$([char]0x00E1)c v$([char]0x1EE5) ch$([char]0x1EA1)y 1 l$([char]0x1EA7)n"
        }
        default {
            if ($titleTb) { $titleTb.Foreground = $script:brushTextWhite }
            $stateDesc = "Tr$([char]0x1EA1)ng th$([char]0x00E1)i: M$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh"
        }
    }
    if ($Entry.IsToggle) {
        $liveBool = ($State -eq "Applied")
        $Entry.InitialToggleState = $liveBool
        if ($Entry.CheckBox) { $Entry.CheckBox.IsChecked = $liveBool }
        if ($Entry.ComboBox -and -not [string]::IsNullOrWhiteSpace($Detail)) {
            for ($ci = 0; $ci -lt $Entry.ComboBox.Items.Count; $ci++) {
                if ([string]$Entry.ComboBox.Items[$ci] -ieq $Detail) {
                    $Entry.ComboBox.SelectedIndex = $ci
                    break
                }
            }
        }
    }
    if ($Entry.Row -and $Entry.BaseToolTip) {
        $Entry.Row.ToolTip = "$($Entry.BaseToolTip)`n$stateDesc"
    }
}

$script:optApplyingSingleToggle = $false

function Invoke-OptimizerInstantToggle {
    param(
        [Parameter(Mandatory = $true)]$Entry,
        [Parameter(Mandatory = $true)][bool]$WantEnabled,
        [switch]$ForceApply
    )
    if (-not $Entry -or -not $Entry.Tweak -or -not $Entry.CheckBox) { return }

    $rollbackToggle = {
        $prevS = $script:optSyncingVisuals
        $script:optSyncingVisuals = $true
        try {
            $Entry.CheckBox.IsChecked = [bool]$Entry.InitialToggleState
        } finally {
            $script:optSyncingVisuals = $prevS
        }
    }

    if ($script:isWindowClosing -or $script:optApplyingSingleToggle -or $script:isActionRunning) {
        & $rollbackToggle
        if ($script:isActionRunning -and $txtStatus) {
            $txtStatus.Text = "$([char]0x0110)ang x$([char]0x1EED) l$([char]0x00FD) t$([char]0x00E1)c v$([char]0x1EE5) kh$([char]0x00E1)c, vui l$([char]0x00F2)ng $([char]0x0111)$([char]0x1EE3)i xong r$([char]0x1ED3)i g$([char]0x1EA1)t l$([char]0x1EA1)i..."
        }
        return
    }
    if (-not $ForceApply -and $WantEnabled -eq [bool]$Entry.InitialToggleState) { return }

    $tw = $Entry.Tweak
    $tid = [string]$tw.Id

    if ($WantEnabled -and $tw.Risk -eq "Caution") {
        $ans = Show-OwnedMessageBox `
            -Text "T$([char]0x00F9)y ch$([char]0x1EC9)nh '$($tw.Name)' thu$([char]0x1ED9)c m$([char]0x1EE9)c N$([char]0x00E2)ng cao.`n$($tw.Description)`n`nApp-Driver s$([char]0x1EBD) t$([char]0x1EF1) $([char]0x0111)$([char]0x1ED9)ng sao l$([char]0x01B0)u tr$([char]0x1EA1)ng th$([char]0x00E1)i g$([char]0x1ED1)c qua OptimizerGuard tr$([char]0x01B0)$([char]0x1EDB)c khi $([char]0x00E1)p d$([char]0x1EE5)ng. Ti$([char]0x1EBF)p t$([char]0x1EE5)c?" `
            -Caption "X$([char]0x00E1)c nh$([char]0x1EAD)n b$([char]0x1EAD)t t$([char]0x00F9)y ch$([char]0x1EC9)nh n$([char]0x00E2)ng cao" `
            -Buttons ([System.Windows.Forms.MessageBoxButtons]::YesNo) `
            -Icon ([System.Windows.Forms.MessageBoxIcon]::Warning)
        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes -or $script:isWindowClosing) {
            & $rollbackToggle
            return
        }
    }

    $isAdminNow = if ("DuckUtil.WindowsOptimizerEngine" -as [type]) { [DuckUtil.WindowsOptimizerEngine]::IsCurrentProcessAdmin() } else { $true }
    if ((Test-OptimizerTweakRequiresAdmin -Tweak $tw) -and -not $isAdminNow) {
        & $rollbackToggle
        Log-Text "[WARN] T$([char]0x00F9)y ch$([char]0x1EC9)nh '$($tw.Name)' c$([char]0x1EA7)n quy$([char]0x1EC1)n Administrator $([char]0x0111)$([char]0x1EC3) ghi v$([char]0x00E0)o h$([char]0x1EC7) th$([char]0x1ED1)ng (HKLM/Service)."
        if ($txtStatus) { $txtStatus.Text = "C$([char]0x1EA7)n m$([char]0x1EDF) App-Driver b$([char]0x1EB1)ng quy$([char]0x1EC1)n Administrator $([char]0x0111)$([char]0x1EC3) b$([char]0x1EAD)t '$($tw.Name)'" }
        [void](Show-OwnedMessageBox -Text "T$([char]0x00F9)y ch$([char]0x1EC9)nh '$($tw.Name)' ghi v$([char]0x00E0)o nh$([char]0x00E1)nh h$([char]0x1EC7) th$([char]0x1ED1)ng (HKLM/Service) n$([char]0x00EA)n c$([char]0x1EA7)n ch$([char]0x1EA1)y App-Driver v$([char]0x1EDB)i quy$([char]0x1EC1)n Administrator." -Caption "Y$([char]0x00EA)u c$([char]0x1EA7)u quy$([char]0x1EC1)n Administrator" -Buttons ([System.Windows.Forms.MessageBoxButtons]::OK) -Icon ([System.Windows.Forms.MessageBoxIcon]::Warning))
        return
    }

    $comboVal = ""
    if ($Entry.ComboBox) {
        if ($WantEnabled) {
            $selItem = [string]$Entry.ComboBox.SelectedItem
            if ([string]::IsNullOrWhiteSpace($selItem) -or $selItem -match 'DHCP') {
                $prevS2 = $script:optSyncingVisuals
                $script:optSyncingVisuals = $true
                try {
                    if ($Entry.ComboBox.Items.Count -gt 0) {
                        $Entry.ComboBox.SelectedIndex = 0
                        $selItem = [string]$Entry.ComboBox.SelectedItem
                    }
                } finally {
                    $script:optSyncingVisuals = $prevS2
                }
            }
            $comboVal = $selItem
        } else {
            $comboVal = "M$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh (DHCP)"
        }
    }

    $script:optApplyingSingleToggle = $true
    $Entry.CheckBox.IsEnabled = $false
    if ($Entry.ComboBox) { $Entry.ComboBox.IsEnabled = $false }
    $actVerb = if ($WantEnabled) { "b$([char]0x1EAD)t" } else { "t$([char]0x1EAF)t" }
    if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)ang ${actVerb}: $($tw.Name)..." }

    try {
        if ($WantEnabled) {
            $conflictId = if ($tid -eq "opt_prefer_ipv4") { "opt_disable_ipv6" } elseif ($tid -eq "opt_disable_ipv6") { "opt_prefer_ipv4" } else { "" }
            if (-not [string]::IsNullOrEmpty($conflictId) -and $script:optEntryById.ContainsKey($conflictId)) {
                $otherEnt = $script:optEntryById[$conflictId]
                if ($otherEnt -and $otherEnt.InitialToggleState) {
                    $cRes = Invoke-SingleOptimizerToggle -Tweak $otherEnt.Tweak -TargetEnabled $false -HardwareProfile $script:optHardwareProfile
                    $prevSc = $script:optSyncingVisuals
                    $script:optSyncingVisuals = $true
                    try {
                        Set-OptimizerEntryVisualState -Entry $otherEnt -State ([string]$cRes.VerifiedState) -Detail ([string]$cRes.VerifiedDetail)
                    } finally {
                        $script:optSyncingVisuals = $prevSc
                    }
                }
            }
        }

        $res = Invoke-SingleOptimizerToggle -Tweak $tw -TargetEnabled $WantEnabled -ComboValue $comboVal -HardwareProfile $script:optHardwareProfile
        $prevS3 = $script:optSyncingVisuals
        $script:optSyncingVisuals = $true
        try {
            Set-OptimizerEntryVisualState -Entry $Entry -State ([string]$res.VerifiedState) -Detail ([string]$res.VerifiedDetail)
        } finally {
            $script:optSyncingVisuals = $prevS3
        }

        if ($res.Success) {
            $detailSuffix = if (-not [string]::IsNullOrWhiteSpace($comboVal) -and $WantEnabled) { " ($comboVal)" } else { "" }
            Log-Text "[OK] T$([char]0x00F9)y ch$([char]0x1EC9)nh: $([char]0x0110)$([char]0x00E3) ${actVerb} '$($tw.Name)'$detailSuffix."
            if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)$([char]0x00E3) ${actVerb}: $($tw.Name)$detailSuffix" }
        } else {
            $errMsg = if ($res.Errors -and $res.Errors.Count -gt 0) { $res.Errors[0] } else { "Kh$([char]0x00F4)ng th$([char]0x1EC3) ghi c$([char]0x1EA5)u h$([char]0x00EC)nh v$([char]0x00E0)o h$([char]0x1EC7) th$([char]0x1ED1)ng" }
            Log-Text "[ERR] T$([char]0x00F9)y ch$([char]0x1EC9)nh '$($tw.Name)': $errMsg"
            if ($txtStatus) { $txtStatus.Text = "L$([char]0x1ED7)i ${actVerb} '$($tw.Name)' $([char]0x2014) $([char]0x0111)$([char]0x00E3) ho$([char]0x00E0)n l$([char]0x1EA1)i tr$([char]0x1EA1)ng th$([char]0x00E1)i th$([char]0x1EF1)c t$([char]0x1EBF)" }
        }
        Apply-OptimizerFilter
        Update-OptimizerSelectionCount
    } finally {
        $Entry.CheckBox.IsEnabled = $true
        if ($Entry.ComboBox) { $Entry.ComboBox.IsEnabled = $true }
        $script:optApplyingSingleToggle = $false
    }
}

function Apply-OptimizerFilter {
    if (-not $script:optInitialized -or $script:isWindowClosing) { return }
    $appliedCount = 0
    $lastVisSectionByLane = @($null, $null)

    foreach ($card in $script:optCategoryCards) {
        foreach ($ent in $card.Entries) {
            if ($ent.State -eq "Applied") { $appliedCount++ }
        }
        if ($card.CardBorder) {
            $card.CardBorder.Margin = $script:optSectionMargin
        }
        if ($null -ne $card.LaneIndex -and $card.LaneIndex -ge 0 -and $card.LaneIndex -lt 2) {
            $lastVisSectionByLane[$card.LaneIndex] = $card.CardBorder
        }
    }

    for ($li = 0; $li -lt 2; $li++) {
        if ($lastVisSectionByLane[$li]) {
            $lastVisSectionByLane[$li].Margin = $thicknessZero
        }
    }

    if ($script:txtOptSummary) {
        $total = $script:optEntries.Count
        $script:txtOptSummary.Text = "T$([char]0x1ED5)ng $total t$([char]0x00F9)y ch$([char]0x1EC9)nh ($appliedCount $([char]0x0111)ang b$([char]0x1EAD)t)"
    }
}

function Refresh-OptimizerLiveState {
    if (-not $script:optInitialized -or $script:isWindowClosing) { return }
    if (-not ("DuckUtil.WindowsOptimizerEngine" -as [type])) { return }
    if (-not $script:optCachedProbeRequests -or $script:optCachedProbeRequests.Length -eq 0) {
        $items = @($script:optEntries | ForEach-Object { $_.Tweak })
        $script:optCachedProbeRequests = Build-TweakProbeRequests $items
    }
    $reqs = $script:optCachedProbeRequests
    if (-not $reqs -or $reqs.Length -eq 0) { return }
    $task = [DuckUtil.WindowsOptimizerEngine]::ProbeTweaksStateAsync($reqs)
    [void](Wait-TaskNonBlocking -Task $task -TimeoutSeconds 8 -CancelCheck { [bool]$script:isWindowClosing })
    if ($task.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion -and $task.Result) {
        $prevSync = $script:optSyncingVisuals
        $script:optSyncingVisuals = $true
        try {
            foreach ($res in $task.Result) {
                if ($script:optEntryById.ContainsKey([string]$res.Id)) {
                    Set-OptimizerEntryVisualState -Entry $script:optEntryById[[string]$res.Id] -State ([string]$res.State) -Detail ([string]$res.Detail)
                }
            }
        } finally {
            $script:optSyncingVisuals = $prevSync
        }
    }
    Apply-OptimizerFilter
    Update-OptimizerSelectionCount
}

function New-OptimizerTweakRowElement {
    param($Tweak)
    $b = [System.Windows.Controls.Border]::new()
    $b.Style = $script:styleOptListRow
    $b.Padding = $script:optRowPadding
    $b.Margin = $thicknessZero
    $b.MinHeight = 26
    $b.Cursor = [System.Windows.Input.Cursors]::Hand

    $riskLabel = switch ([string]$Tweak.Risk) {
        "Caution"  { "N$([char]0x00E2)ng cao" }
        "Moderate" { "Trung b$([char]0x00EC)nh" }
        default    { "An to$([char]0x00E0)n" }
    }
    $baseTipText = "$($Tweak.Name)`n$($Tweak.Description)`nM$([char]0x1EE9)c $([char]0x0111)$([char]0x1ED9): $riskLabel"
    $b.ToolTip = $baseTipText
    [System.Windows.Controls.ToolTipService]::SetInitialShowDelay($b, 5000)

    $isToggleRow = ([string]$Tweak.ControlType -eq "Toggle" -or [string]$Tweak.ControlType -eq "Combo")

    $g = [System.Windows.Controls.Grid]::new()
    $c0 = [System.Windows.Controls.ColumnDefinition]::new(); $c0.Width = if ($isToggleRow) { $script:optColWidthToggle } else { $script:optColWidthCheck }
    $c1 = [System.Windows.Controls.ColumnDefinition]::new(); $c1.Width = $glCol2
    $c2 = [System.Windows.Controls.ColumnDefinition]::new(); $c2.Width = $glAuto
    [void]$g.ColumnDefinitions.Add($c0)
    [void]$g.ColumnDefinitions.Add($c1)
    [void]$g.ColumnDefinitions.Add($c2)

    if ($isToggleRow) {
        $ctrl = [System.Windows.Controls.Primitives.ToggleButton]::new()
        if ($script:styleOptToggleSwitch) { $ctrl.Style = $script:styleOptToggleSwitch }
    } else {
        $ctrl = [System.Windows.Controls.CheckBox]::new()
    }
    $ctrl.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $ctrl.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
    [System.Windows.Controls.Grid]::SetColumn($ctrl, 0)
    [void]$g.Children.Add($ctrl)

    $titleTb = [System.Windows.Controls.TextBlock]::new()
    $titleTb.Text = [string]$Tweak.Name
    $titleTb.FontSize = 11.5
    $titleTb.FontWeight = [System.Windows.FontWeights]::SemiBold
    $titleTb.Foreground = $script:brushTextWhite
    $titleTb.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $titleTb.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
    $titleTb.Margin = $script:optTitleMargin
    [System.Windows.Controls.Grid]::SetColumn($titleTb, 1)
    [void]$g.Children.Add($titleTb)

    $comboCtrl = $null
    if ($Tweak.ControlType -eq "Combo" -and $Tweak.ComboOptions) {
        $comboCtrl = [System.Windows.Controls.ComboBox]::new()
        $comboCtrl.Width = 140
        $comboCtrl.Height = 21
        $comboCtrl.FontSize = 10.5
        $comboCtrl.Margin = [System.Windows.Thickness]::new(4, 0, 0, 0)
        $comboCtrl.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        foreach ($opt in @($Tweak.ComboOptions)) { [void]$comboCtrl.Items.Add([string]$opt) }
        if ($comboCtrl.Items.Count -gt 0) { $comboCtrl.SelectedIndex = 0 }
        [System.Windows.Controls.Grid]::SetColumn($comboCtrl, 2)
        [void]$g.Children.Add($comboCtrl)
    }

    $b.Child = $g

    $entry = [PSCustomObject]@{
        Tweak              = $Tweak
        Row                = $b
        CheckBox           = $ctrl
        TitleText          = $titleTb
        ComboBox           = $comboCtrl
        BaseToolTip        = $baseTipText
        IsToggle           = $isToggleRow
        InitialToggleState = $false
        StateBorder        = $null
        StateText          = $null
        State              = "Default"
        SearchText         = ("$($Tweak.Name) $($Tweak.Description) $($Tweak.Category) $($Tweak.Id)").ToLowerInvariant()
    }
    $b.Tag = $entry
    $ctrl.Tag = $entry
    if ($comboCtrl) {
        $comboCtrl.Tag = $entry
        $comboCtrl.Add_SelectionChanged({
            param($cs, $ce)
            if ($script:optSyncingVisuals -or -not $cs.Tag) { return }
            $selDns = [string]$cs.SelectedItem
            if ([string]::IsNullOrWhiteSpace($selDns)) { return }
            $wantDnsOn = -not ($selDns -match 'DHCP')
            Invoke-OptimizerInstantToggle -Entry $cs.Tag -WantEnabled $wantDnsOn -ForceApply
        })
    }
    $prevSync = $script:optSyncingVisuals
    $script:optSyncingVisuals = $true
    try {
        Set-OptimizerEntryVisualState -Entry $entry -State $(if ($Tweak.ProbeKind -eq "Action") { "Action" } else { "Default" })
    } finally {
        $script:optSyncingVisuals = $prevSync
    }
    return $entry
}

function Initialize-OptimizerTabIfNeeded {
    if ($script:optInitialized -or $script:isWindowClosing) { return }
    $script:optInitialized = $true

    if ($script:optScrollViewer -and ("DuckUtil.SmoothScrollController" -as [type])) {
        try { [DuckUtil.SmoothScrollController]::Attach($script:optScrollViewer) } catch {}
    }

    if ("DuckUtil.WindowsOptimizerEngine" -as [type]) {
        try {
            $script:optHardwareProfile = [DuckUtil.WindowsOptimizerEngine]::DetectHardwareProfile()
            if ($script:txtOptHardwareInfo -and $script:optHardwareProfile) {
                $script:txtOptHardwareInfo.Text = $script:optHardwareProfile.SummaryText
            }
        } catch {}
    }

    $items = Get-OptimizerCatalogItems
    $script:optEntries.Clear()
    $script:optEntryById.Clear()
    $script:optCategoryCards.Clear()
    $script:optLaneCols.Clear()
    $script:optLanePanels.Clear()
    $script:optLaneBorders.Clear()
    $script:optMasonryPanel = $null

    if ($script:optTweaksHost) {
        if (-not $script:optHostHandlersAttached) {
            $script:optHostHandlersAttached = $true
            $script:optTweaksHost.AddHandler(
                [System.Windows.Controls.Primitives.ToggleButton]::CheckedEvent,
                [System.Windows.RoutedEventHandler]{
                    param($sender, $e)
                    if ($script:optSyncingVisuals) { return }
                    $srcTb = $e.OriginalSource -as [System.Windows.Controls.Primitives.ToggleButton]
                    if ($srcTb -and -not ($srcTb -is [System.Windows.Controls.CheckBox]) -and $srcTb.Tag) {
                        Invoke-OptimizerInstantToggle -Entry $srcTb.Tag -WantEnabled $true
                        return
                    }
                    Update-OptimizerSelectionCount
                }
            )
            $script:optTweaksHost.AddHandler(
                [System.Windows.Controls.Primitives.ToggleButton]::UncheckedEvent,
                [System.Windows.RoutedEventHandler]{
                    param($sender, $e)
                    if ($script:optSyncingVisuals) { return }
                    $srcTb = $e.OriginalSource -as [System.Windows.Controls.Primitives.ToggleButton]
                    if ($srcTb -and -not ($srcTb -is [System.Windows.Controls.CheckBox]) -and $srcTb.Tag) {
                        Invoke-OptimizerInstantToggle -Entry $srcTb.Tag -WantEnabled $false
                        return
                    }
                    Update-OptimizerSelectionCount
                }
            )
            $script:optTweaksHost.AddHandler(
                [System.Windows.UIElement]::MouseLeftButtonUpEvent,
                [System.Windows.Input.MouseButtonEventHandler]{
                    param($sender, $e)
                    if ($e.Handled -or $script:isActionRunning -or $script:optApplyingSingleToggle -or $script:isWindowClosing) { return }
                    $cur = $e.OriginalSource -as [System.Windows.DependencyObject]
                    while ($cur -and $cur -ne $sender) {
                        if ($cur -is [System.Windows.Controls.Primitives.ToggleButton] -or
                            $cur -is [System.Windows.Controls.ComboBox] -or
                            $cur -is [System.Windows.Controls.ComboBoxItem]) {
                            return
                        }
                        if ($cur -is [System.Windows.Controls.Border] -and $cur.Tag -and $cur.Tag.CheckBox) {
                            $cur.Tag.CheckBox.IsChecked = -not ($cur.Tag.CheckBox.IsChecked -eq $true)
                            return
                        }
                        if ($cur -is [System.Windows.Media.Visual]) {
                            $cur = [System.Windows.Media.VisualTreeHelper]::GetParent($cur)
                        } else {
                            break
                        }
                    }
                }
            )
        }
        $script:optTweaksHost.Children.Clear()
        $script:optLanesGrid = [System.Windows.Controls.Grid]::new()
        for ($li = 0; $li -lt 2; $li++) {
            $col = [System.Windows.Controls.ColumnDefinition]::new()
            $col.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
            [void]$script:optLanesGrid.ColumnDefinitions.Add($col)
            [void]$script:optLaneCols.Add($col)

            $laneBorder = [System.Windows.Controls.Border]::new()
            $laneBorder.Background = $script:brushOptSectionBg
            $laneBorder.BorderBrush = $script:brushOptSectionBdr
            $laneBorder.BorderThickness = $thicknessOne
            $laneBorder.CornerRadius = [System.Windows.CornerRadius]::new(4)
            $laneBorder.Padding = [System.Windows.Thickness]::new(14, 10, 14, 10)
            $laneBorder.Margin = if ($li -eq 0) { [System.Windows.Thickness]::new(0, 0, 10, 0) } else { [System.Windows.Thickness]::new(0) }
            $laneBorder.VerticalAlignment = [System.Windows.VerticalAlignment]::Stretch

            $lanePanel = [System.Windows.Controls.StackPanel]::new()
            $laneBorder.Child = $lanePanel

            [System.Windows.Controls.Grid]::SetColumn($laneBorder, $li)
            [void]$script:optLanesGrid.Children.Add($laneBorder)
            [void]$script:optLaneBorders.Add($laneBorder)
            [void]$script:optLanePanels.Add($lanePanel)
        }
        [void]$script:optTweaksHost.Children.Add($script:optLanesGrid)
    }

    $grouped = [ordered]@{}
    foreach ($tw in $items) {
        $cat = [string]$tw.Category
        if (-not $grouped.Contains($cat)) {
            $grouped[$cat] = [System.Collections.Generic.List[object]]::new()
        }
        [void]$grouped[$cat].Add($tw)
    }

    $laneMap = @{
        "C$([char]0x01A1) b$([char]0x1EA3)n"               = 0
        "Windows Update"       = 0
        "N$([char]0x00E2)ng cao"             = 0
        "Giao di$([char]0x1EC7)n & Ti$([char]0x1EC7)n $([char]0x00ED)ch" = 1
        "Hi$([char]0x1EC7)u n$([char]0x0103)ng"            = 1
        "M$([char]0x1EA1)ng & Tr$([char]0x00EC)nh duy$([char]0x1EC7)t"   = 1
    }

    $orderedCats = @("C$([char]0x01A1) b$([char]0x1EA3)n", "Windows Update", "N$([char]0x00E2)ng cao", "Giao di$([char]0x1EC7)n & Ti$([char]0x1EC7)n $([char]0x00ED)ch", "Hi$([char]0x1EC7)u n$([char]0x0103)ng", "M$([char]0x1EA1)ng & Tr$([char]0x00EC)nh duy$([char]0x1EC7)t")
    $renderOrder = [System.Collections.Generic.List[string]]::new()
    foreach ($oc in $orderedCats) {
        if ($grouped.Contains($oc)) { [void]$renderOrder.Add($oc) }
    }
    foreach ($k in $grouped.Keys) {
        if (-not $renderOrder.Contains($k)) { [void]$renderOrder.Add($k) }
    }

    $catIdx = 0
    foreach ($catName in $renderOrder) {
        $catTweaks = $grouped[$catName]
        $laneIdx = if ($laneMap.ContainsKey($catName)) { [int]$laneMap[$catName] } else { $catIdx % 2 }
        $catIdx++

        $sectionPanel = [System.Windows.Controls.StackPanel]::new()
        $sectionPanel.Margin = [System.Windows.Thickness]::new(0, 0, 0, 14)

        $hdrGrid = [System.Windows.Controls.Grid]::new()
        $hc0 = [System.Windows.Controls.ColumnDefinition]::new(); $hc0.Width = $glCol2
        $hc1 = [System.Windows.Controls.ColumnDefinition]::new(); $hc1.Width = $glAuto
        [void]$hdrGrid.ColumnDefinitions.Add($hc0)
        [void]$hdrGrid.ColumnDefinitions.Add($hc1)

        $hdrTitle = [System.Windows.Controls.TextBlock]::new()
        $hdrTitle.Text = $catName
        $hdrTitle.FontSize = 13
        $hdrTitle.FontWeight = [System.Windows.FontWeights]::Bold
        $hdrTitle.Foreground = if ($catName -match "N$([char]0x00E2)ng cao|C$([char]0x1EA9)n th$([char]0x1EAD)n|Caution") { $script:brushOptRiskCautFg } else { $script:brushHeaderFg }
        $hdrTitle.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        [System.Windows.Controls.Grid]::SetColumn($hdrTitle, 0)
        [void]$hdrGrid.Children.Add($hdrTitle)

        $cntBadge = [System.Windows.Controls.Border]::new()
        $cntBadge.Background = $script:brushHeaderCntBg
        $cntBadge.CornerRadius = [System.Windows.CornerRadius]::new(3)
        $cntBadge.Padding = [System.Windows.Thickness]::new(6, 1, 6, 1)
        $cntBadge.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $cntTb = [System.Windows.Controls.TextBlock]::new()
        $cntTb.Text = [string]$catTweaks.Count
        $cntTb.FontSize = 10.5
        $cntTb.FontWeight = [System.Windows.FontWeights]::SemiBold
        $cntTb.Foreground = $script:brushHeaderCntFg
        $cntBadge.Child = $cntTb
        [System.Windows.Controls.Grid]::SetColumn($cntBadge, 1)
        [void]$hdrGrid.Children.Add($cntBadge)

        [void]$sectionPanel.Children.Add($hdrGrid)

        $sep = [System.Windows.Controls.Border]::new()
        $sep.Height = 1
        $sep.Background = $script:brushSeparator
        $sep.Margin = [System.Windows.Thickness]::new(0, 5, 0, 4)
        [void]$sectionPanel.Children.Add($sep)

        $itemsPanel = [System.Windows.Controls.StackPanel]::new()
        $catEntries = [System.Collections.Generic.List[object]]::new()
        $rowCount = $catTweaks.Count
        for ($ri = 0; $ri -lt $rowCount; $ri++) {
            $tw = $catTweaks[$ri]
            $entry = New-OptimizerTweakRowElement -Tweak $tw
            if ($ri -eq ($rowCount - 1) -and $entry.Row) {
                $entry.Row.BorderThickness = [System.Windows.Thickness]::new(0)
            }
            [void]$script:optEntries.Add($entry)
            [void]$catEntries.Add($entry)
            $script:optEntryById[[string]$tw.Id] = $entry
            [void]$itemsPanel.Children.Add($entry.Row)
        }
        [void]$sectionPanel.Children.Add($itemsPanel)

        if ($script:optLanePanels.Count -gt $laneIdx) {
            [void]$script:optLanePanels[$laneIdx].Children.Add($sectionPanel)
        }
        [void]$script:optCategoryCards.Add([PSCustomObject]@{
            Category   = $catName
            LaneIndex  = $laneIdx
            CardBorder = $sectionPanel
            ItemsPanel = $itemsPanel
            CountText  = $cntTb
            Entries    = $catEntries
        })
    }

    Refresh-OptimizerLiveState
    Update-OptimizerSelectionCount
    if ($script:optLanesGrid) {
        try {
            $script:optLanesGrid.Measure([System.Windows.Size]::new(1220, 700))
        } catch {}
    }
}

if ($script:optSubBtnCustomize) { $script:optSubBtnCustomize.Add_Click({ Set-OptimizerSubTab 0 }) }
if ($script:optSubBtnResources) { $script:optSubBtnResources.Add_Click({ Set-OptimizerSubTab 1 }) }
if ($script:optSubBtnStartup)   { $script:optSubBtnStartup.Add_Click({ Set-OptimizerSubTab 2 }) }

if ($script:btnOptRefresh) {
    $script:btnOptRefresh.Add_Click({
        if (-not $script:isWindowClosing -and -not $script:isActionRunning) {
            Refresh-OptimizerLiveState
            Log-Text "[OK] $([char]0x0110)$([char]0x00E3) l$([char]0x00E0)m m$([char]0x1EDB)i tr$([char]0x1EA1)ng th$([char]0x00E1)i th$([char]0x1EF1)c t$([char]0x1EBF) c$([char]0x1EE7)a $($script:optEntries.Count) t$([char]0x00F9)y ch$([char]0x1EC9)nh."
        }
    })
}

if ($script:btnOptApply) {
    $script:btnOptApply.Add_Click({
        $toApply = @($script:optEntries | Where-Object {
            $_.CheckBox -and (
                (-not $_.IsToggle -and $_.CheckBox.IsChecked -eq $true) -or
                ($_.IsToggle -and -not $_.InitialToggleState -and $_.CheckBox.IsChecked -eq $true)
            )
        })
        $toUndo = @($script:optEntries | Where-Object {
            $_.CheckBox -and $_.IsToggle -and $_.InitialToggleState -and ($_.CheckBox.IsChecked -ne $true)
        })
        if ($toApply.Count -eq 0 -and $toUndo.Count -eq 0) {
            Log-Text "[!] Ch$([char]0x01B0)a c$([char]0x00F3) t$([char]0x00F9)y ch$([char]0x1EC9)nh $([char]0x00F4) ch$([char]0x1ECD)n (c$([char]0x1ED9)t tr$([char]0x00E1)i) n$([char]0x00E0)o $([char]0x0111)$([char]0x01B0)$([char]0x1EE3)c tick. C$([char]0x00E1)c c$([char]0x00F4)ng t$([char]0x1EAF)c g$([char]0x1EA1)t (c$([char]0x1ED9)t ph$([char]0x1EA3)i) $([char]0x0111)$([char]0x00E3) t$([char]0x1EF1) l$([char]0x01B0)u ngay khi g$([char]0x1EA1)t!"
            if ($txtStatus) { $txtStatus.Text = "Ch$([char]0x01B0)a tick m$([char]0x1EE5)c n$([char]0x00E0)o $([char]0x1EDF) c$([char]0x1ED9)t tr$([char]0x00E1)i (c$([char]0x00F4)ng t$([char]0x1EAF)c g$([char]0x1EA1)t c$([char]0x1ED9)t ph$([char]0x1EA3)i t$([char]0x1EF1) l$([char]0x01B0)u ngay khi g$([char]0x1EA1)t)." }
            return
        }
        $cautionItems = @($toApply | Where-Object { $_.Tweak.Risk -eq "Caution" })
        if ($cautionItems.Count -gt 0) {
            $cNames = ($cautionItems | ForEach-Object { "$([char]0x2022) $($_.Tweak.Name)" }) -join "`n"
            $ans = Show-OwnedMessageBox `
                -Text "B$([char]0x1EA1)n $([char]0x0111)$([char]0x00E3) ch$([char]0x1ECD)n $($cautionItems.Count) t$([char]0x00F9)y ch$([char]0x1EC9)nh m$([char]0x1EE9)c N$([char]0x00E2)ng cao:`n$cNames`n`nApp-Driver s$([char]0x1EBD) t$([char]0x1EF1) $([char]0x0111)$([char]0x1ED9)ng sao l$([char]0x01B0)u tr$([char]0x1EA1)ng th$([char]0x00E1)i g$([char]0x1ED1)c tr$([char]0x01B0)$([char]0x1EDB)c khi l$([char]0x01B0)u. Ti$([char]0x1EBF)p t$([char]0x1EE5)c?" `
                -Caption "X$([char]0x00E1)c nh$([char]0x1EAD)n l$([char]0x01B0)u t$([char]0x00F9)y ch$([char]0x1EC9)nh n$([char]0x00E2)ng cao" `
                -Buttons ([System.Windows.Forms.MessageBoxButtons]::YesNo) `
                -Icon ([System.Windows.Forms.MessageBoxIcon]::Warning)
            if ($ans -ne [System.Windows.Forms.DialogResult]::Yes -or $script:isWindowClosing) { return }
        }
        Invoke-GuardedAction "L$([char]0x01B0)u c$([char]0x1EA5)u h$([char]0x00EC)nh t$([char]0x1ED1)i $([char]0x01B0)u Windows" -AllowDuringUninstallerLoad {
            if ($btnCancelAction) {
                $btnCancelAction.Content = "D$([char]0x1EEB)ng t$([char]0x00E1)c v$([char]0x1EE5)"
                $btnCancelAction.IsEnabled = $true
                $btnCancelAction.Visibility = [System.Windows.Visibility]::Visible
            }
            $totalApplied = 0
            $totalFailed = 0
            if ($toUndo.Count -gt 0) {
                $undoObjs = @($toUndo | ForEach-Object { $_.Tweak })
                Log-Text "=========================================================="
                Log-Text "[OPTIMIZER] T$([char]0x1EAE)T $($undoObjs.Count) C$([char]0x1EA6)N G$([char]0x1EA0)T V$([char]0x1EC0) M$([char]0x1EB6)C $([char]0x0110)$([char]0x1ECA)NH"
                Log-Text "=========================================================="
                $resUndo = Invoke-OptimizerBatch -Tweaks $undoObjs -Mode "Undo" -HardwareProfile $script:optHardwareProfile -ProgressCallback {
                    param($cur, $tot, $nm)
                    if ($progressBar) { $progressBar.Value = [math]::Round(($cur / $tot) * 100) }
                    if ($txtStatus) { $txtStatus.Text = "[$cur/$tot] $([char]0x0110)ang t$([char]0x1EAF)t v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh: $nm..." }
                }
                $totalApplied += $resUndo.Applied
                $totalFailed += $resUndo.Failed
            }
            if ($toApply.Count -gt 0) {
                $combos = @{}
                $twObjs = @()
                foreach ($ent in $toApply) {
                    $twObjs += $ent.Tweak
                    if ($ent.ComboBox -and $ent.ComboBox.SelectedItem) {
                        $combos[[string]$ent.Tweak.Id] = [string]$ent.ComboBox.SelectedItem
                    }
                }
                Log-Text "=========================================================="
                Log-Text "[OPTIMIZER] L$([char]0x01AF)U & B$([char]0x1EAC)T $($twObjs.Count) T$([char]0x00D9)Y CH$([char]0x1EC8)NH WINDOWS"
                Log-Text "=========================================================="
                $res = Invoke-OptimizerBatch -Tweaks $twObjs -Mode "Apply" -ComboSelections $combos -HardwareProfile $script:optHardwareProfile -ProgressCallback {
                    param($cur, $tot, $nm)
                    if ($progressBar) { $progressBar.Value = [math]::Round(($cur / $tot) * 100) }
                    if ($txtStatus) { $txtStatus.Text = "[$cur/$tot] $([char]0x0110)ang l$([char]0x01B0)u: $nm..." }
                }
                $totalApplied += $res.Applied
                $totalFailed += $res.Failed
            }
            $prevSync = $script:optSyncingVisuals
            $script:optSyncingVisuals = $true
            try {
                foreach ($ent in $toApply) {
                    if (-not $ent.IsToggle -and $ent.CheckBox) { $ent.CheckBox.IsChecked = $false }
                }
            } finally {
                $script:optSyncingVisuals = $prevSync
            }
            if ($progressBar) { $progressBar.Value = 0 }
            if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)$([char]0x00E3) l$([char]0x01B0)u t$([char]0x1ED1)i $([char]0x01B0)u ($totalApplied th$([char]0x00E0)nh c$([char]0x00F4)ng, $totalFailed l$([char]0x1ED7)i)" }
            Log-Text "[OK] $([char]0x0110)$([char]0x00E3) l$([char]0x01B0)u c$([char]0x1EA5)u h$([char]0x00EC)nh t$([char]0x1ED1)i $([char]0x01B0)u: $totalApplied th$([char]0x00E0)nh c$([char]0x00F4)ng $([char]0x2022) $totalFailed l$([char]0x1ED7)i."
            if ($totalFailed -gt 0) {
                $isAdminNow = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
                if (-not $isAdminNow) {
                    Log-Text "[WARN] M$([char]0x1ED9)t s$([char]0x1ED1) t$([char]0x00F9)y ch$([char]0x1EC9)nh h$([char]0x1EC7) th$([char]0x1ED1)ng (HKLM/Service) y$([char]0x00EA)u c$([char]0x1EA7)u m$([char]0x1EDF) App-Driver b$([char]0x1EB1)ng quy$([char]0x1EC1)n Administrator."
                }
            }
            Refresh-OptimizerLiveState
        }
    })
}

if ($script:btnOptUndo) {
    $script:btnOptUndo.Add_Click({
        $selected = @($script:optEntries | Where-Object {
            $_.CheckBox -and (
                (-not $_.IsToggle -and $_.CheckBox.IsChecked -eq $true) -or
                ($_.IsToggle -and $_.InitialToggleState -and $_.CheckBox.IsChecked -ne $true)
            )
        })
        $targets = @()
        $promptText = ""
        if ($selected.Count -gt 0) {
            $targets = $selected
            $promptText = "$([char]0x0110)$([char]0x1EB7)t $($targets.Count) t$([char]0x00F9)y ch$([char]0x1EC9)nh $([char]0x0111)$([char]0x00E3) ch$([char]0x1ECD)n v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh c$([char]0x1EE7)a Windows?"
        } else {
            $appliedList = @($script:optEntries | Where-Object { $_.State -eq "Applied" -or $_.State -eq "Partial" })
            if ($appliedList.Count -eq 0) {
                [void](Show-OwnedMessageBox -Text "Hi$([char]0x1EC7)n ch$([char]0x01B0)a c$([char]0x00F3) t$([char]0x00F9)y ch$([char]0x1EC9)nh n$([char]0x00E0)o $([char]0x0111)ang b$([char]0x1EAD)t $([char]0x0111)$([char]0x1EC3) $([char]0x0111)$([char]0x1EB7)t v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh." -Caption "$([char]0x0110)$([char]0x1EB7)t v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh" -Buttons ([System.Windows.Forms.MessageBoxButtons]::OK) -Icon ([System.Windows.Forms.MessageBoxIcon]::Information))
                return
            }
            $targets = $appliedList
            $promptText = "B$([char]0x1EA1)n ch$([char]0x01B0)a tick m$([char]0x1EE5)c n$([char]0x00E0)o.`n$([char]0x0110)$([char]0x1EB7)t to$([char]0x00E0)n b$([char]0x1ED9) $($targets.Count) t$([char]0x00F9)y ch$([char]0x1EC9)nh $([char]0x0111)ang b$([char]0x1EAD)t v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh c$([char]0x1EE7)a Windows?"
        }

        $ans = Show-OwnedMessageBox `
            -Text $promptText `
            -Caption "X$([char]0x00E1)c nh$([char]0x1EAD)n $([char]0x0111)$([char]0x1EB7)t v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh" `
            -Buttons ([System.Windows.Forms.MessageBoxButtons]::YesNo) `
            -Icon ([System.Windows.Forms.MessageBoxIcon]::Question)
        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes -or $script:isWindowClosing) { return }

        Invoke-GuardedAction "$([char]0x0110)$([char]0x1EB7)t t$([char]0x1ED1)i $([char]0x01B0)u v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh" -AllowDuringUninstallerLoad {
            if ($btnCancelAction) {
                $btnCancelAction.Content = "D$([char]0x1EEB)ng t$([char]0x00E1)c v$([char]0x1EE5)"
                $btnCancelAction.IsEnabled = $true
                $btnCancelAction.Visibility = [System.Windows.Visibility]::Visible
            }
            $twObjs = @($targets | ForEach-Object { $_.Tweak })
            $twIds = @($twObjs | ForEach-Object { [string]$_.Id })
            Log-Text "=========================================================="
            Log-Text "[OPTIMIZER] $([char]0x0110)$([char]0x1EB6)T $($twObjs.Count) T$([char]0x00D9)Y CH$([char]0x1EC8)NH V$([char]0x1EC0) M$([char]0x1EB6)C $([char]0x0110)$([char]0x1ECA)NH"
            Log-Text "=========================================================="
            $res = Invoke-OptimizerBatch -Tweaks $twObjs -Mode "Undo" -HardwareProfile $script:optHardwareProfile -ProgressCallback {
                param($cur, $tot, $nm)
                if ($progressBar) { $progressBar.Value = [math]::Round(($cur / $tot) * 100) }
                if ($txtStatus) { $txtStatus.Text = "[$cur/$tot] $([char]0x0110)ang $([char]0x0111)$([char]0x1EB7)t v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh: $nm..." }
            }
            if (Get-Command "Restore-AllOptimizerGuardSnapshots" -ErrorAction SilentlyContinue) {
                [void](Restore-AllOptimizerGuardSnapshots -FilterTweakIds $twIds)
            }
            if ($progressBar) { $progressBar.Value = 0 }
            if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)$([char]0x00E3) $([char]0x0111)$([char]0x1EB7)t v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh ($($res.Applied) th$([char]0x00E0)nh c$([char]0x00F4)ng)" }
            Log-Text "[OK] $([char]0x0110)$([char]0x00E3) $([char]0x0111)$([char]0x1EB7)t $($res.Applied) t$([char]0x00F9)y ch$([char]0x1EC9)nh v$([char]0x1EC1) m$([char]0x1EB7)c $([char]0x0111)$([char]0x1ECB)nh ($($res.Failed) l$([char]0x1ED7)i)."
            Refresh-OptimizerLiveState
        }
    })
}

if ($script:btnOptRestoreBackup) {
    $script:btnOptRestoreBackup.Add_Click({
        $bkps = @(Get-OptimizerBackupsList)
        $oldestDesc = if ($bkps.Count -gt 0) {
            $oldest = $bkps[$bkps.Count - 1]
            $newest = $bkps[0]
            "T$([char]0x1ED5)ng s$([char]0x1ED1) b$([char]0x1EA3)n sao l$([char]0x01B0)u: $($bkps.Count)`nB$([char]0x1EA3)n g$([char]0x1ED1)c $([char]0x0111)$([char]0x1EA7)u ti$([char]0x00EA)n: $($oldest.CreatedAt)`nB$([char]0x1EA3)n g$([char]0x1EA7)n nh$([char]0x1EA5)t: $($newest.CreatedAt)"
        } else {
            "Kh$([char]0x00F4)i ph$([char]0x1EE5)c l$([char]0x1EA1)i c$([char]0x1EA5)u h$([char]0x00EC)nh ngu$([char]0x1ED3)n OEM, $([char]0x1EE9)ng d$([char]0x1EE5)ng n$([char]0x1EC1)n v$([char]0x00E0) d$([char]0x1ECB)ch v$([char]0x1EE5) Lenovo Vantage / Fn+Q"
        }
        $ans = Show-OwnedMessageBox `
            -Text "Kh$([char]0x00F4)i ph$([char]0x1EE5)c to$([char]0x00E0)n b$([char]0x1ED9) tr$([char]0x1EA1)ng th$([char]0x00E1)i h$([char]0x1EC7) th$([char]0x1ED1)ng v$([char]0x1EC1) b$([char]0x1EA3)n sao l$([char]0x01B0)u g$([char]0x1ED1)c ban $([char]0x0111)$([char]0x1EA7)u tr$([char]0x01B0)$([char]0x1EDB)c khi t$([char]0x1ED1)i $([char]0x01B0)u ($([char]0x0111)$([char]0x1ED3)ng th$([char]0x1EDD)i $([char]0x0111)$([char]0x1ED3)ng b$([char]0x1ED9) l$([char]0x1EA1)i d$([char]0x1ECB)ch v$([char]0x1EE5) ngu$([char]0x1ED3)n & Fn+Q)?`n`n$oldestDesc" `
            -Caption "Kh$([char]0x00F4)i ph$([char]0x1EE5)c b$([char]0x1EA3)n sao l$([char]0x01B0)u OptimizerGuard" `
            -Buttons ([System.Windows.Forms.MessageBoxButtons]::YesNo) `
            -Icon ([System.Windows.Forms.MessageBoxIcon]::Question)
        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes -or $script:isWindowClosing) { return }

        Invoke-GuardedAction "Kh$([char]0x00F4)i ph$([char]0x1EE5)c to$([char]0x00E0)n b$([char]0x1ED9) b$([char]0x1EA3)n sao l$([char]0x01B0)u OptimizerGuard" -AllowDuringUninstallerLoad {
            [void](Restore-AllOptimizerGuardSnapshots)
            if ($txtStatus) { $txtStatus.Text = "$([char]0x0110)$([char]0x00E3) kh$([char]0x00F4)i ph$([char]0x1EE5)c to$([char]0x00E0)n b$([char]0x1ED9) b$([char]0x1EA3)n sao l$([char]0x01B0)u g$([char]0x1ED1)c OptimizerGuard" }
            Refresh-OptimizerLiveState
        }
    })
}
#endregion

#region Startup Manager Tab (OptPageStartup)
$script:btnStartRefresh       = $window.FindName("btnStartRefresh")
$script:btnStartCleanOrphans  = $window.FindName("btnStartCleanOrphans")
$script:btnStartRestoreBackup = $window.FindName("btnStartRestoreBackup")
$script:btnStartAddApp        = $window.FindName("btnStartAddApp")
$script:txtStartSearch        = $window.FindName("txtStartSearch")
$script:btnClearStartSearch   = $window.FindName("btnClearStartSearch")
$script:btnStartFilterAll     = $window.FindName("btnStartFilterAll")
$script:btnStartFilterOn      = $window.FindName("btnStartFilterOn")
$script:btnStartFilterOff     = $window.FindName("btnStartFilterOff")
